INSERT INTO keywords (name, description) VALUES ("Abdomen", "Porción del cuerpo entre el tórax y la pelvis que constituye una cavidad separada de la torácica por el diafragma y tapizada por el peritoneo. Esta cavidad contiene las vísceras abdominales y está delimitada por una pared formada por los músculos abdominales, la columna vertebral y los huesos ilíacos.");
INSERT INTO keywords (name, description) VALUES ("Abdominoplastia", "Operación quirúrgica para eliminar tejido graso o exceso de piel de las porciones bajas y medias del abdomen.");
INSERT INTO keywords (name, description) VALUES ("Abducción", "Término anatómico que hace referencia al movimiento de separación de un miembro de la línea media del cuerpo. Lo opuesto a aducción.");
INSERT INTO keywords (name, description) VALUES ("Aborto", "Eliminación o pérdida del feto de la cavidad uterina.");
INSERT INTO keywords (name, description) VALUES ("Absceso", "Colección localizada de pus en tejidos, órganos o espacios delimitados, normalmente causada por un organismo infeccioso.");
INSERT INTO keywords (name, description) VALUES ("Absceso de Bartholin", "Absceso de la glándula vulvovaginal.");
INSERT INTO keywords (name, description) VALUES ("Absceso perianal", "Absceso que se forma junto a la abertura anal.");
INSERT INTO keywords (name, description) VALUES ("Absorciometría radiográfica dual (DEXA)", "Test diagnóstico para la osteoporosis.");
INSERT INTO keywords (name, description) VALUES ("Absorción", "Término electroterápico; varía con el tipo, intensidad y propiedades de la energía, así como con los tipos y distribución de los tejidos a
través de los que pasa. Absorción es lo contrario de penetración; por lo tanto, el ultrasonido de mayor frecuencia (p. ej., 3 MHz) con
su corta longitud de onda es absorbido más rápidamente que el ultrasonido de baja frecuencia (p. ej., 1MHz o menos).");
INSERT INTO keywords (name, description) VALUES ("Abuso", "Daño causado o perpetrado por una persona sobre otra. El abuso puede ser físico, verbal, sexual, psicológico, emocional, financiero o
por abandono. Es normalmente cometido por aquellos que tienen poder sobre personas que son relativamente menos poderosas e
incluye ofensas criminales. El abuso puede ser también incluido en la estructura y carácter de las instituciones, lo que hace referencia al
término «abuso del sistema». En el tratamiento del abuso, los deseos de la víctima deben ser considerados de máxima importancia.");
INSERT INTO keywords (name, description) VALUES ("Accidente cerebrovascular (ACV)", "Interrupción súbita del aporte sanguíneo al ce rebro, que da lugar a un déficit neurológico de más de 24 h de duración. Un término
equivalente es embolia. Puede estar causado tanto por una hemorragia como por un infarto.");
INSERT INTO keywords (name, description) VALUES ("Acción afirmativa", "Política o práctica que apoya favorablemente a grupos en desventaja (incluyendo mujeres, minorías étnicas y personas discapacitadas)
que han experimentado discriminación institucional. También hace referencia a discriminación positiva.
El concepto es complejo y la práctica de una acción afirmativa puede, en algunas circunstancias, ser ilegal.");
INSERT INTO keywords (name, description) VALUES ("Aceleración", "Índice de cambio de la velocidad, es decir, el cambio de la velocidad en un tiempo dado:Acetilcolina
También conocida como ACh, la acetilcolina actúa como neuro-transmisor en muchas sinapsis en el sistema nervioso periférico y el
sistema nervioso central, incluyendo uniones neuromusculares.");
INSERT INTO keywords (name, description) VALUES ("Ácido láctico", "Derivado del metabolismo anaeróbico. Es un producto intermedio del metabolismo de los carbohidratos, derivado en su mayor parte
de las células musculares y los eritrocitos. Los niveles de ácido láctico deben medirse en el torrente sanguíneo en condiciones de
acidosis metabólica.");
INSERT INTO keywords (name, description) VALUES ("Acidosis", "Alteración resultante de la acumulación de mucho ácido o pérdida de base. Si está causada por el sistema respiratorio se conoce como
acidosis respiratoria; si la causa es otro factor, se llama acidosis metabólica. Se manifiesta clínicamente por laxitud, somnolencia,
vértigos, cefaleas, anorexia, vómitos, diarrea, etc.");
INSERT INTO keywords (name, description) VALUES ("Acidosis metabólica", "Puede producirse consecutivamente a una ingesta de ácidos o una producción de ácidos en exceso por el cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Acidosis respiratoria", "Disminución del pH de la sangre y aumento de la PCO 2 , que se observa comúnmente en enfermedades pulmonares crónicas en que el
CO 2 no puede eliminarse eficazmente, haciendo por tanto más ácido el plasma sanguíneo.");
INSERT INTO keywords (name, description) VALUES ("Acinesia", "Incapacidad para iniciar o retraso en el inicio del movimiento, que se observa normalmente en la enfermedad del Parkinson.");
INSERT INTO keywords (name, description) VALUES ("Acné rosácea", "Alteración de la piel resultante de la inflamación crónica de mejillas, nariz, barbilla, frente y/o párpados; es debida generalmente al
abuso de los estimulantes alcohólicos. Se trata con antibióticos.");
INSERT INTO keywords (name, description) VALUES ("Acomodación", "Propiedad del nervio. Si el estímulo aumenta lentamente, la bomba de sodio se ajusta y no habrá potencial de acción. El nervio se ha
acomodado.");
INSERT INTO keywords (name, description) VALUES ("Acortamiento recíproco", "Cuando un grupo de músculos trabaja excéntricamente, los músculos opuestos tienen que acortarse, pero el músculo no se contrae
activamente, sino que se forman puentes cruzados.");
INSERT INTO keywords (name, description) VALUES ("ACP", "Abreviatura médica común de arteria comunicante posterior y de analgesia controlada por el paciente.
La arteria comunicante posterior es una rama de la arteria basilar que irriga la corteza occipital y la parte inferior del lóbulo temporal.
Puede estar afectada en la apoplejía, dando lugar a una hemianopsia homónima en el lado contralateral.");
INSERT INTO keywords (name, description) VALUES ("Acrodinia", "Dolor de las extremidades.
Alteración del sistema nervioso vegetativo, que aparece con frecuencia en la infancia y se caracteriza por aumento de la sensibilidad de
plantas y palmas, con sensación de hormigueo y dolores reumatoides en manos y pies y una erupción eritematosa seguida de exfoliación
y pigmentación parda en la zona distal de las extremidades.");
INSERT INTO keywords (name, description) VALUES ("Acromegalia", "Alteración metabólica causada por un exceso de hormona del crecimiento. Los tejidos corporales aumentan de tamaño, incluyendo los
hue sos de la cara, mandíbulas, manos, pies y cráneo. Puede también afectar al corazón dando lugar a un aumento de su tamaño.
Acropaquia, dedos en palillo de tamborAumento de tamaño de las falanges terminales de los dedos de las manos o los pies. La acropaquia se asocia a alteraciones de corazón,
pulmón, hígado e intestino, aparte de ser una anormalidad congénita. Si es reciente, puede estar relacionada con sepsis, alveolitis
criptogénica fibrosante (ACF) o diversos carcinomas (incluyendo el de pulmón). Puede ser evidente tanto en enfermedades supurativas
(p. ej., bron-quiectasia y fibrosis quística) como en enfermedades pulmonares infiltrativas (p. ej., ACF). No es una característica de la
EPOC.");
INSERT INTO keywords (name, description) VALUES ("Actina", "Proteína implicada en la contracción muscular.
Véase Teoría del filamento corredizo .
La actina y la miosina se deslizan de tal manera que provocan el acortamiento de un músculo.
Véase Teoría del filamento corredizo .");
INSERT INTO keywords (name, description) VALUES ("Actinoterapia", "Término electroterápico; nombre alternativo para la radiación ultravioleta (RUV) usada en el tratamiento de ciertas alteraciones de la
piel.");
INSERT INTO keywords (name, description) VALUES ("Actitud", "Orientación hacia las personas, situaciones e ideas que tienen dimensiones comportamentales, cognitivas y emocionales. Implica una
disposición a responder de una manera predeterminada.");
INSERT INTO keywords (name, description) VALUES ("Actividades de la vida diaria (AVD)", "Las cosas que normalmente hacemos durante el transcurso de nuestra vida diaria; por ejemplo, ponernos la ropa. La habilidad de la
persona para llevar a cabo estas actividades puede ser utilizada como medida de evaluación. Los fisioterapeutas deben ser conscientes
de que lo que para un individuo constituye una forma de vida normal puede no serlo para otro.");
INSERT INTO keywords (name, description) VALUES ("Acueducto cerebral", "Canal lleno de líquido cefalorraquídeo dentro del cerebro medio. Si se bloquea da lugar a hidrocefalia.");
INSERT INTO keywords (name, description) VALUES ("Acupuntura", "Práctica terapéutica tradicional china para el alivio del dolor usando agujas.");
INSERT INTO keywords (name, description) VALUES ("Adaptación", "1. Modificación en respuesta a un estímulo; puede ser un cambio permanente (p. ej., cambio de la dominancia de miembros después de
un traumatismo grave en el miembro previamente dominante) o transitorio. 2. Acomodación psicológica, conductual o emocional a un
conjunto particular de circunstancias o hechos.");
INSERT INTO keywords (name, description) VALUES ("Adenoidectomía", "Eliminación quirúrgica de las glándulas adenoides.");
INSERT INTO keywords (name, description) VALUES ("Adenoma pituitario", "Tumor de la glándula pituitaria; a menudo aparece en la parte anterior de la glándula. Normalmente son benignos.Este término se refiere al aumento de tamaño de una glándula. Se usa especialmente en relación con los ganglios linfáticos.");
INSERT INTO keywords (name, description) VALUES ("Adenosín trifosfato (ATP)", "Nucleótido presente en todas las células vivas que sirve como fuente de energía.");
INSERT INTO keywords (name, description) VALUES ("ADN", "Abreviatura médica común de ácido desoxirribonucleico.");
INSERT INTO keywords (name, description) VALUES ("Aducción", "Término anatómico que indica un movimiento hacia la línea media del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Advertencias", "Después de que el terapeuta haya explicado por qué recomienda la utilización de una terapia particular, debería advertir al paciente,
previamente a cada tratamiento, acerca de:
• Lo que va a sentir durante el tratamiento.
• Lo que no debería sentir.
• Lo que debe hacer si el efecto o lo que siente no es lo esperado.
El paciente dará así el consentimiento para usar el procedimiento recomendado.");
INSERT INTO keywords (name, description) VALUES ("Aeróbico", "Proceso metabólico que requiere la presencia de oxígeno.");
INSERT INTO keywords (name, description) VALUES ("Afasia", "Alteración ocasionada por un daño cerebral que da lugar a la incapacidad para comprender el lenguaje escrito u oral o para expresarse.");
INSERT INTO keywords (name, description) VALUES ("Afasia de Broca", "Alteración del lenguaje en que la persona tiene dificultad para hablar o repetir palabras, pero conserva la comprensión. Se le dio el
nombre del área del cerebro que está dañada en esta alteración: el área de Broca, que se halla en el lóbulo frontal.");
INSERT INTO keywords (name, description) VALUES ("Aferente", "Expresa la aproximación al sistema nervioso central; así, se utiliza para describir las fibras nerviosas que transmiten impulsos a la médula
espinal y al resto del sistema nervioso central (SNC) desde el resto del cuerpo. Por ejemplo, la información sensorial de la mano viajará
a lo largo de las fibras aferentes hacia el SNC.
Véase Eferente.");
INSERT INTO keywords (name, description) VALUES ("Aflicción", "Estar privado de algo o alguien que es valioso y apreciado, normalmente un pariente o amigo muerto. Durante las primeras etapas de
aflicción las personas son más propensas a sufrir enfermedades.
Véase Duelo.");
INSERT INTO keywords (name, description) VALUES ("AFR", "Abreviatura médica común de articulación femororrotuliana.");
INSERT INTO keywords (name, description) VALUES ("Agente mucolítico", "Agente que fluidifica el moco.");
INSERT INTO keywords (name, description) VALUES ("Agentes electrofísicos", "Término electroterápico que se aplica a los métodos de tratamiento que usan estimulación eléctrica o agentes físicos como calor, frío,
ultrasonidos, láser y radiaciones ultravioleta. También se utilizan para el diagnóstico con el material apropiado: ultrasonidos (para la
visualización del tejido subcutáneo) y radiaciones ultravioleta (para el diagnóstico de algunas alteraciones de la piel).Incapacidad de un individuo de dar significado o reconocer algo a pesar de recibir información sensorial. Por ejemplo, un paciente
puede tocar un cepillo pero no reconocer que es un cepillo. Esto se asocia con lesiones en las áreas parietales posteriores del cerebro.");
INSERT INTO keywords (name, description) VALUES ("Flexión de codo", "");
INSERT INTO keywords (name, description) VALUES ("Agonista", "Músculo que actúa como motor principal que genera un movimiento; por ejemplo, cuando elevamos una taza hacia la boca, los
músculos bíceps y bra-quial son agonistas, mientras que el tríceps sería el antagonista en este ejemplo.");
INSERT INTO keywords (name, description) VALUES ("Agotamiento", "Respuesta de ansiedad o estrés, a veces clasificada como trastorno, resultante del sobreesfuerzo. Implica sensaciones de cansancio,
ansiedad, cinesismo y depresión.");
INSERT INTO keywords (name, description) VALUES ("Agudo", "Que cursa con síntomas graves y/o de corta duración.");
INSERT INTO keywords (name, description) VALUES ("Aguja de Steinman", "Véase Tracción ósea.");
INSERT INTO keywords (name, description) VALUES ("AIMS2", "Útil herramienta de medida en alteraciones artríticas (Meenan y cols., 1992).");
INSERT INTO keywords (name, description) VALUES ("AIT", "Abreviatura médica común de ataque isquémico transitorio.
Episodios de síntomas neurológicos focales de duración inferior a 24 h causados por un aporte sanguíneo insuficiente al cerebro.
Pueden ser un aviso inminente de un ataque y deberían tratarse como una afección médica urgente.");
INSERT INTO keywords (name, description) VALUES ("Ajustes posturales", "Son movimientos leves, espontáneos y a menudo pequeños que se producen en el cuerpo para permitir la correcta función de otras
partes de éste; por ejemplo, cuando alargamos el brazo realizamos ajustes posturales en el tronco. Estas reacciones requieren
información desde los sistemas propioceptivo y vestibular.");
INSERT INTO keywords (name, description) VALUES ("Ajustes posturales anticipados", "Son parte del mecanismo de equilibrio global. Ocurren en músculos posturales antes del movimiento global o del movimiento de una
parte del cuerpo. Por ejemplo, previamente al movimiento del brazo habrá ajustes posturales anticipados en el tronco. Estos pequeños
cambios, que pueden pasar inadvertidos a simple vista, son esenciales en el mantenimiento del equilibrio.");
INSERT INTO keywords (name, description) VALUES ("Alcalosis", "Alteración patológica ocasionada por acumulación de bases o pérdida de ácidos con causas primarias respiratorias (hiperventilación) o
metabólicas.Alcalosis metabólica
Ocurre después de vomitar, debido a la pérdida de iones H + .");
INSERT INTO keywords (name, description) VALUES ("Alcalosis respiratoria", "Aparece cuando una persona elimina demasiado CO 2 de la sangre; el aumento del pH puede ocurrir en estados de ansiedad.");
INSERT INTO keywords (name, description) VALUES ("Aldosterona", "Esteroide producido por la corteza suprarrenal que controla el equilibrio de sales y agua a través del riñón.");
INSERT INTO keywords (name, description) VALUES ("Aleatorización (randomización)", "Término de investigación que se aplica al proceso por el cual cada miembro de una población tiene las mismas oportunidades de ser
incluido en la muestra.");
INSERT INTO keywords (name, description) VALUES ("Alendronato (Fosfamax®)", "Fármaco bifosfonado que se utiliza específicamente para la prevención y el tratamiento de la osteoporosis.");
INSERT INTO keywords (name, description) VALUES ("Aleteo auricular", "Término utilizado para describir una actividad auricular regular pero tan rápida que la conducción de impulsos a los ventrículos puede
verse alterada, de tal manera que sólo un impulso de cada dos o tres excita la actividad ventricular y da lugar a una pulsación
detectable.");
INSERT INTO keywords (name, description) VALUES ("Aleteo nasal", "Signo de dificultad respiratoria en niños.");
INSERT INTO keywords (name, description) VALUES ("Algesia", "Doloroso o que causa dolor. Analgesia significa «alivio del dolor».");
INSERT INTO keywords (name, description) VALUES ("Algodistrofia", "Véase Síndrome del complejo regional doloroso (SCRD) .");
INSERT INTO keywords (name, description) VALUES ("Alimentación nasogástrica", "Proceso mediante el cual un paciente con dificultades para la deglución tras una lesión neurológica recibe alimentación a través de un
tubo que se introduce por la nariz y llega hasta el estómago.
Observación clínica Es importante ser consciente de que los tubos nasogástricos pueden desplazarse, por lo que existe el riesgo de
que el alimento entre en los pulmones.");
INSERT INTO keywords (name, description) VALUES ("Alineamiento", "Se refiere a la interrelación postural de los segmentos corporales en diferentes planos. Los fisioterapeutas valoran el alineamiento en
diferentes posiciones (p. ej., en bipedestación y sedestación), ya que el alineamiento normal es esencial para el movimiento eficaz. Hay
una variabilidad constante de alineamiento por lo que la valoración individual y el juicio clínico son importantes.");
INSERT INTO keywords (name, description) VALUES ("Almohadilla grasa infrarrotuliana", "Está situada por debajo del tendón de la rótula y llena el espacio entre los cóndilos tibiales y el fémur.");
INSERT INTO keywords (name, description) VALUES ("Alopecia", "Ausencia de pelo en aquellas áreas de piel donde normalmente está presente.");
INSERT INTO keywords (name, description) VALUES ("Alteraciones neuromusculares", "Alteraciones musculares adquiridas o hereditarias debidas a una enfermedad neuromuscular. Se clasifican de acuerdo con la edad de
inicio y la localización del defecto.Final del parto, en que el feto es expulsado del útero.");
INSERT INTO keywords (name, description) VALUES ("Alveolitis", "Inflamación de los alvéolos.");
INSERT INTO keywords (name, description) VALUES ("Alveolitis fibrosante", "Alteración inflamatoria que comienza con un daño alveolar difuso y que da lugar a una fibrosis que también se observa en las
enfermedades vasculares de colágeno.");
INSERT INTO keywords (name, description) VALUES ("Alveolitis fibrosante criptogénica", "Causa desconocida de la alveolitis fibrosante.");
INSERT INTO keywords (name, description) VALUES ("Alvéolo", "Unidad de intercambio gaseoso del pulmón (saco aéreo). Es particularmente apto para su función de intercambio gaseoso, ya que tiene
un área de sección transversal grande, un aporte abundante de sangre y un tamaño del grosor de una sola célula para facilitar la difusión
a través de la membrana capilar alveolar.");
INSERT INTO keywords (name, description) VALUES ("Amenorrea", "Cese de la menstruación.");
INSERT INTO keywords (name, description) VALUES ("Amígdala", "1. Núcleo situado en el lóbulo temporal anterior que se asocia con el aprendizaje de las emociones y la memoria. 2. Uno de los dos
órganos glandulares situados en la garganta.");
INSERT INTO keywords (name, description) VALUES ("Amiloidosis", "Trastorno metabólico consistente en el depósito intersticial de amiloide en distintos órganos y tejidos; es una complicación común de
enfermedades graves como la artritis reumatoide. Los depósitos pueden causar problemas en el riñón y otros problemas sistémicos.");
INSERT INTO keywords (name, description) VALUES ("Aminoácido", "Sustancia que contiene un grupo amino y un grupo carboxilo; pueden combinarse entre sí para formar proteínas en los seres vivos.");
INSERT INTO keywords (name, description) VALUES ("Amitriptilina", "Fármaco utilizado para tratar la depresión.");
INSERT INTO keywords (name, description) VALUES ("Amnesia", "Pérdida grave de memoria. Puede clasificarse como:
• Amnesia anterógrada. El paciente es incapaz para formar nuevos recuerdos.
• Amnesia retrógrada. Pérdida de memoria de los hechos previos a la lesión.
• Amnesia global transitoria. Corto período en el que coinciden los dos tipos de amnesia anteriores y que normalmente sólo dura horas
o días.
El fisioterapeuta se encontrará con estos casos cuando trate pacientes con lesiones craneales, aunque también puede ocurrir en otras
alteraciones cere brales.");
INSERT INTO keywords (name, description) VALUES ("Amnesia postraumática (APT)", "Afecta al período de tiempo que transcurre entre una lesión cerebral y el momento en que se determina que las funciones relacionadas
con la memoria han sido restauradas. Es una pérdida de la memoria permanente y tiende a reflejar la gravedad de la lesión.");
INSERT INTO keywords (name, description) VALUES ("Amnesia retrógrada", "Incapacidad de recordar un suceso ocurrido antes de una lesión cerebral.Fina membrana que recubre el corion y contiene el feto y el líquido amniótico.");
INSERT INTO keywords (name, description) VALUES ("Amplitud", "Término electroterápico que corresponde a la intensidad de una corriente, clínicamente medida en mA o
ilustraciones de un impulso por la altura.
Véase Impulso.
μA. Representada en");
INSERT INTO keywords (name, description) VALUES ("Amputado", "Persona con una amputación de un miembro o parte de éste.");
INSERT INTO keywords (name, description) VALUES ("Anaeróbico", "Proceso metabólico que requiere ausencia o bajos niveles de oxígeno.");
INSERT INTO keywords (name, description) VALUES ("Anakinra", "Terapia biológica relativamente nueva y potencialmente eficaz para el tratamiento de alteraciones reumatológicas.");
INSERT INTO keywords (name, description) VALUES ("Analgesia", "Alivio del dolor.");
INSERT INTO keywords (name, description) VALUES ("Análisis con intención para tratar", "Término de investigación que se utiliza para designar un método de análisis de datos en el que los cálculos primarios de los datos
resultantes son por el tratamiento asignado, sin tener en cuenta el futuro cumplimiento del tratamiento. En un ensayo de control aleatorio
los pacientes pueden ser asignados a diferentes tratamientos al azar. Después de dicha asignación, los pacientes a los que se ha
asignado una terapia conservadora pueden decidir en cambio someterse a cirugía; a la inversa, los pacientes a los que se ha asignado
tratamiento quirúrgico pueden decidir no someterse a éste. En un análisis con intención para tratar, los pacientes serían analizados de
acuerdo con los grupos a los que se les asignó originalmente.");
INSERT INTO keywords (name, description) VALUES ("Análisis de la duración de un estiramiento", "Término electroterápico. Se trata de un método rápido (conjuntamente con la valoración clínica de los déficits sensitivos y motores y de
los cambios funcionales) para obtener información acerca de un nervio periférico dañado. Se utiliza para establecer la integridad y la
valoración seriada (7-14 días después), puede indicar la dirección del cambio. Ha sido en gran parte sustituido por una valoración
electrofisiológica más moderna, que es más precisa y capaz de proporcionar diagnósticos diferenciales más fiables. Equipo necesario:
impulsos monofásicos, frecuencia de 1 Hz, rango de 6-8 impulsos de entre 10 μs y aproximadamente 300 ms de duración.
Véase Cronaxia y Reobase.");
INSERT INTO keywords (name, description) VALUES ("Análisis del movimiento normal", "El movimiento normal es una facultad aprendida a través de la experiencia y la práctica, basada en una actividad que parte de la
integración de las habilidades sensoriomotoras para la ejecución de funciones eficaces. El análisis del movimiento normal está basado en
un conocimiento profundo de cómo se mueven las personas y permite así reconocer las desviaciones de la norma. Es importante tener
presente que existe una amplia variación en el rango del movimiento entre las personas, de modo que la «normalidad» puede ser
diferente en cada individuo.");
INSERT INTO keywords (name, description) VALUES ("Análisis multivariable", "Término de investigación que se aplica a los análisis en los que se consideran los efectos de diversas variables.");
INSERT INTO keywords (name, description) VALUES ("Análisis post-hoc", "Término de investigación que se aplica al análisis que se realiza después de que los resultados estén disponibles pero que no fueron
definidos antes del inicio de la prueba. La desventaja de estos análisis es que son particularmente propensos a dar falsos positivos o
errores de tipo I.");
INSERT INTO keywords (name, description) VALUES ("Análisis temático", "Término de investigación que se aplica, en la investigación cualitativa, a los intentos del investigador para clasificar y analizar los temasobtenidos a partir de entrevistas.");
INSERT INTO keywords (name, description) VALUES ("Andador de tipo Zimmer", "Instrumento dotado de cuatro puntos de apoyo que puede utilizarse para la asistencia de pacientes que todavía requieren un apoyo
extra durante el proceso de recuperación.
Observación clínica Si bien el andador favorece la independencia del paciente, debe tenerse cuidado de regularlo a la altura
adecuada para reducir una flexión excesiva que comportaría un problema de equilibrio. En algunos casos los puntos de apoyo anterior
pueden equiparse con ruedecillas a fin de favorecer un patrón de marcha más fluido. Al igual que todos los aparatos de asistencia a la
deambulación, el andador de tipo Zimmer requiere un cierto grado de fuerza en las extremidades superiores, factor que debe tenerse
presente al decidir si es apropiado para un paciente determinado.");
INSERT INTO keywords (name, description) VALUES ("Andador Rollator", "Se diferencia de un andador convencional en que tiene ruedas delante, lo que permite empujarlo en vez de levantarlo.
Observación clínica Este tipo de andador es a veces preferible ya que permite un patrón recíproco más normal en la marcha y una
mayor velocidad.");
INSERT INTO keywords (name, description) VALUES ("Anemia", "Defecto de eritrocitos en el torrente sanguíneo. Hay diversos tipos de anemia:
• Anemia aplásica. Resultado de la insuficiencia de la médula ósea.
• Anemia hemolítica. Resultado de la destrucción de los eritrocitos.
• Anemia hipoplásica. Resultado del funcionamiento inadecuado de la médula ósea.
• Anemia ferropénica. Tipo de anemia debida a una falta de hierro en la dieta o a una pérdida del mismo como resultado de una
hemorragia crónica.
• Anemia macrocítica. Cuando el tamaño medio de los eritrocitos es mayor de lo normal.
• Anemia microcítica. Cuando el tamaño medio de los eritrocitos es menor de lo normal.
• Anemia refractaria. Cualquier alteración anémica que no es tratada exitosamente por otro medio que no sea la transfusión sanguínea.");
INSERT INTO keywords (name, description) VALUES ("Anemia aplásica", "Tipo de anemia donde la médula ósea no consigue proporcionar un número suficiente de elementos sanguíneos periféricos.");
INSERT INTO keywords (name, description) VALUES ("Anemia drepanocítica", "Enfermedad hereditaria en la que los glóbulos rojos, normalmente con forma de disco, pasan a tener forma de medialuna. Como
resultado, funcionan de manera anormal y dan lugar a la formación de pequeños coágulos sanguíneos. Estos coágulos hacen que se
produzcan episodios dolorosos recidivantes denominados «crisis de dolor drepanocítico».");
INSERT INTO keywords (name, description) VALUES ("Anestesia", "Pérdida completa de sensaciones. Puede ser inducida de forma deliberada, previamente a una operación u otro procedimiento doloroso
para permitir que pueda llevarse a cabo. También se usa para describir la pérdida de sensación que sigue, por ejemplo, a la rotura de
un nervio.");
INSERT INTO keywords (name, description) VALUES ("Anestesia epidural", "Anestesia inyectada dentro del espacio epidural que tiene el efecto de «dormir» el abdomen y las piernas.");
INSERT INTO keywords (name, description) VALUES ("Anestesia espinal", "");
INSERT INTO keywords (name, description) VALUES ("Véase también Anestesia epidural", "Forma de anestesia que se usa en operaciones llevadas a cabo por debajo del nivel del ombligo, como una sustitución total de la cadera
o rodilla. Se usa particularmente en personas que no tolerarían una anestesia general, como pacientes muy débiles o con problemas
pulmonares o cardíacos.Anestesia epidérmica y espinal");
INSERT INTO keywords (name, description) VALUES ("Aneurisma", "Bolsa formada por la dilatación o rotura de las paredes de una arteria o vena llena de sangre circulante. Hay muchas causas de
aneurisma. Los aneurismas intracraneales aparecen en aproximadamente el 1% de la población. No suelen causar síntomas, pero si se
produce su rotura pueden dar lugar a una hemorragia subaracnoidea. El tratamiento normalmente requiere neurocirugía. En algunos
casos los pacientes presentan déficits neurológicos que requieren tratamiento y supervisión.");
INSERT INTO keywords (name, description) VALUES ("Angina de pecho", "Un ataque de angina se caracteriza por dolor intenso y pesadez o tirantez detrás del esternón. También es común la irradiación del
dolor a los brazos, cuello, mandíbula, espalda o estómago. Una causa de angina puede ser la actividad física, particularmente después
de una comida copiosa. Sin embargo, las personas que lo padecen también pueden sufrir un ataque durante otras formas de estrés o en
reposo, o incluso durante el sueño.");
INSERT INTO keywords (name, description) VALUES ("Angiografía", "Radiografía de los vasos sanguíneos que se realiza después de la inyección intravascular de una sustancia radiográfica. Mediante
tomografía computarizada (TC) pueden obtenerse entonces imágenes que, aumentadas digitalmente, permitirán ver con claridad los
vasos sanguíneos. Se utilizaAngiografía cerebral en la que se observa un aneurisma pequeño
para facilitar el diagnóstico de aneurismas y malformaciones arteriovenosas, y para establecer la relación de vasos sanguíneos con
tumores. Estudios recientes han dado lugar al uso de la resonancia magnética (RM). Anteriormente este procedimiento podía tener
graves consecuencias, como muerte por espasmo arterial, pero gracias a la mejora de las técnicas y medios de contraste, es ahora un
procedimiento más seguro.");
INSERT INTO keywords (name, description) VALUES ("Ángulo del pie (también conocido como ángulo de la marcha)", "Término biomecánico que corresponde al ángulo de orientación del pie fuera de la línea de progresión durante la marcha.");
INSERT INTO keywords (name, description) VALUES ("Ángulo Q", "Dirección de la fuerza del cuádriceps medida por una línea que parte de la espina ilíaca anterosuperior (EIAS), atraviesa el centro de la
rótula e intersecta la línea de la tuberosidad tibial. El ángulo medio para las mujeres es 15,8° ± 4,5° y para los hombres 11,2° ± 3,0°.
Se cree que los ángulos Q anormales predisponen al dolor anterior de la rodilla y otros síndromes.Ángulo Q");
INSERT INTO keywords (name, description) VALUES ("Anillo fibroso", "Porción externa del disco intervertebral, que está formado por fibras de colágeno dispuestas en láminas o sábanas, cada una con una
orientación ligeramente diferente. El aspecto posterior del anillo fibroso es más fino que el del resto del anillo y, por lo tanto, más
propenso a la rotura.
El anillo y el núcleo interaccionan entre sí proporcionando un complejo hidrodinámico, elástico y resistente.");
INSERT INTO keywords (name, description) VALUES ("Núcleo pulposo", "• Colágeno tipo II.
• Hidrófilo (absorbe fácilmente el agua).
• Se mantiene fijado por el anillo.
• Sin terminaciones nerviosas.");
INSERT INTO keywords (name, description) VALUES ("Anillo fibroso", "• Disposición entrecruzada de las láminas.
• Cada capa presenta una ligera diferencia en la orientación de las fibras; esto hace que el disco sea resistente a movimientos de torsión.
• El anillo permite una pequeña cantidad de abombamiento del disco.
• El colágeno tipo I (típico del tendón) proporciona capacidad de tensado al disco.
• El colágeno tipo II (típico del cartílago) proporciona capacidad de compresión al disco.
• Terminaciones nerviosas en la porción externa.Interacción entre anillo y núcleo
ANMPA (ayuda neumática para la movilidad de personas con un miembro amputado)
Aparato utilizado en la rehabilitación de personas a las que se ha amputado un miembro.");
INSERT INTO keywords (name, description) VALUES ("Ánodo", "Término electroterápico que designa un conductor con carga positiva que atrae átomos o grupos de átomos cargados negativamente
(aniones). Normalmente tiene un cable de color rojo y es utilizado como el electrodo indiferente para la estimulación motora con
impulso monofásico o desequilibrado. Bloqueo anódico: si se usa distalmente, el ánodo puede bloquear un potencial de acción a
medida que se recorre en sentido descendente el axón (es decir, los iones cargados positivamente del ánodo pueden ser suficientes
para bloquear los cambios iónicos que componen el potencial de acción, creando una hiperpolarización local).");
INSERT INTO keywords (name, description) VALUES ("Anoxia", "Falta de oxígeno. Los pacientes presentan daño cerebral anóxico cuando su cerebro ha sido privado de oxígeno durante el suficiente
período de tiempo como para causar el daño cerebral. Algunos ejemplos de cómo puede producirse son la lesión cerebral por una
ventilación no mantenida, la estrangulación parcial o la intoxicación por monóxido de carbono en casos de intento de suicidio.");
INSERT INTO keywords (name, description) VALUES ("Anquilosado", "Rígido: limitado por adherencias o fusionado.");
INSERT INTO keywords (name, description) VALUES ("Anquilosis", "Fusión fibrosa u ósea de una articulación.");
INSERT INTO keywords (name, description) VALUES ("Ansiedad", "Estado de malestar o aprensión. La causa de la ansiedad (p. ej., perspectivas futuras o incapacidad para controlar una situación) es a
menudo inespecífica.
Véase Estrés.");
INSERT INTO keywords (name, description) VALUES ("Antagonistas de los canales del calcio", "Tipo de medicamentos que actúan como inhibidores selectivos del flujo de iones calcio a través de las membranas celulares; se utilizan
principalmente en el tratamiento de ciertas patologías cardíacas y de los accidentes cerebrovasculares.");
INSERT INTO keywords (name, description) VALUES ("Antalgia", "Evitación del dolor. Por ejemplo, un paso antálgico durante la marcha es el paso adoptado por la persona en el intento de evitar o
reducir en lo posible el dolor al andar.
Observación clínica Una postura antálgica es a menudo adoptada por alguien con dolor agudo de espalda o de cuello en el intento
de encontrar la posición menos dolorosa.");
INSERT INTO keywords (name, description) VALUES ("Anterior", "Término anatómico que significa cerca de la parte de delante del cuerpo.Antibiótico
Sustancia que mata o inhibe el crecimiento de las bacterias.");
INSERT INTO keywords (name, description) VALUES ("Anticoagulante", "Sustancia que invierte la tendencia de la sangre a coagularse; entre los ejemplos se incluyen la heparina y la warfarina.
Observación clínica La terapia anticoagulante tiene efectos sistémicos, por lo que los fisioterapeutas deben saber si una persona está
siendo sometida a terapia anticoagulante; por ejemplo, la manipulación puede estar contraindicada.");
INSERT INTO keywords (name, description) VALUES ("Anticolinérgico", "Relacionado con el bloqueo de los receptores de acetilcolina para inhibir la actividad nerviosa parasimpática. Los fármacos
anticolinérgicos, por tanto, reducen el espasmo de la musculatura lisa y más notablemente de vejiga, bronquios (causando
broncodilatación) e intestinos. También disminuyen las secreciones gástricas, bronquiales y salivales. Algunos de estos fármacos son
usados en el tratamiento de alteraciones como la enfermedad del Parkinson y la distonía.");
INSERT INTO keywords (name, description) VALUES ("Anticuerpo antinuclear (ANA)", "Se encuentra en personas cuyo sistema inmunoló-gico es propenso a producir una inflamación contra los tejidos de su propio cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Antígeno", "Cualquier sustancia que estimula el sistema inmunológico para producir anticuerpos. Los antígenos son comúnmente sustancias extrañas
u objetos, como las bacterias o virus, que invaden el cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Antiinflamatorio", "Hay una amplia selección de fármacos con un efecto antiinflamatorio; la mayoría actúan bloqueando la conversión de ácido
araquidónico en prostanoides. El tipo más común de antiinflamatorio son los antiinflamatorios no esteroideos (AINE) como el
ibuprofeno, la naprosina y el voltarol. Tienen a menudo efectos secundarios, incluyendo el daño al revestimiento de la mucosa gástrica.");
INSERT INTO keywords (name, description) VALUES ("Antiinflamatorios no esteroideos (AINE)", "Fármacos que producen efectos antipiréticos, analgésicos y, de manera más importante, antiinflamatorios. Actúan modificando el
proceso químico complejo que media en la inflamación en las insuficiencias musculoesqueléticas. Muchos tienen efectos secundarios,
especialmente sobre la mucosa gástrica.
Observación clínica En la actualidad hay gran número de AINE en el mercado fácilmente disponibles.");
INSERT INTO keywords (name, description) VALUES ("Antropométrico", "Relacionado con la medida del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Años de vida de calidad ajustada (AVCA)", "Medida empleada para priorizar el tratamiento médico. Intenta proporcionar una estimación objetiva de los costes y beneficios de la
intervención médica. La medida básica es un año de vida sana como un resultado de tratamiento médico multiplicado por la valoración
de la calidad de vida en una escala de 0 a 1. Los costes por AVCA pueden calcularse, de manera que se dará prioridad a los
tratamientos de costes más bajos. Existen muchos problemas éticos con esta medida ya que puede discriminar a personas que necesitan
un tratamiento caro y puede juzgar mal la posible calidad de vida de personas enfermas o minusválidas.
A coninuación se citan palabras textuales de algunas personas con discapacidad:
«Ser discapacitado no es un fin sino un comienzo, un camino hacia delante». (Barlow JH, Williams B, «I
now feel that I'm not just a bit of left luggage»: the experiences of older women with arthritis attending a
personal independence course. Disability and Society 1999, 14: 1, 53-64.)
«Nunca seré capaz de cumplir los requisitos de la sociedad y me alegro porque estoy feliz de librarme de
todo ese rollo. ¡A la liberación por la desfiguración!» (Shakespeare T, Gillespie-Sells K, Davies D. The
sexual politics of disability, Cassell, Londres, 1996.)
«No puedo desear no haber contraído síndrome de fatiga crónica porque me ha convertido en una persona
nueva, una persona que me alegro de ser, una persona que no me perdería por nada del mundo y que nopodría abandonar aunque me curase». (Wendell S. The rejected body: feminist philosophical perspectives
on disability. Routledge, Londres, 1996.)");
INSERT INTO keywords (name, description) VALUES ("Años de vida ganados", "Promedio de años de vida ganados por una persona como resultado de una intervención.");
INSERT INTO keywords (name, description) VALUES ("Aorta abdominal", "Porción de la aorta situada debajo del diafragma que se divide en las arterias ilíacas comunes derecha e izquierda.");
INSERT INTO keywords (name, description) VALUES ("AP", "Abreviatura médica común que significa anteroposterior.");
INSERT INTO keywords (name, description) VALUES ("Apelación", "Proceso por el que un alumno puede apelar contra una decisión académica exponiendo circunstancias o razones (mitigantes) que
justifiquen su bajo rendimiento. Los alumnos no pueden desafiar el juicio académico del profesorado.");
INSERT INTO keywords (name, description) VALUES ("Apical", "Perteneciente al ápex; por ejemplo, fibrosis apical en el pulmón.");
INSERT INTO keywords (name, description) VALUES ("Aplasia", "Ausencia de desarrollo de un órgano o tejido; lo contrario de hiperplasia.");
INSERT INTO keywords (name, description) VALUES ("Apnea", "Cese de la respiración.
Observación clínica Las alarmas de apnea se pueden presentar en la práctica clínica, especialmente en las unidades pediátricas.");
INSERT INTO keywords (name, description) VALUES ("Apnea del sueño", "Cese de la respiración durante el sueño.");
INSERT INTO keywords (name, description) VALUES ("Apófisis odontoides", "Apófisis que se proyecta hacia arriba desde el cuerpo del axis (C2); el atlas (C1) rota alrededor de la odontoides. Es similar a una
clavija situada en la parte superior de la superficie el axis, que se articula con el atlas.Apoplejía
Déficit neurológico repentino que dura más de 24 h y tiene un origen vascular. El daño cerebral está causado por una interrupción del
aporte sanguíneo, normalmente por un infarto (85%) y menos a menudo debido a hemorragias (15%). Ambos procesos pueden dañar
el tejido cerebral. Es la causa principal de discapacidad en el mundo.");
INSERT INTO keywords (name, description) VALUES ("Apoyo", "Adopta una variedad de formas cuyo objetivo fundamental es asegurar la representación efectiva de las opiniones de un cliente,
paciente o usuario del servicio. Puede producirse a través de la participación de la misma persona a quien se dirige (autoapoyo) o de un
abogado que represente y proteja los intereses de un individuo. Los abogados pueden ser profesionales (pagados) o voluntarios.
Ver Autoapoyo.");
INSERT INTO keywords (name, description) VALUES ("Apraxia", "Incapacidad para llevar a cabo movimientos familiares (actividad gestual normal en función de un resultado o intención) en ausencia de
alteración motora o sensitiva. Posiblemente está causada por una desconexión entre el área del cerebro que formula la idea del
movimiento y el área que se supone que tiene que recibirla (Stokes, 1998).");
INSERT INTO keywords (name, description) VALUES ("Aprendizaje", "Adquisición de conocimientos y compresión, o desarrollo de habilidades o conducta.");
INSERT INTO keywords (name, description) VALUES ("Aprendizaje basado en los problemas", "Sistema que promueve el aprendizaje mediante el uso de problemas encontrados en la práctica clínica como un medio de proporcionar
un contexto y motivación.");
INSERT INTO keywords (name, description) VALUES ("Aproximación a la ciencia del movimiento", "También se conoce como aproximación de reaprendizaje motor y fue originariamente desarrollado por Janet Carr y Roberta Shepherd
a comienzos de la década de 1980 ( Carr y Shepherd, 1998 ). Está basado en el modelo de aprendizaje motor y se usa para la
rehabilitación de pacientes tras una apoplejía.Aproximación al movimiento normal
Este término relaciona la adopción del análisis del movimiento normal como base para reconocer desviaciones de la norma, y a partir
de ahí formular un plan para una intervención terapéutica. Este término se asocia a veces con el concepto Bobath.");
INSERT INTO keywords (name, description) VALUES ("Aproximación de Johnstone", "Aproximación terapéutica desarrollada por Johnstone para pacientes con ictus. Se basa en el uso de secuencias del desarrollo de
movimiento y en la estimulación sensitiva mediante el uso de tablillas de presión. Estas tablillas de presión se utilizan para activar la
capacidad de soportar el peso en patrones que inhiben la espasticidad.");
INSERT INTO keywords (name, description) VALUES ("APTA", "Asociación Americana de Fisioterapia (American Physical Therapy Association), a la que pertenecen más de 63.000 miembros.");
INSERT INTO keywords (name, description) VALUES ("AR", "Abreviatura médica común de artritis reumatoide.");
INSERT INTO keywords (name, description) VALUES ("Aracnoides", "Membrana meníngea delicada, intermedia entre la piamadre y la duramadre en el encéfalo y la médula. La membrana aracnoidea cubre
la cara interna de la duramadre. Existe un espacio entre la membrana aracnoides y la piamadre; este espacio, que se denomina espacio
subaracnoideo, está ocupado por el líquido cerebroespinal.");
INSERT INTO keywords (name, description) VALUES ("Arco doloroso", "Término que describe el dolor en cierta parte de un movimiento; normalmente hace referencia a la abducción del hombro, cuyo dolor
típico aparece a mitad del rango, mientras que los rangos interno y externo están libres de dolor. El dolor es frecuentemente causado
por el impacto del tendón supraespinoso debajo de la apófisis del acromion (v. fig. de la pág. siguiente).");
INSERT INTO keywords (name, description) VALUES ("Arco doloroso", "");
INSERT INTO keywords (name, description) VALUES ("Arco longitudinal lateral del pie", "Formado por el calcáneo, el cuboides y dos metatarsianos laterales. Está sujeto normalmente por ligamentos, músculos intrínsecos y los
tendones de los músculos extrínsecos del pie.");
INSERT INTO keywords (name, description) VALUES ("Arco reflejo", "Compuesto por una parte aferente y otra eferente unidas por una conexión monosináptica en la médula espinal. La estimulación del
reflejo da como resultado la contracción muscular. Por ejemplo, golpear el tendón del cuá-driceps da lugar a una sacudida en la rodilla
debido a la contracción de éste.Arco reflejo");
INSERT INTO keywords (name, description) VALUES ("Área de superficie total quemada (ASTQ)", "Fórmula para estimar los resultados en personas que han sufrido quemaduras:
Por ejemplo:
Es interesante observar que si ambas piernas están quemadas, el 36% del ASTQ está afectado. Así, un paciente de 50 años con tal
extensión de quemaduras tiene 100 − (50 + 36) = 14% de probabilidad de recuperación.
Cuanto mayor sea el ASTQ peor es el pronóstico.
Ilustración de la «regla de los nueves»Un método para medir el ASTQ es la «regla de los nueve». Esta regla divide la superficie del cuerpo en 11 áreas diferentes,
constituyendo cada una de ellas el 9%. El periné cuenta como el 1% restante. La valoración del ASTQ debe ser llevada a cabo por un
doctor experimentado, ya que el porcentaje de área correcto determinará el volumen de sustitución requerido para el proceso de
resucitación.");
INSERT INTO keywords (name, description) VALUES ("Áreas protegidas del cuerpo", "Término electroterápico que se refiere al nivel de seguridad eléctrica requerida cuando los pacientes tienen contacto con el equipo
electromédico. Es menos estricto que el tipo CF, usado cuando puede ocurrir una conexión directa con el corazón.");
INSERT INTO keywords (name, description) VALUES ("Arritmia", "Cualquier variación del ritmo normal del latido cardíaco; pueden incluirse la arritmia sinusal, el bloqueo cardíaco, la fibrilación auricular y
el aleteo auricular. Las arritmias clínicamente más significativas que deben reconocerse son la TSV (taquicardia su-lustración de la
praventricular), la TV (taquicardia ventricular) y la FV (fibrilación ventricular).");
INSERT INTO keywords (name, description) VALUES ("Arteria basilar", "Arteria que irriga el puente y da origen a las arterias vertebrales.
Véase Insuficiencia vertebrobasilar.");
INSERT INTO keywords (name, description) VALUES ("Arteria cerebral media", "Es la rama mayor de la arteria carótida interna. Esta arteria es localización frecuente de oclusiones por embolia o trombosis en la
apoplejía.");
INSERT INTO keywords (name, description) VALUES ("Arteritis de células gigantes", "Alteración inflamatoria de la arteria temporal. Es una enfermedad vascular crónica grave, caracterizada por la inflamación (vasculitis) de
las paredes de los vasos sanguíneos.");
INSERT INTO keywords (name, description) VALUES ("Articulación acromioclavicular (AAC)", "Articulación entre el proceso acromial de la escápula y la terminación lateral de la clavícula.");
INSERT INTO keywords (name, description) VALUES ("Articulación apofisaria", "Véase Articulaciones cigoapofisarias.");
INSERT INTO keywords (name, description) VALUES ("Articulación bicondílea", "Articulación en la que dos superficies distintas y redondeadas de un hueso articulan con las superficies planas del hueso
correspondiente. La articulación de la rodilla es una articulación bicondílea modificada.");
INSERT INTO keywords (name, description) VALUES ("Articulación femororrotuliana", "Véase Tracción rotuliana anormal.
Articulación entre la parte posterior de la rótula y el fémur. La rótula debe moverse arriba y abajo en el canal entre los cóndilos; si no lo
hace, se dice que existe una mala tracción patelar.");
INSERT INTO keywords (name, description) VALUES ("Articulación sacroilíaca", "Articulación en parte fibrosa y en parte sinovial, formada por la carilla auricular del sacro y la cara auricular de la superficie medial del
ilion. Está formada y rodeada por fuertes estructuras ligamentosas. Su principal función es transmitir el peso corporal, pero también
desempeña un importante papel en el movimiento. Es una articulación en la que existen pequeños movimientos de rotación.
Esta articulación puede verse afectada por traumatismos, malas alineaciones biomecánicas, cambios hormonales o enfermedades
inflamatorias de la articulación, como la espondilitis anquilosante.");
INSERT INTO keywords (name, description) VALUES ("Articulación subtalar (talocalcánea)", "Formada por la articulación del talus con el calcáneo. Es una articulación compleja con un eje cilíndrico.");
INSERT INTO keywords (name, description) VALUES ("Articulación temporomandibular (ATM)", "Articulación entre el cóndilo de la mandíbula y la fosa mandibular y el hueso temporal. Hay articulaciones separadas en cada lado de lacara, pero funcionan como una unidad. Están revestidas por cartílago fibroso y no cartílago hialino. Contienen meniscos intraarticulares
que dividen la articulación en dos cavidades sinoviales separadas.");
INSERT INTO keywords (name, description) VALUES ("Articulaciones cigapofisarias (facetas articulares)", "Están constituidas por los pares de articulaciones entre las apófisis articulares superiores de las vértebras inferiores y las apófisis
articulares inferiores de las vértebras superiores. Se trata de articulaciones sinoviales planas que pueden verse afectadas por cambios
degenerativos en casos de espondilosis. Su orientación permite o limita el movimiento de la columna vertebral (p. ej., permiten un grado
considerable de rotación en la columna dorsal, pero la bloquean en la columna lumbar).
Faceta articular: rotación permitida. Faceta articular: rotación bloqueada.");
INSERT INTO keywords (name, description) VALUES ("Articular", "Perteneciente a una articulación.");
INSERT INTO keywords (name, description) VALUES ("Artritis", "Término general para describir la inflamación dentro de una articulación.");
INSERT INTO keywords (name, description) VALUES ("Artritis reumatoide (AR)", "Enfermedad inflamatoria que afecta a las articulaciones sinoviales y los tejidos conectivos. Frecuentemente se observa en la columna
cervical superior, con laxitud del ligamento transverso del diente, lo que lleva a una subluxación de la articulación atlantoaxial. Se
observan muchas deformidades características en las personas con artritis reumatoide (AR). En la actualidad, las terapias biológicas
están revolucionando el tratamiento de la AR.");
INSERT INTO keywords (name, description) VALUES ("Artrodesis", "Operación quirúrgica para producir fusión ósea a través de una articulación. Ocasionalmente se prefiere a la sustitución de una
articulación (artroplastia); comúnmente se realiza para corregir deformidades, como los dedos en martillo o para realizar el seguimiento
de ciertas fracturas complejas.");
INSERT INTO keywords (name, description) VALUES ("Artroplastia", "Cualquier operación para formar una nueva articulación:
• Artroplastia de escisión. Eliminación de una articulación para permitir una unión fibrosa en su lugar.
• Artroplastia de baja fricción. Sustitución de la cadera.");
INSERT INTO keywords (name, description) VALUES ("Artroplastia de Keller (artroplastia de escisión de Keller)", "La artroplastia de escisión de Keller se lleva a cabo para corregir un hallux valgus muy pronunciado.
Implica la escisión del juanete del primer metatarsiano y la escisión de la parte proximal de la primera falange. Después de esta
operación, el dedo gordo queda más corto y flácido de lo normal.Artroplastia de Keller");
INSERT INTO keywords (name, description) VALUES ("Artroscopia", "Examen directo del interior de una articulación por medio de un instrumento especial denominado artroscopio (sonda o cámara). Este
procedimiento es mínimamente invasivo y permite al cirujano valorar, examinar, diagnosticar, reparar o reconstruir tejidos tanto dentro
como fuera de la articulación. Produce un menor traumatismo que las técnicas quirúrgicas abiertas, por lo que facilita la rehabilitación.");
INSERT INTO keywords (name, description) VALUES ("Asbestosis", "Esta enfermedad respiratoria es parte del grupo de enfermedades que encontramos en el inters-Artroplastia de Keller ticio del pulmón,
siendo una de las tres más comunes (las otras son la silicosis y la neumoconiosis). Los pacientes con asbestosis informarán de una
exposición al asbesto (que puede darse muchos años antes de la presentación) y demostrarán la cicatrización del parénquima con varios
síntomas, incluyendo disnea de esfuerzo, crepitaciones en la auscultación con valores espirométricos reducidos de naturaleza restrictiva,
capacidad de difusión de gas reducida y cambios radiológicos de infiltraciones reticulonodulares que afectan a ambas bases del pulmón,
derrame pleural o placas pleurales.");
INSERT INTO keywords (name, description) VALUES ("Ascitis", "Colección de un exceso de fluido en el espacio entre la membrana que limita el abdomen y los órganos abdominales, conocido como
cavidad peritoneal.");
INSERT INTO keywords (name, description) VALUES ("Asesor académico", "Profesional contratado por la universidad, que tiene las aptitudes necesarias para ayudar a los estudiantes con problemas personales o
necesidades de estudio que requieren estrategias especiales de aprendizaje.");
INSERT INTO keywords (name, description) VALUES ("Asesoramiento", "En un sentido informal, el asesoramiento es una relación y comunicación que ayuda a las personas a explorarse y entenderse a sí mismas
y a sus circunstancias personales, y les autoriza para determinar sus metas y resolver sus problemas personales. En un sentido formal, el
asesoramiento es la aplicación de teorías psicológicas y habilidades de comunicación por asesores profesionales que ayudan a los
clientes a resolver sus problemas personales, preocupaciones o deseos conflictivos.");
INSERT INTO keywords (name, description) VALUES ("Asignación del tratamiento", "Asignar un participante a una rama particular del ensayo.");
INSERT INTO keywords (name, description) VALUES ("Asintomático", "Ausencia de síntomas.
Observación clínica Por ejemplo, un cuerpo libre en la articulación de la rodilla puede ser asintomático hasta que se mueve y causa
el bloqueo de la articulación.
Asistencia integradaEs aquella en la que un equipo se reúne y decide cómo se debería cuidar a un paciente, qué debería pasar, cuándo y por quién. Los
mejores caminos de asistencia integran a todos los profesionales de la salud que van a intervenir para maximizar su efectividad, y están
basados en la evidencia y en directrices nacionales, pero aplicándolas dentro de los recursos locales y del contexto. La asistencia
integrada se introdujo inicialmente para pacientes quirúrgicos, pero ahora su uso está ampliamente extendido. Los estándares en los
caminos de asistencia deberían ser monitorizados y auditados como parte de un compromiso de evaluación de la asistencia clínica en
curso. Esto se lleva a cabo frecuentemente usando un documento en el que todo el personal de la salud informa de su tratamiento.");
INSERT INTO keywords (name, description) VALUES ("Asistencia intermedia", "Se refiere al tipo de asistencia que puede darse a los pacientes después de haber salido de un hospital de casos agudos, e incluye
hospitales de día, tutelas de asistencia intermedia y asistencia basada en la comunidad, aunque su definición se interpreta a menudo
localmente. Se suele dar a pacientes que son incapaces de volver a casa inmediatamente y que requieren algún tipo de rehabilitación.
Normalmente su duración es limitada (6 semanas). Su objetivo es salvar la brecha existente entre la asistencia médica aguda y la
independencia en la comunidad.");
INSERT INTO keywords (name, description) VALUES ("Asistolia", "Paro cardíaco o ausencia de latido.");
INSERT INTO keywords (name, description) VALUES ("Asma", "Síndrome clínico caracterizado por ataques episódicos de tos, sibilancias, constricción pectoral y disnea debido al estrechamiento de las
vías aéreas intrapulmonares. Estos síntomas son normalmente variables, pero los síntomas nocturnos son característicos del asma. El
comienzo de la enfermedad es más común en la infancia, pero el asma puede darse a cualquier edad. La gravedad del estrechamiento
varía en cortos períodos de tiempo y es reversible tanto espontáneamente como por resultado del tratamiento. Existen varios factores
desencadenantes, como el ejercicio, los ácaros del polvo, el polen y los animales.
El proceso patológico sostenido es debido a la inflamación de las vías aéreas (en gran parte de naturaleza eosinofílica) que provoca
edema mucoso y un incremento de la secreción mucosa. El tratamiento de esta alteración se realiza con un amplio plan de
bronquiodilatadores y agentes antiinflamatorios, junto con educación y guía del paciente con autotratamiento ( BTS Asthma Guidelines,
2003).");
INSERT INTO keywords (name, description) VALUES ("Aspergilosis", "Infección fúngica (Aspergillus). Esta infección puede afectar a pulmones, conducto auditivo, piel o membranas mucosas del ojo, nariz o
uretra. Se encuentra especialmente en personas que están inmunocomprometidas.");
INSERT INTO keywords (name, description) VALUES ("Aspiración", "Utilización de una aguja estéril y una jeringuilla para drenar fluidos. El término también significa inhalación accidental de una sustancia
dentro de los pulmones, como por ejemplo, aspiración del vómito, que causa neumonía por aspiración. Normalmente, la aspiración
afecta al pulmón derecho, debido a sus rasgos anatómicos, puesto que el bronquio principal derecho abandona la tráquea en un ángulo
más recto que el bronquio principal izquierdo.");
INSERT INTO keywords (name, description) VALUES ("Aspiración con aguja fina", "Procedimiento para obtener una muestra de células o fluido de los tejidos utilizando una aguja con una jeringuilla.");
INSERT INTO keywords (name, description) VALUES ("Aspirina", "Analgésico (alivia el dolor), antipirético (combate la fiebre) y antiinflamatorio que también ejerce un efecto anticoagulante.");
INSERT INTO keywords (name, description) VALUES ("Association of chartered physiotherapists in respiratory care (ACPRC)", "Ir a http://www.csp.org.uk/membergroups/clinicalinterestgroups/microsites/apcp.cfm Véase Grupos de interés clínico.");
INSERT INTO keywords (name, description) VALUES ("Association of physiotherapists interested in neurology (ACPIN)", "Se trata de un grupo de fisioterapeutas de interés especial. Tienen grupos regionales que mantienen reuniones regulares a las que,
miembros y no miembros, pueden asistir.
Ir a http://www.acpin.net
AstrocitomaTumor maligno intrínseco de los astrocitos del cerebro que puede ocurrir en cualquier grupo de edad, a pesar de que es más común
entre los 40 y 60 años. Están graduados del 1 al 4 dependiendo de la malignidad. Las opciones de tratamiento incluyen neurocirugía,
quimioterapia y radioterapia, con un continuo tratamiento de los déficits neurológicos por el equipo multidisciplinario. Los astrocitomas
crecen más lentamente que otros tumores malignos como los glioblastomas.");
INSERT INTO keywords (name, description) VALUES ("Ataque cardíaco", "Véase Infarto de miocardio (IM).");
INSERT INTO keywords (name, description) VALUES ("Ataxia", "Insuficiencia de la coordinación muscular. Sus variedades incluyen ataxia sensorial, laberíntica y cerebelosa:
• La ataxia sensorial es causada cuando hay una pérdida de sensación de los nervios periféricos, ocasionando una marcha con pasos de
base amplia y una compensación a través de la información visual (Edwards, 2002).
• La ataxia vestibular puede ocurrir tanto con alteraciones periféricas como centrales y puede incluir vértigos y problemas visuales.
• La ataxia cerebelosa resulta de las alteraciones del cerebelo.
• Las alteraciones en las que se suele presentar la ataxia son: esclerosis múltiple, ataxia de Friedrich, abuso de alcohol y lesión de la fosa
posterior.");
INSERT INTO keywords (name, description) VALUES ("Ataxia de Friedrich", "Forma hereditaria de ataxia.");
INSERT INTO keywords (name, description) VALUES ("Ataxia sensorial", "Véase Ataxia.
Resulta de lesiones que afectan a los nervios sensoriales periféricos; se trata de alteraciones que afectan a la columna dorsal, como
tabes dorsalis, o lesiones que afectan a la corteza sensorial primaria.
Observación clínica Los pacientes suelen presentar un patrón de marcha basado en la elevación del paso.");
INSERT INTO keywords (name, description) VALUES ("Ataxia troncal", "Movimiento incoordinado del tronco.");
INSERT INTO keywords (name, description) VALUES ("Ataxia vestibular", "Alteración del sistema nervioso que puede deberse a problemas vestibulares periféricos o centrales que afectan al núcleo vestibular y/o
a sus conexiones aferentes o eferentes a través del VIII nervio craneal. Las lesiones periféricas pueden ser tanto bilaterales como
unilaterales (más frecuentes).
Véase Neuroma acústico.
Observación clínica Los pacientes con ataxia vestibular pueden mostrar malas reacciones de equilibrio, una marcha de base amplia,
y lesiones unilaterales hacia el lado de la lesión, con tendencia a la inclinación posterior en caso de personas con lesión bilateral. Los
pacientes también tienden a confiar demasiado en la información visual y por ello pueden experimentar problemas al moverse en lugares
oscuros.");
INSERT INTO keywords (name, description) VALUES ("Atelectasia", "Colapso de los conductos aéreos debido a hipoventilación. Pueden darse diferentes grados de atelectasia, desde aquella que es
indetectable clínicamente, a atelectasia laminar o lobular. Pueden verse opacidades blancas en la radiografía de tórax, mientras en un
colapso total se ve el pulmón totalmente blanco.");
INSERT INTO keywords (name, description) VALUES ("Atención", "Capacidad para concentrarse; una capacidad cognitiva esencial para todas las actividades. Los pacientes que tienen déficit de atención
es probable que experimenten dificultades para aprender a tratar su discapacidad y correrán mayor riesgo de lesión.");
INSERT INTO keywords (name, description) VALUES ("Atención primaria", "Cuidado de primera línea para personas con necesidades de asistencia social o médica. Entre los trabajadores de atención primaria se
incluyen médicos de cabecera, fisioterapeutas, trabajadores sociales, ópticos, dentistas y farmacéuticos.Ateroma o aterosclerosis
Término utilizado para describir depósitos de placas en las paredes arteriales; está caracterizado por una degeneración grasa y un
engrosamiento de la capa interna de las arterias.
Observación clínica Los no especialistas se refieren a este concepto como endurecimiento de las arterias.");
INSERT INTO keywords (name, description) VALUES ("Atetosis", "Término utilizado para describir movimientos aleatorios e incontrolables de circunducción que se transmiten de un área del cuerpo a
otra. Se ve en algunos niños con parálisis cerebral, aunque también puede estar presente en otras alteraciones. El término corea es
utilizado a menudo para describir un patrón de movimiento similar en los adultos.");
INSERT INTO keywords (name, description) VALUES ("Atopia", "Reacción alérgica inmediata y hereditaria como el asma o la dermatitis.");
INSERT INTO keywords (name, description) VALUES ("Atornillado dinámico de la cadera (ADC)", "Procedimiento ortopédico que se lleva a cabo en las fracturas de cuello femoral. Consiste en colocar una placa en la epífisis femoral y
un tornillo que perfore la cabeza femoral para que, cuando la persona se levante para moverse, exista un cierto movimiento entre los
componentes de metal, y se genere una fuerza de compresión (y estimulación de la consolidación ósea) en el lugar de la fractura.");
INSERT INTO keywords (name, description) VALUES ("Atornillado dinámico de la cadera", "");
INSERT INTO keywords (name, description) VALUES ("Atrapamiento del supraespinoso", "Situación que puede darse cuando el espacio subacromial está disminuido; se caracteriza por dolor a la abducción del hombro y test de
atrapamiento positivos. La persona normalmente tratará de evitar el atrapamiento, intentando realizar el movimiento necesario de otro
modo.");
INSERT INTO keywords (name, description) VALUES ("Atresia biliar", "Alteración poco frecuente causada por el desarrollo anormal de los conductos biliares.");
INSERT INTO keywords (name, description) VALUES ("Atrofia", "Disminución de tamaño, normalmente tras un período de desuso, enfermedad o inmovilidad. Lo contrario de hipertrofia.
Observación clínica La atrofia muscular suele ser detectada por los fisioterapeutas en su práctica clínica. Puede desarrollarse con
rapidez, pero no debe olvidarse que la función es más importante que la apariencia externa del músculo.");
INSERT INTO keywords (name, description) VALUES ("Atrofia de sistemas múltiples", "En esta patología, a menudo confundida con la enfermedad de Parkinson, se caracteriza por pérdida celular o gliosis en múltiples
localizaciones. Los pacientes con esta patología, a pesar de la rigidez y la escasez de movimientos, no responden a la levodopa,
mientras que los pacientes con Parkinson mejoran con este fármaco. Normalmente el inicio de la enfermedad se sitúa alrededor de los
50-60 años de edad, y la muerte se produce en el plazo de los 6 años siguientes.Atrofia de Sudeck
Alteración que cursa con dolor espontáneo. La fisiopatología subyacente es aún desconocida. Se caracteriza por dolor intenso,
inflamación, discapacidad e hiperalgesia (excesiva sensibilidad) que no está limitada a un solo territorio nervioso y no guarda relación
con el hecho que la ha causado. Probablemente representa una alteración neurovascular que da lugar a hiperemia y osteoporosis
intensas. Ha sido considerada parte del grupo de alteraciones de la distrofia simpática refleja.");
INSERT INTO keywords (name, description) VALUES ("Atrofias musculares", "Son las enfermedades neuromusculares más comunes en la infancia después de la distrofia muscular de Duchenne. También se
denominan atrofias musculares de la columna, un grupo de trastornos neurológicos que afectan a las células del asta anterior de la
médula espinal y que conducen a debilidad muscular.");
INSERT INTO keywords (name, description) VALUES ("Auditoría clínica", "Véase Revisión clínica.");
INSERT INTO keywords (name, description) VALUES ("Aumento de pecho", "Procedimiento quirúrgico, que a menudo implica el uso de un implante protésico, para aumentar el tamaño o para alterar la forma de la
mama. Una reconstrucción de pecho puede llevarse a cabo después de una mastectomía.");
INSERT INTO keywords (name, description) VALUES ("Auscultación", "Método de exploración que consiste en usar un fonendoscopio para escuchar los efectos de la transmisión del sonido a través del tejido
pulmonar. Estos sonidos han de ser considerados junto con otros signos y no deben ser utilizados de manera aislada para formular un
diagnóstico diferencial o absoluto. Debe tenerse en cuenta la fase de la respiración en que tiene lugar el sonido, así como la intensidad y
el tono del sonido. Los sonidos se producen debido al flujo turbulento de aire que atraviesa las vías aéreas superiores y centrales e
incluyen tonos graves y agudos.
Normalmente los pulmones ventilados filtran los sonidos agudos, pero transmiten bien los graves. Cuando se presenta una enfermedad,
estos sonidos pueden cambiar; por ejemplo, la transmisión se reduce en las áreas de efusión pleural, mientras que el tejido pulmonar
consolidado transmite los sonidos agudos. La semántica, a veces, puede ser confusa, por lo que proponemos la siguiente terminología
para describir los sonidos: respiración bronquial, sonidos de respiración vesicular, crepitantes, ronquidos y sibilancias (algunos términos
pueden haber quedado anticuados, pero todavía se utilizan).");
INSERT INTO keywords (name, description) VALUES ("Autismo", "Alteración compleja del desarrollo. Afecta al desarrollo normal de las habilidades sociales y comunicativas. El autismo engloba un
amplio espectro de comportamientos.");
INSERT INTO keywords (name, description) VALUES ("Autoapoyo", "Terapia que en la mayoría de las veces se aplica a personas con dificultades de aprendizaje. Implica a sujetos que se defienden a sí
mismos y sus derechos y se organizan para promover los intereses del grupo. Como movimiento político, es la lucha de aquellos cuyas
demandas, opiniones, elecciones y perspectivas deberían prevalecer.");
INSERT INTO keywords (name, description) VALUES ("Autoayuda", "Actividades colectivas de grupos de personas, cuyos miembros están experimentando problemas similares. Los grupos de autoayuda
pueden ser pequeños pero pueden expandirse dentro de movimientos sociales, como por ejemplo, el movimiento de personas
discapacitadas y el movimiento del orgullo gay.");
INSERT INTO keywords (name, description) VALUES ("Autoconciencia", "Capacidad reflexiva de las personas para considerarse objeto de sus propios pensamientos. Puede incluir la autoconcepción y el
autocontrol, que implican la observación y el control de la propia presentación.");
INSERT INTO keywords (name, description) VALUES ("Autoeficacia", "Confianza en que una persona puede asumir satisfactoriamente un determinado comportamiento.");
INSERT INTO keywords (name, description) VALUES ("Autoestima", "Grado en que una persona se valora a sí misma.Autoimagen
Imagen que cada uno percibe de sí mismo. La autoimagen puede discrepar de los logros conseguidos o de la visión que los demás
tienen de nosotros.");
INSERT INTO keywords (name, description) VALUES ("Autopsia", "Procedimiento quirúrgico que implica la valoración de los órganos del cuerpo para determinar la causa de muerte.");
INSERT INTO keywords (name, description) VALUES ("AVD", "Abreviatura médica común para referirse a las actividades de la vida diaria.");
INSERT INTO keywords (name, description) VALUES ("Axón", "Parte principal de una neurona a lo largo de la cual discurre el impulso nervioso.");
INSERT INTO keywords (name, description) VALUES ("Axonotmesis", "Lesión nerviosa caracterizada por un trastorno del axón y de la vaina de mielina, pero con conservación de los fragmentos de tejido
conectivo. El resultado es la degeneración del axón, distal a la lesión. Normalmente tiene lugar una regeneración espontánea
satisfactoria.");
INSERT INTO keywords (name, description) VALUES ("Azar", "Término estadístico que hace referencia al concepto de variación aleatoria. Los métodos estadísticos se utilizan para estimar la
probabilidad que el azar, por sí solo, ha justificado en la diferencia de los resultados.B
b.i.d.
Abreviatura médica común que significa »dos veces al día« (del latín bis in die). Se emplea al expresar pautas de medicación.");
INSERT INTO keywords (name, description) VALUES ("Baclofeno", "Fármaco para reducir los espasmos y la hipertonicidad. Puede ser administrado por vía oral o a nivel intratecal mediante una bomba
subcutánea. Normalmente se administra vía oral, a dosis crecientes hasta que se consigue el efecto deseado. Tiene efectos secundarios
significativos, como malestar muscular, somnolencia y fatiga. Por lo tanto, deberá ser utilizado con precaución y tras discutir las
opciones entre el paciente y el equipo multidisciplinario.");
INSERT INTO keywords (name, description) VALUES ("Bacteriemia", "Presencia de bacterias en sangre.");
INSERT INTO keywords (name, description) VALUES ("Balismo", "Alteración patológica en la que aparecen movimientos balísticos incontrolados que se asocian con una lesión subtalámica.");
INSERT INTO keywords (name, description) VALUES ("Ballismus", "Amplios movimientos anormales e involuntarios de los miembros o miembro (hemibalismo).");
INSERT INTO keywords (name, description) VALUES ("Banda A", "Banda ancha y oscura cruzada en las miofibrillas del músculo estriado donde los filamentos gruesos de miosina y filamentos finos de
actina coinciden.
Véase Estructura muscular.");
INSERT INTO keywords (name, description) VALUES ("Banda I", "Porción del filamento muscular que se extiende desde la línea z hasta las bandas a.
Véase Estructura muscular.");
INSERT INTO keywords (name, description) VALUES ("Banda iliotibial", "Banda resistente de tejido conectivo situada en la parte lateral del muslo. Ejerce acción sobre la rodilla (puede actuar como flexor a
partir de los 30° de flexión de la rodilla y como extensor por debajo de los 30° grados de flexión) y puede verse afectada por sobreuso
(síndrome de la banda iliotibial). Puede experimentarse dolor en el compartimiento lateral de la rodilla, donde la banda iliotibial pasa
sobre el cóndilo femoral. El dolor normalmente aparece al correr, y puede estar asociado con crepitaciones o chasquidos.");
INSERT INTO keywords (name, description) VALUES ("Bandera amarilla", "Véase Banderas.");
INSERT INTO keywords (name, description) VALUES ("Bandera roja", "Véase Banderas.");
INSERT INTO keywords (name, description) VALUES ("Banderas", "Hace referencia a la información obtenida durante la valoración del paciente. Los hallazgos que necesitan ser monitorizados y/o
referidos a un especialista se identifican con banderas rojas; el método de tratamiento fisioterápico específico se indica con banderas
amarillas.");
INSERT INTO keywords (name, description) VALUES ("Banderas rojas", "Son los hallazgos de ambas valoraciones, subjetiva y objetiva, que podrían indicar una patología grave, una fractura, tumor o infección y
posible síndrome de la cola de caballo.");
INSERT INTO keywords (name, description) VALUES ("Hallazgos subjetivos", "Incluirían:
• Forma de inicio. Traumatismo importante, accidente de tráfico, inicio súbito de síntomas graves como un dolor agudo que no remite o
debilidad bilateral de los miembros inferiores.• Historia sugestiva de tumor o infección. Paciente de edad superior a 50 años o menor de 20, historia de carcinoma, pérdida de peso
inexplicable, fiebre reciente, infecciones frecuentes del tracto urinario, historias de abuso de drogas o VIH.
• Posible síndrome de cola de caballo. Afección de vejiga, como retención urinaria, frecuencia aumentada o incontinencia por
desbordamiento, y disfunción intestinal como laxitud inesperada del esfínter anal, parestesia bilateral y/o debilidad del miembro inferior.");
INSERT INTO keywords (name, description) VALUES ("Hallazgos objetivos", "• Problemas de flacidez o coordinación.
• Signos neurológicos. Disminución de los reflejos activos, signo de Babinski positivo y clonus.");
INSERT INTO keywords (name, description) VALUES ("Banderas amarillas", "Incluyen:
• Factores psicológicos como actitudes desadaptativas y creencias acerca del dolor, comportamientos que incluyen actividades
reducidas, escasa actividad física, períodos de reposo prolongados, escasa satisfacción en intervenciones anteriores y evitación de la
actividad normal.
• Factores sociales como ausencia prolongada en el trabajo, abandono de aficiones/actividades sociales y excesiva dependencia de la
familia.");
INSERT INTO keywords (name, description) VALUES ("Bañera de cera", "Recipiente específicamente diseñado, controlado con termostato y utilizado para calentar clínicamente la cera terapéutica. Los
volúmenes grandes normalmente requieren que el contenedor esté dentro de una capa de agua circundante para asegurar el
calentamiento.");
INSERT INTO keywords (name, description) VALUES ("Barorreceptor", "Receptor de presión. Se localizan en corazón, vena cava, arteria aorta y seno carotídeo, y forma parte de mecanismos homeostáticos
de función cardiorrespiratoria.");
INSERT INTO keywords (name, description) VALUES ("Barotrauma", "Lesión producida por la aplicación excesiva de presión positiva. Así, se han descrito en el pulmón por la aplicación de ventilación
mecánica de presión positiva; por ejemplo, neumotórax.");
INSERT INTO keywords (name, description) VALUES ("Barrera hematoencefálica", "Barrera selectiva entre vasos sanguíneos cerebrales y el cerebro. Restringe las moléculas que pueden pasar de la sangre al encéfalo.
Ciertos compuestos y fármacos pueden cruzar esta barrera, mientras que otros no.");
INSERT INTO keywords (name, description) VALUES ("Barrido sinovial", "Término para el fenómeno por el que el cartílago articular hialino alcanza su fuente de nutrición (líquido sinovial) mediante el proceso de
movimiento articular y compresión que facilita la dispersación del líquido sinovial a través de la superficie articular.
Observación clínica Por esta razón, muchas fracturas intraarticulares se tratan actualmente con movimiento temprano o movilización
pasiva continua.");
INSERT INTO keywords (name, description) VALUES ("Basal", "Relativo a la porción baja; ejemplo, segmento basal del lóbulo superior.");
INSERT INTO keywords (name, description) VALUES ("Base de sustentación", "Área entre las partes del cuerpo y la superficie sobre la que descansan. Una amplia base de sustentación suele dar lugar a un descenso
de la actividad muscular. Por ejemplo, si una persona se tumba en una cama tiende a relajarse, ya que tiene una base de sustentación
más amplia, mientras que si descansa a la pata coja mantendrá una considerable actividad muscular para mantener el equilibrio sobre la
pequeña base de sustentación. Los pacientes con déficit neurológico pueden no presentar reacciones posturales normales para
adaptarse a la base de sustentación. Por ejemplo, un paciente con una lesión cerebral que presenta un marcado tono extensor puede
arquearse en posición supina de manera que sólo su cabeza y sus talones estén en contacto con la superficie de la cama.
BasófiloLeucocito (célula sanguínea) del grupo de los granulocitos. Constituye el 1% o menos del total de leucocitos y se caracteriza por
presentar un núcleo segmentado y grandes gránulos citoplásmicos basófilos (se tiñen de color azul cuando se exponen a un colorante
básico), que contienen histamina.");
INSERT INTO keywords (name, description) VALUES ("Batanga", "Tipo de tablilla usada normalmente después de un reemplazo articular o tendinoso en la mano o muñeca.");
INSERT INTO keywords (name, description) VALUES ("BCG", "Abreviatura médica común correspondiente al bacilo de Calmette-Gué-rin, utilizado en la inmunización contra la tuberculosis.");
INSERT INTO keywords (name, description) VALUES ("Beneficencia", "Principio ético que dicta que deberíamos procurar hacer el bien a otras personas y promover su bienestar.");
INSERT INTO keywords (name, description) VALUES ("Beneficios secundarios", "Beneficios que resultan de un tratamiento además del resultado primario previsto.");
INSERT INTO keywords (name, description) VALUES ("Benigno", "Término que tiende a ser utilizado con referencia al cáncer; significa no peligroso para la salud o no progresivo. Compárese con
maligno (caracterizado por crecimiento progresivo e incontrolado).");
INSERT INTO keywords (name, description) VALUES ("Bibliografía", "Lista de las referencias utilizadas en la elaboración de un artículo de investigación.");
INSERT INTO keywords (name, description) VALUES ("Bifásico", "Término electroterápico para referirse a un impulso con dos fases opuestamente cargadas.
Véase Fase, Corrientes continua y alterna.
Las dos fases pueden ser equilibradas (cargas iguales en las fases positiva y negativa) o desequilibradas (nivel de carga desigual en cada
fase). Si están equilibradas, no hay concentración iónica en el tiempo sobre la piel; si están desequilibradas, la piel será más alcalina
debajo del cátodo y más ácida debajo del ánodo. Normalmente estos cambios se manifestarán como irritación cutánea, pero en fases
iniciales aparecerá sarpullido.");
INSERT INTO keywords (name, description) VALUES ("Bifosfonatos", "Familia de fármacos específicamente para la prevención y el tratamiento de la osteoporosis. Los tres medicamentos más comúnmente
utilizados dentro de esta familia son el alendronato (Fosamax®), el risedronato (Actonel®) y el etidronato (Didronel®).");
INSERT INTO keywords (name, description) VALUES ("Bilis", "Fluido digestivo, viscoso, amarillo-verdoso, de sabor amargo, reacción alcalina y densidad variable, secretado por el hígado y
almacenado en la vesícula biliar. Ayuda a la digestión, convirtiendo las grasas en ácidos grasos, los cuales pueden ser absorbidos por el
tracto digestivo. El principal pigmento de la bilis es la bilirrubina, que se forma por degradación de la hemoglobina de los glóbulos rojos
por las células reticuloendoteliales.");
INSERT INTO keywords (name, description) VALUES ("Bilobectomía", "Extirpación quirúrgica de dos lóbulos pulmonares.");
INSERT INTO keywords (name, description) VALUES ("Biofeedback", "Uso de algún instrumento para activar procesos psicológicos que permitan al individuo un conocimiento consciente, usando señales
visuales o auditivas.");
INSERT INTO keywords (name, description) VALUES ("Biopsia", "Técnica diagnóstica que implica la extirpación quirúrgica de una pequeña porción de tejido para un examen microscópico y/o cultivo.");
INSERT INTO keywords (name, description) VALUES ("Bipedestador de Oswestry", "Se trata de una estructura originariamente diseñada para ayudar a personas con lesión espinal a mantener la posición de bipedestaciónde forma independiente. Actualmente su utilización está muy extendida en la rehabilitación neurológica, si bien, debido a las regulaciones
sobre manejo manual de los pacientes, a menos que éstos sean ayudados en la maniobra de la posición de sentado a la posición de pie,
su uso es limitado.
Observación clínica Actualmente muchos bipedestadores se fabrican a medida o se diseñan con motor para desplazar gradualmente al
paciente de la posición de sentado a la posición de pie.");
INSERT INTO keywords (name, description) VALUES ("Bipolar", "Término electroterápico que se refiere a dos electrodos de igual tamaño normalmente colocados en un músculo o grupo muscular para
proceder a su estimulación. Por ejemplo, para estimular el cuádriceps femoral: dos electrodos grandes y de igual tamaño situados en la
línea que va desde el polo superior medial de la rótula hasta la espina ilíaca anterosuperior (EIAS). El electrodo proximal se sitúa");
INSERT INTO keywords (name, description) VALUES ("aproximadamente al 30 % de la distancia a la EIAS", "");
INSERT INTO keywords (name, description) VALUES ("Electrodos bipolares", "(sobre el vasto lateral y el recto femoral), y el electrodo distal al 90% (sobre el vasto medial y el recto femoral).");
INSERT INTO keywords (name, description) VALUES ("Bisinosis", "Enfermedad pulmonar intersticial de naturaleza ocupacional (experimentada, p. ej., por aquellos que trabajan en la industria del
algodón).");
INSERT INTO keywords (name, description) VALUES ("Bloqueadores β", "Fármacos antiarrítmicos que actúan alterando las velocidades de conducción del potencial de acción cardíaco a través del músculo
cardíaco.");
INSERT INTO keywords (name, description) VALUES ("Bloqueo articular", "Alteración, normalmente causada por el atrapamiento de un cuerpo libre dentro de la articulación, como un fragmento de un menisco
roto en la rodilla. La persona generalmente describe que tiene que empujar o sacudir la articulación para desbloquearla.");
INSERT INTO keywords (name, description) VALUES ("Bloqueo auriculoventricular", "Alteración de la conducción cardíaca que conduce a la demora y bloqueo del impulso eléctrico entre aurículas y ventrículos.");
INSERT INTO keywords (name, description) VALUES ("Bloqueo con fenol", "Inyección de fenol en un nervio concreto. Se emplea a veces en el tratamiento de la espasticidad grave. El efecto es permanente y, por
lo tanto, la decisión de usar esta modalidad sólo debe adoptarse después de la evaluación por parte de un equipo multidisciplinario
especialista.
Observación clínica Si se emplea para ayudar en el control de la espasticidad del miembro inferior, el paciente debe haber perdido lafunción de la vejiga y los intestinos.");
INSERT INTO keywords (name, description) VALUES ("Bloqueo de talón", "Técnica de acerrojamiento, pensada para asegurar la estabilidad de la articulación subtalar.");
INSERT INTO keywords (name, description) VALUES ("Bocio", "Aumento de tamaño de la glándula tiroidea.");
INSERT INTO keywords (name, description) VALUES ("Bolsa sinovial", "Espacio tisular limitado por la membrana sinovial que contiene una pequeña cantidad de líquido sinovial. Facilita los movimientos sin
fricción.");
INSERT INTO keywords (name, description) VALUES ("Bomba de calcio", "Bomba iónica que mantiene una concentración más alta de iones de calcio fuera que dentro de la célula. Los canales iónicos controlan
el movimiento de los iones dentro y fuera de las células; junto con los iones de sodio y potasio, este gradiente crea una diferencia");
INSERT INTO keywords (name, description) VALUES ("de", "potencial eléctrico. Esto es importante para los fisioterapeutas ya que se ha demostrado que ciertas modalidades electroterápicas, como
la energía electromagnética pulsante (Tsong, 1989) y el ultrasonido ( Dyson, 1985), pueden alterar una diferencia de potencial anormal
en una célula o células dañadas y devolverla a la normalidad, promoviendo así la curación y el restablecimiento de la función.");
INSERT INTO keywords (name, description) VALUES ("Bomba de sodio", "Véase Bomba de calcio.");
INSERT INTO keywords (name, description) VALUES ("Bomba muscular", "Proceso a través del cual la sangre es bombeada desde una válvula a la siguiente en su camino de vuelta al corazón. Los fisioterapeutas
sue len tratar a menudo a pacientes con déficit de la bomba muscular, por ejemplo tras cirugía de reemplazamiento articular o tras
inmovilización. Esto a menudo causa edema en los tobillos.");
INSERT INTO keywords (name, description) VALUES ("Bradicardia", "Frecuencia cardíaca anormalmente lenta (< 60 lat./min).");
INSERT INTO keywords (name, description) VALUES ("Bradicinesia", "Lentitud anormal en el movimiento o al inicio del mismo que se da, por ejemplo, en la enfermedad de Parkinson.");
INSERT INTO keywords (name, description) VALUES ("Bradicinina", "Sustancia producida en el plasma a partir de cininógeno. Tiene muchas reacciones proinflamatorias y también estimula a los
nociceptores (Davies y cols., 2001).");
INSERT INTO keywords (name, description) VALUES ("Bradiglosia", "Habla anormal, lenta y pausada.");
INSERT INTO keywords (name, description) VALUES ("Bradipnea", "Frecuencia respiratoria anormalmente lenta; es decir, respiración lenta.Broncoconstricción
Estrechamiento de los bronquios debido a la contracción de la musculatura lisa. Puede ocurrir por la irritación del tracto respiratorio en
respuesta a la inhalación de sustancias nocivas (p. ej., postaspiración, tabaquismo, inhalación de humo y traumatismo). Los síntomas
incluyen silbidos y disnea.");
INSERT INTO keywords (name, description) VALUES ("Broncodilatación", "Ensanchamiento del árbol traqueobronquial debido a la relajación de la musculatura lisa que forma las paredes de las vías aéreas. Esto
puede deberse a la estimulación del sistema nervioso simpático, pero puede también ocurrir como resultado de un bloqueo
farmacológico de los receptores anticolinérgicos, que causa la relajación de la musculatura lisa.");
INSERT INTO keywords (name, description) VALUES ("Broncofonía", "Modificación de los sonidos vocales, que son intensificados y aumentados en tono; se observan en la auscultación del pecho en ciertos
casos de enfermedad intratorácica.");
INSERT INTO keywords (name, description) VALUES ("Broncoscopia", "Procedimiento mediante el cual el examinador utiliza un tubo para evaluar las vías aéreas de un paciente, incluyendo la caja de voz y las
cuerdas vocales, y la tráquea.");
INSERT INTO keywords (name, description) VALUES ("Bronquial", "Relativo a las vías aéreas.");
INSERT INTO keywords (name, description) VALUES ("Bronquiectasia", "Enfermedad pulmonar crónica y supurativa caracterizada por la dilatación anormal e irreversible de los bronquios, debido a cambios
destructivos e inflamatorios en las paredes de las vías aéreas. La característica clásica es la producción de una cantidad excesiva de
esputo purulento, tanto localizado como difuso. La bronquiectasia quística da lugar a dilataciones en forma de saco en las vías aéreas
distales, que pueden observarse fácilmente en la radiografía de tórax. El tratamiento incluye higiene bronquial y antibióticos; a veces se
requiere el cultivo de los esputos para una prescripción más apropiada.");
INSERT INTO keywords (name, description) VALUES ("Bronquio", "Primera división de los conductos aéreos. Los bronquios (izquierdo y derecho) nacen de la tráquea. El bronquio izquierdo es más largo
y más angulado que el derecho, por lo que una inhalación accidental de materiales entrará antes al pulmón derecho que por el izquierdo.
Los bronquios contienen paredes cartilaginosas que proporcionan estabilidad a las vías aéreas superiores durante la respiración. Hay
alrededor de 10 divisiones bronquiales desde la tráquea.");
INSERT INTO keywords (name, description) VALUES ("Bronquiolitis", "Inflamación y obstrucción de los bronquiolos como resultado de una infección aguda del tracto respiratorio inferior, causada por el virus
sincitial respiratorio (VSR). Es una infección respiratoria común en niños de me nos de 2 años, con síntomas que incluyen dificultadrespiratoria y silbidos.");
INSERT INTO keywords (name, description) VALUES ("Bronquiolos", "Divisiones más pequeñas de los bronquios (comienzan de 5 a 14 divisiones por debajo de los bronquios segmentales). Normalmente
tienen 2 mm o menos de diámetro, y no contienen cartílago entre las paredes muscarínicas. La contracción de la musculatura bronquial
lisa permite cambios en el diámetro de las vías aéreas, que provocan broncoconstricción (estrechamiento de las vías aéreas) y cambios
en la resistencia de éstas. Los bronquiolos respiratorios son subdivisiones más pequeñas y finalizan en los bronquiolos terminales
previos a los alvéolos. Los bronquiolos se mantienen abiertos por la tracción externa ejercida por los alvéolos adyacentes.");
INSERT INTO keywords (name, description) VALUES ("Bronquitis", "Inflamación (aguda o crónica) de la membrana mucosa del árbol traqueobronquial. Los síntomas incluyen silbidos, disnea y aumento de
la producción de moco.");
INSERT INTO keywords (name, description) VALUES ("Bronquitis crónica", "Enfermedad pulmonar caracterizada por la presencia de tos y producción de esputos cada día, durante al menos 3 meses en cada uno
de dos años consecutivos (GOLD Guidelines, 2001).");
INSERT INTO keywords (name, description) VALUES ("Bruxismo", "Rechinamiento de los dientes.");
INSERT INTO keywords (name, description) VALUES ("BSA", "Abreviatura médica común de bolsa subacromial.");
INSERT INTO keywords (name, description) VALUES ("Bulbar", "Perteneciente a o relativo a la médula oblongada (p. ej., parálisis bulbar).");
INSERT INTO keywords (name, description) VALUES ("Bullas", "Sacos aéreos de paredes finas que se desarrollan en el enfisema pulmonar.");
INSERT INTO keywords (name, description) VALUES ("Cambios enfisematosos en el pulmón", "");
INSERT INTO keywords (name, description) VALUES ("Bursitis", "Inflamación de la bolsa sinovial, normalmente causada por sobreuso, infección o traumatismo directo.");
INSERT INTO keywords (name, description) VALUES ("Bursitis de la pata de ganso", "Inflamación de la bolsa entre la inserción del ligamento colateral medial y el grupo muscular denominado »de la pata de ganso«,
formado por los músculos sartorio, grácil y semitendinoso.
Bursitis prerrotulianaLocalizada entre la faceta anterior de la rótula y la piel; es la lesión más común de la bursa en la rodilla. Cuando se inflama se conoce
como »rodilla de criada«.");
INSERT INTO keywords (name, description) VALUES ("Bursitis trocantérica", "Normalmente asociada con tendinitis del glúteo medio, se caracteriza por una inflamación de la bolsa serosa que cubre el trocánter
mayor del fémur. Es, generalmente, una lesión por sobrecarga, vista en los corredores. El dolor normalmente se reproduce con el
estiramiento (flexión de cadera de 90° con rotación externa completa) o la contracción del glúteo medio, como en la abducción de
cadera resistida.");
INSERT INTO keywords (name, description) VALUES ("Burst", "Término electroterápico que se utiliza para designar series continuas de impulsos bifásicos (trenes) seguidos de un intervalo sin impulsos
(es decir, un intervalo entre ráfagas) y a continuación más ráfagas de impulsos, dependiendo de la frecuencia de la ráfaga. La frecuencia
de ráfaga es el número de ráfagas por segundo; si la corriente rusa es de 50 ráfagas/s (es decir, cada ráfaga tiene normalmente 10 ms
de duración) seguido de un intervalo entre ráfagas de 10 ms. Las ráfagas e intervalos entre ráfagas se pueden cambiar. Por ejemplo,
reduciendo la duración de la ráfaga a 5 ms y aumentando el intervalo entre ráfagas a 15 ms, se reducirá la velocidad de fatiga de la fibra
muscular durante la estimulación motora.");
INSERT INTO keywords (name, description) VALUES ("Frecuencia de bursts", "");
INSERT INTO keywords (name, description) VALUES ("Bypass de la arteria coronaria", "Procedimiento quirúrgico utilizado para perfundir un miocardio isquémico. Las arterias mamarias internas y/o las venas safenas largas");
INSERT INTO keywords (name, description) VALUES ("son injertadas en el miocardio para circunvalar las arterias coronarias", "bloqueadas y alteradas después de un infarto de miocardio (o en pacientes que corren el riesgo de sufrirlo). Para llevar a cabo este
procedimiento, tradicionalmente se colocaba al paciente en bypass cardiopulmonar, pero los avances técnicos y quirúrgicos permiten
actualmente su realización mediante procedimientos endoscópicos en algunas unidades.C");
INSERT INTO keywords (name, description) VALUES ("Cadenas cinéticas abiertas", "Véase Ejercicios de cadena cinética.
Este término hace referencia a las cadenas de articulaciones. Por ejemplo, el hombro, el codo y la muñeca forman una cadena de tres
articulaciones en el miembro superior. En los movimientos de una cadena articular abierta, el miembro articular proximal está fijo o
estable, mientras que el miembro distal se mueve. Estirarse para alcanzar un objeto en el espacio o dar una patada a un balón son
ejemplos de movimientos de cadena abierta.");
INSERT INTO keywords (name, description) VALUES ("Cadenas cinéticas cerradas", "Véase Ejercicios de cadena cinética.");
INSERT INTO keywords (name, description) VALUES ("Cadencia", "Número de pasos en un tiempo determinado. Se suele utilizar como una medida de resultados. El test más común utilizado es el test de
10 metros de marcha.");
INSERT INTO keywords (name, description) VALUES ("Caída del pie", "Parálisis o debilidad de los músculos flexores dorsales del tobillo. Puede indicar diversas patologías, incluyendo la lesión del nervio
peroneo común como consecuencia de una fractura o una escayola demasiado ajustada alrededor del cuello del peroné, un prolapso
del disco en la columna lumbar u otras alteraciones neurológicas. El tibial anterior, en un principio, desempeña el papel de decelerar el
pie después de que el talón alcance el suelo, por lo que una persona con una caída del pie arrastrará el pie por el suelo durante la
marcha, o adoptará una marcha con pasos elevados en un intento de asegurarse que el pie no toque el suelo durante la fase de
oscilación de la marcha.");
INSERT INTO keywords (name, description) VALUES ("Calcáneo equinovaro", "Frecuente anormalidad congénita del pie. Puede darse de diferentes formas, pero el equinovaro de calcáneo es la más común. En este
caso, el pie se encuentra orientado hacia abajo y hacia dentro.");
INSERT INTO keywords (name, description) VALUES ("Calcitonina", "Hormona producida por el tiroides que causa la reducción de los iones calcio en la sangre.");
INSERT INTO keywords (name, description) VALUES ("Cálculo vesical", "Concreción compuesta generalmente por sales minerales que se encuentra en la vesícula urinaria.");
INSERT INTO keywords (name, description) VALUES ("Calentamiento", "El calentamiento se utiliza para mejorar la circulación y aumentar la temperatura del tejido corporal; por lo tanto, prepara física y
mentalmente a las personas que van a hacer ejercicio. Los ejercicios de calentamiento podrían limitar también la formación de
metabolitos y la consiguiente acidosis durante el ejercicio. La propiocepción podría ser también significativamente más sensible después
del calentamiento.");
INSERT INTO keywords (name, description) VALUES ("Calidad de vida relacionada con la salud", "Combinación del bienestar físico, mental y social de un individuo; no es simplemente la ausencia de enfermedad (NICE, 2004).");
INSERT INTO keywords (name, description) VALUES ("Calificación cruzada", "Práctica consistente en que dos personas corrijan independientemente el mismo trabajo de un estudiante, normalmente de forma
anónima, para después comparar las puntuaciones e intentar estandarizarlas.");
INSERT INTO keywords (name, description) VALUES ("Callo", "Primera deposición ósea en el proceso de consolidación de la fractura.");
INSERT INTO keywords (name, description) VALUES ("Cámara hiperbárica", "Cámara sometida a presión que permite el reparto de oxígeno en altas concentraciones para el beneficio terapéutico.Campo
Término electroterápico que se refiere a la fuerza que rodea a una partícula u objeto cargado. El tamaño, distribución y magnitud de un
campo se representan por líneas de campo alrededor de un objeto o entre objetos (p. ej., las placas de capacitación utilizadas para
SWD). El campo magnético es la fuerza que rodea a un cable que conduce una corriente eléctrica. Depende de la magnitud de la
corriente y de la distancia entre los bucles de cable adyacentes que conducen la corriente.");
INSERT INTO keywords (name, description) VALUES ("Canales de Havers", "Canales pequeños que recorren longitudinalmente los centros de los sistemas de Havers del hueso compacto.");
INSERT INTO keywords (name, description) VALUES ("Canales de Lambert", "Canales colaterales de ventilación entre los bronquiolos terminales y los alvéolos. Permanecen abiertos incluso durante la contracción de
la musculatura lisa bronquial y tienen un tamaño de alrededor de 30 μm.");
INSERT INTO keywords (name, description) VALUES ("Canales semicirculares", "Conjunto de canales que contienen endolinfa y que son parte del aparato vestibular que se encuentra dentro del oído interno. Los
diferentes movimientos de la cabeza hacen que la información se transmita al componente vestibular del VIII nervio craneal (nervio
auditivo); por lo tanto, los canales semicirculares son importantes en el mantenimiento del equilibrio.");
INSERT INTO keywords (name, description) VALUES ("Canalículos", "En el hueso, se trata de canales que recorren la matriz calcificada entre pequeños orificios
hígado, son pequeños canales a través de los cuales fluye la bilis hacia el conducto biliar.
(lacunae) que contienen osteocitos. En el");
INSERT INTO keywords (name, description) VALUES ("Candidiasis", "Infección fúngica que suele localizarse en las membranas mucosas y en la piel. Cuando está restringida a la boca, la infección se
denomina muguet. Esta infección se puede extender a nivel sistémico en un individuo inmunodeprimido.");
INSERT INTO keywords (name, description) VALUES ("Capacidad de percepción", "Este término hace referencia a la capacidad cognitiva de los pacientes para entender su situación. La capacidad de percepción puede
alterarse después de una lesión cerebral. Los pacientes con escasa percepción pueden resultar difíciles e inconformistas, ya que no
reconocen sus propios problemas.");
INSERT INTO keywords (name, description) VALUES ("Capacidad vital forzada (FVC)", "Capacidad pulmonar medida cuando el sujeto espira tan rápido como puede.");
INSERT INTO keywords (name, description) VALUES ("Capacitancia", "Término electroterápico que se refiere a la capacidad de un conductor para almacenar carga eléctrica (C); se mide en faradays. La
capacitancia aumenta de forma directamente proporcional con el tamaño del área de las placas y las propiedades dieléctricas del tejido
atravesado (p. ej., el agua, el riñón y el tejido graso son más dieléctricos que la médula ósea), mientras que la relación entre la
capacitancia y la separación entre las dos placas es inversamente proporcional.
La resistencia de la piel es una combinación de la reactancia capacitiva (principalmente proporcionada por las capas cutáneas externas,
más gruesas y secas) y la resistencia.");
INSERT INTO keywords (name, description) VALUES ("Cápsula con protección entérica", "Cápsulas con recubrimiento destinado a retrasar la liberación del fármaco hasta después de salir del estómago.");
INSERT INTO keywords (name, description) VALUES ("Cápsula interna", "Banda de fibras que recorre el espacio entre el núcleo basal y el tálamo, en el cerebro.");
INSERT INTO keywords (name, description) VALUES ("Caquexia", "Término utilizado para describir un estado de salud general enfermizo y malnutrición caracterizado por debilidad y emaciación.
Normalmente asociado con enfermedades terminales.Sustancia creada cuando el monóxido de carbono se une a la hemoglobina en la sangre. El monóxido de carbono tiene una gran
afinidad por la hemoglobina.");
INSERT INTO keywords (name, description) VALUES ("Carga", "Término electroterápico para referirse a una propiedad fundamental de la materia medida en culombios (C). Por ejemplo, un electrón
tiene carga negativa, y una partícula del cuerpo que pierde suficientes electrones (1 o más dependiendo del estado inicial) se cargará
positivamente. La corriente es el flujo de carga por unidad de tiempo:");
INSERT INTO keywords (name, description) VALUES ("donde", "");
INSERT INTO keywords (name, description) VALUES ("Carta del paciente", "Documento que fue introducido en el NHS británico en 1991 como forma de aumentar el control y la participación del paciente. Ha
sido criticado por concentrarse más en materias de procedimiento (p. ej., cómo presentar quejas) que en los derechos del paciente.");
INSERT INTO keywords (name, description) VALUES ("Cartílago articular", "Tejido blando especializado que recubre las terminaciones de los huesos y permite la distribución de cargas compresivas sobre la
sección transversal de los huesos; proporciona además una superficie casi sin fricción para el movimiento articular (v. fig. de la pág.
siguiente).");
INSERT INTO keywords (name, description) VALUES ("Catéter", "Instrumento tubular quirúrgico utilizado para inyectar fluidos en el cuerpo o para drenarlos.");
INSERT INTO keywords (name, description) VALUES ("Cátodo", "Término electroterápico que se aplica al conductor con una carga negativa que atrae átomos o grupos de átomos (cationes) cargados
positivamente. Normalmente es el cable negro (o blanco) unido al electrodo distal. Se suele usar como el electrodo estimulador para la
estimulación motora, con un impulso monofásico o desequilibrado.
Véase también Ánodo.");
INSERT INTO keywords (name, description) VALUES ("Cauda equina (cola de caballo)", "Conjunto de raíces espinales que emergen del extremo distal de la médula espinal.Causalgia
Dolor del sistema nervioso autónomo caracterizado por quemazón intensa e hiperestesia a lo largo de la distribución de un nervio
periférico incompletamente dañado.
Véase Algodistrofia.");
INSERT INTO keywords (name, description) VALUES ("Cavitación", "Término electroterápico que designa la formación de burbujas de un gas previamente absorbido en un líquido. Puede ser estable
(permanecer relativamente sin cambios) o inestable (con tendencia a formarse y romperse rápidamente dando lugar a un descenso del
calor). Puede ser producido por ultrasonidos. Improbable durante la aplicación de los ultrasonidos terapéuticos, si la salida está en el
2 . Suele describirse en las explicaciones de cómo funciona el
rango de frecuencia de 0,8 a 3 MHz y la intensidad de 0 a 3 W/cm
ultrasonido terapéutico, pero la relevancia de los resultados no está clara.");
INSERT INTO keywords (name, description) VALUES ("Célula alveolar", "Célula del alvéolo (saco de aire del pulmón en el que tiene lugar el intercambio gaseoso).");
INSERT INTO keywords (name, description) VALUES ("Célula caliciforme", "Célula secretora de moco dentro de las vías aéreas. La célula tiene un mecanismo protector, ya que el moco secretado atrapa las
partículas que han entrado en el tracto respiratorio, que son entonces llevadas hasta la boca por el transporte mucociliar para su
eliminación.");
INSERT INTO keywords (name, description) VALUES ("Célula de Schwann", "Célula que desprende una envoltura de mielina para recubrir los nervios mielinizados.
(A) Axón mielinizado en el sistema nervioso periférico. (B) Relación entre axones no mielizados y células de Schwann");
INSERT INTO keywords (name, description) VALUES ("Células de Purkinje", "Neuronas de gran tamaño situadas en la corteza cerebelar que dan lugar a los axones eferentes y proporcionan la única salida desde la
corteza cerebelar.Células T
Clase de linfocitos derivados del timo implicados principalmente en el control de las reacciones inmunológicas celulares y en el control
del desarrollo de las células B. Coordinan el sistema inmunológico secretando hormonas linfocinas.");
INSERT INTO keywords (name, description) VALUES ("Centro de la apnea", "Parte del centro de control respiratorio responsable del cese de la inspiración para permitir la espiración.");
INSERT INTO keywords (name, description) VALUES ("Centro de presión", "Término biomecánico que hace referencia a las fuerzas que actúan por debajo del pie.");
INSERT INTO keywords (name, description) VALUES ("Cepillado", "Técnica empleada en el intento de facilitar la actividad muscular. Persiste la controversia sobre sus beneficios (Stokes, 1998).");
INSERT INTO keywords (name, description) VALUES ("Cera", "Mezcla de cera de parafina y un aceite mineral normalmente calentado a 42-52 °C en un recipiente específicamente diseñado (bañera
de cera). Se utiliza para proporcionar calor superficial a los tejidos, especialmente los de las manos, para aliviar el dolor crónico
asociado a diversas condiciones artríticas o después de una fractura. Los peligros específicos son los asociados al calentamiento.");
INSERT INTO keywords (name, description) VALUES ("Cerebelo", "Estructura del cerebro localizada en la fosa posterior. Está unida al tallo cerebral en el puente y es importante en el control del
movimiento.");
INSERT INTO keywords (name, description) VALUES ("Cesárea", "Procedimiento quirúrgico en el que se hace una incisión en el abdomen y el útero, y se extrae el feto transabdominalmente.
Normalmente se lleva a cabo en casos en que el parto vaginal sería arriesgado.");
INSERT INTO keywords (name, description) VALUES ("Cetosis", "Producción metabólica de cantidades anormales de cetonas. Es una consecuencia de la diabetes mellitus.");
INSERT INTO keywords (name, description) VALUES ("CFCT", "Abreviatura médica común de complejo fibrocartilaginoso triangular (en la muñeca).");
INSERT INTO keywords (name, description) VALUES ("Chlamydia pneumoniae", "Germen patógeno (bacteria de la familia clamidiáceas) responsable de la neumonía atípica.");
INSERT INTO keywords (name, description) VALUES ("Cianosis", "Decoloración azulada de las membranas cutaneomucosas. Se clasifica en cianosis central, en que la punta de la lengua pierde su color
rosado, lo cual indica desaturación de la sangre arterial, y cianosis periférica, caracterizada por el color azulado en dedos de manos y
pies, lo cual indica una perfusión insuficiente, posiblemente local, o una estasis de sangre (no necesariamente desaturación); por
ejemplo, la que se observa en la enfermedad vascular periférica. La cianosis es difícil de detectar a menos que sea grave (SaO");
INSERT INTO keywords (name, description) VALUES ("2 <", "85%), con un error de observación elevado; pueden influir factores como la pigmentación de la piel, el diámetro de los vasos o la
iluminación (p. ej., presencia de esmalte de uñas), la Hb y el observador. Su ausencia no se debe interpretar de modo falsamente
alentador.");
INSERT INTO keywords (name, description) VALUES ("Ciática", "Dolor en el trayecto del nervio ciático o sus ramas, causado por presión directa o irritación. No incluye el dolor reflejo derivado de las
articulaciones vertebrales, los ligamentos o los músculos.");
INSERT INTO keywords (name, description) VALUES ("Cicatriz hipertrófica", "Cicatriz elevada que normalmente se observa después de quemaduras graves.");
INSERT INTO keywords (name, description) VALUES ("Cicatrización por primera intención", "Consolidación por adhesión fibrosa, sin supuración o formación de tejido de granulación.Cicatrización por segunda intención
Cierre retardado de dos superficies de tejido de granulación.");
INSERT INTO keywords (name, description) VALUES ("Ciclo activo de respiración (CAR)", "Método para facilitar la expulsión de secreciones pulmonares excesivas.
(A) Control respiratorio. Adaptado de: Physiotherapy for respiratory and cardiac problems.
Todo el ciclo debe repetirse dos o tres veces o hasta que el paciente no produzca más secreciones. En pacientes recientemente
intervenidos, la fatiga puede ser un problema y el tratamiento debe concluir en este punto. Las respiraciones deben ser de tipo torácico,
lentas y profundas, tomando aire por la nariz y expulsándolo por la boca. El mantenimiento del aire al final de la inspiración puede
mejorar el flujo aéreo, llevándolo a regiones pobremente ventiladas ( Hough, 2001 ); esta apnea postinspiratoria debe ser mantenida
durante 2-3 s.");
INSERT INTO keywords (name, description) VALUES ("Ciclo cardíaco", "En un individuo en reposo con una frecuencia cardíaca de alrededor de 70 lat./min, cada ciclo cardíaco dura aproximadamente 0,8 s.
La fasede contracción, conocida como sístole, dura alrededor de 0,3 s. La fase de relajación, conocida como");
INSERT INTO keywords (name, description) VALUES ("diástole, dura algo más", "(alrededor de 0,5 s). Durante este período, las cavidades cardíacas se llenan con la sangre de retorno. Cada ciclo es iniciado por la
génesis espontánea de un potencial de acción en el nódulo sinoauricular. La figura muestra la relación entre los factores eléctricos y
mecánicos durante el ciclo cardíaco.");
INSERT INTO keywords (name, description) VALUES ("Ciclo de función", "Término electroterápico. Indica el porcentaje de tiempo en modo de salida (output). Fórmula:
On y off se miden normalmente en segundos. Se usan más comúnmente para la estimulación eléctrica, el ultrasonido pulsante y el SWD
pulsante (PSWD).");
INSERT INTO keywords (name, description) VALUES ("CIE-10", "Décima revisión de la Clasificación Internacional de Enfermedades. Es la última de una serie que fue iniciada formalmente en 1893
como la Bertillon Classification or International List of Causes of Death.");
INSERT INTO keywords (name, description) VALUES ("Ciego (caecum)", "Primera porción del intestino grueso.");
INSERT INTO keywords (name, description) VALUES ("Ciego (estudio)", "Proceso de investigación en el que los participantes de un estudio, cuidadores, investigadores y asesores de resultados no conocen las
intervenciones a las que los participantes han sido asignados durante el estudio.
Observación clínica La fisioterapia está abierta a cualquier sesgo, como cualquier otra profesión, por lo que siempre hay que hacer
esfuerzos para minimizar sesgos en cualquier proyecto de investigación que se lleve a cabo.");
INSERT INTO keywords (name, description) VALUES ("Cifoescoliosis", "Deformidad postural caracterizada por una curvatura vertebral anteroposterior y lateral, que puede dar lugar a un patrón de respiración
restrictivo.Cifosis
Curvatura vertebral exagerada en el eje de flexoextensión. En la vejez, la causa más común de cifosis es la osteoporosis. Esto puede
dar lugar a un defecto pulmonar restrictivo, como se detecta en la espirometría.
Observación clínica. Si no es adaptativa o compensatoria, entonces será necesario ajustar los asientos y cojines para asegurar un
soporte apropiado.");
INSERT INTO keywords (name, description) VALUES ("Cifosis (joroba) de la viuda", "Curva de la parte superior de la columna vertebral. Normalmente constituye un síntoma de osteoporosis.");
INSERT INTO keywords (name, description) VALUES ("Cigoma", "Hueso de la mejilla.");
INSERT INTO keywords (name, description) VALUES ("Cilios", "Estructuras finas semejantes a pelos presentes en el interior de las vías aéreas, desde la nariz hasta los bronquiolos terminales. Los cilios
son un componente importante del mecanismo de defensa del cuerpo. Hay aproximadamente 200 cilios en cada célula epitelial, y cada
uno de ellos sigue un movimiento semejante al de una ola (ola mitocondrial) con una frecuencia de 10-20/s, para impulsar los desechos
inhalados hacia la faringe de manera que puedan ser expectorados (o deglutidos).");
INSERT INTO keywords (name, description) VALUES ("CINAHL", "Cumulative index to Nursing and allied health (Índice acumulativo correspondiente a enfermería y salud pública). Se trata de una base
de datos de referencia que cubre la literatura relacionada con la enfermería y la salud pública.");
INSERT INTO keywords (name, description) VALUES ("Cinemática", "Ciencia relacionada con la descripción exacta de las diversas posiciones y movimientos del cuerpo en el espacio.");
INSERT INTO keywords (name, description) VALUES ("Cinesi-", "Relativo al movimiento.");
INSERT INTO keywords (name, description) VALUES ("Cinesiología", "Estudio del movimiento del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Cinética", "Rama de la dinámica que se centra en las fuerzas que dan lugar a la detención o modificación de los movimientos del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Cinta de marcha", "Forma de intervención terapéutica que se centra en el reentrenamiento de la marcha después de una lesión neurológica. Generalmente
requiere una cinta de marcha especial con un sistema de soporte de peso.");
INSERT INTO keywords (name, description) VALUES ("Circunducción", "Movimiento de un miembro de manera circular, trazando la figura de un cono.Circunstancias mitigantes
Circunstancias aducidas por un estudiante como razón para un resultado insuficiente en procesos de valoración.");
INSERT INTO keywords (name, description) VALUES ("Cirugía para la reducción del volumen pulmonar (CRVP)", "Proceso para mejorar la función respiratoria en pacientes con enfisema bulloso grave. Puede conseguirse eliminando el tejido bulloso y
moldeando la expansión pulmonar restante del pulmón sano y de la cúpula del diafragma. Esto mejorará el mecanismo respiratorio y
conducirá al alivio sintomático de la disnea. Los pacientes deberían someterse a un período de rehabilitación pulmonar preoperatorio
para maximizar su función respiratoria (Dyson, 2003).");
INSERT INTO keywords (name, description) VALUES ("Citotóxicos", "Cualquier agente o proceso que sea tóxico para las células dará lugar a la supresión de la función celular o a la muerte celular.");
INSERT INTO keywords (name, description) VALUES ("Ciudadanía", "Conjunto de derechos y obligaciones humanos y civiles esperables en una sociedad democrática. Incluyen el derecho a la participación
en la selección de un gobierno legítimo y el derecho a la libertad de expresión y a la libertad religiosa. Las obligaciones incluyen
obedecer la ley y considerar las necesidades de otras personas.");
INSERT INTO keywords (name, description) VALUES ("CK", "Abreviatura médica común correspondiente a creatincinasa.");
INSERT INTO keywords (name, description) VALUES ("Clase social", "Posición estructural en la sociedad de un individuo o grupo en comparación con otros individuos o grupos. Término básico dentro de
las ciencias sociales y objeto de notable controversia y desacuerdo. En las estadísticas oficiales, las personas se clasifican normalmente
según su ocupación e ingresos.");
INSERT INTO keywords (name, description) VALUES ("Clasificación de Garden", "Método utilizado para clasificar la gravedad y el subsiguiente tratamiento de la fractura del cuello femoral.
• Tipo 1. La cortical inferior no está completamente rota.
• Tipo 2. La cortical está rota pero no existe angulación.
• Tipo 3. Ligero desplazamiento y rotación de la cabeza femoral.
• Tipo 4. Desplazamiento completo.Clasificación de Garden. Cualquier desplazamiento debe ser valorado de acuerdo con las directrices formuladas por Garden, que, entre
otros factores, tienen en cuenta la alteración de las trabéculas que soportan el peso irradiando desde el calcar femorale
Fractura tipo 1. La cortical inferior no está completamente rota, pero las trabéculas están anguladas (fractura en abducción).
Fractura tipo 2. La línea de fractura es completa y la cortical inferior está claramente rota. Las líneas trabeculares están interrumpidas,
pero no anguladas. En ambos tipos de fracturas, 1 y 2, no hay desplazamiento obvio de los fragmentos principales, en relación uno con
otro.
Fractura tipo 3. Aquí la línea de fractura es obviamente completa. Hay una rotación de la cabeza femoral en el acetábulo, y el fragmento
proximal está en abducción y rotación interna. Esto puede ponerse de manifiesto en el patrón trabecular. La fractura está ligeramente
desplazada.
Fractura tipo 4. Éste es el grado más grave. La fractura está completamente desplazada y la cabeza femoral tiende a descansar en una
posición neutra dentro del acetábulo. Las fracturas tipo 3 y 4, según la clasificación de Garden, tienen los peores pronósticos.");
INSERT INTO keywords (name, description) VALUES ("Clasificación de las articulaciones", "Principales tipos de articulación sinovial.");
INSERT INTO keywords (name, description) VALUES ("Clasificación de las recomendaciones", "Código (A, B, C, D) dado a una directriz o recomendación, que indica el peso de la evidencia que la respalda (NICE, 2004).");
INSERT INTO keywords (name, description) VALUES ("Clasificación de Neer", "Sistema de clasificación de fracturas de la zona proximal del húmero.");
INSERT INTO keywords (name, description) VALUES ("Clasificación de Neer", "");
INSERT INTO keywords (name, description) VALUES ("Grupo 1 Desplazamiento mínimo", "Grupo 2 Fractura del cuello anatómico con menos de 1 cm de desplazamiento");
INSERT INTO keywords (name, description) VALUES ("Grupo 3 Desplazamiento o angulación del cuello quirúrgicoGrupo 4", "");
INSERT INTO keywords (name, description) VALUES ("Grupo 5 Fractura con desplazamiento del tubérculo mayor", "");
INSERT INTO keywords (name, description) VALUES ("Fractura del tubérculo menor", "");
INSERT INTO keywords (name, description) VALUES ("Grupo 6 Dislocación con fractura", "");
INSERT INTO keywords (name, description) VALUES ("Clasificación del movimiento", "");
INSERT INTO keywords (name, description) VALUES ("Movimiento pasivo", "Un hombre se queda dormido con el brazo sobre un libro, un amigo llega y levanta el brazo del hombre dormido para recuperar el
libro. Este movimiento no requiere acción muscular del hombre dormido y es, por tanto, un ejemplo de movimiento pasivo.");
INSERT INTO keywords (name, description) VALUES ("Movimiento activo asistido", "Un hombre es ayudado por su amigo a vestirse y su amigo le ayuda a levantar el brazo para ponerse el jersey. Él hace una parte del
trabajo, pero su amigo también. Esto es, por tanto, un ejemplo de movimiento activo asistido.");
INSERT INTO keywords (name, description) VALUES ("Movimiento activo", "El hombre está ahora en el baño y alcanza a coger la pasta de dientes. Sus propios músculos controlan el movimiento completamente.
Esto es, por lo tanto, un ejemplo de movimiento activo.");
INSERT INTO keywords (name, description) VALUES ("Movimiento resistido", "El hombre baja corriendo al vestíbulo; al final del vestíbulo una puerta se atasca y tiene que empujarla muy fuerte. Los músculos tienen
que trabajar contra una fuerza externa. Esto es, por tanto, un ejemplo de movimiento resistido.");
INSERT INTO keywords (name, description) VALUES ("Clasificación internacional del funcionamiento, la discapacidad y la salud (CIFDS)", "Sistema de clasificación de la salud y de los dominios relacionados con la salud, que describen las funciones y estructuras corporales,
las actividades y la participación. Utilizada para describir cómo las personas viven con su alteración de la salud. Los dominios se
clasifican desde perspectivas corporales, individuales y sociales, e incluyen una lista de factores ambientales. Pueden utilizarse en
escenarios clínicos, servicios sanitarios o encuestas a nivel del individuo o de la población. Ir a
http://www3.who.int/icf/icftemplate.cfm?myurl=homepage.html1&mytitle-Home%20Page");
INSERT INTO keywords (name, description) VALUES ("Claudicación", "Alteración caracterizada por episodios de dolor de tipo calambres en los gemelos, causada por una insuficiente circulación sanguínea
hacia los músculos de la pierna. La alteración se suele asociar con arteriosclerosis. La claudicación intermitente es un tipo de alteración
llamativa, y se produce sólo en momentos concretos, normalmente después de andar durante períodos prolongados; se alivia con el
reposo.");
INSERT INTO keywords (name, description) VALUES ("Claudicación intermitente", "Alteración caracterizada por dolor y debilidad en las piernas que aparece con el ejercicio o la marcha; los síntomas desaparecen
después de un breve descanso. La mayoría de las veces está causada por un estrechamiento arterioesclerótico de las arterias ilíaca y
femoral, a menudo combinada con lesiones en las arterias distales de la pierna.");
INSERT INTO keywords (name, description) VALUES ("Clavo intramedular", "El enclavamiento intramedular ha revolucionado el tratamiento de las fracturas de los huesos largos. Se introduce una varilla de metal
hueca en un extremo del hueso largo, que recorre en sentido descendente el canal medular y puede fijarse con tornillos tanto distal
como proximalmente. El extremo proximal del clavo está enhebrado, lo cual permite introducir posteriormente un instrumento en el
clavo para retirarlo. El enclavamiento intramedular para fracturas de huesos largos ha revolucionado el tratamiento de muchas fracturas
que hasta hace pocos años se habrían tratado con reposo en cama. El traumatismo es menor que en las técnicas abiertas y da lugar a
que el paciente tenga que estar menos tiempo en el hospital, se movilice más rápidamente y su rehabilitación suponga un mínimo riesgo
de complicaciones asociadas a la inmovilización. El implante, a diferencia del hueso, recibirá los esfuerzos y cargas y, por esta razón, el
cirujano puede optar por eliminar los tornillos de fijación en etapas posteriores. Esto permite al clavo moverse ligeramente y favorece laconsolidación de los extremos óseos, conocida como dinamización. Esto permite al hueso soportar de nuevo los esfuerzos y cargas
normales y adaptarse de acuerdo con la ley de Wolff. Las fracturas de la diáfisis de la tibia y del húmero pueden enclavarse de esta
manera.");
INSERT INTO keywords (name, description) VALUES ("Clon", "Grupo de células u organismos genéticamente idénticos que descienden de un antecesor común.");
INSERT INTO keywords (name, description) VALUES ("Clonus", "Contracciones rítmicas e involuntarias que se producen cuando un grupo muscular se estira con rapidez; se observa comúnmente en el
tobillo cuando el pie está en flexión dorsal. Si es muy pronunciado, puede interferir en la función.");
INSERT INTO keywords (name, description) VALUES ("Enclavamiento intramedular para la fractura de la diáfisis del fémur", "");
INSERT INTO keywords (name, description) VALUES ("Coartación aórtica", "Anormalidad cardíaca que es una causa común de insuficiencia cardíaca congestiva.");
INSERT INTO keywords (name, description) VALUES ("Cociente internacional normalizado (INR)", "Tiempo que le cuesta a la sangre coagularse comparado con un control. El INR debería ser de entre 0,9 y 1,2.");
INSERT INTO keywords (name, description) VALUES ("Codificar", "Término de investigación cualitativo que se refiere a la tarea de atribuir códigos a conceptos y temas que tienen lugar en la transcripción
de una entrevista.");
INSERT INTO keywords (name, description) VALUES ("Códigos éticos", "Directrices marcadas por organizaciones profesionales que ayudan al personal sanitario a tomar decisiones éticas y los guían en las
tareas, responsabilidades y estándares de comportamiento apropiado. El consejo dado es amplio y general, y no absuelve a los
profesionales de la responsabilidad de tomar decisiones éticas. Los códigos éticos tienden a aunar asuntos genuinamente éticos con
temas relacionados con la imagen profesional y etiqueta profesional, para mantener el buen nombre de la profesión.");
INSERT INTO keywords (name, description) VALUES ("Codo de tenista", "Término que hace referencia a la inflamación del extensor común que se origina en el epicóndilo lateral del húmero (en el codo de los
golfistas se ve afectada la epitróclea).
Véase Epicondilitis lateral.");
INSERT INTO keywords (name, description) VALUES ("Cognición", "Procesos de pensamiento que permiten al individuo ser consciente de sí mismo, de los objetos y de otras personas, y comprender e
interaccionar racionalmente con el medio.Cognitivo
Perteneciente al pensamiento, conciencia o capacidad para comprender racionalmente el mundo.");
INSERT INTO keywords (name, description) VALUES ("Colaboración Cochrane", "Organización internacional sin ánimo de lucro e independiente, cuyo objetivo es proporcionar información exacta y actualizada en todo
el mundo sobre los efectos del cuidado de la salud. Produce y divulga revisiones sistemáticas de intervenciones del cuidado de la salud
y promociona la búsqueda de evidencias en forma de ensayos clínicos y otros estudios de intervenciones. La Cochrane Collaboration
fue fundada en 1993 y recibió el nombre del epidemiólogo británico Archie Cochrane. El resultado más importante de la Collaboration
es la Cochrane Database de Systematic Reviews, publicada cada trimestre como parte de la Cochrane Library. Las revisiones son
preparadas por profesionales de la salud que, de forma voluntaria, trabajan en uno de los muchos grupos de Collaborative Review,
junto con equipos editoriales que supervisan la preparación de mantenimiento de las revisiones, así como la aplicación de estándares de
calidad rigurosos por los que las revisiones de Cochrane se han hecho famosas.
Ir a http://www.cochrane.org/inde0.htm");
INSERT INTO keywords (name, description) VALUES ("Colágeno", "Sustancia proteica de las fibras blancas de piel, tendón, hueso, cartílago y otros tejidos conectivos.");
INSERT INTO keywords (name, description) VALUES ("Colecistectomía", "Extirpación quirúrgica de la vejiga.");
INSERT INTO keywords (name, description) VALUES ("Colectomía", "Término dado a la escisión de la totalidad o parte del colon.");
INSERT INTO keywords (name, description) VALUES ("Colesterol", "Compuesto graso. Se encuentra en muchas comidas, en el torrente sanguíneo y en todas las células. El colesterol es esencial para:
• Formación y mantenimiento de las membranas celulares.
• Formación de las hormonas sexuales.
• Producción de sales biliares, que ayudan a digerir la comida.
• Conversión en vitamina D en la piel, cuando se expone a la luz solar.
Hay dos tipos de colesterol, comúnmente considerados como colesterol bueno y colesterol malo. El colesterol »malo« corresponde a
las lipoproteínas de baja densidad (LDL), y constituye la mayor parte del colesterol en sangre; altos niveles de estas LDL están
asociados con arteriosclerosis. El colesterol »bueno« corresponde a las lipoproteínas de alta densidad (HDL); un nivel elevado de HDL
proporciona protección contra el bloqueo arterial, ya que este tipo de lipoproteínas actúan a modo de »desatascador«.");
INSERT INTO keywords (name, description) VALUES ("Colitis", "Inflamación del intestino grueso caracterizada por ataques de dolor cólico, diarrea o estreñimiento, que a menudo empeora por estrés
emocional.");
INSERT INTO keywords (name, description) VALUES ("Coloide", "Sustancia formada por moléculas grandes que atraen y sostienen agua. Los coloides se administran para ayudar a corregir la
hipovolemia (un estado de bajo volumen de circulación sanguínea).");
INSERT INTO keywords (name, description) VALUES ("Colonoscopia", "Exploración del colon realizada con un endoscopio elongado (co-lonoscopio).");
INSERT INTO keywords (name, description) VALUES ("Colostomía", "Creación de un ano artificial en la pared abdominal. Una colostomía puede ser tanto permanente como temporal. La colostomía
temporal puede realizarse después de una intervención quirúrgica para permitir que descanse el intestino.Exploración de un tejido vivo bajo aumento para identificar la localización y extensión de una lesión o enfermedad.");
INSERT INTO keywords (name, description) VALUES ("Columna cervical", "Porción de la columna constituida por siete vértebras (C1-C7). Se articula en su extremo craneal con el occipucio y en su extremo
caudal con la primera vértebra torácica (T1). El término común es cuello.");
INSERT INTO keywords (name, description) VALUES ("Columna dorsal", "Rutas por las que las aferencias sensoriales viajan hasta el cerebro. Incluyen receptores para vibración, tacto y propioceptores.
Principales trayectorias ascendentes en la médula espinal. La columna dorsal (o posterior) conduce la información aferente desde los mecanorreceptores (piel) y
propioceptores (músculos y articulaciones) hasta la corteza somatosensorial. Los tractos espinotalámicos, en la sustancia blanca anterior (ventral) y lateral, conducen
principalmente la información desde los nociceptores y termoceptores al tálamo y a la corteza. Los tractos espinocerebelosos en la materia blanca lateral conducen las
entradas propioceptivas al cerebelo. Los tractos proprioespinales unen los diferentes segmentos de la médula espinal.");
INSERT INTO keywords (name, description) VALUES ("Columna en caña de bambú", "Término que hace referencia a una imagen radiográfica de espondilitis anquilosante avanzada, donde se muestra la fusión de vértebras
adyacentes que hace que la columna se parezca a un tallo de bambú.");
INSERT INTO keywords (name, description) VALUES ("Columna lumbar", "Formada por cinco vértebras; normalmente denominada »parte baja de la espalda«.");
INSERT INTO keywords (name, description) VALUES ("Columna torácica", "Comprende 12 vértebras (T1-T12), situadas entre la columna cervical y la lumbar. Proporcionan uniones a las costillas.");
INSERT INTO keywords (name, description) VALUES ("Coma", "Estado de inconsciencia en que el paciente no responde a la aplicación de estímulos sensitivos y en que la actividad cerebral cortical
persiste.
Comisión de la asistencia sanitaria (comisión para la auditoría e inspección de la asistencia sanitaria)
Establecida para promover una mejora en la calidad del NHS, asistencia sanitaria privada y voluntaria en Inglaterra y Gales. Formada
por la Health and Social Care (Community Health and Standards) Act 2003 y puesta en marcha el 1 de abril de 2004.");
INSERT INTO keywords (name, description) VALUES ("Comité ético de investigación", "Comité independiente que analiza propuestas de investigación para asegurar que son éticamente aceptables.");
INSERT INTO keywords (name, description) VALUES ("Community Health Council (CHC)", "Cuerpos reglamentarios independientes de las autoridades de la salud y NHS Trusts, que representan los intereses de la salud de las
personas y proporcionan consejos en los servicios de la salud.");
INSERT INTO keywords (name, description) VALUES ("Community Mental Health (CMH)", "Filosofía de tratamiento basada en el modelo social de cuidado psiquiátrico que aboga por un conjunto de servicios comprensivos de
salud mental, disponibles rápidamente para la comunidad.Community Mental Health Centre (CMHC)
Centro comunitario que proporciona un amplio abanico de servicios de salud mental.");
INSERT INTO keywords (name, description) VALUES ("Comorbilidad", "Coexistencia de más de una enfermedad o una enfermedad adicional (otra distinta de la que está siendo tratada o evaluada) en un
individuo.");
INSERT INTO keywords (name, description) VALUES ("Complejo de ataque de la membrana", "Anillo de fragmentos complementarios que tienen la capacidad de insertarse en una célula invasora y causar su destrucción.");
INSERT INTO keywords (name, description) VALUES ("Complejo QRS", "Parte de un electrocardiograma.
Véase Ciclo cardíaco.");
INSERT INTO keywords (name, description) VALUES ("Complemento", "Grupo de proteínas que se encuentran en el suero y plasma sanguíneo que, en combinación con los anticuerpos, causa la destrucción de
los antígenos.");
INSERT INTO keywords (name, description) VALUES ("Complianza", "Capacidad de distensión. La distensión pulmonar es la facilidad con la que los pulmones se insuflan y es definida como el cambio de
volumen por unidad de cambio de presión (medida en l/cm de agua). Las alteraciones que dan lugar a una distensión/complianza
insuficiente incluyen enfermedades pulmonares fibróticas (p. ej., alveolitis fibrosante, tuberculosis [TB] y síndrome de distrés respiratorio
agudo [SDRA]) y anormalidades de la pared torácica como cifoescoliosis grave y
pectus excavatum (pecho »en embudo«). Los
pulmones con distensión baja son rígidos y producirán un volumen corriente más bajo para el mismo esfuerzo aplicado a la respiración
que los pulmones »normales«. La ecuación de la distensión pulmonar puede emplearse para calcular la capacidad de distensión de los
pulmones de un paciente ventilado:");
INSERT INTO keywords (name, description) VALUES ("donde", "C = complianza; Vc = volumen corriente, y P = presión de conducción.
Por ejemplo:
lo cual indicaría pulmones rígidos difíciles de hinchar (el valor normal de complianza es 75).");
INSERT INTO keywords (name, description) VALUES ("Comportamiento", "Actividades de una persona que pueden ser observadas y medidas por otra persona.");
INSERT INTO keywords (name, description) VALUES ("Comportamiento ante la enfermedad", "Modo en que las personas responden a la enfermedad y a la discapacidad y al tipo de ayuda, si existe, que buscan. El comportamiento
de la enfermedad depende de multitud de factores incluyendo la forma en que se perciben y evalúan los síntomas, la gravedad de éstos,
la experiencia pasada de enfermedad, el apoyo social, y lo conveniente o inconveniente de estar enfermo en un momento dado.");
INSERT INTO keywords (name, description) VALUES ("Comportamiento desafiante", "Término aplicado la mayoría de las veces al comportamiento de las personas con dificultades de aprendizaje, juzgado como inaceptable
por los estándares sociales y relevante en relación con el trasfondo cultural y la edad. Puede implicar comportamiento autolesivo,
alteración del comportamiento sexual o verbal y/o violencia física. El comportamiento desafiante podría, sin embargo, tenerse en
consideración según el impacto que tiene en la vida de los individuos afectados y en la de los demás, como un desafío a la capacidad de
autosuficiencia (de la provisión de servicio). »Comportamiento desafiante« es un término más amplio que »comportamiento difícil o
problemático«, ya que tiene en cuenta el medio ambiente.");
INSERT INTO keywords (name, description) VALUES ("Compresión", "Término que hace referencia al empuje sobre el tórax durante la maniobra de resucitación, o una técnica de aproximación de las
superficies de una articulación; puede utilizarse como test de diagnóstico o como técnica de tratamiento.Comunicación
Proceso de compartir y dar significado a todas las situaciones sociales. Es aplicado la mayoría de las veces a contextos persona a
persona, incluyendo la interacción cara a cara. Gracias a los avances tecnológicos (p. ej., teléfonos móviles y e-mail), la comunicación
interpersonal se ha convertido en global para muchas personas. Definiciones más amplias incluyen la comunicación intrapersonal o
conversación interna, por ejemplo en el sentido de la relación entre lenguaje y pensamiento. Las definiciones también abarcan la
comunicación de grupo y masa. Hay numerosos modos de comunicación, incluyendo la verbal, simbólica, escrita y no verbal (expresión
facial, contacto ocular y paralenguaje como el acento y el tono de la voz).");
INSERT INTO keywords (name, description) VALUES ("Concepto de sensibilización", "Término de investigación utilizado para describir cómo determinados conceptos pueden guiar al investigador hacia un comportamiento
determinado.");
INSERT INTO keywords (name, description) VALUES ("Concepto Mulligan", "1. Durante la valoración, el terapeuta identificará uno o más signos comparables a los descritos por Maitland. Éstos pueden consistir en
pérdida del movimiento articular, dolor asociado al movimiento o dolor asociado a actividades funcionales específicas (p. ej., dolor
lateral del codo a la extensión de muñeca resistida, tensión neural adversa).
2. Se aplica una movilización articular accesoria pasiva siguiendo los principios de Kaltenborn (es decir, paralela o perpendicular al
plano de tratamiento articular). Este deslizamiento accesorio debe estar libre de dolor.
3. El terapeuta debe monitorizar la reacción del paciente de forma continua para asegurarse de que el dolor no reaparece. Utilizando
sus conocimientos de biomecánica articular, un sentido bien desarrollado del grado de tensión del tejido y su capacidad de
razonamiento clínico, el terapeuta investiga varias combinaciones de deslizamientos perpendiculares o paralelos para encontrar el plano
de tratamiento y grado de movimiento correctos.
4. Mientras se mantiene el deslizamiento accesorio, se solicita al paciente que efectúe el gesto que provocaba los signos. Éstos deberían
haber mejorado significativamente (aumento del rango de movimiento y disminución significativa o incluso ausencia del dolor inicial).
5. El hecho de que los signos no mejoren indica que el terapeuta no ha encontrado el punto de contacto correcto, el plano de
tratamiento, el grado o dirección de movilización, o el segmento espinal adecuado, o bien que la técnica no está indicada.
6. El movimiento o actividad previamente restringido o doloroso es repetido por el paciente mientras el terapeuta continúa manteniendo
el deslizamiento accesorio apropiado. Se espera obtener mayores beneficios mediante la repetición durante la sesión de tratamiento
(típicamente tres series de diez repeticiones).
7. Pueden lograrse beneficios mayores mediante la aplicación de sobrepresiones pasivas en el final del rango disponible. Se espera que
esa sobrepresión vuelva a ser indolora.");
INSERT INTO keywords (name, description) VALUES ("Principios", "En la aplicación de técnicas de terapia manual, los fisioterapeutas reconocen que existen contraindicaciones para el tratamiento y que
éstas deberán respetarse siempre. A pesar de que siempre se guíe por las reglas básicas de nunca causar dolor, la elección del
terapeuta del uso de SNAGS (sustained natural apophyseal glides) en la columna y MCM (movilización con movimiento) en las
extremidades debe someterse al conocimiento de las reglas básicas de aplicación de técnicas de terapia manual. Para especificar la
aplicación de MCM y SNAGS en la práctica clínica, se han desarrollado una serie de principios básicos.
El autotratamiento es a menudo posible usando los principios del MCM con cinta adhesiva y/o el propio paciente proporcionando el
componente de deslizamiento del MCM y los propios esfuerzos del paciente para producir el movimiento activo. El dolor es siempre la
guía. Si las técnicas SNAGS y MCM tienen éxito, deberán transformar los signos observados en no dolorosos y mejorar
significativamente la función durante la aplicación de la técnica. Las mejoras sostenidas son necesarias para justificar la continuación de
la intervención.
Ir a http://www.bmulligan.com/about/concept.html
Nuestro agradecimiento a Brian R. Mulligan NZRP, Dip MT, FNZSP, MCTA y Jack Miller BSc(PT), Dip MT (NZ), FCAMT,
MCTA.");
INSERT INTO keywords (name, description) VALUES ("Conciencia espacial", "Para que las personas sean capaces de funcionar de manera efectiva en el medio que las rodea, deben saber dónde se encuentra cada
parte de su cuerpo en relación con el entorno.Observación clínica La conciencia espacial puede verse afectada después de una lesión cerebral y es importante para la seguridad (p.
ej., juzgar la profundidad de las escaleras o saber a qué distancia está un coche cuando se desea cruzar la calle).");
INSERT INTO keywords (name, description) VALUES ("Cóndilo", "Proyección articular redondeada.");
INSERT INTO keywords (name, description) VALUES ("Condroma", "Tumor en el cartílago.");
INSERT INTO keywords (name, description) VALUES ("Condromalacia patelar", "Nombre común dado a un conjunto de síndromes que dan lugar al reblandecimiento del cartílago en la superficie articular de la rótula.
Se suele observar en adolescentes y mujeres jóvenes; comúnmente se asocia con deficiencias funcionales y mecánicas de la articulación
femoropatelar, como un ángulo Q anormal. Véase Ángulo Q.
Es común en adolescentes, y puede estar relacionado con sobreuso, traumatismo y/o fuerzas anormales en la rodilla. Es más habitual en
mujeres. Los síntomas incluyen:
• Sensibilidad en la rodilla.
• Derrames recurrentes y aumento de la temperatura de la articulación.
• Dolor anterior en la rodilla que empeora después de una sedestación prolongada.
• Sensación áspera y de rechinamiento debajo de la rótula en la extensión de la rodilla.");
INSERT INTO keywords (name, description) VALUES ("Conducción saltatoria", "Término que describe la transmisión de un impulso nervioso a lo largo de los nervios mielinizados. Los potenciales de acción se generan
a intervalos a lo largo del nervio, como se muestra a continuación. Esto da lugar a una transmisión más rápida que si la vaina fuera
continua.");
INSERT INTO keywords (name, description) VALUES ("Conductividad aérea", "Facilidad con la que el gas fluye a lo largo de los conductos aéreos y es calculado por la fórmula flujo/presión. Es el concepto recíproco
de resistencia aérea.");
INSERT INTO keywords (name, description) VALUES ("Conductos aéreos", "Son los conductos hacia los pulmones; están formados por el tracto respiratorio superior (TRS) e inferior (TRI). El TRS está formado
por nariz, faringe y laringe, y calienta, filtra y humedece el aire inhalado previamente a su paso hacia el TRI. El TRS es también
importante para las funciones de habla, gusto y olor. El TRI comprende el sistema conductor y comienza en la tráquea, que se bifurca
hasta los bronquiolos terminales, antes de formar la unidad de intercambio gaseoso del pulmón (sacos alveolares).");
INSERT INTO keywords (name, description) VALUES ("Conferencia", "Forma tradicional de enseñanza universitaria donde el profesor habla para los estudiantes reunidos y presenta todo el material que
considera que el estudiante debe conocer.Principio ético por el que se promete mantener en estricta confianza la información sobre otra persona.");
INSERT INTO keywords (name, description) VALUES ("Conflicto de rol", "Situación que se produce cuando las expectativas de dos o más roles entran en conflicto. El conflicto de roles puede ocurrir, por
ejemplo, cuando las expectativas del salario entran en conflicto con las expectativas del rol del cuidador. El conflicto de rol puede
causar ansiedad.");
INSERT INTO keywords (name, description) VALUES ("Congénito", "Presente desde el nacimiento.");
INSERT INTO keywords (name, description) VALUES ("Coning", "Lugar donde la presión intercraneal creciente da lugar a una hernia cerebral a través del
neuroquirúrgica.
foramen magnum. Es una emergencia");
INSERT INTO keywords (name, description) VALUES ("Conjunto de motoneuronas", "Todas las α-motoneuronas que proporcionan la inervación de las fibras musculares en un músculo individual.");
INSERT INTO keywords (name, description) VALUES ("Conocimiento de la ejecución", "Término utilizado para describir la conciencia que tienen los pacientes de cómo se ha realizado el movimiento.
Se hace referencia a este término en la »aproximación de reeducación motora« ( Carr y Shepherd, 1998 ) al manejo y tratamiento de
pacientes neurológicos.");
INSERT INTO keywords (name, description) VALUES ("Conocimiento de los resultados", "Información mejorada proporcionada sobre el éxito o los errores que se realizan en el logro de movimientos funcionales. Es un término
utilizado para describir la conciencia que tiene el paciente de haber logardo realizar la tarea o no.
Referencias a este término aparecen en la »aproximación de reeducación motora« ( Carr y Shepherd, 1998) al manejo y tratamiento de
pacientes neurológicos.");
INSERT INTO keywords (name, description) VALUES ("Consecuencialismo", "Enfoque en la toma de una decisión ética por el que las consecuencias de una acción se consideran más importantes que principios
éticos fundamentales como el respeto a la autonomía.");
INSERT INTO keywords (name, description) VALUES ("Consejo de profesionales de la salud", "El consejo de profesionales de la salud (CPS) es un cuerpo regulador independiente en el Reino Unido, responsable de fijar y mantener
los estándares del entrenamiento profesional, así como supervisar la realización y conducta de las doce profesiones de la asistencia
sanitaria que regula. El registro en el CPS significa que se reúnen los estándares de entrenamiento y capacidades profesionalesacordados y, si algún miembro no cumple estos estándares, puede que su capacidad para la práctica sea investigada por el CPS. El
CPS es responsable de desarrollar estrategias y políticas y está formado por 24 miembros (un representante de cada una de las
profesiones reguladas y 12 miembros laicos) más un presidente. Además, el CPS dirige comités que ayudan al consejo con su trabajo.
Para más información sobre los comités del CPS, véase la sección de comités en la página web: http://www.hpc-uk.org
El CPS regula las siguientes profesiones: terapeutas artísticos, traumatólogos, científicos de ciencias biomédicas, técnicos ortopédicos u
ortoprotésicos, podólogos, paramédicos, científicos clínicos, fisioterapeutas, dietistas, radiólogos, terapeutas ocupacionales y
logopedas.
Nuestro agradecimiento a Niamh O'Sullivan, del CPS.");
INSERT INTO keywords (name, description) VALUES ("Consentimiento", "El consentimiento es el permiso que da una persona para ser tratada, explorada o sometida a un procedimiento de asistencia, ya se trate
de la propia persona ya de un menor que esté bajo su cuidado. El consentimiento válido debe obtenerse antes de empezar cualquier
intervención. Los pacientes tienen derecho a decidir, y el consentimiento es una parte fundamental de la buena práctica. Un profesional
de la salud que no respeta este principio puede ser responsable tanto de la acción legal por el paciente como de la acción interpuesta
por su propio cuerpo profesional. Los cuerpos de empresarios pueden ser también responsables de las acciones de sus empleados.
La ley de casos ha establecido que, además, tocar a una persona sin el consentimiento válido puede constituir una ofensa. Si los
profesionales de la salud no obtienen el consentimiento apropiado y el paciente posteriormente sufre un daño como resultado del
tratamiento, esto puede ser un factor en una reclamación de negligencia contra el profesional implicado.");
INSERT INTO keywords (name, description) VALUES ("Consentimiento informado", "Proceso por el que los pacientes, clientes y participantes de una investigación están completamente informados de los procedimientos
que llevarán a cabo para que puedan realizar una elección informada. Asegurar un consentimiento informado es una responsabilidad
moral y legal de los profesionales de la salud.");
INSERT INTO keywords (name, description) VALUES ("Consolidación", "Proceso de solidificación, que se observa especialmente en el pulmón cuando el fluido se solidifica.");
INSERT INTO keywords (name, description) VALUES ("Consumismo", "Práctica de compra y venta de bienes en un mercado libre y a precio de mercado. Las reformas del Gobierno, por ejemplo el NHS y el
Community Care Act (1990), han intentado dar a pacientes y clientes (consumidores) más posibilidades dentro de los servicios sociales
y sanitarios. Sus posibilidades son, sin embargo, limitadas debido a los recursos restringidos y a la falta de control. Así, el mercado
asistencial sociosanitario puede considerarse un »cuasi-mercado«.
Véase Mercado interno.");
INSERT INTO keywords (name, description) VALUES ("Contracción de Braxton Hicks", "Contracciones rítmicas del músculo uterino que tienen lugar durante la gestación para facilitar un mejor flujo sanguíneo hacia la placenta
y el feto.");
INSERT INTO keywords (name, description) VALUES ("Contracción isotónica", "Carga constante de un músculo, con velocidad variable.");
INSERT INTO keywords (name, description) VALUES ("Contractura", "Acortamiento anormal del tejido.");
INSERT INTO keywords (name, description) VALUES ("Contractura de Dupuytren", "Contracción fibrosa de la fascia palmar de la mano, que puede producir una deformidad de flexión de las articulaciones
metacarpofalángicas e interfalángicas proximales; es común en personas de origen anglosajón. La causa es desconocida, pero un
traumatismo menor y una predisposición genética pueden desempeñar un papel importante; otros factores de riesgo son el alcoholismo,
la diabetes y las enfermedades hepáticas. Pueden verse afectadas una o ambas manos. El dedo más a menudo afectado es el anular, se
guido de meñique, corazón e índice. Se desarrolla un nódulo dentro del tejido conectivo que acaba dando lugar a una banda con forma
de cuerda. El movimiento de extensión del dedo se ve limitada. La alteración es más común a partir de la edad de los 40 años, siendo
más frecuente en hombres que en mujeres.
Síntomas• Nódulo indoloro en la palma de la mano.
• Engrosamiento de las líneas en las palmas de las manos.
• Dificultad en la extensión de los dedos, especialmente el cuarto y el quinto.");
INSERT INTO keywords (name, description) VALUES ("Contraindicación", "Cualquier tratamiento que causa graves resultados adversos y posiblemente irreversibles; por ejemplo, usar SWD a 3-5 m del paciente
con un estimulador interno como un marcapasos; aplicar calor o frío a un área que es incapaz de absorberlo o disiparlo adecuadamente
(p. ej., circulación local reducida); aplicar corriente alterna a través del tórax; aplicar UVR o láser (clase 3B) sin que el terapeuta o el
paciente lleven puestas gafas que los protejan específicamente de las ondas.
Véase Efectos interactivos.");
INSERT INTO keywords (name, description) VALUES ("Contrairritante", "Irritante que es administrado a una parte del cuerpo para aliviar una irritación existente en otra. El principio del contrairritante puede
comprobarse en la vida diaria: si nos golpeamos la espinilla contra una mesa, nos frotamos a fin de aliviar el dolor; cuando paramos de
frotarnos, el dolor regresa. En fisioterapia esto es un concepto importante: los aerosoles de calor actúan según este principio, causando
una irritación menor en la piel; la terapia con hielo tendría el mismo efecto, así como las fricciones transversas y la neuroestimulación
eléctrica transcutánea (TENS).");
INSERT INTO keywords (name, description) VALUES ("Contralateral", "Miembro del lado contrario del cuerpo. Comparar con ipsolateral, que hace referencia al mismo lado.");
INSERT INTO keywords (name, description) VALUES ("Control motor", "Capacidad para controlar los movimientos del cuerpo de manera funcional y adecuada.");
INSERT INTO keywords (name, description) VALUES ("Contusión", "Hematoma.");
INSERT INTO keywords (name, description) VALUES ("Coordinación motora visual", "Capacidad para coordinar la visión con movimientos o partes del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Cor pulmonale", "Insuficiencia cardíaca derecha secundaria a una enfermedad pulmonar primaria. Se asocia a menudo con EPOC grave y al resultado de
una hipoxemia secundaria debida a la respuesta refleja (a hipoxemia) de vasoconstricción pulmonar. Otros factores que contribuyen e
interactúan con el cor pulmonale incluyen aumento de la viscosidad de la sangre (con policitemia), hipoxia miocárdica (causando
contracción y función ventricular deficiente), destrucción del lecho vascular pulmonar (en asociación con cambios patológicos en el
pulmón enfisematoso) y acidosis (que causa retención secundaria de agua y sodio).");
INSERT INTO keywords (name, description) VALUES ("Corea", "Término neurológico que hace referencia a movimientos espontáneos e irregulares, a veces bruscos. Pueden variar en apariencia desde
mera inquietud hasta agitación e incluso series de movimientos violentos (Stokes, 1998).");
INSERT INTO keywords (name, description) VALUES ("Corpúsculo de Meissner", "Se encuentran exclusivamente en pequeñas elevaciones de la dermis que se proyectan en la epidermis de la piel sin vello. Estos
receptores responden a vibraciones de baja frecuencia. Se sitúan cerca de la superficie de la piel y tienen pequeños campos receptivos,
pero se adaptan rápidamente al estímulo.");
INSERT INTO keywords (name, description) VALUES ("Corpúsculos de Pacini", "Mecanorreceptores de rápida adaptación. Los corpúsculos de Pacini contienen una fibra nerviosa aferente rodeada por una cápsula.
Son sensibles a estímulos de alta frecuencia, así como a las vibraciones.");
INSERT INTO keywords (name, description) VALUES ("Correlación (r)", "Término de investigación que se aplica a la técnica estadística usada para valorar la relación entre dos variables. Los valores de rpueden variar entre − 1 y + 1.");
INSERT INTO keywords (name, description) VALUES ("Corriente", "Término electroterápico. Flujo de partículas cargadas (iones o electrones) por unidad de tiempo. La corriente clínica suele expresarse
en mA; si se usa microcorriente, en μA. Para tratar las heridas en la piel se utiliza corriente baja (p. ej., para curación de las heridas), ya
que la impedancia de la piel se reduce notablemente, pues la piel lesionada elimina la mayor parte del componente de impedancia
capacitativa. A medida que la corriente pasa a través de la piel, se extiende más si los electrodos se encuentran alejados y/o si se utiliza
una intensidad más alta, y mucho menos si se utiliza una intensidad baja o cerrada. La extensión de la corriente tiene lugar debido a la
baja resistencia de los tejidos subcutáneos.");
INSERT INTO keywords (name, description) VALUES ("Corriente acústica", "Movimiento unidireccional del fluido en un campo de ultrasonido. Se piensa que estimula la actividad celular, si ocurre en los límites
entre la membrana celular y el fluido tisular circundante. Puede alterar la permeabilidad de la membrana celular dando lugar a:
• Aumento de la síntesis de proteínas.
• Aumento de la secreción de los mastocitos.
• Aumento de la movilidad de los fibroblastos.
• Liberación de factores del crecimiento por parte de los macrófagos.");
INSERT INTO keywords (name, description) VALUES ("Corriente alterna", "Término electroterápico que corresponde a una de las tres categorías reconocidas de corrientes terapéuticas (pulsadas, directas y
alternas). Consiste en series continuas (trenes) de impulsos bifásicos. Los impulsos continuos pueden ser interrumpidos (bursts).
Véase Impulso para más características.");
INSERT INTO keywords (name, description) VALUES ("Corriente constante", "Término electroterápico. El término »constante« indica que la corriente es fijada por el aparato operador. Si se selecciona una
intensidad de 10 mA, la salida de la corriente permanece en 10 mA, independientemente de los cambios de resistencia o voltaje. La ley
de Ohm dice que cualquier cambio en la resistencia producirá, por lo tanto, un cambio en el voltaje. Por ejemplo, si el contacto del
electrodo se reduce, la impedancia aumentará y mucho más el voltaje. Desventaja: la densidad de la corriente aumentará a medida que
el área de contacto disminuye (mA/cm 2 ), aumentando cualquier riesgo de lesión cutánea.
Véase Voltaje continuo .
Corriente continuaTérmino electroterápico. Se aplica a una de las tres categorías reconocidas de corrientes terapéuticas (pulsada, continua y alterna).
Corriente con un flujo de carga unidireccional (electrones) y continuo (definido indistintamente como de 100 ms o de 1 s de duración).
La dirección se describe, tradicionalmente, como la establecida desde el electrodo negativo (cátodo) al positivo (ánodo). Se usa en
iontoforesis y, si se interrumpe, se utiliza para estimular músculos denervados.");
INSERT INTO keywords (name, description) VALUES ("Corriente de aumento", "Término electroterápico. En este tipo de corriente, los primeros y escasos impulsos de cada tren tienen una frecuencia más alta,
típicamente 80 Hz, que los impulsos tardíos, a menudo de 40 Hz. El objetivo es reducir la fatiga muscular asociada utilizando corrientes
pulsantes.");
INSERT INTO keywords (name, description) VALUES ("Corriente de baja frecuencia", "Término electroterápico que hace referencia al nombre alternativo para la corriente de impulso. El problema es la falta de acuerdo para
definir la baja, media y alta frecuencia. En la práctica clínica la frecuencia va normalmente desde 1 Hz a aproximadamente 200 Hz
(debe ser menor de 1 kHz o se convierte en corriente de media frecuencia).");
INSERT INTO keywords (name, description) VALUES ("Corriente de media frecuencia", "Término electroterápico; nombre alternativo para la corriente alterna en el rango de frecuencia de 1 a 10 kHz. El impulso individual
puede ser sinusoidal, rectangular o triangular.
Véase también Corriente rusa.
La corriente rusa tiene una frecuencia de 2,5 kHz, y la típicamente interfe-rencial de 4 kHz o entre 2 y 10 kHz.");
INSERT INTO keywords (name, description) VALUES ("Corriente farádica", "Término electroterápico utilizado por algunos fabricantes de aparatos electromédicos para indicar una corriente diseñada para la
estimulación motora. Normalmente designa una corriente pulsada con impulso bifásico, con una duración de menos de 1 ms y una
frecuencia entre 30 y 70 Hz. Las variaciones incluyen el uso de impulsos monofásicos. El término »farádica« no es útil, ya que designa
un tipo de equipo con determinados parámetros ya en desuso, y no tiene una definición acordada universalmente.");
INSERT INTO keywords (name, description) VALUES ("Corriente galvánica", "Término electroterápico. Nombre antiguo para designar la corriente continua, aún utilizada por fabricantes de aparatos de
electromedicina. También existe la corriente galvánica interrumpida: impulsos unidireccionales que pueden ser de formas rectangulares,
trapezoidales, triangulares, etc., con duraciones de entre 10 μs y 600 ms, una frecuencia entre 1 y 1,5 Hz, utilizados para la valoración
de la fuerza-duración.Impulsos separados por intervalos entre impulsos");
INSERT INTO keywords (name, description) VALUES ("Corriente pulsada", "Término electroterápico que se aplica a una de las tres categorías reconocidas de las corrientes terapéuticas (corrientes alterna, pulsada
y directa). Serie de impulsos separados por intervalos interimpul-so. La duración del impulso varía en un rango de μs a ms, y el impulso
puede ser monofásico (p. ej., EPAV o estimulación pulsada de alto voltaje) o bifásico (típicamente corrientes de estimulación motora o
sensorial). La característica distintiva de la corriente pulsada es que tiene un intervalo entre impulsos sucesivos (intervalo interimpulso).
Una frecuencia de 50 Hz, por ejemplo, indica 50 impulsos separados por segundo.
Véase también Impulso.");
INSERT INTO keywords (name, description) VALUES ("Corriente rusa", "Término electroterápico. Corriente alterna con una frecuencia de impulso de 2,5 kHz (frecuencia portadora), impulsos rectangulares,
triangulares o sinusoidales y una frecuencia de ráfaga de 50 Hz, empleada para la estimulación motora. La duración de las ráfagas es
típicamente de 10 ms (intervalo entre ráfagas = 10 ms), pero puede ser menor, especialmente si el objetivo es reducir la velocidad de
fatiga en el músculo que está siendo estimulado. El nombre de la corriente se debe a su utilización por Kots en Rusia para el
entrenamiento de atletas de élite en los juegos olímpico de Montreal en 1976.
Véase Corriente alterna.");
INSERT INTO keywords (name, description) VALUES ("Corte en asa de cubo", "Tipo de corte del menisco en la articulación de la rodilla. Se extiende por toda la longitud del menisco, dentro del cuerpo del menisco.
(A) Corte en asa de cubo; (B) corte radial; (C) separación completa
Este corte permite a la porción interna del menisco rasgado deslizarse dentro de la articulación. Normalmente da lugar a una rodilla
»bloqueada«.");
INSERT INTO keywords (name, description) VALUES ("Corteza adrenal", "Segmento externo de la glándula adrenal que segrega cortisol cuando es estimulado por la hormona pituitaria adrenocortitropa (ACTH).");
INSERT INTO keywords (name, description) VALUES ("Corteza cerebelosa", "La materia gris que descansa debajo de la superficie pial del cerebelo.");
INSERT INTO keywords (name, description) VALUES ("Corteza motora", "Área del cerebro que contiene el área motora primaria, el área premotora y el área suplementaria.Corticoides
Hormonas (naturales o sintéticas) asociadas con la corteza suprarrenal que desempeñan un papel determinante en la regulación del agua
y los electrólitos y otras funciones corporales clave (p. ej., funciones cardíaca y renal y procesos metabólicos).");
INSERT INTO keywords (name, description) VALUES ("Cortisona", "Véase Corticoides.");
INSERT INTO keywords (name, description) VALUES ("Costocondral", "Perteneciente a las costillas y al cartílago asociado.");
INSERT INTO keywords (name, description) VALUES ("Costofrénico", "Perteneciente a las costillas y al diafragma; por ejemplo, el ángulo costofrénico en una radiografía de tórax es el ángulo formado en el
punto en que la pleura costal se encuentra con el diafragma.");
INSERT INTO keywords (name, description) VALUES ("Costovertebral", "Perteneciente a las costillas y a la columna vertebral.");
INSERT INTO keywords (name, description) VALUES ("Course leader", "Persona que es becada por la universidad (y algunas veces por el cuerpo profesional) para administrar un cuerpo específico (p. ej.,
fisioterapia).");
INSERT INTO keywords (name, description) VALUES ("Coxalgia o coxodinia", "Dolor en el cóccix. Es causado a menudo por un traumatismo, como una caída sobre las nalgas; suele ser muy intenso.
Las tres principales áreas motoras de la corteza cerebral del cerebro humano. Estas localizaciones son sólo aproximadas, ya que los estudios neuroanatómicos y
neurofisiológicos detallados se han realizado en monos y no en humanos");
INSERT INTO keywords (name, description) VALUES ("CPK", "Abreviatura médica común que corresponde a creatinfosfocinasa.");
INSERT INTO keywords (name, description) VALUES ("CPRE", "Abreviatura médica común de colangiopancreatografía retrógrada endoscópica.
Test diagnóstico para valorar el duodeno, los conductos biliares, la vesícula y el conducto pancreático. El procedimiento se lleva a cabo
utilizando un instrumento de visualización largo y flexible.Crepitación
Ruido o sensación rechinante dentro de una articulación u otro tejido.");
INSERT INTO keywords (name, description) VALUES ("Crepitantes", "Nombre antiguo para el crujido en una auscultación con estetoscopio.");
INSERT INTO keywords (name, description) VALUES ("Crioterapia", "Uso local o general de frío. Más comúnmente utilizada para reducir la extensión del dolor agudo o respuestas del cuerpo a
traumatismos agudos (es decir, más efectivo en los primeros minutos u horas). Los métodos locales incluyen la aplicación de bolsas de
gel en una cubierta húmeda o puño hinchable a través del cual circula el agua fría. Los paquetes de hielo se suelen utilizar conjuntamente
con reposo o compresión y, dependiendo de la región afectada, elevación (RICE o CRIE dependiendo de si el énfasis está en el
enfriamiento (hielo) o en la compresión. Los métodos generales o sistémicos incluyen una temperatura aérea ambiental reducida,
bañarse en agua que contiene hielo o la distracción quirúrgica del aporte sanguíneo a través de un sistema de enfriamiento externo. El
enfriamiento reduce los requerimientos metabólicos durante y tras su aplicación.");
INSERT INTO keywords (name, description) VALUES ("¿Qué le pasa a un vaso sanguíneo cuando se enfría?", "Si un fisioterapeuta coloca un paquete de hielo en un vaso sanguíneo, para minimizar el contacto con el medio ambiente frío y la pérdida
de calor futuro, el revestimiento de la musculatura lisa de las paredes de los vasos se contraerá, causando así la disminución del
diámetro del vaso sanguíneo (vasoconstricción). Después de unos 5 min, el músculo de la pared del vaso comienza a paralizarse. Si esta
vasoconstricción continuase, los tejidos que ese vaso irriga comenzarían a necrosarse. El vaso, por lo tanto, se vuelve a abrir
(vasodilatación inducida por el frío). Sin embargo, esto no es de ayuda, ya que al volverse a abrir, se pone en contacto con más frío.
Durante todo el tiempo que el paquete de hielo permanece en esta localización, el vaso está constantemente cambiando entre
vasoconstricción y vasodilatación en un intento de buscar el diámetro más adecuado. Esto se conoce como la reacción de búsqueda de
Lewis.
El hielo se considera como un procedimiento que limita el daño inmediatamente después de una lesión de los tejidos como rotura o
esguince. El hielo debería aplicarse probablemente durante poco más de 2-3 min, y después debería reaplicarse regularmente para
enfatizar el efecto de vasoconstricción. Hay muy pocas pruebas sobre los efectos antiinflamatorios del hielo después del período agudo.");
INSERT INTO keywords (name, description) VALUES ("Otros efectos del hielo", "La aplicación de hielo estimula el dolor y la sensación de frío, pero si el frío es lo suficientemente intenso, ambas sensaciones quedan
suprimidas. Las fibras de pequeño diámetro amielínicas del grupo 4 son las menos afectadas, y las fibras con mielina son las más
afectadas.
La fuerza muscular disminuye con el enfriamiento, pero aumenta más allá de su valor inicial 1 h después. El frío es útil en la disminución
del espasmo y espasticidad muscular.
A medida que la temperatura cutánea disminuye, la necesidad de producir calor interno aumenta; esto se logra parcialmente mediante
contracciones musculares (temblores). Asimismo, el hecho de adoptar una posición fetal ayuda a reducir la pérdida de calor.
Finalmente, no debe olvidarse que el hielo puede causar una sensación desagradable, por ejemplo en manos, pies, abdomen, etc. Debe
tenerse esto en cuenta al aplicar crioterapia a los pacientes.
Los efectos del frío han sido estudiados en vasos sanguíneos caninos y humanos. Se llegó a las siguientes conclusiones que tienen en
cuenta los fenómenos de la reacción de búsqueda que se observa en las extremidades humanas cuando se exponen a frío intenso:
• Durante la exposición al frío, existe un notable aumento de la afinidad de los alfa-adrenoceptores por la noradrenalina. Esto da lugar a
una potente constricción de los vasos sanguíneos y al cese de flujo sanguíneo al tejido distal.
• A medida que la temperatura de estos tejidos disminuye rápidamente, se interrumpe la conducción nerviosa simpática y tiene lugar la
vasodilatación, debido a que cesa la liberación de noradrenalina y a la acción depresora del frío en la »maquinaria« contráctil. El retorno
sanguíneo resultante recalienta el tejido, se reestablece la conducción nerviosa, y todo esto, combinado con el aumento de la afinidad de
los alfa-adrenoceptores por la noradrenalina, da lugar a una nueva vasoconstricción.
• La repetición de este ciclo podría dar lugar a la reacción de búsqueda (Shepherd y Rusche, 1983).");
INSERT INTO keywords (name, description) VALUES ("Crisis de Addison", "Estado agudo de insuficiencia adrenocortical profunda que pone en peligro la vida.");
INSERT INTO keywords (name, description) VALUES ("Criterio (en auditoría)", "Declaración explícita que define un atributo específico de un estándar que puede ser medido.Criterios de exclusión
Término de investigación que se aplica a los criterios por los que algunos miembros de la población de la muestra serán excluidos; por
ejemplo, en un estudio de la frecuencia cardíaca, las personas con una historia de problemas cardíacos serían excluidas.");
INSERT INTO keywords (name, description) VALUES ("Criterios de inclusión", "Término de investigación; criterio que define quién es apto para participar en un estudio clínico determinado.");
INSERT INTO keywords (name, description) VALUES ("Criterios de Nueva York modificados", "Criterios para el diagnóstico de espondilitis anquilosante (1984):
1. Dolor lumbar durante al menos 3 meses, que mejora con el ejercicio y no se alivia con el reposo.
2. Limitación de los movimientos de la columna lumbar en los planos sagital y frontal.
3. Disminución de la expansión torácica en relación con los valores normales según edad y sexo.
4. Sacroileítis bilateral, grado 2-4.
5. Sacroileítis unilateral, grado 3-4.");
INSERT INTO keywords (name, description) VALUES ("Cromosoma Y", "Cromosoma que determina el sexo masculino en la mayoría de los mamíferos.");
INSERT INTO keywords (name, description) VALUES ("Cronaxia", "Término electroterápico que hace referencia a una medida aplicada a la gráfica intensidad-tiempo para evaluar la función nerviosa
periférica. Cálculo basado en la reobase, ya que se define como la duración requerida para percibir una respuesta mínima (motora o
sensitiva dependiendo del test) con una intensidad doble de la reobase, utilizando impulsos monofásicos y una frecuencia de
aproximadamente 1 Hz. Los valores normales varían dependiendo de si se utiliza corriente constante o un estimulador de voltaje
constante.
Pueden consultarse textos de electroterapia para ver los valores normales.");
INSERT INTO keywords (name, description) VALUES ("Crónico", "Que persiste durante mucho tiempo; corresponde a un estado de estancamiento en los tejidos.");
INSERT INTO keywords (name, description) VALUES ("CSP", "Chartered Society of Physiotherapy. Estatuto de la sociedad de fisioterapia, el cuerpo profesional de fisioterapeutas del Reino Unido.");
INSERT INTO keywords (name, description) VALUES ("Cuadraparesia", "Debilidad de los cuatro miembros.");
INSERT INTO keywords (name, description) VALUES ("Cuádriceps femoral", "Músculo grande localizado en la parte delantera del muslo, formado por el recto femoral, el vasto medial, el vasto lateral y el vasto
intermedio.");
INSERT INTO keywords (name, description) VALUES ("Cuadriplejía", "Parálisis de los cuatro miembros.");
INSERT INTO keywords (name, description) VALUES ("Cuasimercado", "Véase Mercado interno.");
INSERT INTO keywords (name, description) VALUES ("Cuello rígido", "Véase Torticolis espasmódico.");
INSERT INTO keywords (name, description) VALUES ("Cuerno posterior", "Región dorsal de la médula espinal que contiene los cuerpos celulares.Cuernos anteriores
Son las proyecciones de la materia gris que descansan en la parte anterior de la materia gris de la médula espinal. El tamaño de los
cuerpos anteriores refleja la cantidad de los músculos esqueléticos inervados a ese nivel. Así, son más grandes en la región cervical y
lumbar debido a la inervación de la musculatura de las extremidades.");
INSERT INTO keywords (name, description) VALUES ("Cuerpo libre", "Objeto localizado dentro de una articulación que se ha separado y se mueve en el interior de la articulación. Es causa común de
bloqueo articular.");
INSERT INTO keywords (name, description) VALUES ("Cuestionario", "Formato común para obtener datos de investigación de una población; existen varias formas de presentación de un cuestionario
mediante impresos vía postal, por teléfono, etc. Cada una de ellas tiene sus ventajas y desventajas. El diseño del cuestionario debe ser
planificado y pensado de manera cuidadosa. Hay que considerar los siguientes puntos en el diseño de un cuestionario:
• La primera prioridad es valorar si un cuestionario es una herramienta de investigación adecuada para la cuestión que se desea tratar.
Si es así, ¿cómo asegurar la validez y fiabilidad?, es decir, ¿existe ya un cuestionario validado?
• Un cuestionario debe:
— Someterse a una fase piloto adecuada.
— Tener una introducción breve y una página de cubierta.
— Ser claro y fácil de entender por los encuestados; por ejemplo, evitar la jerga que no vaya a ser entendida.
— Estar estructurado y presentado profesionalmente con gramática adecuada.
— Evitar sesgos.
— Explicar el fundamento en que se basan las cuestiones preguntadas.
— No incluir frases tendenciosas.
— Presentar las cuestiones sucintamente.
— Garantía de confidencialidad y anonimato del encuestado.
— Tener un número de serie.
— Tener páginas numeradas.
— Tener una dirección de retorno.
— Tener casillas de codificación formateadas claramente.
— Limitarse a las preguntas esenciales.
— Indicar qué deberán hacer los encuestados al final.
— Incluir un formulario de consentimiento informado, o detalles de aprobación ética si son necesarios.");
INSERT INTO keywords (name, description) VALUES ("Cuestionario de la valoración de la salud (CVS)", "Medida de resultados muy útil en la artritis crónica (Fries y cols., 1980).");
INSERT INTO keywords (name, description) VALUES ("Cuidado", "Concepto multifacético que sugiere el interés y la consideración de otros. El cuidado puede ser expresado de muchas maneras,
incluyendo el dar asistencia práctica, apoyo emocional, apoyo social, consejo, intimidad física y oración. El cuidado puede ser
agobiante y opresivo, si los destinatarios tienen poco control sobre la cantidad de cuidado que reciben, sobre el que se lo proporciona
y el modo en el que es dado. El cuidado, en esta situación, puede estar estrechamente relacionado con el control.");
INSERT INTO keywords (name, description) VALUES ("Cuidado de la comunidad", "Cuidado proporcionado principalmente por los miembros de la familia, en diversos modos, en la comunidad. Más formalmente, elcuidado de la comunidad abarca un conjunto diverso de políticas asociadas con la desinstitucionalización, teniendo como eje central el
NHS y el Community Care Act (1990). Está dirigido a grupos de personas con dificultades de aprendizaje o enfermedad mental, así
como a personas mayores.");
INSERT INTO keywords (name, description) VALUES ("Cuidado domiciliario", "Cuidados médicos y nos médicos que se proporcionan a personas enfermas y discapacitadas en sus propias casas. Incluyen servicios
del tipo »comidas sobre ruedas«, asistencia de enfermería y fisioterapia.");
INSERT INTO keywords (name, description) VALUES ("Cuidado informal", "Cuidado y asistencia proporcionados por cuidadores no remunerados (normalmente parientes, pero a veces amigos y vecinos) que
tienen una relación afectiva o un sentimiento de responsabilidad hacia la persona necesitada de asistencia.");
INSERT INTO keywords (name, description) VALUES ("Cuidado paliativo", "Enfoque que mejora la calidad de vida de los pacientes que están enfrentándose a una enfermedad terminal y la de sus familiares.
Cuidado paliativo:
• Proporciona alivio del dolor.
• No tiene intención de apresurar o aplazar la muerte.
• Incorpora aspectos espirituales y psicológicos en el cuidado de los pacientes.
• Ofrece un sistema de apoyo para ayudar a los pacientes a tener una vida lo más activa posible hasta su muerte.
• Ofrece un sistema de apoyo para ayudar a las familias durante la enfermedad del paciente, incluyendo asesoramiento psicológico para
el duelo en caso necesario.
Definición de cuidado paliativo según la Organización Mundial de la Salud (OMS) (2002).");
INSERT INTO keywords (name, description) VALUES ("Cuidador", "Persona no profesional de la salud que participa en el cuidado de una persona con alteración médica.");
INSERT INTO keywords (name, description) VALUES ("Culpabilización de la víctima", "Tendencia a culpar a una persona que presenta una salud deficiente u otra dificultad. Un fumador, por ejemplo, puede ser culpado de
sufrir cáncer de pulmón. La culpabilización de la víctima niega la influencia de los factores económicos, políticos y sociales sobre el
comportamiento de la persona, sobre el que pueden no tener mucho control.");
INSERT INTO keywords (name, description) VALUES ("Cultura", "Valores, creencias, costumbres, normas, prácticas y modos de vivir en una sociedad. La cultura abarca todo aquello que se transmitesocialmente.");
INSERT INTO keywords (name, description) VALUES ("Cuñas", "Las cuñas pueden ser de tamaños muy diversos; se utilizan para ayudar a mantener la posición de los pacientes y eliminar patrones de
actividad muscular, es decir, una cuña bajo las rodillas en decúbito supino puede introducir la flexión en una posición extensora
dominante. Alternativamente puede ser también usada para mantener áreas de bajo tono, como por ejemplo,");
INSERT INTO keywords (name, description) VALUES ("Paciente en decúbito supino con cuña", "bajo la cabeza y zona superior del tórax para interrumpir la caída hacia atrás de un hombro con bajo tono. Las cuñas son un elemento
coadyuvante útil para el tratamiento.");
INSERT INTO keywords (name, description) VALUES ("Curva de disociación de la oxihemoglobina", "Curva sinusoidal que se obtiene cuando la saturación de Hb con oxígeno se traza como función de PaO 2 (es decir, la curva demuestra
la relación de la saturación de Hb con los cambios en la presión parcial arterial de oxígeno). La parte aplanada superior de la curva,
donde existen cambios mínimos en la PaO 2 , demuestra la gran afinidad de la Hb por el oxígeno y representa la circulación arterial. Por
debajo de una PaO 2 de ∼ 8 kPa (nivel de funcionamiento normal de los tejidos) la curva asciende bruscamente y la saturación de Hb
con oxígeno cae; dado que la afinidad de la Hb por el oxígeno se reduce, éste es fácilmente repartido a los tejidos.
En pacientes con enfermedad pulmonar crónica que presentan fallo respiratorio de tipo II, se recomienda que el oxígeno se valore para
conseguir y mantener una saturación de oxígeno del 90%, ya que no existe mayor beneficio clínico con una saturación más alta, mientras
que la sobreoxigenación en pacientes hipóxicos suele generar un empeoramiento de la acidosis.");
INSERT INTO keywords (name, description) VALUES ("Curva de longitud-tensión", "Es la relación entre la capacidad de contracción de un músculo y su longitud. Los músculos que han sido alargados, por ejemplo al ser
inmovilizados con yeso, generan tensión más lentamente que los músculos que han sido acortados. Los músculos cortos generarán
tensión rápidamente, tendiendo así a ser utilizados primero. Es un fundamento básico para la selección seriada. Imagine una banda
elástica colocada alrededor de los dos dedos índices; la goma generará más tensión a medida que se vayan separando los de dos. Si se
elige una goma elástica más pequeña, la tensión se generará con más rapidez.D");
INSERT INTO keywords (name, description) VALUES ("Datos", "Término de investigación utilizado para designar informaciones, hechos y cifras que han resultado de un estudio.
Los datos pueden ser de cuatro tipos:
1. Nominales. Datos que pueden nombrarse; por ejemplo, hombre o mujer, sí o no.
2. Ordinales. Ligeramente más detallados; pone los datos en orden, por ejemplo:
• Claramente de acuerdo.
• De acuerdo.
• Ni de acuerdo ni en desacuerdo.
• En desacuerdo.
• En fuerte desacuerdo.
3. Intervalo. Como en los anteriores, pero asume intervalos iguales entre las categorías.
4. Tasa o proporción. Como en los anteriores, pero también posee un punto cero.
Esto es importante en investigación porque el tipo de datos determina los métodos estadísticos que deben utilizarse.");
INSERT INTO keywords (name, description) VALUES ("Datos ordinales", "Término de investigación que hace referencia a una escala en que los números se encuentran ordenados, pero no necesariamente con la
misma distancia entre cada categoría.");
INSERT INTO keywords (name, description) VALUES ("DCC", "Abreviatura médica para referirse a la dislocación congénita de la cadera.");
INSERT INTO keywords (name, description) VALUES ("Débito de oxígeno", "Fenómeno que ocurre después del ejercicio prolongado en el que ha existido un »gran gasto« de las reservas metabólicas que deberán
ser »reembolsadas« después del ejercicio.");
INSERT INTO keywords (name, description) VALUES ("deca-", "Prefijo de origen griego que significa »diez«.");
INSERT INTO keywords (name, description) VALUES ("deci-", "Prefijo de origen griego que significa »décima parte«.");
INSERT INTO keywords (name, description) VALUES ("Declaración de CONSORT (informe consolidado de ensayos clínicos)", "Recomendaciones para mejorar los artículos de ensayos aleatorios controlados de las publicaciones. Un diagrama de flujo y un listado
de comprobación permiten a los lectores entender el comportamiento/dirección del estudio y valorar la validación de resultados.");
INSERT INTO keywords (name, description) VALUES ("Decorticación", "Extirpación quirúrgica de la pleura del pulmón.");
INSERT INTO keywords (name, description) VALUES ("Dedo en gatillo", "Tiene lugar cuando hay una formación de un nódulo dentro del tendón del flexor de la mano. Normalmente es secundario a una
tenosinovitis (generalmente debida a sobreuso) o a una artritis reumatoide. Más comúnmente, el nódulo queda atrapado debajo del
ligamento metacarpofalángico, cuando el tendón se flexiona. La inyección de corticoides puede aliviar los síntomas, pero a veces hay
que recurrir a la intervención quirúrgica.Dedo en gatillo");
INSERT INTO keywords (name, description) VALUES ("Dedo del pie en martillo", "Deformidad del pie en que la articulación IFP se flexiona y la IFD se extiende. La articulación MTF está normalmente extendida o
permanece en la posición neutra.");
INSERT INTO keywords (name, description) VALUES ("Dedo de la mano en martillo", "Patología común debida a la rotura del tendón extensor largo del dedo a nivel de su inserción en la falange distal.");
INSERT INTO keywords (name, description) VALUES ("Defecación", "Proceso de expulsión de las heces desde el recto.");
INSERT INTO keywords (name, description) VALUES ("Defecto del septo auricular", "Alteración hereditaria en la que el foramen oval no cierra en el nacimiento, lo que da lugar a una enfermedad cardíaca congénita.");
INSERT INTO keywords (name, description) VALUES ("Defecto del tubo neural", "Tipo de defecto del nacimiento que es resultado del fallo en el desarrollo normal de la médula espinal o el encéfalo. Un ejemplo sería la
espina bífida.");
INSERT INTO keywords (name, description) VALUES ("Dedos en martilloDeficiencia de alfa-1-antitripsina", "Forma heredada de enfisema destructivo resultante de la ausencia o de niveles inadecuados de alfa-1-antitripsina que inhibe a la tripsina
(una enzima proteolítica). La elastasa neutrófila puede no ser revisada en esta deficiencia y dar lugar a la destrucción de la elastina y la
consecuente disolución de las paredes alveolares. Esta patología debería entrar en el diagnóstico diferencial en pacientes de alrededor
de 40 años o menos que presentan EPOC (enfermedad normalmente asociada a edades más avanzadas).");
INSERT INTO keywords (name, description) VALUES ("Deformidad de Boutonnière", "Deformidad común de los dedos presente en la artritis reumatoide. Se trata de una lesión de la articulación interfalángica proximal con
daño de las fibras centrales dorsales y subluxación de las bandas laterales, con más frecuencia del dedo índice. La articulación
interfalángica distal puede hallarse en hiperextensión.");
INSERT INTO keywords (name, description) VALUES ("Deformidad en cuello de cisne", "Deformidad del dedo característica de la artritis reumatoide.");
INSERT INTO keywords (name, description) VALUES ("Deformidad en tenedor", "Típica deformidad que sigue a una fractura de Colles, en que la mano está desplazada posteriormente en relación con los huesos del
antebrazo.
Véase Fractura de Colles.");
INSERT INTO keywords (name, description) VALUES ("Deformidad en valgo", "Hace referencia a la inclinación lateral del hueso distal de una articulación desde la línea media.");
INSERT INTO keywords (name, description) VALUES ("Deformidad en varo", "Hace referencia a la inclinación medial del hueso distal de una articulación desde la línea media.Deformidad en valgo");
INSERT INTO keywords (name, description) VALUES ("Deformidad en varo", "");
INSERT INTO keywords (name, description) VALUES ("Deformidad protectora", "Postura adoptada por una persona en un intento por minimizar su malestar, dolor o discapacidad. Por ejemplo, un paciente con dolor
crónico de espalda puede adoptar una postura en que la columna se halle desplazada. Es a menudo inconsciente.");
INSERT INTO keywords (name, description) VALUES ("Degeneración walleriana", "Describe el proceso físico y químico que tiene lugar durante el cambio que experimenta el axón tras una lesión o traumatismo.");
INSERT INTO keywords (name, description) VALUES ("Delirium tremens", "Reacción aguda a la retirada del alcohol o de una droga; se caracteriza por sudoración, temblor, insomnio, frecuencia cardíaca elevada,
fiebre, ansiedad, dolor en el pecho, confusión mental y alucinaciones.");
INSERT INTO keywords (name, description) VALUES ("Demencia", "Deterioro progresivo de la memoria, intelecto y personalidad. La causa más común es la enfermedad de Alzheimer. Aunque en un
principio no afecta a la función motora, puede hacer que los pacientes sean incapaces de andar o llevar a cabo las actividades de la vida
diaria (AVD), ya que pierden la capacidad para planificarlas y organizarlas.");
INSERT INTO keywords (name, description) VALUES ("Demencia multiinfarto", "Está causada por »miniapoplejías« que pueden causar una pérdida progresiva de la función; puede empeorar por la presencia de
hipertensión y diabetes.Densidad de corriente
2 . La densidad de corriente
Término electroterápico. Corriente por unidad de área de electrodo. Se mide clínicamente en mA/cm
aumenta si se reduce el tamaño del electrodo, tanto intencionadamente o porque el gel de contacto se ha secado o porque el electrodo
no está firme y consistentemente en contacto con la piel. Si la densidad de corriente es demasiado elevada, existe el riesgo de que la
piel se queme. (Se ha visto que la taza de succión interferencial especializada, que contiene cuatro electrodos de 1 cm 2 de diámetro,
causa quemaduras cutáneas. La densidad de corriente alta con electrodos tan pequeños, combinados con una media alta de corriente
interferencial, incrementa notablemente el riesgo de lesión cutánea.)
Véase Corriente constante.");
INSERT INTO keywords (name, description) VALUES ("Densidad mineral ósea (DMO)", "Medida utilizada para valorar la densidad de un hueso en un individuo. En individuos normales sigue el patrón descrito a continuación;
está alterado en la osteoporosis.
Densidad mineral ósea a lo largo de la vida de hombres y mujeres.");
INSERT INTO keywords (name, description) VALUES ("Densidad ósea", "Véase Densidad mineral ósea.
Descripción de la masa ósea, la cual está disminuida en la osteoporosis.");
INSERT INTO keywords (name, description) VALUES ("Denuncia de irregularidades", "Proceso a través del cual un empleado de una organización hace saber la práctica o comportamiento no ético o incompetente de otros
colegas. La gente que »denuncia las irregularidades« es frecuentemente perseguida y, por ello, en 1998 se aprobó en Gran Bretaña la
Public Interest and Disclosure Act, a fin de proporcionarles algún tipo de protección.");
INSERT INTO keywords (name, description) VALUES ("Deontología", "Enfoque ético por el que los principios fundamentales, como el respeto a la autonomía, se usan para guiar la toma de decisiones.");
INSERT INTO keywords (name, description) VALUES ("Depresión", "Estado mental de tristeza y desesperación con una pérdida de interés que puede estar acompañado de insomnio, sentimientos de
desesperanza, culpa y pensamientos recurrentes de muerte o suicidio. La depresión debe ser considerada como clínica si es persistente
y grave.");
INSERT INTO keywords (name, description) VALUES ("Derechos", "Término genérico que engloba los derechos y privilegios disfrutados por el hecho de ser humano (derechos humanos) o ciudadano
(derechos civiles) si bien unos no son enteramente diferentes de los otros. Los derechos humanos pueden incluir libertad de
pensamiento, conciencia y religión, y libertad de asamblea pacífica y asociación. Los derechos civiles son reconocidos como
pertenecientes a todos los individuos dentro de una sociedad y pueden defenderse recurriendo a la ley. Los derechos desempeñan un
importante aunque discutido papel en la vida política, como por ejemplo en las reivindicaciones conflictivas entre el derecho a la vida y
el derecho de la mujer a elegir con relación al aborto.Derivación
Sistema de clasificación de pacientes de acuerdo con su enfermedad o lesión, para que puedan ser enviados al centro sanitario
apropiado.");
INSERT INTO keywords (name, description) VALUES ("Dermatitis", "Inflamación de la piel.");
INSERT INTO keywords (name, description) VALUES ("Dermatoma", "Área de piel inervada por un nivel determinado de los nervios espinales.");
INSERT INTO keywords (name, description) VALUES ("Dermatomas del miembro superiorDermatomas del miembro inferior", "");
INSERT INTO keywords (name, description) VALUES ("Dermatomiositis", "Enfermedad del tejido conectivo que se caracterizada por la tumefacción e inflamación del tejido muscular. Miopatía inflamatoria de
causa desconocida; muestra niveles elevados de creatincinasa, anormalidades electrofisiológicas e inflamación en la biopsia muscular
(Briemberg y Amato, 2003).");
INSERT INTO keywords (name, description) VALUES ("Derrame pleural", "Acumulación anormal de fluido en el espacio pleural; se clasifican según la causa. La producción aumentada de fluido pleural u
obstrucción o bloqueo del drenaje puede causar acumulación del fluido pleural. Las causas incluyen neumonía, infección vírica,
tumoraciones malignas, enfermedades del tejido conectivo, obstrucción linfática y muchas más. Las características clínicas varían con el
tamaño y el comienzo; por ejemplo, derrames pequeños pueden no dar síntomas mientras que derrames mayores estarán acompañados
de disnea y dolor tipo pleurítico seguido de la acumulación de fluido. Los derrames malignos tienen a menudo un aspecto sanguinolento,
mientras que una neumonía posbacteriana con fluido asociado turbio es calificada de empiema (fluido pleural lleno de pus). Los
procesos de exploración incluyen radiografía torácica, aspiración del fluido pleural y biopsia, ecografía torácica y biopsia toracoscópica
asistida con vídeo (TAV). El tratamiento de los derrames se determina por la causa, de forma que puede implicar la no intervención, la
administración de analgésicos y/o antibióticos, el drenaje pectoral o intervenciones quirúrgicas.");
INSERT INTO keywords (name, description) VALUES ("Desarrollo personal", "Proceso planeado a través del cual un individuo desarrolla habilidades y conocimientos beneficiosos para sí mismo y su carrera.");
INSERT INTO keywords (name, description) VALUES ("Desarrollo profesional continuado (DPC)", "Proceso por el que los trabajadores profesionales, como los fisioterapeutas, continúan desarrollando sus conocimientos y habilidades
(por medios formales e informales), una vez están cualificados para ello. El desarrollo profesional continuado se convertirá en
obligatorio para los fisioterapeutas en 2006 para permanecer en el nivel alcanzado en su puesto de trabajo dentro del NHS.");
INSERT INTO keywords (name, description) VALUES ("Desbridamiento", "Extirpación del material extraño de una herida para dejar al descubierto el tejido sano subyacente.Descompresión subacromial
Descompresión quirúrgica del hombro, normalmente con escisión de la porción lateral de la clavícula, que se lleva a cabo para aliviar el
atrapamiento.");
INSERT INTO keywords (name, description) VALUES ("Desequilibrio muscular", "Los desequilibrios de grupos musculares causan una gran variedad de patologías, desde el desgaste natural de la articulación a la artritis
y desde tendinitis a músculos doloridos. Todas las articulaciones del cuerpo están controladas por dos o más grupos de músculos.
Normalmente un grupo de músculos estabiliza y fija la articulación, mientras que otros grupos musculares adjuntos crean el movimiento.
Sin embargo, a veces un grupo llega a ser inusualmente fuerte y tenso, mientras que el grupo opuesto se debilita y aparece
sobreestirado. Este desequilibrio desemboca en un deficiente control articular y una biomecánica anormal. Si los patrones de
movimiento defectuosos se repiten muchas veces, los tejidos pueden comenzar a degenerarse. Las técnicas de desequilibrio muscular se
acercan a los pacientes que se presentan con disfunción de movimiento y sus problemas asociados. Se han sugerido numerosas
clasificaciones de desequilibrio en relación con la estructura muscular, función y respuesta a la lesión. La disfunción del movimiento
puede ser tanto local o segmentaria a nivel de una sola articulación, como global y afectar a muchos segmentos de una región.
Los músculos pueden ser estabilizadores o movilizadores. Los músculos estabilizadores son profundos, con inserciones amplias y su
papel es postural y de control dinámico. Los músculos movilizadores son productores de fuerza, están situados más superficialmente y
tienen vientres musculares largos. En ciertos estados patológicos estas dos clasificaciones de músculos cambian su patrón de
reclutamiento, lo cual desemboca típicamente en una alteración en la función.");
INSERT INTO keywords (name, description) VALUES ("Grupos musculares comúnmente afectados por desequilibrios musculares", "Músculos propensos a la rigidez (movilizadores) Músculos propensos a la debilidad (estabilizadores)");
