INSERT INTO keywords (name, description) VALUES ("Gastrocnemio", "");
INSERT INTO keywords (name, description) VALUES ("Desfibrilación", "Término dado al método de aplicación de una descarga eléctrica intencionada al corazón para devolverlo a su patrón regular de latido
cuando el músculo cardíaco muestra un patrón de contracción incoordinado (fibrilación).");
INSERT INTO keywords (name, description) VALUES ("Desgarro radial", "Tipo de desgarro meniscal que se observa en la articulación de la rodilla.
Véase Corte en asa de cubo.");
INSERT INTO keywords (name, description) VALUES ("Desinhibición", "En ocasiones un paciente pierde las inhibiciones sociales habituales y, como resultado, se comporta y expresa de un modo inapropiado.
La desinhibición se asocia con lesión de los lóbulos frontales. Por ejemplo, un paciente puede ser desinhibido sexualmente.
DesmielinizaciónProceso patológico característico de la esclerosis múltiple, que daña las vainas de mielina que rodean a los nervios, de tal manera que la
conducción nerviosa se ve alterada.");
INSERT INTO keywords (name, description) VALUES ("Desorientación", "Incapacidad para estar orientado en el tiempo, en el espacio y como persona, a veces se observa después de una lesión neurológica;
puede ser transitoria o duradera.");
INSERT INTO keywords (name, description) VALUES ("Desplazamiento", "Fenómeno por el que una persona mueve una parte del cuerpo, normalmente la columna, en un intento de adoptar la postura menos
dolorosa.");
INSERT INTO keywords (name, description) VALUES ("Despolarización", "Se produce cuando el potencial de membrana se vuelve menos negativo, dando lugar al paso de una corriente eléctrica por el nervio.
Véase Potencial de acción.");
INSERT INTO keywords (name, description) VALUES ("Desuso aprendido", "Es un término empleado para describir aquel estado en que un paciente experimenta un cierto grado de recuperación en un miembro
afectado, pero no usa esa recuperación funcionalmente ya que se ha acostumbrado a no hacerlo. Es a menudo empleado para describir
el caso de pacientes con recuperación de la funcionalidad del brazo tras una apoplejía, pero que no utilizan la actividad motora que han
recuperado en sus actividades de la vida diaria (AVD). Algunos investigadores, para el tratamiento de esta presentación, abogan por el
uso de la terapia de coacción/fuerza inducida.");
INSERT INTO keywords (name, description) VALUES ("Desviación", "Se refiere a la transgresión de una norma de comportamiento o a la posesión de un atributo o característica que transgrede la norma.
Una persona con una alteración puede ser considerada desviada, lo mismo que alguien que se niega a comprometerse con un empleo
remunerado. Sin embargo, precisamente quién o qué es considerado desviado depende de las razones de calificación y del contexto
social. La desviación, desde esta perspectiva, es una etiqueta dada a ciertos comportamientos, características o categorías de personas
en circunstancias particulares quienes, como consecuencia, son devaluados y frecuentemente excluidos. Divorciados y madres solteras
fueron considerados, por ejemplo, más desviados en el pasado de lo que están actualmente en la sociedad británica. Además, el grado
de desviación varía de un país a otro.");
INSERT INTO keywords (name, description) VALUES ("Desviación de la línea media", "Término referido a un desplazamiento de la línea media desde el centro del cuerpo.
Observación clínica Debido a los cambios de tono que siguen a una apoplejía, es común ver un desplazamiento de la línea media. El
desplazamiento aparece más comúnmente alejándose del lado hemipléjico, pero también puede ocurrir hacia el lado hemipléjico
Véase Síndrome pusher (»empujador«).");
INSERT INTO keywords (name, description) VALUES ("Desviación estándar", "Término de investigación que se aplica a la medida de la variabilidad o extensión de los datos. La desviación estándar cuantifica la
variación de los valores uno con respecto del otro. Es una medida de la extensión de las observaciones individuales en torno al valor
principal de la muestra. Una curva normal tendrá el 34% de los casos entre el valor principal y una desviación estándar por encima o
por debajo de ese valor principal; el 68% de los casos entre una desviación estándar por encima y otra por debajo del valor principal;
el 95,5% de los casos estarán entre dos desviaciones estándar del valor principal.");
INSERT INTO keywords (name, description) VALUES ("Diafragma", "Es el músculo inspiratorio más importante (con forma de cúpula); está constituido por aproximadamente un 50% de fibras de tipo 1 y
50% de fibras musculares de tipo 2, permitiendo contracciones rápidas, fuertes, de intensidad baja y prolongadas. Los pilares del
diafragma se insertan en las vértebras lumbares superiores, y su porción costal en el tubérculo interno de las seis costillas inferiores. En
contracción (es decir, en la inspiración), el diafragma desciende contra las vísceras abdominales (empujando la pared abdominal hacia
fuera), usando el abdomen como un fulcro sobre el cual elevar la caja torácica, provocando un aumento de la presión intraabdominal. El
movimiento interno del diafragma en la inspiración (movimiento paradójico) es indicador de fatiga, debilidad o parálisis del diafragma.
Los volúmenes pulmonares elevados reducirán la longitud de reposo del diafragma y, por lo tanto, proporcionarán una desventaja
mecánica para la contracción (como en los estados de hiperinsuflación, como la obstrucción crónica del flujo aéreo; éstos pueden darlugar a un aumento del trabajo de la respiración y predisponer a fatiga diafragmática e insuficiencia de bombeo respiratorio).");
INSERT INTO keywords (name, description) VALUES ("Diagnóstico", "Determinación de la naturaleza o causa de una enfermedad, a menudo indicada en las notas médicas con el símbolo Δ. Evaluación de la
historia médica de un paciente, síntomas clínicos y exámenes de laboratorio que confirman o establecen una enfermedad.");
INSERT INTO keywords (name, description) VALUES ("Diagrama de movimiento", "Concepto de utilidad en terapia manual, que permite al terapeuta analizar los resultados de su examen. Maitland afirma que el diagrama
de movimiento es »un mapa dinámico que representa la calidad y cantidad de movimiento pasivo percibido por el fisioterapeuta durante
su examen… incluirá la cantidad, comportamiento y relaciones de algunos de los hallazgos físicos anormales encontrados, por ejemplo
dolor, resistencia, espasmo, etc.«.
Se emplea como herramienta de autoaprendizaje, método de enseñanza y forma de comunicación. Para mayor información se aconseja
al lector consultar la obra Vertebral manipulation (2001) de Maitland. A continuación se muestran diferentes ejemplos de diagramas
del movimiento.");
INSERT INTO keywords (name, description) VALUES ("Diálisis", "Procedimiento que utiliza una máquina para filtrar los productos de desecho del torrente sanguíneo.Diastasis del recto abdominal
Separación excesiva de los músculos rectos del abdomen a la altura del ombligo, que puede producirse durante el embarazo
(Boissonnault y Blaschak, 1988).");
INSERT INTO keywords (name, description) VALUES ("Diástole", "Fase de dilatación del corazón.");
INSERT INTO keywords (name, description) VALUES ("Diatermia", "Término electroterápico que se aplica al calor profundo producido clínicamente con diatermia de onda corta (DOC), microondas
(MW) o ultrasonidos. Los riesgos dependen del método utilizado. Por ejemplo, el uso de DOC o MW a 3-5 m de un paciente con un
estimulador interno o bomba está contraindicado porque la diatermia puede alterar el funcionamiento del equipo. El ultrasonido aplicado
directamente sobre el estimulador (interno) o bomba está también contraindicado por el riesgo de alterar la función del equipo.");
INSERT INTO keywords (name, description) VALUES ("Diatermia de onda corta (DOC)", "Término electroterápico que se aplica a una radiación electromagnética con una frecuencia de 27,12 MHz. La salida puede ser continua
(DOCC) o pulsada (DOCP). La DOCC se utiliza para el calentamiento profundo de los tejidos y la DOCP para favorecer la
cicatrización. Tipos: capacitativa e inductotermia. Los peligros y contraindicaciones incluyen bombas o estimuladores de funcionamiento
interno a 3-5 m o metales implantados internamente a una distancia de menos de 30 cm; si la circulación local está reducida, existe
riesgo de lesión inducida por el calor.");
INSERT INTO keywords (name, description) VALUES ("Didronel® (etidronato)", "Fármaco bifosfonado, específicamente para la prevención y tratamiento de la osteoporosis.");
INSERT INTO keywords (name, description) VALUES ("Diferencia clínica mínima importante", "Medida de interpretación de la puntuación generada por una medida de resultados. »La menor diferencia de puntuación en el ámbito de
interés que es percibida como beneficiosa por los pacientes, y que sugeriría, en ausencia de efectos secundarios molestos y excesivos
costes, un cambio en la gestión del paciente« (Jaeschke y cols., 1989).
Diferencia de oxígeno alveoloarterial (gradiente P A O 2 -PaO 2 ) Es una medida de la eficiencia del pulmón para el intercambio
gaseoso. En una situación ideal, los dos valores serían los mismos, pero en el pulmón normal la diferencia de oxígeno arterial-alveolar se
aproxima a 0,5-2 kPa. En estados de hipoventilación, la diferencia será pequeña porque ambos se reducen. Sin embargo, donde se
presentan malas relaciones V/Q o donde se experimentan problemas de difusión, la PaO 2 será relativamente normal, pero la P A O 2 se
reducirá, dando lugar a una mayor diferencia A-a PO 2 .");
INSERT INTO keywords (name, description) VALUES ("Diferencia de potencial", "Término electroterápico; también denominada fuerza electromotriz. Se mide en voltios (V).");
INSERT INTO keywords (name, description) VALUES ("Dificultad respiratoria", "Uno de los cuatro síntomas cardinales de la enfermedad respiratoria. Ha sido descrita como la intensidad percibida de estímulo
producido con la respiración (Altose, 1989). Es una percepción subjetiva, relacionada con las AVD y se trata, por lo tanto, de un signo
detallado por el paciente. El médico no puede apreciar ni juzgar totalmente el nivel de disnea, como ocurre con otras sensaciones
similares (p. ej., dolor, miedo, hambre, pena, etc.). No debe confundirse con la taquipnea (frecuencia respiratoria alta). La sensación se
convierte en angustiante cuando la dificultad respiratoria percibida es mayor que la que se espera para la actividad que se lleva a cabo.
Se cree que este síntoma desempeña un papel significativo en el desacondicionamiento que se produce durante las medidas de evitación
llevadas a cabo por pacientes que sufren enfermedad pulmonar crónica.");
INSERT INTO keywords (name, description) VALUES ("Dificultades de aprendizaje", "La definición de dificultades del aprendizaje ha sido dominada por el modelo médico de incapacidad. El criterio para el diagnóstico de
dificultades de aprendizaje incluye un bajo nivel de inteligencia (valorada mediante tests de coeficiente intelectual estandarizados) y la
»incompetencia social« en términos de normas en las diversas áreas de la vida social. Más recientemente, este planteamiento ha sido
cuestionado de diferentes formas por personas con dificultad de aprendizaje y sus defensores, que han cuestionado este etiquetaje por
la marginación que genera.Difusión
Movimiento de los átomos o moléculas desde un área de alta concentración/presión hacia un área de baja concentración/presión.");
INSERT INTO keywords (name, description) VALUES ("Digital", "Familia de fármacos que aumentan la fuerza de la contracción miocárdica. La digoxina es uno de estos medicamentos; aún es muy
utilizada en pacientes con arritmias que pueden dar lugar a insuficiencia cardíaca.");
INSERT INTO keywords (name, description) VALUES ("Dilatación", "Proceso de aumento o expansión; por ejemplo, la vasodilatación es el aumento del diámetro de un vaso sanguíneo.");
INSERT INTO keywords (name, description) VALUES ("Dilatación y raspado", "Procedimiento ginecológico en que se muestra el recubrimiento del útero con un instrumento metálico denominado espéculo. Se realiza
para determinar si existe alguna anomalía en las células que recubren el útero (endometrio).");
INSERT INTO keywords (name, description) VALUES ("Dinamómetro", "Instrumento mecánico que permite medir la acción muscular concéntrica y excéntrica, la resistencia muscular y las relaciones de
equilibrio muscular.");
INSERT INTO keywords (name, description) VALUES ("Diplopía", "Visión doble.");
INSERT INTO keywords (name, description) VALUES ("Directriz clínica", "Serie de afirmaciones desarrolladas sistemáticamente, diseñadas para ayudar a que los practicantes y pacientes tomen decisiones sobre
el cuidado apropiado de la salud para cada circunstancia clínica específica.");
INSERT INTO keywords (name, description) VALUES ("Disartria", "Problemas en la articulación del lenguaje, que dan lugar a la incapacidad para hablar, causada por debilidad, falta de coordinación o
espasticidad. El paciente conserva la compresión y sabe lo que quiere decir. Se suele observar comúnmente en alteraciones
neurológicas que afectan a las neuronas motoras.");
INSERT INTO keywords (name, description) VALUES ("Discapacidad", "Término utilizado para describir la pérdida o anormalidad de una estructura psicológica, fisiológica o anatómica, o de una función. La
discapacidad también tiene una dimensión social, ya que significa cosas diferentes en sociedades diferentes en tiempos diferentes. El
término fue utilizado dentro del modelo de salud de la OMS: discapacidad, incapacidad, minusvalía. La OMS redefinió las definiciones
en 1997, con el resultado de que el término »función« se utiliza ahora en sustitución del término discapacidad. Se puede definir desde un
modelo individual (incluyendo modelos médicos y trágicos) o desde un modelo social. El modelo individual es de discapacidad
dominante y asume que las dificultades a las que se enfrentan las personas discapacitadas son el resultado directo de sus alteraciones
individuales y de la pérdida o ausencia del funcionamiento. El modelo social de discapacidad reconoce");
INSERT INTO keywords (name, description) VALUES ("los orígenes sociales de", "discapacidad en una sociedad adaptada por y para personas no discapacitadas. Las desventajas o restricciones, a menudo
denominadas barreras, se encuentran en cada aspecto del medio ambiente físico y social. La discapacidad puede, por lo tanto, ser¿De quién es el problema?");
INSERT INTO keywords (name, description) VALUES ("Discectomía", "Extirpación quirúrgica de la porción prolapsada del núcleo pulposo.");
INSERT INTO keywords (name, description) VALUES ("Discinesia", "Alteración del movimiento voluntario, que normalmente da lugar a movimientos fragmentarios o incompletos.");
INSERT INTO keywords (name, description) VALUES ("Causas principales de algunas alteraciones que causan movimientos discinésicos", "");
