INSERT INTO keywords (name, description) VALUES ("Distonía sensible a la dopa", "");
INSERT INTO keywords (name, description) VALUES ("Hemidistonía", "Lesiones de los ganglios basales (p. ej., tumores, vascular, postalamotomía)");
INSERT INTO keywords (name, description) VALUES ("Disco articular", "Término anatómico utilizado para describir una lámina de fibrocartílago unida a la cápsula de la articulación, que separa, a una distancia
variable, las superficies articulares de los huesos; mejora la congruencia articular.");
INSERT INTO keywords (name, description) VALUES ("Disco desprendido", "Término que describe el desprendimiento completo de una porción de un disco intervertebral herniado, a menudo con migración dentro
del canal vertebral.");
INSERT INTO keywords (name, description) VALUES ("Disco intervertebral", "Véase Anillo fibroso y Núcleo pulposo.
El disco forma una articulación cartilaginosa entre los cuerpos vertebrales, formada por el anillo fibroso, el núcleo pulposo y las láminas
finales del cartílago. Es la causa más común de alteraciones de la columna lumbar. Los discos intervertebrales (a los que nos referimos
como »disco«) se describen a menudo como elementos capaces de absorber cargas, permitiendo que éstas se transmitan de una
vértebra a la siguiente; ésta es sólo una parte de su función. Un papel igualmente importante del disco es permitir movimientos
controlados de pequeña amplitud entre las vértebras superior e inferior a él. Entre dos vértebras adyacentes sólo son posibles pequeños
movimientos, pero cuando se suman los movimientos de los discos de todas las vértebras, el resultado es una columna extremadamente
móvil sin que por ello se sacrifique la estabilidad. La columna vertebral normal se autoestabiliza y se utiliza muy poca acción muscular
para mantener erectos a los seres humanos, lo que queda demostrado por el hecho de que las personas que han estado encamadas
durante períodos prolongados pueden sentarse en vertical con relativa facilidad.
Función de los discos intervertebrales. A. Sólo pequeños movimientos. B. La suma de los movimientos da lugar a una gran movilidad.");
INSERT INTO keywords (name, description) VALUES ("Discriminación", "Identificación de diferencias entre individuos y grupos de personas. La discriminación puede ser positiva o negativa, aunque el término
normalmente denota negatividad. La discriminación implica no sólo el reconocimiento de diferencias, como de clase social, edad,
discapacidad y orientación sexual, sino también la respuesta negativa a un individuo o grupo, sea actitudinal, comportamental o
estructural.");
INSERT INTO keywords (name, description) VALUES ("Discriminación por razón de edad", "Creencias estereotipadas y negativas acerca de las personas mayores que pueden dar lugar a discriminación. Frecuentemente, esta
discriminación por la edad da lugar a la no prestación a las personas mayores de los servicios apropiados para ellos y a una falta de
oportunidades equitativas en comparación con otros ciudadanos.Discriminación positiva
VéaseAcción afirmativa.");
INSERT INTO keywords (name, description) VALUES ("Disdiadococinesia", "Incapacidad para llevar a cabo movimientos alternantes, rápidos y suaves, que requieren las acciones de grupos musculares opuestos.
Normalmente se valora pidiéndole a la persona que se toque las piernas con las manos, primero con la cara palmar y luego con la
dorsal rápidamente.");
INSERT INTO keywords (name, description) VALUES ("Diseño de un estudio cruzado", "Término de investigación que significa la administración de dos o más terapias experimentales, una después de la otra.
GRUPO A: TEST-TRATAMIENTO, TEST-NO TRATAMIENTO.
GRUPO B: TEST-NO TRATAMIENTO, TEST-TRATAMIENTO.");
INSERT INTO keywords (name, description) VALUES ("Disfagia", "Dificultades con la deglución normalmente vistas después de un ACV. Los pacientes pueden aspirar su comida o bebida, por lo que
ésta puede pasar a los bronquios principales y llegar hasta los pulmones. Esto puede dar lugar a serias complicaciones, y por tanto
requiere asistencia y tratamiento efectivo por el equipo multidisciplinario. Cuando se presenta, se deben establecer vías alternativas de
alimentación, por ejemplo a través de un tubo nasogástrico o mediante gastrostomía endoscópica percutánea (GEP); de lo contrario, el
paciente podría desnutrirse rápidamente.");
INSERT INTO keywords (name, description) VALUES ("Disfasia", "Alteración del lenguaje y el habla, que puede ser receptiva (dificultad de comprensión) o expresiva (dificultad de expresión). Diferentes
estrategias pueden emplearse para permitir una comunicación más efectiva. Los terapeutas del habla y el lenguaje (logopedas) pueden
aconsejar sobre los mejores métodos que se deben utilizar en cada paciente.");
INSERT INTO keywords (name, description) VALUES ("Disfunción autonómica", "Reacción anormal del sistema nervioso autónomo que sigue a una enfermedad, lesión o desequilibrio químico. Aparece más
frecuentemente dentro del sistema simpático, como respuesta a un estímulo nocivo (p. ej., enrojecimiento y sudoración de las manos).");
INSERT INTO keywords (name, description) VALUES ("Disfunción ejecutiva", "Pérdida de las funciones de alto nivel cognitivo (ejecutivo) normal debido a una lesión cerebral. Los pacientes pueden aparecer
letárgicos, escasamente motivados, desinteresados y con deficientes habilidades de planteamiento y organización; sin embargo, este
déficit puede no ser inmediatamente aparente a menos que se le pida al paciente que lleve a cabo tareas complejas. Los pacientes
suelen presentar también desinhibición, por lo que tienen grandes dificultades en situaciones sociales.Dismenorrea
Menstruación difícil y dolorosa.");
INSERT INTO keywords (name, description) VALUES ("Dismetría", "Incapacidad para ubicar los miembros adecuadamente en relación con otros objetos.");
INSERT INTO keywords (name, description) VALUES ("Disnea", "Dificultad en la respiración. La disnea es una sensación percibida por un individuo y no debe ser confundida con la taquipnea (aumento
de la frecuencia respiratoria), hiperventilación (respiración que excede las necesidades metabólicas) o hiperpnea (aumento de la
respiración). La dificultad respiratoria se ha descrito como la intensidad percibida del estímulo producido con la respiración (");
INSERT INTO keywords (name, description) VALUES ("Altose,", "1989).
Este conocimiento consciente de la respiración se convierte en una sensación insoportable, que afecta de forma grave a la existencia de
algunos pacientes pulmonares crónicos. Como la sensación es subjetiva y está relacionada con la experiencia vital, el médico no puede
apreciar completamente ni juzgar el nivel de disnea, al igual que ocurre con otras sensaciones (p. ej., dolor, miedo, hambre, pena, etc.)
(Borg, 1982).");
INSERT INTO keywords (name, description) VALUES ("Dispepsia", "Término utilizado para describir un trastorno digestivo.");
INSERT INTO keywords (name, description) VALUES ("Dispraxia", "Dificultad para llevar a cabo movimientos voluntarios intencionados en pacientes con buena compresión, sensación normal y cierta
actividad motora.");
INSERT INTO keywords (name, description) VALUES ("Distal", "Término anatómico que significa remoto, lejano de cualquier punto de referencia; lo opuesto de proximal.
Observación clínica La posición anatómica es siempre el punto de partida para tratamientos y exploraciones, por lo que, por
ejemplo, independientemente de la posición en que se encuentre el brazo de una persona, la mano es siempre distal con respecto al
codo, incluso si se eleva por encima de la cabeza.");
INSERT INTO keywords (name, description) VALUES ("Distaxia", "Dificultad en el control de los movimientos voluntarios.");
INSERT INTO keywords (name, description) VALUES ("Distonía", "Describe un movimiento anormal en el que los músculos agonistas y antagonistas se contraen isométrica e involuntariamente, dando
lugar a una postura alterada. Esto ocurre frecuentemente cuando el paciente trata de iniciar el movimiento. Está presente en algunas
alteraciones neurológicas y puede afectar a todo el cuerpo o a una parte.");
INSERT INTO keywords (name, description) VALUES ("Distonía espástica", "Término utilizado para describir la contracción crónica mantenida de un músculo que no se mueve. Se cree que está causada por una
hiperactividad muscular eferente, dependiente de la conducción supraespinal continua de las alfa-motoneuronas (Burke 1988).");
INSERT INTO keywords (name, description) VALUES ("Distribución del peso", "La distribución del peso corporal es un factor significativo que influye en la estabilidad postural. Por ejemplo, una persona es más
estable con una amplia base de sustentación que cuando está de puntillas en apoyo monopodal. Para tener estabilidad, el centro de
gravedad del cuerpo debe hallarse dentro de la base de sustentación. Un problema común en los pacientes con hemiplejía (apoplejía)
es su dificultad para mover el centro de gravedad sobre el pie hemipléjico (de ahí los problemas con el movimiento de la pierna no
afectada), pero realmente esto se debe a que la distribución del peso todavía es proporcionalmente mayor sobre el lado no afectado.");
INSERT INTO keywords (name, description) VALUES ("Distribución normal", "Término de investigación que se aplica a aquellos datos que, en una gráfica, describen una curva campaniforme. Un ejemplo sería el
número de calzado de una población: pocas personas tienen un número pequeño o grande, sino que la mayoría utilizan un calzado de
tamaño medio.Distrofia muscular
Grupo de trastornos caracterizados por debilidad muscular progresiva y pérdida de tejido muscular.
Véase la tabla siguiente para más información.");
