INSERT INTO keywords (name, description) VALUES ("Distrofia muscular de Duchenne", "Distrofia muscular hereditaria que afecta a los niños varones; progresa muy rápidamente y de forma grave. Se hereda de manera
recesiva a través del cromosoma X. Normalmente aparece antes de los 5 años de edad; normalmente su progreso es rápido y el
paciente fallece entre los 10 y 19 años debido a insuficiencia cardíaca o respiratoria.");
INSERT INTO keywords (name, description) VALUES ("Distrofia simpática refleja (DSR)", "Actualmente se conoce como síndrome de dolor regional complejo. Causado por un reflejo simpático anormal, que provoca una
respuesta desproporcionada e inconsecuente a la lesión. Es bastante variable con respecto a signos y síntomas, y su tratamiento va
desde el bloqueo simpático hasta el TENS o la fisioterapia.
Véase Síndrome hombro-mano .
DiuréticoCualquier sustancia que estimula la formación de orina. Se usan a menudo en el tratamiento de la insuficiencia cardíaca.");
INSERT INTO keywords (name, description) VALUES ("División comprador/proveedor", "División entre la adquisición o demanda y la provisión de servicios de cuidados sanitarios y sociales. En el Reino Unido, antes del NHS
y del Community Care Act (1990) , eran las agencias estatutarias de servicios sanitarios y sociales las que típicamente contrataban y
proporcionaban servicios para pacientes y clientes. Por ejemplo, los departamentos de servicios sociales eran los que contrataban y
proporcionaban instalaciones residenciales y centros de día para las personas ancianas. Actualmente se contratan servicios de muy
diversas agencias, algunas privadas y otras de voluntariado. Muchos servicios hospitalarios, como el de limpieza o el de lavandería, se
»externalizan« a compañías privadas; los médicos de atención primaria pueden contratar servicios para sus pacientes de los centros
hospitalarios de la zona, que compiten por conseguir contratos.
Véase Mercado interno.");
INSERT INTO keywords (name, description) VALUES ("DLCO", "Valoración de la función pulmonar, que detalla la capacidad de difusión del monóxido de carbono; por tanto, se trata de una medida de
la efectividad de la difusión de gas a través de la membrana capilar alveolar. Se mide en ml/min/mmHg.");
INSERT INTO keywords (name, description) VALUES ("DM", "Abreviatura médica común de diabetes mellitus.");
INSERT INTO keywords (name, description) VALUES ("DMNID", "Abreviatura médica común de diabetes mellitus no insulinodependiente.");
INSERT INTO keywords (name, description) VALUES ("Doble ciego", "Término de investigación que hace referencia, en un ensayo clínico, al procedimiento de asignación de un código numérico al
tratamiento sin dejar que el personal clínico, especialmente los responsables de administrarlo a los pacientes, conozca la asignación de
tratamientos.");
INSERT INTO keywords (name, description) VALUES ("Dolor intratable", "Es aquel que resulta difícil de controlar.");
INSERT INTO keywords (name, description) VALUES ("Dolor muscular de aparición tardía (DMAT)", "Sensación dolorosa sorda que sigue a un esfuerzo muscular al que no se está acostumbrado. El dolor alcanza su pico más alto a las 24-
48 h después del ejercicio (Vickers, 2001). El ejercicio excéntrico parece ser el tipo de ejercicio que provoca el mayor grado de dolor,
aunque el ejercicio isométrico puede también causarlo (Byrnes y Clarkson, 1986).");
INSERT INTO keywords (name, description) VALUES ("Dolor talámico", "Dolor que se origina en el sistema nervioso central (SNC), causado por lesión en la región del tálamo. Este dolor puede experimentarse
como una quemazón intensa, que normalmente empeora con el tacto y se encuentra en el lado contralateral (opuesto) a la lesión.");
INSERT INTO keywords (name, description) VALUES ("Dolor tardío", "Dolor que aparece típicamente un día después del tratamiento.");
INSERT INTO keywords (name, description) VALUES ("Dopamina", "Neurotransmisor sintetizado a partir de la dopa.");
INSERT INTO keywords (name, description) VALUES ("Dosificación", "Contexto electroterápico. Los parámetros generales de dosificación incluyen: intensidad, longitud de onda, duración y frecuencia de los
tratamientos, así como localización de la aplicación. El hecho de informar de todos los parámetros relevantes después de cada
tratamiento permite realizar las modificaciones apropiadas al repetir las terapias y también es útil en las revisiones, al analizar la
contribución de un agente electrofísico en los resultados obtenidos.");
INSERT INTO keywords (name, description) VALUES ("Doxapram", "Estimulante respiratorio central útil en la narcosis opiácea inversa. (Su eficacia no está probada en el tratamiento de los pacientes coninsuficiencia respiratoria taquipneica aguda.)");
INSERT INTO keywords (name, description) VALUES ("Drenaje autógeno", "Técnica de respiración variable diseñada para facilitar la expulsión de secreciones pulmonares, mantener óptimo el movimiento de la
pared torácica y mejorar la ventilación.
Esta técnica, ideada en Bélgica, implica el control de la respiración para alterar su velocidad, profundidad y localización, con el objetivo
de proporcionar un método más efectivo al mismo tiempo que se permite al paciente tener más independencia (la técnica puede llevarse
a cabo sin ayuda de otras personas). La técnica belga (que consta de tres fases) ha sido ligeramente modificada por los alemanes (con
una sola fase), pero los objetivos de ambos métodos son obtener el mayor flujo aéreo posible a través de los bronquios y facilitar la
eliminación de los esputos bajo los principios de respiración controlada, en pacientes con secreciones pulmonares de naturaleza o
cantidad anormales.
Drenaje autógeno: método belga. Fases del drenaje autógeno mostradas en el espirograma de una persona normal. Fase 1: despegue; fase 2: recogida; fase 3. evacuación
(ERV, volumen de reserva espiratorio; FRC, capacidad residual funcional; IRV, volumen de reserva inspiratorio; IRV + Vt + ERV, capacidad vital; RV, volumen de
reserva; Vt, volumen corriente).
Drenaje autógeno: método alemán. Drenaje autógeno mostrado en un espirograma de una persona normal. El método no se divide en diferentes fases (ERV, volumen de
reserva espiratorio; FRC, capacidad residual funcional; IRV, volumen de reserva inspiratorio; IRV + Vt + ERV, capacidad vital; RV, volumen de reserva; Vt, volumen
corriente). De: Autogenic drainage: a modern approach to physiotherapy in cystic fibrosis. Journal of the Royal Society of M edicine, 82(suppl. 16): 32-37.");
INSERT INTO keywords (name, description) VALUES ("Drenaje con sellado bajo el agua", "Sistema de drenaje que permite que el aire o los fluidos sean retirados del tórax y transportados a una vía de evacuación. El hecho de
estar sellado bajo el agua asegura que haya solamente un único flujo.Drenaje intercostal
Se utiliza para eliminar el aire o los fluidos del espacio pleural, permitiendo que tenga lugar la reexpansión pulmonar, por ejemplo
después de un traumatismo, de una operación o de un neumotórax. Estos drenajes requieren un drenaje de sellado bajo el agua para
permitir el restablecimiento de la integridad del espacio pleural. Se puede añadir succión al drenaje cuando la filtración de aire es rápida,
pero no debería ser tan elevada como para evitar que el pulmón se cierre. Se requiere la monitorización regular de estos drenajes, y
debe apuntarse la cantidad, tipo y color del líquido drenado. El agua del tubo debería fluctuar con la respiración, mientras que la
presencia de burbujas en el drenaje de sellado bajo agua durante la respiración o la tos sería indicativa de una filtración de aire (del
pulmón). Los drenajes se eliminan cuando cesan el drenaje de fluidos y las fluctuaciones, y cuando la radiografía y los ruidos
respiratorios vuelven a ser normales (lo que indica que el pulmón se ha reinsuflado).");
INSERT INTO keywords (name, description) VALUES ("Drenaje postural", "Uso terapéutico de la posición del paciente asistida por la gravedad para facilitar la eliminación de secreciones pulmonares excesivas.
Se puede emplear junto con otras técnicas como percusión torácica, expansión torácica y respiración con presión positiva intermitente.");
INSERT INTO keywords (name, description) VALUES ("Drenaje torácico", "Tubo introducido en el pecho para drenar el exceso de fluido o aire, que normalmente incorpora una franja visible en la radiografía.
Véase Drenaje con sellado bajo el agua.");
INSERT INTO keywords (name, description) VALUES ("Dualismo cuerpo/mente", "Postura filosófica que adopta la visión de que mente y cuerpo son entidades esencialmente distintas con esferas de existencia separadas.
Esta postura se encuentra en las raíces ideológicas de la práctica médica ortodoxa contemporánea, pero cada vez está siendo más
modificada por la visión de que cuerpo y mente están unidos e influenciados entre sí. El excesivo estrés mental puede, por ejemplo,
conducir a una mala salud física.");
INSERT INTO keywords (name, description) VALUES ("Duelo", "Sentimiento de tristeza intenso y prolongado cuando se pierde a alguien que es muy valorado. La pérdida de objetos, situación,
identidad y estilo de vida también puedan dar lugar a este sentimiento de duelo (p. ej., la pérdida de trabajo, país o casa).Duración del impulso (amplitud)
Se trata de un ciclo completo de flujo de corriente. Normalmente se mide en μs o ms. A veces es denominado »amplitud del impulso«,
pero ello es incorrecto porque se trata de una medida de tiempo, no una dimensión espacial. La duración del impulso, junto con la
intensidad, indica qué tipos de fibras nerviosas van a ser más probablemente estimuladas y de ahí puede deducirse el posible nivel de
comodidad o incomodidad que experimentará el paciente y el tipo de respuesta a la estimulación.");
INSERT INTO keywords (name, description) VALUES ("Duramadre", "Cubierta más gruesa, fibrosa y externa de la médula espinal y nervios espinales. La hemorragia localizada por debajo de esta membrana
recibe el nombre de hematoma subdural.E");
INSERT INTO keywords (name, description) VALUES ("Eburnación", "Término que hace referencia a la apariencia brillante del cartílago articular afectado por osteoartritis. Se refiere a la apariencia densa y
esclerótica que adquiere el cartílago en un intento de remodelación a fin de realizar un esfuerzo extra. Se parece al marfil en su aspecto
blanco y denso.");
INSERT INTO keywords (name, description) VALUES ("Eccema", "Tipo de dermatitis (afección inflamatoria aguda o crónica de la piel) que tiene lugar como reacción a diversos agentes. Se caracteriza
por eritema, descarga serosa entre las células de la epidermis e infiltrado inflamatorio de la dermis.");
INSERT INTO keywords (name, description) VALUES ("E(c)FDS", "Abreviatura médica común de epífisis (capital) femoral con desplazamiento superior.
Alteración común en los adolescentes en que la cabeza del fémur se desliza sobre su lámina de crecimiento, una bola de helado que se
resbala del cucurucho. Puede provocar dolor, rigidez, pérdida funcional y cojera.");
INSERT INTO keywords (name, description) VALUES ("ECG", "Abreviatura médica común de electrocardiograma.
Test no invasivo que se usa para reflejar las alteraciones cardíacas esenciales, midiendo la actividad eléctrica del corazón mediante la
colocación de electrodos en partes determinadas del cuerpo.
Configuración de un electrocardiograma o ECG típico. La onda P corresponde a la despolarización auricular, el complejo QRS indica el comienzo de la despolarización
ventricular y la onda T corresponde a la repolarización ventricular.");
INSERT INTO keywords (name, description) VALUES ("Ecocardiografía", "Test diagnóstico que utiliza las ondas de ultrasonido para obtener imágenes de las cavidades cardíacas, válvulas y estructuras
circundantes. También puede medir el gasto cardíaco y detectar pericarditis o válvulas cardíacas anormales.");
INSERT INTO keywords (name, description) VALUES ("Ecografía Doppler", "El ultrasonido Doppler-corregido permite ver los tejidos, el flujo sanguíneo y los órganos en tiempo real.");
INSERT INTO keywords (name, description) VALUES ("Economía mixta de bienestar", "Forma de describir la diversidad de caminos a través de los cuales se han fundado y desarrollado los diferentes servicios. Esto incluye
los sectores estatutarios, sectores voluntarios y privados, así como los cuidados informales.");
INSERT INTO keywords (name, description) VALUES ("Ecuación Henderson-Hasselbach", "Fórmula utilizada para calcular la concentración de bicarbonato en la sangre arterial cuando el pH y la PaCO 2 se conocen.");
INSERT INTO keywords (name, description) VALUES ("EDD", "Abreviatura médica utilizada habitualmente para referirse a la enfermedad discal degenerativa.Acumulación excesiva de fluido tisular.");
INSERT INTO keywords (name, description) VALUES ("Edema pulmonar", "Acumulación de fluido dentro del alvéolo. El edema pulmonar hidrostático ocurre cuando hay un aumento en la presión hidrostática del
intersticio pulmonar, lo cual hace que se inunde el espacio alveolar. El edema pulmonar no hidrostático implica la interrupción de la
barrera endotelial y epitelial, que induce una respuesta inflamatoria sistémica asociada con lesión microvascular extensa, incluyendo los
pulmones (p. ej., síndrome de distrés respiratorio agudo). Está asociado con un aumento total del agua pulmonar a pesar de una presión
hidrostática normal. A menudo se debe a una ineficaz función de bombeo del corazón.");
INSERT INTO keywords (name, description) VALUES ("Educación interprofesional (multiprofesional)", "Es aquella en que un conjunto de diferentes grupos de profesionales aprenden juntos de modo estructurado.");
INSERT INTO keywords (name, description) VALUES ("Educación para la salud", "Medidas designadas para mejorar la salud a través de la educación, como por ejemplo dar consejo sobre la dieta y el ejercicio. La
educación para la salud es una faceta de la promoción de la salud.");
INSERT INTO keywords (name, description) VALUES ("Educación/reeducación motora", "Logro de las habilidades del movimiento funcional a partir de la experiencia y feedback con los resultados potenciales obtenidos.");
INSERT INTO keywords (name, description) VALUES ("EED", "Escala del estado de discapacidad. Es un esquema o escala de clasificación que asegura que todos los participantes de los ensayos
clínicos están en la misma clase, tipo o fase de esclerosis múltiple. También se utiliza para seguir la progresión de la discapacidad y
evaluar los resultados del tratamiento.");
INSERT INTO keywords (name, description) VALUES ("EEG", "Abreviatura médica común de electroencefalograma.
Test que informa de la actividad eléctrica del cerebro mediante electrodos colocados en el cuero cabelludo.");
INSERT INTO keywords (name, description) VALUES ("EEP", "Abreviatura médica común de energía electromagnética pulsada.
¿Cómo trabaja una onda corta pulsada? Una forma útil y sencilla de explicarlo a los pacientes es la que sigue:
La onda corta pulsátil devuelve la diferencia de potencial de la membrana celular a valores normales, lo que permite que la célula recupere su funcionamiento normal y
pueda repararse, dividirse, etc.");
INSERT INTO keywords (name, description) VALUES ("Efectividad clínica", "Grado de beneficio en la salud que produce una intervención en la práctica clínica rutinaria.Efecto de Bohr
Efecto de la concentración de H + (pH) en la posición de la curva de disociación de oxihemoglobina. En estados de acidosis, la curva
aparece desviada a la derecha, mientras que se desvía a la izquierda en estados de alcalosis. Estos cambios ocurren en respuesta a los
cambios de la molécula de hemoglobina, a medida que el pH se altera. La curva a la derecha reduce la afinidad de la hemoglobina por
el oxígeno (por lo que tiene lugar una mejor descarga de oxígeno en los tejidos), mientras que una desviación a la izquierda (con un pH
elevado) aumenta la afinidad de la hemoglobina por el oxígeno (y por lo tanto se incrementa su absorción en el alvéolo).
Otros factores pueden también ocasionar una desviación de la curva; por ejemplo, alteraciones de la temperatura corporal o
hemoglobina de estructura anormal (cambios en la secuencia de aminoácidos de la hemoglobina alterarán su forma y, por lo tanto, su
afinidad por el oxígeno).");
INSERT INTO keywords (name, description) VALUES ("Efecto de Hawthorne", "Término de investigación que se refiere al fenómeno por el que los sujetos alteran su comportamiento cuando saben que están siendo
observados.");
INSERT INTO keywords (name, description) VALUES ("Efecto piezoeléctrico", "Término electroterápico que se aplica al fenómeno por el que el paso de una corriente alterna rápidamente a través de un cristal
produce vibraciones mecánicas rápidas del cristal. En la producción de ultrasonido se emplea el efecto piezoeléctrico inverso.");
INSERT INTO keywords (name, description) VALUES ("Efectos interactivos", "Término electroterápico que designa la aplicación de dos agentes electrofísicos diferentes, de forma concurrente o secuencial, lo que
puede aumentar los riesgos para el paciente. Por ejemplo, la aplicación de hielo o TENS sobre una región, antes o durante la
realización de un ultrasonido, puede reducir la capacidad del paciente para informar de si está muy caliente, lo cual puede dar lugar a
quemaduras cutáneas.");
INSERT INTO keywords (name, description) VALUES ("Eferente", "Que emerge del sistema nervioso central (SNC); así, los axones eferentes son aquellos que llevan información fuera del SNC.");
INSERT INTO keywords (name, description) VALUES ("Eficacia clínica", "Extensión en la que una intervención logra sus efectos deseados cuando es estudiada bajo condiciones de investigación controladas.");
INSERT INTO keywords (name, description) VALUES ("Efusión", "Inflamación articular limitada a la cavidad sinovial. También puede darse en los pulmones; en tal caso recibe el nombre de efusión
pleural.");
INSERT INTO keywords (name, description) VALUES ("Ejercicio activo asistido", "Ejercicio en el que parte de la actividad es llevada a cabo por el paciente y parte por el terapeuta o algún tipo de material o dispositivo.
Por ejemplo, la flexión asistida del hombro en decúbito usando una polea.");
INSERT INTO keywords (name, description) VALUES ("Ejercicio pliométrico", "Emplea una contracción muscular excéntrica que es seguida rápidamente por una contracción muscular concéntrica. Los ejercicios
pliométricos a menudo implican un movimiento de salto.");
INSERT INTO keywords (name, description) VALUES ("Ejercicios de cadena cinética", "Véase Cadenas cinéticas.
»Cadena cinética« es un término de ingeniería utilizado para describir un sistema de eslabones conectados por articulaciones. Pueden
ser abiertas o cerradas.A. Cadena cinética cerrada. B. Cadena cinética abierta
El ejercicio de cadena abierta se define como aquel en que el extremo distal del segmento no actúa en contra de una restricción o
resistencia. En un ejercicio de cadena cerrada, el segmento terminal está restringido. Una sentadilla es un ejemplo de ejercicio en
cadena cerrada.");
INSERT INTO keywords (name, description) VALUES ("Sentadilla", "Una extensión de la pierna desde la posición de sentado en una silla es un ejemplo de ejercicio en cadena abierta.");
INSERT INTO keywords (name, description) VALUES ("Extensión de pierna", "");
INSERT INTO keywords (name, description) VALUES ("Ejercicios de respiración", "Entrenamiento de pacientes para conseguir aumento máximo de los volúmenes inspiratorios pulmonares, que promueve el flujo aéreo a
través de los canales colaterales ( Menkes y Britt, 1980 ) y facilita la ventilación y la expulsión de las secreciones pulmonares. La
posición tiene una importante influencia en la distribución de la ventilación, por lo que debe ser utilizada junto con lo anterior.
Véase Técnica respiratoria cíclica activa.");
INSERT INTO keywords (name, description) VALUES ("Elastina", "Tipo de fibras del tejido conectivo que pueden estirarse rápidamente y que se encuentran en las paredes de los vasos sanguíneos y
otras estructuras capaces de dilatarse (p. ej., venas, vejiga, etc.). La elastina es una proteína estructural que da elasticidad a nuestros
tejidos y órganos. Recubre las arterias, pulmones, intestinos y piel. En cuanto a su función, complementa al colágeno, ya que mientras
que éste proporciona rigidez, la elastina permite que el tejido conectivo se estire y vuelva de nuevo a su posición inicial.");
INSERT INTO keywords (name, description) VALUES ("Electrodo", "Término electroterápico que designa la aplicación de una corriente de salida desde una máquina a una parte del cuerpo para ser tratada
mediante estimulación eléctrica o para ampliar las señales bioeléctricas (p. ej., EMG, EEC, ECG, etc.). Los tipos de electrodos para la
estimulación eléctrica incluyen goma de carbón reutilizable con una almohadilla de gel de estimulación eléctrica diseñado a propósito
para este uso; metal (incluyendo aluminio y plomo) utilizado con una esponja humedecida o gasa; autoadhesivos; electrodos de metal
sin protección específica para la tarea (p. ej., anal o vaginal), etc. El tamaño varía de acuerdo con los objetivos y el área que se va atratar; el hecho de que ambos sean del mismo o diferente tamaño también depende del tipo de corriente y de los objetivos; el tamaño
afecta a la densidad de corriente, por lo que si éste es muy pequeño y la corriente media es elevada, hay un alto riesgo de quemaduras
cutáneas. La localización variará con los objetivos del tratamiento. Número: como mínimo dos por circuito eléctrico, aunque pueden
utilizarse cuatro (interferencial o 2 canales de corriente), o bien, si se usa HVPS, puede haber un ánodo y dos o más cátodos
(bifurcada).");
INSERT INTO keywords (name, description) VALUES ("Electrodos para amplificación", "La elección de tipo, número y localización es a menudo ligeramente diferente para EMG, EEC y ECG que para la estimulación
eléctrica. Por ejemplo, para la EMG biofeedback se usan normalmente tres electrodos pequeños (un electrodo de tierra y dos activos
a lo largo de la línea de las fibras). Pueden estar separados o formar un preamplificador de tres electrodos.");
INSERT INTO keywords (name, description) VALUES ("Electrólitos", "Sustancias que en solución se ionizan y adquieren la capacidad para conducir electricidad. El equilibrio normal de electrólitos es esencial
para la función normal.");
INSERT INTO keywords (name, description) VALUES ("Electromiografía biofeedback", "Término electroterápico que se utiliza para designar el uso de señales bioeléctricas de la actividad de la unidad motora amplificadas
como una forma de retroalimentación. Se emplea para aumentar o disminuir el nivel de la actividad de la unidad motora. Por ejemplo,
es utilizado para reeducar el movimiento después de un ACV y para disminuir la actividad muscular asociada a cefaleas.
Véase Electrodo.");
INSERT INTO keywords (name, description) VALUES ("Electroterapia", "Utilización terapéutica de agentes electrofísicos. En Estados Unidos solamente se refiere al uso de la estimulación eléctrica. En otros
países su significado es más amplio y hace referencia a todos los agentes electrofísicos. Las modalidades utilizadas en el tratamiento de
las alteraciones musculo-esqueléticas incluyen la diatermia de onda corta, la terapia interferencial, la estimulación nerviosa eléctrica
transcutánea y el láser.");
INSERT INTO keywords (name, description) VALUES ("Elongación recíproca", "Cuando un grupo de músculos trabaja concéntricamente, los músculos opuestos se tienen que alargar para permitir el movimiento; de lo
contrario nunca nos moveríamos hacia ningún lado.");
INSERT INTO keywords (name, description) VALUES ("EM", "1. Abreviatura médica común de encefalopatía miálgica. 2. Esclerosis múltiple.");
INSERT INTO keywords (name, description) VALUES ("Emancipación", "Política de eliminar o reducir la presión, desigualdad, justicia y explotación. Consiste en la liberación de individuos y grupos de la
coacción y relaciones de poder desiguales que limitan las posibilidades y la calidad de vida.");
INSERT INTO keywords (name, description) VALUES ("Embarazo ectópico", "Embarazo en cualquier localización fuera del útero (a menudo en las trompas de Falopio).");
INSERT INTO keywords (name, description) VALUES ("Embolia", "Bloqueo de un vaso sanguíneo por un coágulo u otro material extraño que llega al sitio en que se aloja a través del flujo sanguíneo. Son
frecuentes los émbolos pulmonares que se han desprendido de una trombosis venosa profunda (TVP) previa.");
INSERT INTO keywords (name, description) VALUES ("Embolia grasa", "Descarga de grasa desde la médula ósea a la circulación. Puede ser consecuencia de fracturas de huesos largos o de lesiones de
aplastamiento y se diagnostica por confusión creciente, saturación de oxígeno disminuida en la sangre y, ocasionalmente, hemorragias
petequiales en los brazos y el pecho; puede resultar letal.");
INSERT INTO keywords (name, description) VALUES ("Embolia pulmonar", "Coágulo de sangre dentro de la circulación pulmonar, potencialmente fatal (aproximadamente 20.000 muertes hospitalarias anuales en
el Reino Unido por esta causa). Las causas predisponentes pueden incluir traumatismo, cirugía reciente, inmovilización, enfermedad
maligna, embarazo, etc. El tamaño del coágulo es de gran importancia clínica cuando el 25% de la circulación pulmonar está obstruida,pues la función cardíaca está dañada. El tamaño del coágulo, la edad del paciente y la comorbilidad pulmonar existente, así como el
estado de salud general, influirán en el resultado. La presentación clínica no es específica hasta que los signos y síntomas incluyen
disnea, dolor, cambios en el ecocardiograma (ECG), edema periférico, taquicardia y cianosis. Las investigaciones incluyen ECG,
radiografía torácica, gases sanguíneos arteriales, V/Q, angiografía, tomografía computarizada (TC) espiral y test de D-dímeros. El
tratamiento incluye oxigenoterapia, analgesia, terapia anticoagulante, trombólisis y embolectomía pulmonar (aunque ésta se aplica
raramente y requiere especialistas en cirugía torácica). Alrededor del 10% de las embolias pulmonares son mortales y un 5% adicional
causan la muerte con posterioridad, a pesar del diagnóstico y tratamiento. Aproximadamente el 50% de las embolias pulmonares se
resuelven después de un mes de tratamiento; la perfusión acaba regresando a la normalidad en dos de cada tres pacientes (");
INSERT INTO keywords (name, description) VALUES ("Kearon,", "2003).");
INSERT INTO keywords (name, description) VALUES ("Embolización", "Técnica para bloquear quirúrgicamente una malformación arteriovenosa a fin de prevenir el estallido subsiguiente. Gracias a los avances
tecnológicos, la embolización se está volviendo más efectiva.");
INSERT INTO keywords (name, description) VALUES ("EMD", "Abreviatura médica común de equipo multidisciplinario.");
INSERT INTO keywords (name, description) VALUES ("EMG", "Abreviatura médica común de electromiograma.
Test que informa de la actividad eléctrica de un músculo. Normalmente se lleva a cabo utilizando agujas que se insertan dentro del
músculo, pero también puede realizarse mediante electrodos de superficie; en este caso se denomina1 EMG de superficie y es menos
preciso. Se emplea en el diagnóstico de muchas alteraciones y en la aplicación de inyecciones de toxina botulínica.");
INSERT INTO keywords (name, description) VALUES ("Empiema", "Colección de pus dentro del espacio pleural, a menudo como resultado de una infección bacteriana o posneumonía.");
INSERT INTO keywords (name, description) VALUES ("Empowerment", "Proceso de facilitar a las personas el logro de un mejor control sobre sus vidas, y sobre las elecciones y desafíos sociales y personales a
los que se enfrentan. Aunque el empowerment puede ser facilitado, esto puede cambiar por aquellos que se benefician de la sensación
de control que confiere. En este sentido el empowerment no se puede »dar« sino »tomar«.");
INSERT INTO keywords (name, description) VALUES ("Empuje extensor", "Respuesta compensatoria en la que el paciente adopta bruscamente una extensión en un intento por vencer la fuerza de la gravedad.EMT
Abreviatura médica común de estimulación magnética transcraneal.
Test neuropsicológico en el que se colocan imanes en el cráneo y se puede aplicar estimulación al cerebro para ocasionar movimiento
muscular dependiente del lugar del estímulo. La EMT puede utilizarse más fácilmente en un marco clínico, proporcionando una
herramienta de medida de la actividad cerebral.");
INSERT INTO keywords (name, description) VALUES ("Encefalitis", "Inflamación del encéfalo.");
INSERT INTO keywords (name, description) VALUES ("Encéfalo", "Parte del sistema nervioso central situada dentro del cráneo, que comprende el cerebro, el cerebelo, la protuberancia anular y la médula
oblongada o bulbo.");
INSERT INTO keywords (name, description) VALUES ("Endocarditis bacteriana aguda", "Inflamación aguda o crónica del endocardio ocasionada por organismos piógenos como el estreptococo y el estafilococo.");
INSERT INTO keywords (name, description) VALUES ("Endorfinas", "Sustancias implicadas en el alivio del dolor producidas como resultado del estrés corporal o durante el ejercicio.");
INSERT INTO keywords (name, description) VALUES ("Endoscopia", "Procedimiento quirúrgico que permite visualizar la cavidad interna de un cuerpo con un instrumento de fibras ópticas flexibles.");
INSERT INTO keywords (name, description) VALUES ("Enema de bario", "Inyección de una solución de bario en el recto y el colon. Se utiliza en exámenes radiográficos para dar mayor contraste a la imagen del
intestino grueso. Estas radiografías se utilizan para diagnosticar la anatomía normal y anormal de colon y recto.");
INSERT INTO keywords (name, description) VALUES ("Energía", "Cantidad de trabajo realizado, medido en julios (J). Por ejemplo, para el láser de nivel bajo que también utiliza la densidad de energía:");
INSERT INTO keywords (name, description) VALUES ("Energía transcutánea", "Se aplica externamente y pasa hacia los tejidos subyacentes a través de la piel (p. ej., la estimulación eléctrica, utilizando electrodos de
superficie, pasa a través de la piel llegando hasta los tejidos internos). El término estimulación eléctrica nerviosa transcutánea (TENS) se
refiere normalmente a un método de estimulación eléctrica para el control del dolor, pero realmente puede designar cualquier tipo de
corriente que pasa a través de la piel.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad", "Sensación subjetiva de malestar. La enfermedad puede o no estar asociada con dolencia o alteración.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad autoinmune", "Cualquier enfermedad que implique la producción de autoanticuerpos contra los propios tejidos.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Addison", "Alteración endocrina que resulta de una deficiencia de las glándulas adrenérgicas al no producir cantidades correctas de aldosterona y
cortisol.
Los síntomas incluyen malestar, presión sanguínea baja, anemia, hipoglucemia y problemas con el equilibrio electrolítico.
Observación El presidente de Estados Unidos John F. Kennedy padecía esta enfermedad.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Alzheimer", "Es la causa más común de demencia en la vejez. Se trata de una demencia progresiva que lleva a una pérdida de la capacidad para la
realización de las AVD. La enfermedad de Alzheimer se define patológicamente por la presencia de un excesivo número de redes
neurofibrilares y placas seniles en la corteza cerebral.Enfermedad de Creutzfeldt-Jacob (ECJ)
Alteración que incluye el rápido descenso de la función mental y el movimiento. Se cree que estas anormalidades son debidas al daño
cerebral causado por una proteína denominada prión.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Crohn", "Enfermedad intestinal inflamatoria crónica que afecta normalmente al ilion y/o al colon. Se caracteriza por episodios frecuentes de
diarrea, dolor abdominal intenso, náuseas, fiebre, resfriados, malestar y pérdida de peso.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Cushing", "Es causada por una sobredosis crónica de glucocorticoides. Los síntomas varían, pero la mayor parte de las personas presentan
obesidad en la parte superior del cuerpo y cara redondeada, con aumento de la grasa alrededor del cuello.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Freiberg", "Osteocondritis disecante con necrosis avascular del hueso; normalmente afecta a la cabeza del segundo metatarsiano.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Huntington", "Enfermedad hereditaria degenerativa que afecta a los ganglios basales y a la corteza cerebral, dando lugar a una pérdida de la función
cognitiva y movimientos coreiformes (vacilantes, involuntarios).");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de la arteria coronaria", "Término utilizado para describir cualquier alteración anormal que afecta a las arterias del corazón y provoca diversos efectos
patológicos.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de la membrana hialina", "Enfermedad respiratoria del recién nacido.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de la neurona motora (ENM)", "Enfermedad caracterizada por la degeneración progresiva de las células del asta anterior, de los tractos corticoespinales y del núcleo
del tallo encefálico. Las características clínicas incluyen pérdida de movimiento, dolor, disnea, disartria, disfagia y otros problemas
dependientes de la parte del sistema nervioso afectado. La función sensitiva y cognitiva permanece intacta.
Véase la tabla siguiente para más información.
Lesiones en la enfermedad de la neurona motora y sus síntomas relacionados");
