INSERT INTO keywords (name, description) VALUES ("Parálisis del diafragma", "");
INSERT INTO keywords (name, description) VALUES ("Debilidad espástica", "");
INSERT INTO keywords (name, description) VALUES ("Tracto corticoespinal", "");
INSERT INTO keywords (name, description) VALUES ("Lesión de la neurona motora superior", "");
INSERT INTO keywords (name, description) VALUES ("RigidezCélulas de asta/cuerno anterior", "");
INSERT INTO keywords (name, description) VALUES ("Lesión de la neurona motora inferior", "");
INSERT INTO keywords (name, description) VALUES ("Emaciación muscular", "");
INSERT INTO keywords (name, description) VALUES ("Fasciculación muscular", "");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Lyme", "Enfermedad bacteriana que aparece tras la picadura de una garrapata infectada.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Marburg", "Forma de esclerosis múltiple.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Menière", "Trastorno episódico del oído interno que afecta al equilibrio y al oído; se caracteriza por vértigo, mareo y pérdida de la audición de uno
o ambos oídos: también puede aparecer tinnitus.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Osgood-Schlatter", "Epifisitis de tracción del tubérculo tibial, que se observa habitualmente en adolescentes. Suele manifestarse como dolor a la presión
directa y a la contracción del grupo muscular del cuádriceps, por ejemplo al apoyar el peso sobre la pierna, saltar o ponerse en
cuclillas. Suele apreciarse una notable tumefacción, que en la radiografía se traduce en una separación de la apófisis.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Paget", "Enfermedad ósea que inicialmente da lugar a una excesiva reabsorción de hueso seguida por el reemplazamiento de médula ósea normal
por tejido vascular y fibroso. Es una enfermedad ósea metabólica que implica la destrucción ósea y una nueva formación ósea que da
lugar a deformidades. La causa de la enfermedad de Paget es desconocida.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Parkinson", "Enfermedad degenerativa de origen desconocido que se presenta en la segunda mitad de la vida y afecta a la sustancia");
INSERT INTO keywords (name, description) VALUES ("nigra del", "cerebro. Se caracteriza por movimientos lentos, temblor de reposo, rigidez e inestabilidad postural.
Observación clínica La enfermedad de Parkinson es siempre progresiva, aunque la velocidad de deterioro varía. Es importante
intentar mantener movimientos de extensión y rotación, ya que las posturas generalmente acaban dominadas por posiciones de flexión;
hay una tendencia a andar encorvado y a la festinación (pasos arrastrados cortos).");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Perthe", "Necrosis avascular de la cabeza femoral; suele presentarse entre los 3 y los 12 años de edad y normalmente es más común en
individuos del sexo masculino. Habitualmente da lugar a una cabeza femoral aplastada.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Scheuermann", "Osteocondrosis de las epífisis vertebrales en los adolescentes.
Cursa con aplastamiento de las vértebras, nódulos de Schmorl o irregularidades en las láminas y estrechamiento de los espacios
discales intervertebrales. Su etiología no está clara. La enfermedad de Scheuermann afecta generalmente a la columna dorsal baja y
lumbar alta. Normalmente comienza en la pubertad y afecta por igual a mujeres y hombres. La alteración da lugar a cifosis dorsal, y la
mitad de los afectados presentan también escoliosis.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Sever", "Apofisitis del centro de osificación del calcáneo en el lugar de inserción del tendón de Aquiles. Puede confundirse con tendinitis aquílea.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de Sinding-Larsen-Johansson", "Osteocondrosis de tracción en el polo inferior de la rótula.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad de von Recklinghausen (neurofibromatosis)", "Alteración hereditaria en la que aparecen múltiples granos (conocidos como granos de café con leche) y neurofibromas. JosephMerrick, el famoso hombre elefante, fue diagnosticado de esta enfermedad. Ahora se cree que, de hecho, sufría el síndrome proteus
(Tibbles & Cohen, 1986).");
INSERT INTO keywords (name, description) VALUES ("Enfermedad degenerativa articular (EDA)", "Véase Osteoartritis.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad del ovario poliquístico", "Patología ginecológica caracterizada por quistes ováricos múltiples.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad mental", "Predominantemente caracterizada como una patología mental con trastorno de la función mental, como delirio, alucinaciones, euforia
excesiva o depresión. Las connotaciones médicas de este término han sido consideradas por algunos autores erróneas o al servicio de
los propósitos de grupos poderosos dentro de la sociedad. Los científicos sociales han desarrollado conocimientos acerca de las
causas de las enfermedades mentales y de éstas como fenómenos sociales que establecen el límite que estima el funcionamiento mental
como estable en diferentes culturas y sociedades y conductas humanas regulares. Algunos, por ejemplo, han sido considerados
enfermos mentales por sus creencias políticas o porque su comportamiento no encajaba con una norma cultural.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad pulmonar intersticial (EPI)", "Este término abarca un cierto número de alteraciones pulmonares agrupadas de forma conjunta debido a las similitudes en su
presentación clínica, características radiológicas y fisiológicas. Las anormalidades son más consecuentes con los cambios en el
intersticio que con los espacios aéreos. Dentro de esta clasificación se incluyen un número de enfermedades con diferentes causas,
tratamientos y pronósticos. Estas enfermedades incluyen aquellas asociadas con causas ocupacionales, alérgicas, de tejidos blandos e
idiopáticas (p. ej., asbestosis, pulmón reumático, sarcoidosis, fibrosis inducida por medicamentos, alveolitis fibrosante, etc.). Sin
embargo, la alteración habitual es un déficit fisiológico restrictivo con volúmenes pulmonares reducidos (aunque con valores de
espirometría forzada) en espirometría, mantenidos (v. Espirometría), y capacidad de difusión del monóxido de carbono (v. DLCO).
Los síntomas clínicos incluyen disnea progresiva, tos, pérdida de peso, letargia, fiebre y artralgia. Los hallazgos de la valoración pueden
incluir disnea, crepitaciones inspiratorias finas, cianosis y artritis reumatoide, con la muerte como resultado de un deterioro gradual que
termina en insuficiencia respiratoria después de un período de 4-5 años. Sin embargo, el pronóstico puede variar de meses a años. Los
regímenes de tratamiento (dependiente del diagnóstico de la EPI específica) pueden incluir la evitación de la exposición, corticoides,
agentes citotóxicos, terapia de oxígeno, trasplante, vacunación y rehabilitación pulmonar.");
INSERT INTO keywords (name, description) VALUES ("Enfermedad pulmonar obstructiva crónica (EPOC)", "Esta enfermedad se caracteriza por una limitación del flujo aéreo progresiva e irreversible, asociada con respuestas inflamatorias
anormales del pulmón a agentes nocivos. La lesión de las vías aéreas afecta tanto a las vías aéreas menores como a las paredes del
parénquima. La inflamación crónica da lugar al remodelamiento y estrechamiento de las vías aéreas menores, mientras que la ingestión
de elastasa por las proteasas pulmonares destruye las estructuras de soporte elástico y el acoplamiento alveolar, dando lugar al
atrapamiento del aire.
El diagnóstico se obtiene detectando la limitación del flujo aéreo en la valoración espirométrica, junto con los detalles de una historia
completa del paciente y los hallazgos clínicos (NICE COPD Guidelines, 2004). La gravedad de la limitación del flujo aéreo se clasifica
mediante la evaluación del FEV1 (volumen espiratorio forzado en el primer segundo) y la valoración clínica.
El tabaco es la causa principal de EPOC (el 90% de los pacientes que sufren EPOC tienen antecedentes de tabaquismo). La EPOC es
una causa importante de mortalidad crónica y morbididad en todo el mundo y supone una carga significativa personal, social y
psicológicamente. El curso de la enfermedad es variable, pero inevitablemente irreversible. Un equipo multiprofesional de expertos
debería liderar las estrategias de gestión holísticas, incluyendo apoyo farmacológico, oxigenoterapia, fisioterapia respiratoria, abandono
del hábito tabáquico y medidas nutricionales (v. GOLD Guidelines [2001] y NICE Guidelines [2004] para información más detallada).");
INSERT INTO keywords (name, description) VALUES ("Enfermedad pulmonar restrictiva", "Se caracteriza por una capacidad pulmonar total (expansión del pulmón) limitada. Es típica de enfermedades pulmonares (p. ej., fibrosis
pulmonar), pleurales (p. ej., neumotórax y mesotelioma), neuromusculares (p. ej., distrofia muscular y parálisis del nervio frénico), de la
pared torácica (p. ej., pectus excavatum y espondilitis anquilosante) y problemas subdiafragmáticos (p. ej., obesidad y ascitis). Su
diagnóstico se realiza con medidas espirométricas simples cuando es posible.
Véase Espirometría.Enfermedades ocupacionales
Enfermedades debidas a factores que intervienen durante el transcurso del trabajo de una persona; por ejemplo, asbestosis.");
INSERT INTO keywords (name, description) VALUES ("Enfisema", "Enfermedad pulmonar obstructiva caracterizada por el aumento de tamaño de los bronquiolos terminales y la destrucción de las paredes
alveolares sin fibrosis. El volumen pulmonar total aumenta al crecer el espacio muerto debido al atrapamiento de aire, dando lugar a un
aumento del trabajo respiratorio. La causa más común de enfisema es el tabaco, pero algunos pacientes pueden tener una alteración
hereditaria denominada deficiencia alfa-1-antitripsina.
Véase Bullas.
»Soplador rosado« (pink puffer) es un término antiguo a menudo utilizado para describir la apariencia de un paciente enfisematoso.
Los individuos clásicamente tienen la musculatura atrofiada y el pecho hiperinsuflado (costillas elevadas con grandes campos
pulmonares, diafragma aplanado y gran diámetro torácico anteroposterior y tiraje costal); adoptan además una actitud respiratoria fija
(es decir, fijan el manguito de los rotadores para utilizar los músculos respiratorios accesorios, inclinándose hacia delante sobre los
brazos) y respiran automáticamente con los labios fruncidos cuando están estresados (para generar presión inspiratoria positiva
intrínseca, y así mantener abiertas las vías aéreas, que en su caso se colapsan con facilidad, facilitando así la llegada de oxígeno). Esto
permite al paciente enfisematoso mantener los niveles de presión parcial de oxígeno normales.");
INSERT INTO keywords (name, description) VALUES ("Enfisema quirúrgico", "Acumulación de aire en los tejidos debajo de la piel, normalmente alrededor del cuello o del pecho, que da lugar a una sensación
crepitante a la compresión. Tiene lugar cuando el aire del mediastino ha ascendido.");
INSERT INTO keywords (name, description) VALUES ("Enfoque de Bobath", "Forma de rehabilitación neurológica basada en un enfoque pionero de Berta y Karel Bobath. Pretende lograr la reeducación del
movimiento y la función mediante la facilitación del movimiento a través del uso de la entrada propioceptiva. La valoración es guiada
por la reacción de la persona a ser manejada por el terapeuta (Stokes, 1998).");
INSERT INTO keywords (name, description) VALUES ("Enfoque de Brunnstrom", "Técnica desarrollada por Brunnstrom para maximizar la recuperación después de un accidente cerebrovascular (ACV). Está basada en
la idea de que la actividad refleja y las sinergias del movimiento son la base para el movimiento voluntario y en la progresión desde
movimiento grueso proximal hacia movimiento fino distal.");
INSERT INTO keywords (name, description) VALUES ("Enfoque de McKenzie", "El enfoque de McKenzie de terapia y diagnóstico mecánico fue creado por el fisioterapeuta neozelandés Robin McKenzie y
actualmente se usa en todo el mundo por sanitarios y pacientes para el manejo de problemas musculoesqueléticos espinales y no
espinales. Durante la historia clínica y el examen físico se determinan las respuestas mecánicas y sintomáticas a los movimientos y a las
posturas; el análisis incluye movimientos repetidos y posiciones mantenidas. La comprensión de estas respuestas permite su clasificación
dentro de uno de los síndromes mecánicos: desajuste, síndrome postural o disfunción. Se emplean ejercicios guiados específicos para
tratar los síntomas y restaurar la función, poniendo siempre el énfasis en las fuerzas generadas por el propio paciente, de forma que se
maximiza su independencia. El manejo depende sobre todo de una adecuada educación del paciente. Siempre se usa la mínima fuerza
terapéutica, pero se introduce una progresión de fuerzas si no se consiguen mejoras. Se utiliza una combinación de ejercicios eintervenciones del terapeuta, si fuera necesario para producir un cambio. Existen varios libros de texto que describen con detalle el
diagnóstico mecánico y la terapia: Lumbar Spine (McKenzie, 1981), Cervical and Thoracic Spine (McKenzie, 1990), Extremities
(McKenzie, 2000) y Lumbar Spine, 2nd. eédition (McKenzie, 2003). Incluso existen los cuadernillos Treat Your Own Back/Neck,
que han sido escritos específicamente para pacientes. Existe en estos momentos una gran riqueza de estudios que han sido realizados
para investigar los componentes de este enfoque. Esta investigación se ha orientado tanto al diagnóstico mecánico como a la terapia,
como herramientas para la valoración y para el enfoque terapéutico. Por ejemplo, la respuesta sintomática de centralización se ha
asociado sistemáticamente a un buen pronóstico: el sistema de valoración es fiable cuando es usado por aquellos que están bien
entrenados; como intervención es equiparable a la manipulación quiropráctica y a los ejercicios de entrenamiento de fuerza. Existe un
programa de educación internacional disponible para profesionales sanitarios cualificados; este programa se compone de cinco cursos
secuenciales, un examen acreditativo y un diploma del programa.
Puede accederse a http://www.mckenziemdt.org y buscar en la página: research. Ésta contiene una lista actualizada regularmente de
referencias de las investigaciones más relevantes, ordenadas bajo toda una variedad de encabezamientos.");
INSERT INTO keywords (name, description) VALUES ("ENM", "Abreviatura médica de enfermedad de la neurona motora.");
INSERT INTO keywords (name, description) VALUES ("Ensayo controlado aleatorio/randomizado (ECA)", "Término de investigación que se aplica a un experimento en el cual el investigador asigna al azar a algunos pacientes la realización de al
menos una maniobra y a otros pacientes un placebo. Cuando se lleva a cabo correctamente, un ECA puede ser usado para determinar
una relación causa-efecto.");
INSERT INTO keywords (name, description) VALUES ("Ensayos N-de-1", "Metodología de investigación en la cual un paciente se somete a pares de períodos de tratamiento, organizados de modo que un
período implique el uso de tratamiento experimental y el otro una terapia alternativa o placebo. Si es posible, se hace »a simple ciego« y
se monitorizan los resultados. Los períodos de tratamiento se repiten hasta que el personal clínico y el paciente están convencidos de
que los tratamientos son claramente diferentes o claramente no diferentes.");
INSERT INTO keywords (name, description) VALUES ("Entablillado", "Coadyuvante del tratamiento de fisioterapia que puede utilizarse de diferentes maneras.
• Preventiva. Para mantener una posición articular y prevenir una pérdida del rango de movimiento.
• Correctiva. Para corregir una pérdida del rango o una mala alineación.
• Funcional. Por ejemplo, una tablilla para la muñeca para mantener la extensión y maximizar la extensión de los dedos, o bien una
ortesis del tobillo para permitir una marcha segura.");
INSERT INTO keywords (name, description) VALUES ("Entonox", "Mezcla a partes iguales de óxido nitroso y oxígeno. Tiene propiedades para aliviar el dolor y puede ser autoadministrado.");
INSERT INTO keywords (name, description) VALUES ("Entorno terapéutico", "Entorno terapéutico es aquel concertado y diseñado para permitir a los pacientes lograr la mejor realización. Se ha demostrado que el
entorno es un factor muy importante en la rehabilitación, tanto física como mental.");
INSERT INTO keywords (name, description) VALUES ("Entrevista", "Método de investigación. Las entrevistas pueden ser abiertas, estructuradas o semiestructuradas.");
INSERT INTO keywords (name, description) VALUES ("Entrevista estructurada", "El entrevistador tratará de utilizar preguntas específicas y cortas, leer la pregunta exactamente como está en el programa, y realizar las
preguntas en el mismo orden especificado por el programa.");
INSERT INTO keywords (name, description) VALUES ("Entrevista semiestructurada", "El investigador dispone de una serie de preguntas en un programa de entrevistas, pero éste servirá tan sólo como guía, sin que tenga
que seguirse de manera estricta. Existe un intento de establecer compenetración con el paciente; el entrevistador es libre de explorar
áreas de interés que puedan surgir, en función de los intereses o preocupaciones de la persona entrevistada.Enuresis
Orinar de forma involuntaria (»mojar la cama«); suele tener lugar por la noche y es común en los niños.");
INSERT INTO keywords (name, description) VALUES ("Enzima", "Proteína que desencadena o acelera las reacciones químicas sin consumirse.");
INSERT INTO keywords (name, description) VALUES ("Enzima conversora de la angiotensina (ECA)", "Esta enzima cambia la angiotensina I (biológicamente inactiva) en angiotensina II.
La angiotensina II provoca la contracción de la musculatura lisa de los vasos sanguíneos y así eleva la presión sanguínea.");
INSERT INTO keywords (name, description) VALUES ("Enzimas cardíacas", "Son liberadas por células musculares cardíacas que están dañadas; pueden, por lo tanto, utilizarse como indicadores diagnósticos de un
infarto miocárdico.");
INSERT INTO keywords (name, description) VALUES ("Eosinófilo", "Células sanguíneas de la serie blanca que pueden digerir microorganismos.");
INSERT INTO keywords (name, description) VALUES ("EP", "Abreviatura médica común de embolismo pulmonar.");
INSERT INTO keywords (name, description) VALUES ("EPI", "Abreviatura médica común de enfermedad pélvica inflamatoria.");
INSERT INTO keywords (name, description) VALUES ("Epicondilitis lateral", "También conocida como »codo de tenista«, si bien a menudo el paciente no tiene una historia deportiva; se asocia con el origen del
tendón extensor común en el epicóndilo lateral humeral.");
INSERT INTO keywords (name, description) VALUES ("Epicondilitis medial (codo de golfista)", "Inflamación de los tendones que se insertan en el epicóndilo medial (del húmero) en el codo. Los síntomas incluyen dolor a la flexión
resistida de la articulación de la muñeca.");
INSERT INTO keywords (name, description) VALUES ("Epicóndilo", "Eminencia ósea situada por encima del cóndilo.");
INSERT INTO keywords (name, description) VALUES ("Epidemia", "Aumento significativo en la prevalencia de una enfermedad en una población o área específica.");
INSERT INTO keywords (name, description) VALUES ("Epidemiología", "Ciencia de la determinación de las causas específicas de una enfermedad o la interrelación entre varios factores que determinan una
enfermedad; estudia también la evolución de una enfermedad en una población.");
INSERT INTO keywords (name, description) VALUES ("Epidermólisis bullosa", "Grupo de alteraciones hereditarias poco frecuente en el que se produce un abrasamiento de la piel como respuesta a un traumatismo
cutáneo.");
INSERT INTO keywords (name, description) VALUES ("Epífisis", "Lámina ósea de crecimiento formada a partir de un centro secundario de osificación; normalmente se encuentra en los extremos de los
huesos largos. Separada de la porción principal del hueso por el cartílago (lámina epifisaria).");
INSERT INTO keywords (name, description) VALUES ("Epiglotis", "Estructura cartilaginosa que cierra la glotis mientras la comida o el líquido pasan a través de la faringe.Epiglotitis
Infección aguda de las vías aéreas superiores, que supone un riesgo para la vida y causa una obstrucción importante por inflamación
supraglótica; normalmente se da en niños menores de 5 años. La causa infecciosa más común es Haemophilus influenzae tipo B. Las
manifestaciones incluyen fiebre, garganta irritada, estridor, aumento del esfuerzo para la respiración y problemas en la deglución. La
intubación de emergencia o incluso la traqueotomía pueden estar indicadas como procedimiento para salvar la vida.");
INSERT INTO keywords (name, description) VALUES ("Epilepsia", "Alteración crónica del sistema nervioso caracterizada por la presentación periódica de ataques consistentes en períodos de pérdida de
conciencia, alteración del funcionamiento normal o actividad motora anormal. Entre los ataques, la persona funcionará de manera
normal. El tratamiento es principalmente farmacológico y permite que muchos pacientes lleven una vida normal.");
INSERT INTO keywords (name, description) VALUES ("Epimisio", "Cubierta de tejido conectivo fibroso que envuelve al músculo esquelético.");
INSERT INTO keywords (name, description) VALUES ("Episiotomía", "Incisión realizada entre la vagina y el recto que se usa para aumentar la abertura de la vagina a fin de facilitar el parto.");
INSERT INTO keywords (name, description) VALUES ("Epistemología", "Término de investigación que se utiliza para designar la teoría del conocimiento y su modo de adquisición. Incluye la posibilidad de
lograr un conocimiento objetivo y los aspectos psicológicos de éste.");
INSERT INTO keywords (name, description) VALUES ("Epitelio de transición", "Epitelio muy distensible, con grandes células cuboideas en estado de relajación que se extienden y escaman en estado distendido; se
halla presente en riñón, uretra y vejiga.");
INSERT INTO keywords (name, description) VALUES ("EPOC", "Abreviatura médica común de enfermedad pulmonar obstructiva crónica.");
INSERT INTO keywords (name, description) VALUES ("Equidad", "Principio aplicado a la asignación de recursos. El principio de equidad reivindica que casos parecidos no sean tratados de forma
diferente, pero también reconoce que la igualdad no se logra tratando a todo el mundo de la misma manera.");
INSERT INTO keywords (name, description) VALUES ("Equilibrio", "Capacidad para alcanzar y mantener el centro de gravedad del cuerpo sobre su base de sustentación en un medio sensorial dado. Las
reacciones de equilibrio son respuestas complejas basadas en un aprendizaje experimental previo en una situación de normal
funcionamiento del sistema nervioso. Las dos respuestas más comúnmente descritas son:
• Reacciones de enderezamiento. Se trata de reacciones automáticas que llevan la cabeza y el tronco de vuelta a la línea media.
• Reacciones de equilibrio. Se trata de reacciones pequeñas y a menudo imperceptibles que ayudan a mantener la postura y la posición
durante el movimiento.");
INSERT INTO keywords (name, description) VALUES ("Equilibrio ácido-básico", "Equilibrio normal entre ácidos y bases en el plasma sanguíneo medido en términos de concentración del ion hidrógeno o pH. Los
valores normales de ácido-base para los seres humanos se exponen en la siguiente tabla.");
INSERT INTO keywords (name, description) VALUES ("Valores normales del equilibrio ácido-básico en adultos", "");
INSERT INTO keywords (name, description) VALUES ("Unidades", "");
INSERT INTO keywords (name, description) VALUES ("Media", "");
