INSERT INTO keywords (name, description) VALUES ("94,0-97,5", "Véase Addosis/alcalosis metabólicayrespiratoria.");
INSERT INTO keywords (name, description) VALUES ("Equimosis", "Pequeña coloración hemorrágica, en la piel o en las mucosas, que forma una mancha azulada o morada.");
INSERT INTO keywords (name, description) VALUES ("Equinovaro", "Deformidad del pie en la que éste señala hacia abajo y hacia el interior. También conocido como talipes equinovarus.");
INSERT INTO keywords (name, description) VALUES ("Equipo de atención primaria", "Trabajadores sanitarios que se encuentran generalmente adscritos a un centro médico o quirúrgico que proporcionan servicios sanitarios
a la comunidad. Constituyen un ancho espectro de profesionales entre los que se incluyen los fisioterapeutas, quienes se están
convirtiendo cada vez más en parte integral de la atención primaria.");
INSERT INTO keywords (name, description) VALUES ("Equipo interdisciplinario", "Tipo de equipo en el que los profesionales y otros trabajadores se reúnen regularmente y trabajan en colaboración estrecha. No existen
límites profesionales para administrar una asistencia holística e integrada. Estos equipos tienden a ser relativamente informales y se
caracterizan por relaciones de igualdad entre los miembros. Los pacientes y clientes deberían considerarse elementos centrales en estos
equipos.");
INSERT INTO keywords (name, description) VALUES ("Equipo intradisciplinario", "Equipo formado por miembros de la misma profesión que pueden tener diferentes niveles y tipos de experiencia y habilidad. Los
pacientes y clientes deberían ser considerados componentes centrales de estos equipos.");
INSERT INTO keywords (name, description) VALUES ("Equipo multidisciplinario", "Equipo de un cierto número de profesionales y otros trabajadores que emprenden tratamientos e intervenciones relativamente
independientes unos de otros con una interacción limitada. El equipo está encabezado por un líder y tiende a ser formal y jerárquico.
Los equipos de asistencia sanitaria primaria se dividen en categorías en que el médico generalista dirige el equipo. Cada miembro del
equipo está vinculado por su propia educación profesional y creencias, las cuales pueden diferir considerablemente de las de los otros
miembros del equipo. Pacientes y clientes deben constituir la parte central de los equipos.");
INSERT INTO keywords (name, description) VALUES ("Erector espinal", "Grupo de músculos que se encuentran en la parte posterior de la columna vertebral. Sus acciones son complejas. Los músculos
extensores de la columna pueden ser capaces de controlar los movimientos vertebrales individuales y parece ser que el complejo del
erector espinal trabaja en patrones complejos para resistir la tendencia de la columna a flexionarse en varias posturas.M úsculo erector espinal y partes de las que está constituido");
INSERT INTO keywords (name, description) VALUES ("Ergonomía", "Estudio de cómo el lugar de trabajo se adapta al ser humano y a su función.");
INSERT INTO keywords (name, description) VALUES ("Eritema", "Enrojecimiento de la piel que se produce tras la aplicación de radiación ultravioleta (UVR), de calor o de frío. Se usa como base para
la dosificación de UVR. El nivel de UVR necesario para producir un mínimo grado perceptible de eritema (EPM o E1). Se establece en
un test previo al tratamiento con UVR. Los grados son de E1 a E4 y están basados en la profundidad del enrojecimiento, el tiempo
hasta que la piel se vuelve roja y el tiempo durante el cual permanece roja, el grado de pigmentación subsiguiente y cualquier
descamación.
Consúltese un libro de texto estándar para ver los grados y el método utilizado para graduar el eritema.");
INSERT INTO keywords (name, description) VALUES ("Eritema nudoso", "Alteración reumatológica caracterizada por la aparición de nódulos dolorosos y enrojecidos en la parte anterior de las piernas.");
INSERT INTO keywords (name, description) VALUES ("Error de tipo I (error α)", "Consiste en decidir negar la hipótesis nula cuando ésta es verdadera. El investigador determina que está pasando algo cuando ello no es
así.");
INSERT INTO keywords (name, description) VALUES ("Error de tipo II (error β)", "Equivocarse al negar la hipótesis nula cuando la hipótesis alternativa es verdadera. El investigador determina que no está pasando nada
cuando sí lo está.");
INSERT INTO keywords (name, description) VALUES ("Error estándar de la media", "Término de investigación que se aplica a la medición de la variabilidad. El error estándar de la media cuantifica el grado de precisión de
la media de la población.Escala análoga visual (EAV)
Escala que se emplea para el control del dolor. Se le pide a la persona que haga una marca en una línea. La marca puede medirse y
grabarse para futuras comparaciones utilizando una regla. Aunque estas medidas no son totalmente objetivas, permiten cambios a
medida que avanza el tratamiento.");
INSERT INTO keywords (name, description) VALUES ("Ejemplo de analogía visual usada en práctica fisioterápica", "");
INSERT INTO keywords (name, description) VALUES ("Escala de Ashworth", "La escala de Ashworth sirve para medir el tono muscular. Hay dos versiones: una estándar y otra modificada. Es fácil de usar en el
ámbito clínico; consiste en una escala graduada en cinco puntos. Ha sido muy utilizada en investigación, aunque hay un debate
considerable en la literatura sobre si realmente mide el tono o simplemente la resistencia al movimiento, que podría ser debida a una
contractura u otros factores. Ha sido modificada y muchas de las investigaciones recientes tienden a defender o a estar a favor de la
nueva escala de Ashworth.");
INSERT INTO keywords (name, description) VALUES ("Escala modificada de Ashworth", "0 = Sin aumento en el tono muscular.
1 = Ligero aumento en el tono muscular, manifestado por un bloqueo y relajación (catch and release) o por una mínima resistencia al
final del rango de movimiento, cuando la parte se mueve hacia la flexión o extensión/abducción o aducción, etc.
1+ = Ligero aumento en el tono muscular, manifestado por un bloqueo seguido de una mínima resistencia en todo el resto (menos de la
mitad) del ROM.
2 = Incremento más notable en el tono muscular en la mayor parte del ROM, pero la parte afectada es movida fácilmente.
3 = Incremento considerable en el tono muscular, en movimiento pasivo es difícil.
4 = La parte afectada está rígida en la flexión o extensión (abducción o aducción, etc.).");
INSERT INTO keywords (name, description) VALUES ("Escala de Berg", "Mide el equilibrio durante 14 tareas e incluye sentarse, levantarse, recoger objetos del suelo y girarse 360°. Tiene buena fiabilidad y es
fácil de llevar a cabo en el ambiente clínico.");
INSERT INTO keywords (name, description) VALUES ("Escala de coma de Glasgow", "La escala de coma de Gasglow es el sistema de puntuación más ampliamente utilizado para la cuantificación del nivel de conciencia
después de una lesión cerebral traumática.");
INSERT INTO keywords (name, description) VALUES ("Escala de coma de Glasgow", "Abertura de los ojos (O) Respuesta verbal (V) Respuesta motora (M)");
INSERT INTO keywords (name, description) VALUES ("4 = Espontánea 5 = Conversación normal 6 = Normal", "3 = A la voz 4 = Conversación desorientada 5 = Localizada al dolor
2 = Al dolor 3 = Palabras, pero no coherentes 4 = Retirada al dolor
1 = Nada 2 = Sin palabras, sólo sonidos 3 = Postura decorticada");
INSERT INTO keywords (name, description) VALUES ("1 = Nada", "");
INSERT INTO keywords (name, description) VALUES ("2 = Descerebración", "");
INSERT INTO keywords (name, description) VALUES ("1 = Nada", "");
INSERT INTO keywords (name, description) VALUES ("Total = O + V + M", "");
INSERT INTO keywords (name, description) VALUES ("Escala de control del locus de salud multidimensional", "(Wallston y cols., 1978).Escala de disnea de Borg
Escala de medida validada usada para cuantificar en los pacientes la gravedad de la disnea percibida.");
INSERT INTO keywords (name, description) VALUES ("Escala de disnea del consejo de investigación médica (CIM)", "Medida de la dificultad respiratoria útil para proporcionar una indicación de la limitación en la práctica de ejercicio.");
INSERT INTO keywords (name, description) VALUES ("Escala de eficacia propia de la artritis (ASES)", "Herramienta de medida útil para las alteraciones artríticas (Lorig y cols., 1989).");
INSERT INTO keywords (name, description) VALUES ("Escala de Likert", "Forma de recopilación de datos en la que la persona encuestada marca, con círculos o algún otro tipo de señal, una categoría
determinada, como se muestra por ejemplo en la tabla que incluimos a continuación.
Después, la respuesta será codificada, por ejemplo, 1-2-3-4-5, pero hay que tener presente que se trata sólo de una codificación. Los
datos recogidos son ordinales, es decir, tienen un orden inherente o una secuencia, pero no puede suponerse que las diferencias entre
cada respuesta sean de igual medida, es decir, la escala no es lineal.");
INSERT INTO keywords (name, description) VALUES ("Escala de Likert", "");
INSERT INTO keywords (name, description) VALUES ("Completamente de acuerdo", "");
INSERT INTO keywords (name, description) VALUES ("De acuerdo", "");
INSERT INTO keywords (name, description) VALUES ("Indeciso, dudoso", "");
INSERT INTO keywords (name, description) VALUES ("No estoy de acuerdo", "");
INSERT INTO keywords (name, description) VALUES ("Completamente en desacuerdo", "");
INSERT INTO keywords (name, description) VALUES ("Escala de medida del impacto de la artritis (AIMS)", "Herramienta de medida útil para las alteraciones artríticas (Meenan y cols., 1982).");
INSERT INTO keywords (name, description) VALUES ("Escala de Oxford", "Escala de uso fácil y relativamente rápido que es ampliamente utilizada en la práctica clínica. Sin embargo, no es muy objetiva, funcional
o sensible a los cambios por cuanto que los movimientos resistidos son contracciones concéntricas y el espacio entre los grados no es
lineal:
0 - Ausencia de contracción.
1 - Sólo aparece un amago de la contracción, sin movimiento de la articulación.
2 - El movimiento sólo es posible a favor de la gravedad.
3 - El movimiento en contra de la gravedad es posible.
4 - El movimiento contra resistencia es posible.
5 - Es posible un movimiento funcional normal.");
INSERT INTO keywords (name, description) VALUES ("Escala de valoración motora", "Medida de resultados utilizada para valorar la función motora grosera. Tiene una versión modificada llamada");
INSERT INTO keywords (name, description) VALUES ("Modifled Motor", "Assessment Scale (MMAS). Fue desarrollada por J.H. Carr y R.B. Shepherd y es utilizada por los fisioterapeutas neurológicos que
emplean el enfoque de reaprendizaje motor.");
INSERT INTO keywords (name, description) VALUES ("Escala modificada de Ashworth", "Véase Escala de Ashworth.");
INSERT INTO keywords (name, description) VALUES ("Escáner óseo", "Técnica radiográfica que a menudo implica inyectar una sustancia radiactiva suave que se une a los glóbulos blancos, para que tras un
período de espera se lleve a cabo un escáner para averiguar cuáles son las áreas de inflamación o infección. También utilizado para
identificar la localización de tumores.");
INSERT INTO keywords (name, description) VALUES ("Escáner óseo con tecnecio", "Investigación radiológica sensitiva, que utiliza un radioisótopo, usada en la detección de fracturas de estrés, así como en otras patologíasEscáner PET
Abreviatura médica común de tomografía de emisión de positrones. Es similar a una tomografía computarizada (TC), pero utiliza la
emisión de positrones por un radioisótopo. Puede emplearse para mostrar el flujo sanguíneo regional y la oxigenación del cerebro.");
INSERT INTO keywords (name, description) VALUES ("Escáner V/P", "Escáner que puede utilizarse para el diagnóstico de una embolia pulmonar.");
INSERT INTO keywords (name, description) VALUES ("Escápula", "La escápula, unida a la pared torácica por la clavícula, actúa como una plataforma móvil para los movimientos del miembro superior; es
delgada en su parte central (puede comprobarse mirando una a contraluz) y gruesa en sus bordes medial y lateral, donde se insertan
músculos potentes.
Escápula derecha: (A) visión posterior; (B) visión anterior");
INSERT INTO keywords (name, description) VALUES ("Escápula alada", "Lesión que se produce cuando se empuja el brazo extendido contra resistencia. La escápula »se ala« cuando existe debilidad del
serrato anterior, normalmente debido a una lesión del nervio torácico largo.");
INSERT INTO keywords (name, description) VALUES ("Escarotomía", "Tratamiento de las quemaduras en que el cirujano disminuye la tensión de los tejidos quemados con incisiones longitudinales a través de
la escara y a lo largo de toda su longitud.Quemaduras de grosor completo: piel inelástica de apariencia similar al cuero con escarotomías hacia el miembro inferior");
INSERT INTO keywords (name, description) VALUES ("Escayola de París", "Venda de escayola que puede ser moldeada en torno al miembro cuando está mojada y después se endurece. El método estándar de
entablillado externo sigue siendo la escayola de París. Actualmente se emplean materiales sintéticos para las férulas en algunas fracturas
por impermeabilidad y ligereza. El termoplástico ligero y ajustable puede ser moldeado en el miembro y remodelado si hay inflamación
o atrofia que causan cambios en el contorno del miembro. Algunos materiales sintéticos, sin embargo, son menos maleables y no
pueden ser moldeados tan efectivamente como la escayola de París. A veces pueden causar alergias. Es necesario emplear una sierra
para extraer el molde; esta herramienta especial tiene una cuchilla oscilante que corta sin dañar la piel.");
INSERT INTO keywords (name, description) VALUES ("Ventajas de la escayola de París", "• Evita la cirugía y sus complicaciones.
• No hay riesgo de infección.
• Aplicación rápida.
• El paciente puede ser rápidamente dado de alta.
• Económico, relativamente fácil de aplicar con algo de práctica.
• Existen nuevos moldes ligeros.
• El material es radiotranslúcido (los huesos pueden ser radiografiados a través de la escayola).
• Podría absorber fluidos o sangrados. La extensión del sangrado puede observarse en la misma escayola y monitorizarse diariamente.
• Puede moldearse durante varios minutos antes de su endurecimiento.");
INSERT INTO keywords (name, description) VALUES ("Desventajas de la escayola de París", "• Puede no ser posible realizar una correcta reducción de la fractura o mantener la reducción.
• Puede requerir cirugía unos días después.
• La escayola necesita extraerse o abrir una ventana (extraer una pieza de la escayola) para inspeccionar la piel.
• Puede ser necesario retirarla en caso de aumento de la inflamación o recolocarla cuando la inflamación ha remitido.
• Huele mal si se moja.
• Pesada.
• Puede agrietarse.
• Si se pega a la piel puede causar úlceras.
• Debe pedirse consejo médico si ocurre algo de lo siguiente en el miembro en el que se ha aplicado la escayola de París o una férula
simple:
— Coloración azulada o pálida de la piel de la parte lesionada.
— Entumecimiento, hormigueo o vibración de la parte lesionada.
— Incapacidad para mover los dedos de la mano o el pie.— Dolor excesivo en la parte lesionada.
— Inflamación, tumor o hinchazón en torno al extremo de la escayola.
— Olor fétido bajo la escayola.
— Si comienza a aflojarse o deslizarse.
Escherichia coli (E. coli)
Bacilo con forma de vara que abunda en el intestino grueso.");
INSERT INTO keywords (name, description) VALUES ("Esclerosis lateral amiotrófica (ELA)", "Forma más común de enfermedad de la motoneurona caracterizada por debilidad muscular, atrofia, espasticidad, disfagia,");
INSERT INTO keywords (name, description) VALUES ("disartria,", "dificultad respiratoria, daño de las neuronas motoras inferiores y superiores y anormalidades de los reflejos. Es una enfermedad
degenerativa que no tiene un tratamiento probado y, por lo tanto, el cuidado y la gestión de los síntomas es importante y debe ser
llevado a cabo por un equipo multi-disciplinario. Existe un grupo de apoyo activo: asociación de la enfermedad de la motoneurona.
Ir a http://www.mndassociation.org");
INSERT INTO keywords (name, description) VALUES ("Esclerosis múltiple", "Enfermedad desmielinizante de causa desconocida que puede dar lugar a una extensa degeneración del sistema nervioso central y
déficits neurológicos progresivos.
Se divide en:
• Primaria progresiva. Declive progresivo e ininterrumpido de la función.
• Recaídas remitentes. Una historia de »brotes« con períodos temporales de pérdida de la función seguidos de períodos de
recuperación posterior de los niveles previos de capacidad. Puede cambiar con el tiempo a secundaria progresiva.
• Secundaria progresiva. La enfermedad empezará inicialmente como »recaídas remitentes« y luego se instalará en una fase progresiva.
Observación clínica La esclerosis múltiple es la causa más común de discapacidad en los jóvenes. La presentación clínica puede
variar enormemente dependiendo de la localización de la lesión y puede incluir espasticidad, ataxia, incontinencia, visión alterada y
dificultades en la deglución y el lenguaje.");
INSERT INTO keywords (name, description) VALUES ("Escoliosis", "");
INSERT INTO keywords (name, description) VALUES ("Escoliosis", "Curvatura lateral de la columna vertebral. La causa puede ser estructural, compensatoria o protectora. En la escoliosis estructural,
existe una rotación vertebral asociada con la curvatura lateral, con una acentuación tanto de la curva como de la rotación en la flexión
anterior.
EsguinceTiene lugar cuando existe una distensión de las estructuras capsulares o ligamentosas. Una articulación que se fuerza más allá de su
rango de movilidad puede estirarse, distenderse o a veces sufrir un deterioro de los tejidos conectivos que estabilizan la articulación. Se
clasifican en:");
INSERT INTO keywords (name, description) VALUES ("Esguince de primer grado", "Unas pocas fibras están desgarradas.");
INSERT INTO keywords (name, description) VALUES ("Esguince de segundo grado", "Aproximadamente la mitad de las fibras están desgarradas.");
INSERT INTO keywords (name, description) VALUES ("Esguince de tercer grado", "Desgarro completo.");
INSERT INTO keywords (name, description) VALUES ("Esguince de tobillo", "Distensión violenta de los ligamentos de la articulación del tobillo, siendo el más común aquel que se produce por una lesión de
inversión, que daña al fascículo anterior del ligamento lateral del tobillo.");
INSERT INTO keywords (name, description) VALUES ("Consejo para el estudiante Esguince = ligamento", "");
INSERT INTO keywords (name, description) VALUES ("Tirón = músculo o tendón", "");
INSERT INTO keywords (name, description) VALUES ("Espacio articular", "Término que hace referencia al espacio que aparece en la radiografía de una articulación. No es, de hecho, un espacio, ya que está
ocupado por cartílago hialino articular, pero éste es invisible en la radiografía tradicional.");
INSERT INTO keywords (name, description) VALUES ("Espacio muerto", "Aire presente en el tracto respiratorio no implicado directamente en el intercambio gaseoso. Es de alrededor de 150 ml en los se res
humanos.");
INSERT INTO keywords (name, description) VALUES ("Espacio pleural", "Espacio potencial entre dos pleuras. Está lleno de una capa fina de fluido seroso, la cual permite a las superficies pleurales deslizarse
fácilmente una sobre la otra durante todo el ciclo respiratorio, al tiempo que permite la transmisión de fuerzas de la pared torácica a los
pulmones. La interrupción de este espacio (p. ej., por traumatismo torácico) puede dar lugar a una separación de las dos superficies
pleurales, en la que la pleura parietal permanece contra la pared torácica mientras la pleura visceral y los pulmones se desplazan hacia
dentro, lejos de la pared torácica (p. ej., neumotórax).Espacio subacromial
Región del hombro que se encuentra rodeada por la articulación del mismo nombre, la articulación subacromial, entre el húmero y un
arco superior, compuesto por el proceso acromial y la apófisis coracoides de la escápula, unidos por el ligamento coracoacromial. Este
arco está recubierto por el líquido sinovial de la bolsa subacromial.");
INSERT INTO keywords (name, description) VALUES ("Espasmo", "Este término describe un aumento transitorio en el tono de un músculo o grupo muscular en presencia de patología neurológica.
Observación clínica Se debería explorar la causa de los espasmos ya que pueden indicar, por ejemplo, una infección en el tracto
urinario o el comienzo de un foco de presión en un paciente con lesión neurológica.");
INSERT INTO keywords (name, description) VALUES ("Espasmo flexor", "Espasmo (contracción involuntaria de los músculos) en el grupo muscular flexor. Normalmente se da en el miembro inferior, con flexión
de cadera y rodilla y flexión dorsal del pie. Después del espasmo, la pierna cae otra vez. Los espasmos pueden ser dolorosos y dar
lugar a posturas corporales incorrectas o anormales.");
INSERT INTO keywords (name, description) VALUES ("Espasmo muscular", "Estado de un músculo en contracción incapaz de relajarse voluntariamente. Puede ocurrir localmente en un músculo, por lo general
como respuesta a la lesión de un tejido blando, mientras que en pacientes con daño neurológico la zona afectada puede ser muy
extensa, abarcando la pierna o el brazo enteros.");
INSERT INTO keywords (name, description) VALUES ("Espasmo protector", "Espasmo muscular que a menudo ocurre después de una lesión, traumatismo o dolor. Es un intento del cuerpo por detener el
movimiento; desafortunadamente el espasmo está a menudo fuera de toda proporción con la lesión inicial. Los pacientes pueden
quejarse de una »espalda bloqueada«; en ocasiones, los espasmos pueden llegar a perpetuarse, convirtiéndose en el problema
primordial. Un pack caliente o un masaje pueden ser sumamente efectivos para aliviar el dolor y facilitar el movimiento.
EspasticidadTambién conocida como aumento de tono, hipertonicidad e hiperreflexia.
En sentido estricto describe una alteración motora que se caracteriza por un aumento de los reflejos de estiramiento dependiente de la
velocidad. Se da en una gran variedad de alteraciones neurológicas como la apoplejía, la esclerosis múltiple y la lesión cerebral.
Observación clínica La presencia de espasticidad en algunos pacientes es esencial para la función; por tanto, debe llevarse a cabo
una valoración completa y cuidadosa.");
INSERT INTO keywords (name, description) VALUES ("Especificidad (de un test)", "Proporción de individuos clasificados como negativos de acuerdo a unas referencias, que se identifican correctamente en el test de
estudio. Proporción de personas libres de enfermedad que dan un test negativo.");
INSERT INTO keywords (name, description) VALUES ("Espina bífida", "Defecto congénito de la columna vertebral caracterizado por la ausencia de arco vertebral, a través del cual la médula espinal puede
protruir.");
INSERT INTO keywords (name, description) VALUES ("Espina bífida oculta", "Ausencia de unión entre las láminas. Puede deberse simplemente a un fallo en la osificación de un arco neural, o puede estar asociada
con algunas anormalidades del saco dural, cola de caballo y médula espinal.");
INSERT INTO keywords (name, description) VALUES ("Espirometría", "Medida del flujo de aire y volúmenes pulmonares en el tiempo. Estas medidas incluyen el volumen espiratorio forzado en un segundo (o
en otro tiempo especificado) (FEV 1 ), la capacidad vital forzada (FVC) y la relación espiratoria forzada (FER), es decir, la relación
FEV1/FVC. Dichas medidas pueden utilizarse tanto para el diagnóstico como para propósitos de control, pero dependen del esfuerzo,
por lo que se requiere una técnica correcta para conseguir resultados precisos.
• FEV 1 . Volumen de aire expulsado en el primer segundo.
• FVC. Volumen total de aire espirado a partir de una inspiración máxima.
• FER. Relación entre FEV 1 y FVC, es decir, FEV 1 /FVC × 100. Normalmente se encuentra alrededor del 80%. Cuando la relación es
< 70% se detecta obstrucción del flujo aéreo, como por ejemplo en la enfermedad pulmonar obstructiva crónica (EPOC) y el asma;
por el contrario, si la relación es normal o está un poco elevada (con valores reducidos tanto para FEV1 como para FVC), ello es
indicativo de alteraciones restrictivas como la fibrosis, edema, deformidad de la caja torácica y alteraciones neuromusculares.
Cuando se necesita un análisis más detallado de la función pulmonar, se miden otros volúmenes.
Estos incluyen:
• FRC. Capacidad funcional residual (aproximadamente 2.500 ml). Es la cantidad de aire residual en los pulmones después de una
espiración normal corriente. (Se requiere pletismografía para medir este volumen pulmonar.)
• TLC. Capacidad pulmonar total (aproximadamente 6 l). Es el volumen total de aire en los pulmones después de una inspiración
máxima.
• RV. Volumen residual (aproximadamente 1.200 ml). Es la cantidad de aire que queda en los pulmones después de una espiración
máxima. Este volumen no puede medirse utilizando técnicas espirométricas normales. La pletismografía corporal o técnicas de dilución
de gases son necesarias para obtener este valor.
Vt o volumen corriente (aproximadamente 500 ml). Es el volumen de aire intercambiado durante una respiración normal en reposo.");
INSERT INTO keywords (name, description) VALUES ("Espirometría incentivadora", "Método para aumentar la expansión pulmonar mediante el uso de un flujo simple o de un instrumento volumétrico, como por ejemplo
los espirómetros incentivadores Triflo® y Voldyne®, que dan feedback visual si se ha alcanzado el objetivo fijado. Los instrumentos
fomentan una inhalación mantenida y máxima que disminuye la presión pleural y, por lo tanto, favorecen la insuflación. Hay pocas
complicaciones asociadas con su uso, pero éstas incluyen hiperventilación, dolor en pacientes insuficientemente anestesiados, hipoxemia
secundaria a interrupciones en la terapia y fatiga.");
INSERT INTO keywords (name, description) VALUES ("Espolón calcáneo", "Formación de un espolón óseo (eminencia en forma de espuela de gallo), que se extiende desde la cara inferior del calcáneo hasta lafascia plantar.");
INSERT INTO keywords (name, description) VALUES ("Espondilitis anquilosante", "Poliartritis seronegativa que afecta principalmente a la columna, y que se caracteriza por la inflamación en el lugar de unión del ligamento
o tendón con el hueso (entesopatía). Presenta una rigidez progresiva y dolorosa de las articulaciones y ligamentos. Comienza de forma
casi exclusiva en la etapa tardía de la edad adulta y típicamente afecta a hombres y mujeres en una relación 3:1. Está estrechamente
relacionado con la HLA B27, y el 90% de los que la padecen son HLA B27 positivos; sin embargo, una proporción de la población
son B27 positivos y no presentan espondilitis anquilosante.");
INSERT INTO keywords (name, description) VALUES ("Espondilolistesis", "");
INSERT INTO keywords (name, description) VALUES ("Espondilolistesis", "Desplazamiento anterior de una vértebra sobre su inferior. Se suele apreciar en L5/S1. El grado de espondilolistesis se determina por la
distancia que existe entre la vértebra deteriorada y su homóloga; existen cuatro grados.");
INSERT INTO keywords (name, description) VALUES ("Espondilosis", "Véase Espondilosis cervical y Espondilosis lumbar.");
INSERT INTO keywords (name, description) VALUES ("Espondilosis", "Causada por un defecto en los pares interarticulares, concretamente un pequeño fragmento de hueso que descansa entre la lámina y la
apófisis articular inferior y el pedículo y la apófisis articular superior. Su origen puede ser congénito, traumático o por sobreuso. En las
visiones radiográficas oblicuas, en las que esta zona tiene la apariencia de un perrito, las espondilosis a través de los pares
interarticulares serían semejantes al collar alrededor del cuello del perro.
La característica principal de la espondilosis es la pérdida de agua en el disco. Los desgarros también tienen lugar en el núcleo, el anillo
y la lámina. La alimentación del disco adulto es más precaria que la del disco inmaduro y los primeros signos de espondilosis suelen
presentarse clínicamente alrededor de los 30 años, siendo más común a los 45. Los cambios patológicos que tienen lugar son los
mismos independientemente del lugar, pero las diferencias en la anatomía funcional hacen que haya numerosos síntomas y signos. La
patología incluye el engrosamiento del anillo fibroso, separación de las fibras de colágeno y aparición de desgarros en el anillo. El núcleopulposo se deshidrata y se vuelve más fibroso, y el disco pierde peso. Estos cambios pueden presentarse sin que aparezcan síntomas y
signos. Tiene lugar una alteración del cuerpo vertebral, debido a una biomecánica alterada del disco, que tracciona del periostio por las
uniones del anillo fibroso. También puede haber calcificaciones dentro del cuerpo vertebral. Los ligamentos intervertebrales pueden
contraerse y engrosarse, especialmente en los lugares donde existen cambios importantes. La duramadre de la médula espinal, que
forma una funda alrededor de la raíz nerviosa, puede inducir cambios inflamatorios de bajo grado. Esto puede dar lugar a adherencias
en la raíz nerviosa con síntomas neurales asociados.
Normalmente, el cambio principal es la osteofitosis, la formación de espuelas óseas a lo largo de la unión de los cuerpos vertebrales y
los correspondientes discos intervertebrales.");
INSERT INTO keywords (name, description) VALUES ("Espondilosis cervical", "Artritis degenerativa que afecta a la columna cervical.
Véase Insuficiencia vertebral basilar.");
INSERT INTO keywords (name, description) VALUES ("Estadística descriptiva", "Término de investigación que se refiere a las estadísticas que transmiten información e interpretan grandes conjuntos de números de un
modo eficiente. Comparar con las estadísticas inferenciales, las cuales pueden utilizarse para realizar inferencias de los datos y expresar
la confianza con la que se puede llevar a cabo la generalización de toda una población.");
INSERT INTO keywords (name, description) VALUES ("Estadísticas inferenciales", "Son aquellas que pueden utilizarse para hacer deducciones a partir de los datos y determinar hasta qué punto se puede generalizar a
toda una población.");
INSERT INTO keywords (name, description) VALUES ("Estado del bienestar", "Sistema a través del cual el Gobierno proporciona un mínimo de ingresos y servicios garantizados. En Gran Bretaña el estado de
bienestar está unido a una legislación de amplia escala, aprobada después de la Segunda Guerra Mundial y que incluye el National
Health Service Act (1948) y el National Assistance Act (1948). Los orígenes del estado de bienestar se remontan, sin embargo, a
mucho antes.");
INSERT INTO keywords (name, description) VALUES ("Estado epiléptico", "Estado que puede suponer un riesgo para la vida, caracterizado por ataques alternados con fases de inconciencia. Es una emergencia
mé-dica. Puede deberse a muy diversas causas: lesión en la región frontal del cerebro, infecciones, fármacos o drogas, etc.");
INSERT INTO keywords (name, description) VALUES ("Estado socioeconómico", "Medida de clasificación de los individuos, familias y hogares. Los indicadores incluyen la ocupación, los ingresos, la educación y la
vivienda.");
INSERT INTO keywords (name, description) VALUES ("Estado vegetativo", "Véase EVP.
Consecuencia de una enfermedad o lesión cerebral grave que causa daños irrevocables en el sistema nervioso central. El paciente se
vuelve dependiente de otros para todas las actividades de la vida diaria.
Existen tres características principales del estado vegetativo:
1. El paciente tiene ciclos de sueño y de despertar.
2. Todas las respuestas pueden identificarse como patrones reflejos.
3. El paciente lleva a cabo respuestas no significativas y no tiene conciencia (Andrews, 1999).
En las recomendaciones del International Working Party (1996) , los términos »persistente« o »permanente« no deberían utilizarse, ya
que confunden pronóstico con diagnóstico.");
INSERT INTO keywords (name, description) VALUES ("Estándar", "Descripción del nivel de conducta o de cuidados aceptables, convencionalmente acordado, que sirve como criterio para juzgar y medir
los casos concretos.Estenosis del canal espinal (estenosis espinal)
Reducción de los diámetros ante-roposterior y lateral del canal medular. Puede deberse a factores congénitos, factores de desarrollo o
enfermedades degenerativas. Las características incluyen: dolor en las nalgas, muslos o gemelos que empeoran con la marcha o el
ejercicio. El dolor en la espalda irradia hacia las piernas.
Canal espinal (zona sombreada) para indicar (A) tamaño normal y (B) estenosis espinal");
INSERT INTO keywords (name, description) VALUES ("Estenosis mitral", "Patología cardíaca, más común en mujeres que en hombres, cuya causa más frecuente es la endocarditis reumática. La cicatrización o
fusión de las cúspides de la válvula, de modo que la abertura de la válvula adopta una forma de embudo, provoca la estenosis mitral y la
calcificación de la válvula en la edad adulta del individuo, lo que la hace más estrecha y menos funcional (Moore, 2003).");
INSERT INTO keywords (name, description) VALUES ("Estereognosia", "Este término hace referencia a la capacidad de reconocer un objeto cuando se coloca o manipula con la mano. Permite detectar la
textura, peso, tamaño y forma del mismo sin utilizar la visión.");
INSERT INTO keywords (name, description) VALUES ("Estereotipo", "Concepción generalizada, sobresimplificada, parcial e inflexible sobre un grupo social. Los estereotipos se asocian frecuentemente con
grupos oprimidos y proporcionan justificaciones para mantener la opresión.");
INSERT INTO keywords (name, description) VALUES ("Esternotomía", "Incisión utilizada en cirugía torácica que divide el esternón verticalmente.");
INSERT INTO keywords (name, description) VALUES ("Esternotomía media", "Incisión quirúrgica que divide el esternón.");
INSERT INTO keywords (name, description) VALUES ("Esteroides anabolizantes", "Derivados de la testosterona que se utilizan para aumentar el rendimiento e incrementar la masa y la fuerza muscular. Pueden ser
tomados vía oral o parenteral.");
INSERT INTO keywords (name, description) VALUES ("Estetoscopio", "Instrumento utilizado para la auscultación.");
INSERT INTO keywords (name, description) VALUES ("Estigma", "Término asociado con el trabajo del sociólogo Ervin Goffman. Su uso generalmente denota vergüenza y desgracia atribuida a la persona
(p. ej., el estigma de ser prisionero), aunque en la teoría más formal denota una relación de devaluación (p. ej., el estigma de ser
discapacitado).");
INSERT INTO keywords (name, description) VALUES ("Estilo de vida", "Término con diferentes significados. Puede denotar el contraste entre las formas de vida de diferentes grupos en la sociedad, como
jóvenes ricos, personas mayores y desempleados. También conceptualiza formas alternativas de vivir, evidente en valores,
comportamientos, ropa, comida y consumo en general.Estimulación eléctrica funcional (EEF)
La EEF es un tipo específico de estimulación eléctrica neuromuscular cuyo objetivo es aumentar la función más que conseguir una
contracción muscular. Las formas simples de EEF incluyen la estimulación eléctrica de los músculos flexores dorsales del tobillo
después de un ictus u otra lesión del sistema nervioso central (SNC). La estimulación es activada por un mecanismo con interruptor en
el tobillo y localizado en el zapato. Esto permite una estimulación oportuna de los flexores dorsales, elevando los dedos de los pies,
evitando el arrastre del pie durante la fase de oscilación y promoviendo un mejor golpe de talón (estimuladores de la caída del pie).
Formas más complejas de EEF incluyen los sistemas de bipedestación y marcha utilizados por pacientes con déficits neurológicos (p.
ej., pacientes parapléjicos). Estos sistemas de estimulación presentan muchos canales controlados por ordenador; en los sistemas más
avanzados se usan electrodos implantados. Al estimular numerosos grupos musculares en una secuencia cuidadosamente programada,
se puede lograr un patrón de estimulación que imita una actividad funcional (p. ej., patrones de sedestación a bipedestación y de
marcha básica). Recientes avances en el control de sistemas por ordenador para estimular patrones complejos junto con avances
tecnológicos en el implante de electrodos han permitido el avance en estas complejas aplicaciones, y cada vez son más utilizados en
centros especializados.");
INSERT INTO keywords (name, description) VALUES ("Estimulación eléctrica nerviosa transcutánea (TENS)", "La TENS consiste en la liberación de impulsos eléctricos de corta duración (50-250 μs) dirigidos a los nervios sensitivos y que pueden
lograr, por tanto, el alivio sintomático del dolor de forma efectiva. Es una modalidad ampliamente utilizada y que ha demostrado buenos
resultados. Los aparatos de TENS generalmente son pequeños y funcionan a pilas, por lo que resultan apropiados para
autotratamiento. Algunos de los grandes estimuladores eléctricos que se utilizan en la práctica clínica hospitalaria ofrecen una opción de
TENS que consigue los mismos efectos. La TENS es una forma de estimulación generalmente bien tolerada. Con la TENS tradicional o
la de alta frecuencia (80-150 Hz), los nervios diana son las fibras sensitivas (Aβ). Una vez estimuladas, servirán para cerrar la puerta de
entrada del dolor para así reducir la conciencia de éste. La estimulación con frecuencias bajas (2-5 Hz) utilizando acupuntura como
AL-TENS trata de estimular las fibras sensitivas Ad y la producción de opioides en la médula espinal, haciendo descender la
modulación extrasegmentaria.
El modo de TENS en ráfagas (bursts) utiliza una salida interrumpida con máquinas comúnmente preprogramadas para estimular de 2 a
3 veces/s. La salida modulada es también una característica estándar y se puede lograr variando la amplitud, la frecuencia o la duración
de los impulsos estimulantes.
Los electrodos se colocan generalmente en cualquier zona del área dolorosa, proporcionando estimulación segmentaria. La colocación
de electrodos alternativa (y evidenciada) incluye la estimulación de raíces nerviosas espinales, nervios periféricos, puntos motores,
dermatomas, miotomas o esclerotomas, acupuntura y puntos gatillo.");
INSERT INTO keywords (name, description) VALUES ("Estimulación eléctrica neuromuscular (EENM)", "Existen muchos aparatos clínicos que administran una forma de estimulación eléctrica con objeto de estimular nervio y músculo. Existe
un cierto grado de confusión por lo que hace a la terminología, aunque la EENM es probablemente el término genérico preferido. La
existencia de variantes como la EENM crónica (EENMC) responde al hecho que la estimulación no es un tratamiento de corta
duración, más que implicar que ésta deba utilizarse únicamente para lesiones crónicas. La EENM ha sido aplicada en circunstancias
clínicas muy diferentes, desde la reducción de la espasticidad en niños con lesión del SNC hasta el fortalecimiento muscular en atletas
de élite, desde la curación de una herida hasta la reeducación de los músculos esqueléticos. Probablemente es más apropiado describir
la forma de estimulación como alterna, directa o pulsada (más que utilizar el nombre de una máquina en particular). La EENM puede
emplearse para mejorar la función muscular en pacientes con atrofia significativa, para prevenir la atrofia durante la inmovilización, como
parte de un programa de reeducación neuromuscular, para facilitar el equilibrio muscular, y como parte de un programa de control del
suelo pélvico en caso de incontinencia. Se ha utilizado en pacientes con escoliosis como modo de facilitar la corrección. En neurología,
la EENM puede emplearse para facilitar la recuperación motora e incrementar la fuerza, reducir el impacto de la subluxación del
hombro después de un golpe y como ayuda en programas de tratamiento de la espasticidad.");
INSERT INTO keywords (name, description) VALUES ("Estimulación pulsada de alto voltaje (EPAV)", "Término electroterápico que se aplica a un tipo de corriente pulsante con impulsos monofásicos muy cortos; la forma suele ser o bien un
impulso con dos picos iguales, o un impulso doble sin intervalo entre los impulsos. La duración es normalmente menor de 50 μs, por lo
que la corriente es bien tolerada y existe bajo riesgo de irritación cutánea. La EPAV (también conocida como CPAV) tiene una
corriente media baja, ideal para usar en un estimulador portátil cargado con batería; la carga por impulso puede ser demasiado baja
para conseguir una estimulación efectiva de músculos grandes, incluso usando múltiples cátodos (opción de usar una corriente alterna oEPAV, impulso de pico gemelo");
INSERT INTO keywords (name, description) VALUES ("Estiramiento", "Ejercicios que normalmente se utilizan para movilizar el tejido neural o muscular hasta los límites del rango disponible. Los estiramientos
se pueden aplicar de uno o dos modos: dinámico o estático.");
INSERT INTO keywords (name, description) VALUES ("Estiramiento dinámico", "Implica un rango de movimiento activo y no debería confundirse con el estiramiento balístico, que implica el uso de movimientos
repetitivos, de rebote, dinámicos y rítmicos llevados a cabo a velocidades altas. El estiramiento dinámico implica el aumento progresivo
del rango a través de movimientos sucesivos hasta que se alcanza el final del rango. Estos ejercicios son especialmente útiles en el
ámbito de la rehabilitación deportiva más avanzada, ya que aumentan la función dinámica y el control neuromuscular debido a la
repetición y práctica; por lo tanto, aumentan la memoria del movimiento.");
INSERT INTO keywords (name, description) VALUES ("Estiramiento estático", "Como su nombre indica, implica el mantenimiento de una posición durante un período de tiempo para conseguir el efecto deseado. El
tiempo efectivo de mantenimiento del estiramiento estático es de 30 s. El estiramiento estático es un movimiento controlado, lento, con
énfasis en el alineamiento correcto del cuerpo. Los elementos del control postural fino y de la conciencia postural son esenciales durante
los ejercicios de estiramiento estático, lo cual puede potenciarse con el uso de la retroalimentación y la corrección por parte del
fisioterapeuta, así como con el uso de un espejo.
Ejercicios de estiramiento: guía práctica");
INSERT INTO keywords (name, description) VALUES ("Antes de realizar el estiramiento", "• Antes de comenzar un programa de estiramiento, hay que asegurarse de que no se ha identificado ninguna contraindicación al estiramiento en la valoración
• Asegurarse de que hay una base lógica y razonada para el programa de estiramiento; por ejemplo, si hay un bloqueo óseo al movimiento causado por osteófitos
• Considerar de qué modo el paciente colaborará en la realización de un programa de estiramiento en su domicilio
• Explica cómo y por qué se está realizando el estiramiento para conseguir la máxima implicación y mínima resistencia
• Considerar cómo se puede realizar el estiramiento de la forma más cómoda; por ejemplo, utilizando un paquete de calor o hidroterapia");
INSERT INTO keywords (name, description) VALUES ("Durante el estiramiento", "• Hacer una toma firme, pero manteniendo al paciente cómodo. Asegurar al paciente que el estiramiento se detendrá cuando él lo pida");
INSERT INTO keywords (name, description) VALUES ("• Estabilizar las articulaciones cuando sea necesario", "");
INSERT INTO keywords (name, description) VALUES ("• En los músculos biarticulares, estirar en una articulación", "");
INSERT INTO keywords (name, description) VALUES ("• Realizar el estiramiento lento y mantenido, sin rebotes", "• El paciente debe experimentar una sensación de tirantez, no de dolor");
INSERT INTO keywords (name, description) VALUES ("• M antener la posición durante 30 s (Bandy, 1997)", "• Si la tensión disminuye, progresar un poco en el movimiento");
INSERT INTO keywords (name, description) VALUES ("• Deshacer el estiramiento con lentitud", "");
INSERT INTO keywords (name, description) VALUES ("Después del estiramiento", "• Avisar al paciente de la sensación que va a tener después del estiramiento
• Recordar que una vez que se ha conseguido el movimiento, será necesario un control muscular activo en todo ese rango, así como alguna forma de mantener el");
INSERT INTO keywords (name, description) VALUES ("estiramiento a largo plazo", "");
INSERT INTO keywords (name, description) VALUES ("Estiramiento del nervio ciático", "Véase Test/signo de Lasègue.
Test de la movilidad de las raíces nerviosas y de la duramadre que los reviste.");
INSERT INTO keywords (name, description) VALUES ("Estiramiento dinámico", "Véase Estiramiento.Estiramiento reflejo
Está formado por trayectos mono y polisinápticos que conducen la información sensitiva (aferente) de los husos musculares y pueden
dar lugar a la contracción de una fibra muscular o músculo. El papel de este reflejo no está muy claro, pero se cree que es importante
en la actividad diaria.");
INSERT INTO keywords (name, description) VALUES ("Estrabismo", "Desviación del alineamiento de un ojo respecto al otro.");
INSERT INTO keywords (name, description) VALUES ("Estrategias de afrontamiento", "Comúnmente asociadas con estrategias cognitivas y emocionales. El trabajo terapéutico se puede centrar en ayudar a personas para
que adquieran estrategias de afrontamiento beneficiosas cuando las circunstancias cambian, como en una alteración adquirida.");
INSERT INTO keywords (name, description) VALUES ("Estreñimiento", "Se refiere a la deposición de heces duras o a su evacuación infrecuente o difícil.");
INSERT INTO keywords (name, description) VALUES ("Estrés", "Tensión psicológica que puede tener manifestaciones físicas, asociada con eventos, experiencias o circunstancias que son difíciles de
tolerar y sobrellevar.
Véase Ansiedad.");
INSERT INTO keywords (name, description) VALUES ("Estribo", "Técnica de sujeción del tobillo utilizando esparadrapo rígido (normalmente óxido de zinc). El esparadrapo se coloca en el tobillo,
adhiriéndolo de medial a lateral a la superficie inferior del talón, al modo de un estribo.");
INSERT INTO keywords (name, description) VALUES ("Estridor", "Sonido agudo y similar a un silbido que se escucha durante la inspiración; indica obstrucción de la tráquea o laringe.
Estructura muscularPartes de un músculo. Partes componentes de un músculo voluntario, desde la unidad funcional (miofibrillas) al epimisio, el cual
envuelve todo el músculo y se continúa con los tendones de origen e inserción.
(A) Músculo. (B) Fibra muscular (célula).
Miofibrilla.");
INSERT INTO keywords (name, description) VALUES ("(C)", "");
INSERT INTO keywords (name, description) VALUES ("Estudio de cohorte", "Término de investigación. Estudio longitudinal que comienza con la selección de dos grupos de pacientes (cohortes): uno de ellos es
expuesto a la variable de interés y el otro no. Tras un seguimiento en el tiempo (prospectivo) de los dos grupos se miden las diferencias
entre ellos.");
INSERT INTO keywords (name, description) VALUES ("Estudio piloto", "Término de investigación que se aplica a la realización de un estudio a pequeña escala bajo las mismas condiciones del estudio de
investigación propuesto; es útil como medio de resolver posibles problemas antes de empezar el verdadero estudio.");
INSERT INTO keywords (name, description) VALUES ("Estudio transversal", "Término de investigación. Medición de una población entera por la presencia o ausencia de una enfermedad y/u otra variable en todos
sus miembros (o en una muestra representativa) y sus principales factores de riesgo en un momento determinado o en un intervalo de
tiempo.");
INSERT INTO keywords (name, description) VALUES ("Estudio y aprendizaje autodirigidos", "Estrategia de aprendizaje centrada en el alumno, en la que éste determina sus necesidades de aprendizaje, las estrategias para satisfacer
estas necesidades, los recursos de aprendizaje requeridos y cómo evaluarlos y reflejarlos en un proceso.");
INSERT INTO keywords (name, description) VALUES ("Ética", "Rama de la filosofía relativa al estudio de los valores humanos y la moralidad.");
INSERT INTO keywords (name, description) VALUES ("Ética de la virtud", "Enfoque ético que enfatiza las características de las personas que toman decisiones éticas. Se considera importante que las personasque realizan juicios éticos posean rasgos de personalidad como coraje, sabiduría, sensibilidad, compasión y empatía. Este enfoque
puede dar lugar a la suposición errónea de que la toma de decisiones éticas trata simplemente de ser el tipo correcto de persona más
que del hecho de poseer la capacidad para analizar hábil y minuciosamente los dilemas éticos.");
INSERT INTO keywords (name, description) VALUES ("Etnicidad", "Modo de clasificar a las personas que comparten características comunes, definidas por sí mismos o por otros. La etnicidad puede ser
un aspecto importante para la identidad de los individuos y los grupos, ya que indica los orígenes culturales y sus diferencias. Puede ser
la base de la identidad nacional y política. La etnicidad es un término diferente que el rebatido término de »raza«, que clasifica a las
personas de acuerdo con las diferencias físicas, como el color de la piel, ignorando las diferencias culturales.");
INSERT INTO keywords (name, description) VALUES ("Etnocentricidad", "Actitud que presupone que las creencias, valores y estilo de vida del grupo de cada uno son superiores a los de otros.");
INSERT INTO keywords (name, description) VALUES ("Etnografía", "Término de investigación que se aplica la descripción, estudio o interpretación de una cultura.");
INSERT INTO keywords (name, description) VALUES ("Eutanasia", "Proceso indoloro de acabar con la vida de una persona que sufre una enfermedad terminal o muy dolorosa, normalmente con su
consentimiento. La eutanasia activa va en contra de la ley en Inglaterra, pero la eutanasia pasiva, como dejar de aplicar un tratamiento
fisioterápico o medicamentoso, se practica a veces.");
INSERT INTO keywords (name, description) VALUES ("Eversión", "Giro externo de la articulación subastragalina del pie. Su opuesto es inversión.");
INSERT INTO keywords (name, description) VALUES ("Evidencia", "Información en la que se basa una decisión. Ésta puede obtenerse de un abanico de fuentes que pueden incluir ensayos de investigación
(cuantitativos y cualitativos), consenso de la práctica actual y la opinión experta de profesionales clínicos o pacientes.");
INSERT INTO keywords (name, description) VALUES ("EVP", "Abreviatura médica común de estado vegetativo persistente. Véase Estado vegetativo.");
INSERT INTO keywords (name, description) VALUES ("Excéntrico", "Elongación controlada y activa de un músculo. Por ejemplo, cuando se deja una taza en una mesa, el bíceps trabaja »en excéntrico«
para bajar la taza.");
INSERT INTO keywords (name, description) VALUES ("Extensión", "Enderezamiento de una articulación; lo opuesto a flexión.");
INSERT INTO keywords (name, description) VALUES ("Exteroceptivo", "Receptores estimulados por el medio ambiente externo.");
INSERT INTO keywords (name, description) VALUES ("Extraarticular", "Término anatómico que se refiere a algo que es externo a la articulación. Por ejemplo, una característica extraarticular de la artritis
reumatoide puede ser la anemia.");
INSERT INTO keywords (name, description) VALUES ("Extrapiramidal", "Término utilizado para describir el par de masas subcorticales o núcleos de materia gris.");
INSERT INTO keywords (name, description) VALUES ("Extubación", "Retirada de un tubo de un órgano, estructura u orificio.F");
INSERT INTO keywords (name, description) VALUES ("FA", "Abreviatura médica común de fibrilación auricular.");
INSERT INTO keywords (name, description) VALUES ("Fabela", "Hueso sesamoideo que se asienta dentro de la cabeza del gastrocnemio. No siempre está presente.
Consejo para el estudiante Puede parecer un cuerpo suelto en una proyección radiográfica lateral de la rodilla.");
INSERT INTO keywords (name, description) VALUES ("Faceta articular", "Véase Articulaciones cigapoflsarias.");
INSERT INTO keywords (name, description) VALUES ("La fabela en una radiografía lateral de la rodilla", "");
INSERT INTO keywords (name, description) VALUES ("Facilitación", "Aceleración o ayuda a un proceso natural o al aumento de la excitabilidad de una neurona después de la estimulación. Las técnicas
facilitadoras pueden ser utilizadas tanto para estimular como para inhibir la actividad. Por ejemplo, un estiramiento lento y suave de un
músculo tenderá a ser inhibitorio, mientras que un estiramiento rápido y súbito será estimulante. Las técnicas que pueden considerarse
de facilitación son:
• Cepillado.
• Hielo.
• Vendaje.
• Estiramiento pasivo.
• Compresión articular (aproximación).
• Vibración.
• Estimulación vestibular.
La conducción facilitadora se da cuando el terapeuta utiliza las manos de manera adecuada para asistir el movimiento y los cambios en
la postura (Stokes, 1998).");
INSERT INTO keywords (name, description) VALUES ("Facilitación neuromuscular propioceptiva (FNP)", "Esta técnica utiliza las propiedades de la propiocepción que responden a la presión y estiramiento y fue desarrollada como un enfoque
terapéutico para la reeducación del movimiento. Implica el uso de resistencia y facilitación de movimientos en patrones en masa
reconocidos, de movimientos diagonales o espirales, junto con el uso de estiramiento, repetición y órdenes verbales.");
INSERT INTO keywords (name, description) VALUES ("Factor de impacto", "Valor atribuido por la comunidad académica a la importancia de una revista:• Alto impacto. Importante.
• Bajo impacto. Menos importante.");
INSERT INTO keywords (name, description) VALUES ("Factor de necrosis tumoral (TNF)", "Citosina producida por un macrófago que ayuda a activar las células T. La medicación anti-TNF está actualmente revolucionando el
tratamiento en reumatología.");
INSERT INTO keywords (name, description) VALUES ("Factor reumatoide", "Anticuerpo cuyos niveles pueden medirse en sangre. El factor reumatoide es actualmente un anticuerpo que puede vincularse a otros
anticuerpos.");
INSERT INTO keywords (name, description) VALUES ("Factores SIN (severidad, irritabilidad y naturaleza)", "");
INSERT INTO keywords (name, description) VALUES ("Severidad", "Un síntoma se define como severo o grave si la actividad que causa el dolor necesita interrumpirse como consecuencia de la intensidad
del dolor. En muchos casos, esto es una indicación de que se debe tener precaución en la valoración y en los procedimientos
terapéuticos.");
INSERT INTO keywords (name, description) VALUES ("Indicadores de gravedad", "• Elevado número de analgésicos.
• Sueño alterado.
• Bajas laborales como consecuencia del dolor.
• Escala analógica visual alta (EAV).");
INSERT INTO keywords (name, description) VALUES ("Irritabilidad", "Se habla de irritabilidad cuando una pequeña actividad causa mucho dolor que tarda mucho tiempo en desaparecer. En muchos casos,
es una indicación de que se deben tomar precauciones de acuerdo con la valoración y los procedimientos de tratamiento.");
INSERT INTO keywords (name, description) VALUES ("Indicadores de irritabilidad", "• Susceptibilidad al dolor.
• Grado de dolor.
• El período de tiempo que tarda el dolor en aliviarse.");
INSERT INTO keywords (name, description) VALUES ("Naturaleza", "Se refiere a los aspectos de los problemas que requieren consideración en los procedimientos de valoración y tratamiento. Puede incluir
procesos patobiológicos subyacentes a la alteración, factores contribuyentes como la osteoporosis, la fase de curación, la fase y
estabilidad de la alteración, y ciertas características personales, como el miedo al movimiento.");
INSERT INTO keywords (name, description) VALUES ("Falso positivo", "Término de investigación que se utiliza para designar una respuesta erróneamente positiva. Se produce cuando el resultado del test de
un paciente es positivo pero en realidad este último no presenta el atributo para el cual se ha llevado a cabo el test.");
INSERT INTO keywords (name, description) VALUES ("Fármacos citotóxicos", "Nombre utilizado para describir cualquier compuesto farmacológico que inhibe el crecimiento de las células dentro del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Fascia", "Capas planas de tejido fibroso que separan las diferentes capas de tejido.");
INSERT INTO keywords (name, description) VALUES ("Fascia toracolumbar", "Fascia que cubre los músculos profundos de la espalda.");
INSERT INTO keywords (name, description) VALUES ("Fasciculación", "Contracción localizada de los músculos que puede observarse a través de la piel como un destello o tic nervioso; representan una
descarga espontánea de un número de fibras inervadas por un solo filamento nervioso motor. Es común en una alteración de neuronamotora.");
INSERT INTO keywords (name, description) VALUES ("Fasciotomía", "División quirúrgica de la fascia. Se lleva a cabo a menudo para aliviar la presión resultante del síndrome compartimental.
Véase Síndrome compartimental.");
INSERT INTO keywords (name, description) VALUES ("Fascitis plantar", "También se conoce como síndrome del talón doloroso. Su síntoma principal es el dolor en la inserción de la fascia plantar en el
tubérculo medial del calcáneo. Predomina el dolor matinal y puede agravarse al correr y hacer
jogging. Puede ser debido a
anormalidades biomecánicas o ser secuela de otra patología, como una espondilitis anquilosante.");
INSERT INTO keywords (name, description) VALUES ("Fase de amortización", "Término para describir el período de tiempo comprendido entre una contracción excéntrica y una contracción concéntrica.");
INSERT INTO keywords (name, description) VALUES ("Fases", "Término electroterápico. Un impulso puede ser monofásico o bifásico. La representación gráfica de una fase indica la frecuencia de
aplicación de carga (pendiente y forma), la cantidad de carga aplicada (área de cada fase) y la duración de cada fase.");
INSERT INTO keywords (name, description) VALUES ("Fatiga", "Término que se utiliza para describir:
• La incapacidad de un músculo para llevar a cabo una contracción fuerte, debido a debilidad causada por la realización de un trabajo
repetido.
• La alteración afectiva general que da lugar a cansancio y letargia.
La fatiga general es difícil de cuantificar y valorar. Es común en muchas enfermedades crónicas, como la esclerosis múltiple, en la que
pueden necesitarse consejos para la conservación de la energía.");
INSERT INTO keywords (name, description) VALUES ("Feedback verbal", "Retroalimentación verbal o auditiva que puede ser utilizada por los fisioterapeutas para reforzar los objetivos del tratamiento en relación
con su desarrollo. Es importante promover el efecto apropiado, ya que es esencial que exista una retroalimentación precisa en el
proceso de aprendizaje. No debería haber relación entre la acción del paciente y la retroalimentación del terapeuta. Sin embargo, la
negatividad puede no ser motivadora y, por tanto, se debe tener especial cuidado en conseguir un equilibrio cuando se trata a los
pacientes.");
INSERT INTO keywords (name, description) VALUES ("FEF", "Abreviatura médica común correspondiente a flujo espiratorio forzado. Se mide de forma espirométrica. Se usa como herramienta de
diagnóstico en la obstrucción de flujo aéreo, en diferentes etapas de la espiración, por ejemplo, a través del 25–75% (escrito FEF 25–
75 ).");
INSERT INTO keywords (name, description) VALUES ("Feminismo", "Movimiento social comprometido con la denuncia e impugnación de la experiencia desventajosa de las mujeres debido a su género. Es
un conjunto de ideas basadas en la afirmación de que las mujeres están estructuralmente");
INSERT INTO keywords (name, description) VALUES ("subordinadas a los hombres dentro de la", "sociedad. Como perspectiva, el feminismo tiene diversas formas dentro de las ciencias sociales.");
INSERT INTO keywords (name, description) VALUES ("Fémur", "Hueso del muslo. Es el hueso más largo del cuerpo:
• Arqueado para ayudar a la absorción de cargas.
• Vascular (su fractura puede provocar una gran hemorragia).
• Formado por hueso esponjoso (en los extremos) y cortical en la región central.Fenilcetonuria
Patología que se manifiesta por microcefalia (cerebro pequeño) y dificultades de aprendizaje.");
INSERT INTO keywords (name, description) VALUES ("Fenómeno de »navaja plegable« (clasp knife)", "Tipo de espasticidad que se observa en el movimiento pasivo de un miembro con resistencia al movimiento (cogida), que desaparece en
los intentos siguientes a mover pasivamente la articulación.");
INSERT INTO keywords (name, description) VALUES ("Fenomenología", "Término de investigación que se aplica al estudio de las experiencias vividas por las personas, es decir, una descripción de la apariencia
de las cosas independientemente de su origen, explicación o causa.");
INSERT INTO keywords (name, description) VALUES ("Férula para la caída del pie", "Férula que se fabrica normalmente para encajarse en un zapato estándar y que puede recortarse o moldearse con calor. Se usa en
casos de caída del pie o gran inestabilidad en el tobillo.
Véase Caída del pie.");
INSERT INTO keywords (name, description) VALUES ("Férula de reposo", "Férula empleada durante la noche o cuando una persona está en reposo para preservar el alineamiento normal de la articulación o
aliviar el dolor/prevenir la deformidad.");
INSERT INTO keywords (name, description) VALUES ("FEV", "Abreviatura médica común de volumen espiratorio forzado.
Véase Espirometría.");
INSERT INTO keywords (name, description) VALUES ("Fiabilidad", "Término de investigación que se aplica a la repetibilidad de un estudio (capacidad de un estudio de ser repetido obteniendo el mismo
resultado). Un ejemplo clínico sería que la medida de la flexión de la rodilla con un goniómetro muy pequeño no es fiable, ya que existen
muchas fuentes potenciales de error en el posicionamiento de los brazos del goniómetro y también en las diferencias entre un test y el
siguiente (fiabilidad intraexaminador) y la diferencia entre los fisioterapeutas que aplican el mismo test (fiabilidad interexaminador).
Fibra de MossyUno de los dos tipos de fibras (la otra es una fibra ascendente) que llevan información a la corteza cerebelosa.");
INSERT INTO keywords (name, description) VALUES ("Fibra intrafusal", "Haz de fibras localizadas dentro del huso muscular; se dividen en paquete nuclear y fibras de cadena nuclear.");
INSERT INTO keywords (name, description) VALUES ("Fibra muscular de contracción rápida", "Tipo de fibra musculoesquelética que se contrae y fatiga rápidamente. Presenta un elevado nivel de glucógeno y depende del
metabolismo anaeróbico para el aporte de energía. Compárese con las fibras musculares de contracción lenta.
Véase Tipos de fibras musculares .");
INSERT INTO keywords (name, description) VALUES ("Fibras A", "Véase Tipos de fibras nerviosas.");
INSERT INTO keywords (name, description) VALUES ("Fibras ascendentes", "Axón de una neurona oliva inferior que inerva a una célula de Purkinje en el cerebelo.");
INSERT INTO keywords (name, description) VALUES ("Fibras C", "Véase Tipos de fibras nerviosas.
Fibras nerviosas de naturaleza posganglionar y autónoma, con capacidad para transmitir sensaciones de temperatura y dolor.");
INSERT INTO keywords (name, description) VALUES ("Fibras de Purkinje", "Extensa red de fibras ramificadas, que desempeñan un importante papel en la conducción de los impulsos eléctricos a través del
corazón.");
INSERT INTO keywords (name, description) VALUES ("Fibras extrafusales", "Fibras musculoesqueléticas inervadas por motoneuronas fuera del huso muscular.");
INSERT INTO keywords (name, description) VALUES ("Fibras musculares de contracción lenta", "Una de las tres subclases de fibras musculares esqueléticas, caracterizadas por mitocondrias abundantes, resistencia a la fatiga y miosina
con baja sensibilidad al ATP.");
INSERT INTO keywords (name, description) VALUES ("Fibras no mielinizadas", "Término que hace referencia a las fibras nerviosas que no están cubiertas de mielina. Las fibras de tipo C son de diámetro muy pequeño
y conducen la información sensorial de dolor y temperatura.");
INSERT INTO keywords (name, description) VALUES ("Fibrilación", "Este término tiene dos significados en medicina:
1. Contracciones incoordinadas irregulares del músculo cardíaco.
2. Término utilizado para describir los pequeños crujidos que se aprecian en las etapas iniciales de la osteoartritis.");
INSERT INTO keywords (name, description) VALUES ("Fibrilación auricular", "Ritmo cardíaco anormal e irregular por el que se generan señales eléctricas de forma caótica a través de las cavidades superiores
(aurículas) del corazón. Muchas personas con fibrilación auricular no tienen síntomas; los síntomas más comunes son las palpitaciones y
la incómoda sensación de latidos rápidos e irregulares. La fibrilación auricular puede ser transitoria o persistente y puede contribuir al
bombeo sanguíneo inefectivo del corazón.");
INSERT INTO keywords (name, description) VALUES ("Fibroblasto", "Célula que reside dentro del tejido conectivo que secreta procolágeno, fibronectina y colagenasa.");
INSERT INTO keywords (name, description) VALUES ("Fibromialgia", "Alteración caracterizada por dolor muscular, rigidez y fatiga. La etiología y patogenia de la fibromialgia son aún desconocidas. Los
patrones miopatológicos en fibromialgia no son específicos: fibroatrofia tipo II, un ligero aumento de depósitos de lípidos y proliferaciónde mitocondrias (Pongratz y Spath, 2001).");
INSERT INTO keywords (name, description) VALUES ("Fibrosis pulmonar", "Fibrosis e inflamación crónica de las paredes alveolares que cursa con dificultad respiratoria progresiva, y que da finalmente lugar a la
muerte por falta de oxígeno o fallo cardíaco derecho.");
INSERT INTO keywords (name, description) VALUES ("Fibrosis quística (FQ)", "Enfermedad hereditaria que afecta principalmente a los tractos respiratorio y gastrointestinal. La FQ se caracteriza por la obstrucción
del flujo aéreo y estasis de la mucosa respiratoria, malabsorción debida a insuficiencia pancreática exocrina y elevados niveles de
electrólitos. Los problemas respiratorios son frecuentes e incluyen tos productiva recurrente con secreciones espesas y persistentes,
infecciones bronquiales bacterianas resistentes repetidas (p. ej., por estafilococos y Pseudomonas), obstrucción de las vías aéreas,
hemoptisis, neumotórax e insuficiencia respiratoria. Las estrategias de tratamiento incluyen fisioterapia torácica, drenaje postural,
broncodilatadores, mucolíticos, antibióticos y trasplante para enfermedades terminales. La esperanza de vida es de alrededor de 30
años.");
INSERT INTO keywords (name, description) VALUES ("Fibrositis", "Proceso de enfermedad benigno, periódico y prolongado, con ausencia de patología subyacente. La alteración se asocia a menudo con
dolor muscular y rigidez.");
INSERT INTO keywords (name, description) VALUES ("Fijación de objetivos", "Véase SMART.");
INSERT INTO keywords (name, description) VALUES ("Fijación externa", "Método de fijación de una fractura por el que los clavos y alambres son conducidos dentro de los fragmentos y se sostienen mediante
parte del aparato fuera del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Ventajas de la fijación externa", "");
INSERT INTO keywords (name, description) VALUES ("Desventajas de la fijación externa", "");
INSERT INTO keywords (name, description) VALUES ("Riesgo de infección en los lugares de implantación del fijador", "M ínima interrupción en el lado de la fractura Necesita cuidado meticuloso de la herida
Permite la inspección de la herida y la fractura Estéticamente desagradable
Puede ser ajustada con traumatismo mínimo Puede ser utilizada para procedimientos de elongación del miembro Alteración funcional; por ejemplo, las articulaciones adyacentes pueden estar");
INSERT INTO keywords (name, description) VALUES ("restringidas o los tejidos blandos perforados por el fijador", "Puede ser usada para unir múltiples fragmentos (p. ej., fracturas conminutas) Riesgo de la anestesia y sus complicaciones asociadas
Permite la conservación de los tejidos en fracturas abiertas o compuestas,
lesiones con arrancamiento de la piel y quemaduras El paciente necesitará estar varios días en el hospital
Esfuerzos tomados por el estímulo disminuido para la formación del callo");
INSERT INTO keywords (name, description) VALUES ("Pesada", "");
INSERT INTO keywords (name, description) VALUES ("Fisioterapia", "Profesión sanitaria relacionada con el movimiento y la función y la maximización del potencial humano. Emplea enfoques físicos para
promover, mantener y restaurar el bienestar físico, psicológico y social teniendo en cuenta las variaciones en el estado sanitario. Está
basada en la ciencia, y está destinada a la extensión, aplicación, evaluación y revisión de la evidencia de la práctica en la que se basa.
Su núcleo central es el ejercicio del juicio clínico y la interpretación informada (Chartered Society of Physiotherapy, 2000).");
INSERT INTO keywords (name, description) VALUES ("Fístula", "Conexión anormal entre los tejidos.");
INSERT INTO keywords (name, description) VALUES ("Fístula broncopleural", "Comunicación entre el pulmón y la pleura, por complicación de una intervención torácica, normalmente después de una neumonectomía
(derrame del contenido espacial que tiene lugar en el pulmón contrario a través del muñón del pulmón extirpado quirúrgicamente). La
fístula broncopleural tiende a aparecer cuando se llevan a cabo resecciones debido a infecciones tuberculosas o fúngicas, y la gravedad
de los síntomas del paciente varía con el tamaño de la fístula.
FlacidezTérmino utilizado para describir un tono muscular por debajo de lo normal, es decir, que el músculo presenta una mayor flexibilidad y
ausencia de movimiento. De ahí que haya una falta de resistencia al movimiento pasivo.");
INSERT INTO keywords (name, description) VALUES ("FLD/FLI", "Abreviatura médica común de flexión del lado derecho/izquierdo.");
INSERT INTO keywords (name, description) VALUES ("Flexión de rodilla en prono (FRP)", "Véase Neurodinámica.");
INSERT INTO keywords (name, description) VALUES ("Flexión pasiva del cuello", "Véase Neurodinámica.");
INSERT INTO keywords (name, description) VALUES ("Floxacilina/flucloxicilina", "Antibiótico común.");
INSERT INTO keywords (name, description) VALUES ("FNP", "Abreviatura médica común de facilitación neuromuscular propioceptiva.");
INSERT INTO keywords (name, description) VALUES ("Fonoforesis", "Término usado para describir el proceso de administración de un fármaco por medio de ondas de ultrasonido. Existe todavía debate,
pero hay alguna evidencia de que esta técnica puede llegar a aumentar la concentración de ciertos fármacos antiinflamatorios.");
INSERT INTO keywords (name, description) VALUES ("Fontanela anterior", "Porción de membrana con forma de diamante en la unión de las suturas del cráneo en el recién nacido.");
INSERT INTO keywords (name, description) VALUES ("Foramen", "Término anatómico que significa abertura o pasaje, especialmente a través de un hueso.");
INSERT INTO keywords (name, description) VALUES ("Foramen magnum", "Agujero grande en la base del cráneo donde la médula espinal se encuentra con el cerebro.");
INSERT INTO keywords (name, description) VALUES ("Formación continuada", "Se define como un aprendizaje que continúa a lo largo de toda la vida del individuo. Su propósito es asegurar que la mano de obra está
equipada para hacer el trabajo que contribuirá a servicios públicos de alta calidad y promover la prosperidad en el país. La formación
continuada puede variar desde actividades educacionales altamente estructuradas hasta los modos de aprendizaje más informales. La
formación continuada abarca muchos niveles diferentes, propósitos, contenidos, resultados y motivos para el aprendizaje. La formación
continuada puede tener una variedad de estilos de aprendizaje y enfoques.
Con la amable autorización de Dariel Terry, Assistant Profesor of Information System Technology, Northern Virginia Community
College, Estados Unidos.");
INSERT INTO keywords (name, description) VALUES ("Formación reticular", "Se extiende a través del pedúnculo cerebral; se asocia con niveles de excitación, respuesta efectiva y motivada a estímulos, y respuestas
reflejas autonómicas incluyendo la respiración y la locomoción.");
INSERT INTO keywords (name, description) VALUES ("Fosa", "Término anatómico que hace referencia a un canal, es decir, un área hueca o deprimida.");
INSERT INTO keywords (name, description) VALUES ("Fractura", "Interrupción en la continuidad del hueso.
Véase Fractura abiertayFractura cerrada.
Fracturas. Complicaciones
• Embolia pulmonar.• Trombosis venosa profunda.
Shock, causado por hipovolemia o pérdida de sangre. En las fracturas de la diáfisis femoral se pueden llegar a perder hasta 1,7 l de
sangre, y en las fracturas pélvicas hasta 3,4 l. Los signos clínicos de shock hipovolémico son taquicardia (frecuencia cardíaca elevada),
perfusión periférica reducida, hipoxia (saturación de oxígeno disminuida), confusión y estado de semiconciencia.
• Infección/tétanos, especialmente después de fracturas abiertas o compuestas. La osteomielitis (infección del hueso) puede responder
mal al tratamiento.
• Embolia grasa (SDRA o síndrome de distrés respiratorio agudo). Si una persona sufre múltiples fracturas de huesos grandes o
lesiones de aplastamiento, o si grandes cantidades de médula quedan al descubierto, puede que haya una fuga de glóbulos grasos
microscópicos en el sistema circulatorio. Éstos pueden quedarse atrapados en los pulmones. Los síntomas incluyen dolor respiratorio,
dificultad en la respiración, insomnio, descenso en la saturación de los niveles de oxígeno y petequias (hemorragias minúsculas que
aparecen en el pecho). El SDRA puede ser fatal.
• Llagas de la escayola. Debe informarse al paciente de que, tras la retirada de la escayola, aparecerán grandes cantidades de piel
escamosa. Se debe informar también de que pueden aparecer áreas enrojecidas o llagas causadas por la escayola.
• Lesión muscular y atrofia. Las fibras musculares pueden estar distendidas, aplastadas o rotas como resultado de la lesión, y esto
causará tumefacción y hemorragia adicionales. Los tendones pueden estar afectados, particularmente en el caso de fracturas abiertas, o
a veces puede haber una rotura después de una fractura. La intervención quirúrgica es normalmente necesaria para reparar la rotura.
• Síndrome compartimental. Si se dañan los músculos o se inflaman en el momento de la lesión y la presión intramuscular crece sin
posibilidad de disminuir, puede darse la muerte (necrosis) de los tejidos por isquemia (falta de aporte sanguíneo). Se define como una
alteración en que la elevada presión dentro de la cubierta fascial cerrada reduce la perfusión sanguínea capilar por debajo del nivel
necesario para la viabilidad del tejido. Si se fríe una salchicha sin pincharla antes, la presión en su interior se eleva hasta que ocurren los
problemas. Esta analogía es útil para explicar a los pacientes el síndrome compartimental. El síndrome compartimental se observa más
comúnmente en los músculos tibial anterior y del antebrazo. El tratamiento gira en torno a un diagnóstico preciso, valoración del color,
sensación y movimiento después de una lesión o intervención; se debe elevar y enfriar el miembro. La descompresión quirúrgica
(fasciotomía) puede ser necesaria como procedimiento de emergencia. Los signos clínicos de un miembro con signo compartimental sonlos siguientes:
— Palidez.
— Dolor.
— Ausencia de pulso.
— Parestesia.
— Parálisis.
• Necrosis avascular. El hueso recibe su aporte sanguíneo a través de dos vías: gracias a las estructuras del tejido blando a las que se
encuentra unido o por vasos intraóseos. En ciertos casos, el aporte sanguíneo de una parte del hueso es muy dependiente de los vasos
intraóseos (dentro del hueso) y si éste se interrumpe debido a una fractura, puede tener lugar una necrosis avascular (una parte del
hueso fracturado puede morir). Puede producirse en fracturas del cuello del fémur que den lugar a una necrosis avascular de la cabeza
de éste, y en fracturas del hueso escafoides en las que esté afectado el polo proximal. Ésa puede ser una de las causas de que la
fractura no consolide y, dado que el fragmento normalmente incluye una superficie articular, de que desemboque en una osteoartritis.
• Retraso en la consolidación. Puede ocurrir si el espacio entre los extremos del hueso es muy grande, si el aporte sanguíneo es
insuficiente (tercio inferior de la tibia), si el área se infecta o si se emplea una fijación interna (esto a veces elimina el estímulo para la
formación del callo).
• Sin consolidación. En este caso hay cambios patológicos diferentes y evidencia radiológica de que no hay consolidación.
Aparentemente no hay formación de callo y los extremos de hueso fracturados se vuelven densos y el contorno claro. El espacio entre
los fragmentos claros puede rellenarse con tejido fibroso y producirse una seudoartrosis. El tercio inferior de la tibia destaca por su
escasa capacidad de curación incluso en niños jóvenes y sanos.
• Consolidación alterada. Una fractura puede curarse en una posición que no sea perfecta. El solapamiento de los fragmentos pueden
dar lugar a acortamiento, lo cual afectará a la función. La angulación o rotación de los fragmentos puede alterar la función debido a la
alteración de la biomecánica resultante.
• Alteración del crecimiento. Se produce cuando la fractura incluye la epífisis (placa de crecimiento).
• Atrofia de Sudeck. Distrofia simpática refleja (DSR), algodistrofia o causalgia. El término síndrome de dolor regional complejo se
emplea actualmente para describir estos estados patológicos. Se trata de una complicación en que el paciente se queja de dolor intenso
durante el movimiento y en reposo, desproporcionado a la lesión inicial y con tumefacción de la extremidad. La piel aparece brillante,
descolorida y fría; en casos extremos esto puede dar lugar a que el miembro esté excesivamente sensible y descolorido. Puede seguirse
de osteoporosis y contracturas permanentes. El tratamiento es difícil. Los agentes vasodilatadores, como la guanetedina, tienen éxito
ocasionalmente. También puede responder a bloqueos nerviosos, analgesia local, TENS y otras terapias locales, pero la recuperación
es lenta y puede durar varios meses. Afortunadamente esta complicación es comparativamente rara.
• Fracturas intraarticulares. Implican una predisposición del cartílago articular a sufrir osteoartritis en un futuro (p. ej., fracturas de la
meseta tibial). Esto es debido al área de desigualdad que inevitablemente se forma después de una fractura, y también a la
inmovilización de la fractura que da lugar a la necrosis del cartílago (v. más adelante). Por esta última razón, puede observarse que
algunas fracturas son tratadas agresivamente por fisioterapeutas desde una etapa temprana.
Otro problema con las fracturas intraarticulares es que, si el callo está intentando formarse dentro de la cavidad articular, estará
constantemente siendo »limpiado« por el líquido sinovial (p. ej., después de una fractura del cuello del fémur).
• Lesiones viscerales. Por ejemplo, una fractura de pelvis también puede dañar la vejiga o la uretra. Una fractura costal puede causar
neumotórax. Una fractura del cráneo puede dar lugar a una lesión cerebral.
• Adherencias. Pueden darse dentro de la articulación (intraarticulares) o fuera de la articulación (periarticulares).
• Lesión de grandes vasos. Una arteria grande se incluye en una posición tal que se corta la irrigación del miembro y ello da lugar a una
gangrena o, si hay oclusión parcial, se podrá desarrollar una contractura isquémica. Estas lesiones deben ser tratadas urgentemente
mediante cirugía. La trombosis de las venas puede producirse en la proximidad de la fractura. Esto se presenta como un desarrollo
súbito de un dolor similar al de un calambre, con un aumento de la tumefacción y con una sensibilidad notable a lo largo del trayecto de
la vena. Cualquier cosa que parezca anormal en el sistema circulatorio debe comunicarse al cirujano inmediatamente. Los vasos
sanguíneos pueden sufrir daños; por ejemplo, después de fracturas humerales la arteria braquial puede verse dañada.
• Lesión nerviosa. Ciertas fracturas, como por ejemplo la de la diáfisis media del húmero, pueden dar lugar a una parálisis del nervio
radial. Si una escayola está muy apretada, puede causar lesión nerviosa; el nervio peroneo común es vulnerable; si la escayola es muyestrecha a la altura de la cabeza del peroné, dará lugar a una caída del pie, ya que puede afectar al músculo tibial anterior y éste es
incapaz de realizar su función de deceleración del pie en el apoyo del talón, y permitir el despegue del pie durante la fase de oscilación
de la marcha.");
INSERT INTO keywords (name, description) VALUES ("Fractura abierta (o compuesta)", "Es aquella que presenta comunicación con el entorno externo. Este tipo de fracturas se producen cuando el extremo del hueso o algún
otro objeto penetra en la piel. Estas fracturas son más preocupantes que las cerradas por la posibilidad de introducción de
microorganismos que infecten el hueso, es decir, que den lugar a una osteomielitis.
Véase Fractura cerrada y Fractura (clasificación).");
INSERT INTO keywords (name, description) VALUES ("Fractura cerrada", "No hay comunicación entre la fractura y el medio ambiente externo.
Véase Fractura abierta y Fractura (clasificación).");
INSERT INTO keywords (name, description) VALUES ("Fractura compuesta; (también conocida como fractura abierta)", "Fractura en la que la piel está rota. No hay solución de continuidad en la piel.");
INSERT INTO keywords (name, description) VALUES ("Fractura conminuta", "Fractura en la que hay muchos fragmentos pequeños de hueso.");
INSERT INTO keywords (name, description) VALUES ("Fractura de Bennetts", "Fractura con luxación que afecta a la articulación trapeciometacarpiana del pulgar.");
INSERT INTO keywords (name, description) VALUES ("Fractura de Colles", "Fractura común de la porción distal del radio producida por una caída con la mano extendida, normalmente manifestada como una
deformidad en forma de tenedor.Fractura de Galeazzi
Fractura del radio y subluxación del extremo distal del cúbito.");
INSERT INTO keywords (name, description) VALUES ("Fractura de Hangman", "Tipo de fractura de la columna cervical. Fractura bilateral de los pedículos del axis (C2).");
INSERT INTO keywords (name, description) VALUES ("Fractura de March", "Fractura por fatiga o estrés que afecta a los metatarsianos.");
INSERT INTO keywords (name, description) VALUES ("Fractura de Monteggia", "Fractura angulada en la unión entre el tercio medio y proximal del cúbito acompañada de una luxación anterior de la cabeza radial.");
INSERT INTO keywords (name, description) VALUES ("Fractura de Pott", "Fractura de la parte final del peroné y del maléolo medial con desplazamiento externo del pie.");
INSERT INTO keywords (name, description) VALUES ("Fractura de Smith", "Es similar a la fractura de Colles pero con desplazamiento palmar en vez de dorsal del fragmento distal.");
INSERT INTO keywords (name, description) VALUES ("Fractura del escafoides", "Es común después de una caída con la muñeca en hiperextensión. Una fractura del escafoides del carpo es a veces difícil de detectar en
una primera radiografía, por lo cual es necesario repetirla dos semanas después para confirmar. Normalmente, si la fractura afecta al
tercio proximal del escafoides, existe un riesgo elevado de que no consolide bien y tenga lugar una necrosis avascular, debido a un
aporte sanguíneo insuficiente.");
INSERT INTO keywords (name, description) VALUES ("Fractura deprimida del cráneo", "Es aquella que se produce cuando el cráneo se fractura y se forma un hundimiento, que puede ser abierto (compuesto) o cerrado
(simple). Aunque el paciente se encuentre bien, puede requerir intervención neuroquirúrgica para corregirla, y puede existir traumatismo
interno. Normalmente se produce cuando alguien es golpeado con un objeto en la cabeza.");
INSERT INTO keywords (name, description) VALUES ("Fractura en estallido", "Fractura del suelo de la órbita o de la fosa ocular.");
INSERT INTO keywords (name, description) VALUES ("Fractura en tallo verde", "Fractura sufrida por niños en la que el hueso no se rompe a través de su diámetro, sino que se suele comportar como una rama verde
que se parte sólo parcialmente.
Véase Fractura (clasificación).");
INSERT INTO keywords (name, description) VALUES ("Fractura impactada", "Fractura en la que un fragmento se ha introducido dentro de otro.");
INSERT INTO keywords (name, description) VALUES ("Fractura patológica", "Fractura que ocurre porque la arquitectura normal del hueso se ha visto comprometida por una enfermedad; ejemplos comunes son los
tumores óseos y la osteoporosis primaria o secundaria.Fractura en tallo verde");
INSERT INTO keywords (name, description) VALUES ("Fractura por arrancamiento", "Se produce cuando la inserción de un ligamento, músculo o tendón, tracciona de un fragmento de hueso o cuando éste es dañado.
Observación clínica Los ejemplos observados en la práctica clínica incluyen el arrancamiento de la punta del maléolo medial después
de una lesión en eversión, debido a la fuerza del ligamento deltoideo del tobillo.");
INSERT INTO keywords (name, description) VALUES ("Fractura por estrés", "Fractura causada por sobrecarga acumulada sobre el hueso. Puede deberse a numerosos factores, incluyendo sobreesfuerzo,
biomecánica incorrecta, fatiga, desequilibrio hormonal, nutrición deficiente u osteoporosis.");
INSERT INTO keywords (name, description) VALUES ("Fractura trimaleolar", "Fractura que implica ambos maléolos y la parte posterior de la superficie articular tibial.");
INSERT INTO keywords (name, description) VALUES ("FRC", "Abreviatura médica común de capacidad residual funcional.
Véase Espirometría.");
INSERT INTO keywords (name, description) VALUES ("Frecuencia", "Término electroterápico. Es el número de impulsos por segundo registrado en herzios (Hz). Es un parámetro relevante para un cierto
número de agentes electrofísicos. Por ejemplo, la frecuencia del ultrasonido que se usa terapéuticamente está entre 0,8 y 3 MHz, y 1,5
MHz para la consolidación de las fracturas. Para una respuesta rápida a la estimulación eléctrica (p. ej., para la valoración de la
duración de la fuerza), una frecuencia de 1 Hz es ideal. Para una contracción tetánica (una respuesta fusionada de las unidades motoras
individuales) se requiere una frecuencia de 30-50 Hz, dependiendo del músculo. El par de torsión aumenta a medida que se incrementa
la frecuencia de la corriente pulsante, alcanza su pico poco después de los 50 Hz y después ya no se incrementa mucho más, llegando
alrededor de los 70 Hz. Una frecuencia portadora es una frecuencia que alterna impulsos de corriente.
Véase Corriente rusa.");
INSERT INTO keywords (name, description) VALUES ("Frecuencia cardíaca", "Número de latidos cardíacos por minuto. La frecuencia cardíaca normal del adulto en reposo es de 60-100 pulsaciones/min (ppm); el
paciente se monitoriza para determinar la frecuencia, fuerza y ritmo cardíacos.
Frecuencia modulada en amplitud (FMA), también conocida como frecuencia de latido
Tiene lugar cuando se usa la terapia interferencial, en la que dos corrientes de media frecuencia interfieren o se anulan entre sí de un
modo predecible para producir la frecuencia deseada.");
INSERT INTO keywords (name, description) VALUES ("Frecuencia urinaria", "Orinar muy a menudo, a intervalos muy frecuentes.");
INSERT INTO keywords (name, description) VALUES ("Fricción transversa profunda (FTP)", "Técnica creada por James Cyriax, que consiste en la aplicación de un masaje de pequeña amplitud en los tejidos blandos, sobre los que
se ha sugerido que produce un efecto local de anestesia. La estimulación selectiva de los mecanorreceptores por un movimiento rítmico
sobre el área afectada puede cerrar el umbral de dolor. Otro mecanismo con el que se puede reducir el dolor es la liberación de
opiáceos endógenos. El masaje de fricción puede tener un efecto beneficioso en las tres fases de la reparación.
La fricción transversa suave aplicada en la fase inflamatoria temprana puede aumentar la movilización del fluido tisular y, por lo tanto,incrementar la velocidad de la fagocitosis.
Durante la maduración, el tejido cicatricial se reestructura y refuerza por la eliminación, reorganización y sustitución de células y matriz.
El estrés mecánico, interno y externo, aplicado al tejido reparado es el principal estímulo para la remodelación del tejido tisular
inmaduro y pobre, con fibras orientadas en todas las direcciones y a través de diversos planos, y dando lugar a haces lineales de tejido
conectivo reorganizado. Dado que la fricción transversa pretende básicamente lograr el movimiento transverso del colágeno, se debería
prevenir la formación de la estructura de adhesión del tejido conectivo. La fricción induce una hiperemia traumática o aumento del flujo
sanguíneo al área, que puede facilitar la eliminación de irritantes químicos e incrementa el transporte de opiáceos endógenos.");
INSERT INTO keywords (name, description) VALUES ("Fricciones transversas", "Véase Fricción transversa profunda (FTP).");
INSERT INTO keywords (name, description) VALUES ("Frotis cervical", "Toma de una muestra de secreciones y células superficiales del cérvix, extraídas con un aplicador estéril desde la pared uterina externa.
La muestra es extendida en un portaobjetos y enviada para su examen.");
INSERT INTO keywords (name, description) VALUES ("Fuerza de reacción terrestre", "Fuerza que actúa sobre un cuerpo como resultado de que éste descanse sobre la tierra o la golpee.");
INSERT INTO keywords (name, description) VALUES ("Fugel-Meyer", "Una valoración de la rehabilitación sensoriomotora después de un ACV. Se usa frecuentemente como medida de la recuperación
motora, equilibrio, sensación, movilidad articular y dolor. No valora el movimiento fino o complejo.");
INSERT INTO keywords (name, description) VALUES ("Función pulmonar", "Medida para evaluar el funcionamiento pulmonar. La valoración incluye espirometría, gases sanguíneos arteriales y medidas de
transferencia gaseosa y volúmenes pulmonares.");
INSERT INTO keywords (name, description) VALUES ("Functio laesa", "Pérdida de la función; es el quinto signo de la inflamación añadido por Galeno a los propuestos por Celso (es decir: rubor, tumor, calor
y dolor).G");
INSERT INTO keywords (name, description) VALUES ("Ganglión", "1. Grupo de cuerpos de células nerviosas localizadas fuera del sistema nervioso.
2. Tumor benigno que se presenta en la sinovial de la articulación o en la vaina del tendón. Se encuentra comúnmente alrededor de la
muñeca.");
INSERT INTO keywords (name, description) VALUES ("Ganglios basales", "Colección de cinco núcleos nerviosos en la base de la corteza cerebral. Son el núcleo caudado, el putamen, el globo pálido, la sustancia
negra y el núcleo subtalámico. La degeneración o lesión en esta área puede ocasionar enfermedad de Parkinson, enfermedad de
Huntington y hemibalismo.Localización del núcleo que forma el ganglio basal");
INSERT INTO keywords (name, description) VALUES ("Gases sanguíneos arteriales", "Los gases sanguíneos arteriales (interpretados tras analizar la sangre arterial obtenida de una arteria o un capilar) miden el estado ácido-
básico (el pH, es decir, los niveles de acidosis y alcalosis) de un individuo. Los resultados obtenidos determinarán la causa primaria
(respiratoria o metabólica) de un desequilibrio y detectarán la presencia o ausencia de mecanismos compensatorios. Miden el pH
(niveles de ion hidrógeno en plasma), presiones parciales de oxígeno (PaO 2 ) y dióxido de carbono (PaCO 2 ) y niveles de bicarbonato, y
son diagnósticos de una insuficiencia respiratoria.");
INSERT INTO keywords (name, description) VALUES ("Las cuatro alteraciones primarias del equilibrio ácido-basico", "");
INSERT INTO keywords (name, description) VALUES ("Desequilibrios primarios Alteración primaria Respuestas secundarias Mecanismo de respuesta secundaria", "Acidosis respiratoria Incremento en la PaCO 2 Incremento de [HCO 3 ] en plasma Titulación ácida de los tamponadores tisulares
Un incremento transitorio en la secreción de ácido ocurre unido con un aumento sostenido de la reabsorción de HCO 3 por el riñón");
INSERT INTO keywords (name, description) VALUES ("Alcalosis respiratoria", "");
INSERT INTO keywords (name, description) VALUES ("Descenso en la PaCO 2", "");
INSERT INTO keywords (name, description) VALUES ("Descenso de [HCO 3 ] en plasma", "");
INSERT INTO keywords (name, description) VALUES ("Titulación básica de los tamponadores tisulares", "Una supresión transitoria en la secreción de ácido ocurre junto con una reducción sostenida de la reabsorción de HCO 3 por el riñón
Acidosis metabólica Descenso de [HCO 3 ] en plasma Descenso de PaCO 2 Hiperventilación alveolar
Alcalosis metabólica Incremento de [HCO 3 ] en plasma Incremento de PaCO 2 Hipoventilación alveolar
Los valores arteriales obtenidos deberán encontrarse dentro de los rangos normales de:
Se debe recordar que el CO 2 es un gas ácido, y el bicarbonato es una base y, por lo tanto, alcalina. Así que, tanto un CO 2 elevado
como un nivel de bicarbonato reducido causarán una acidosis (o una caída del pH por debajo de 7,35). Niveles de CO 2 bajos o de
bicarbonato elevados causarán una alcalosis (o aumento del pH por encima de 7,45). Aunque la PaO 2 es una medida importante (y
necesaria para el diagnóstico de la insuficiencia respiratoria y para averiguar el estado de oxigenación del paciente) no ayuda a
interpretar el estado ácido-base del paciente. Las principales consideraciones para este propósito son el pH, la PaCO 2 y SBC. Para
interpretar los datos, pueden usarse los siguientes pasos:
1. Determinar el pH (bajo = acidosis; alto = alcalosis).
2. Determinar el estado respiratorio (¿está el CO 2 dentro de sus parámetros normales y justifica el pH?).
3. Determinar la implicación metabólica (¿está el bicarbonato dentro de sus parámetros normales y justifica el pH?).
4. Considerar los mecanismos compensatorios, por ejemplo:
a. pH 7,25; PaCO 2 9,6; SBC 24 indicaría una acidosis respiratoria (pH bajo; CO 2 elevado y bicarbonato normal).
a. pH 7,46; PaCO 2 5,4; SBC 35 indicaría una alcalosis metabólica (el pH está elevado y el bicarbonato también).");
INSERT INTO keywords (name, description) VALUES ("Mecanismos compensatorios determinantes", "Cuando un desequilibrio ácido-base tiene lugar, los pulmones pueden compensar rápidamente las alteraciones metabólicas, pero a los
riñones les lleva más tiempo alterar los niveles de bicarbonato en respuesta a las alteraciones respiratorias. Cuando el pH se mantiene
dentro de sus límites normales se está produciendo una »plena compensación«.");
INSERT INTO keywords (name, description) VALUES ("¿Es la compensación total o parcial?", "Donde ha tenido lugar la compensación (a través de mecanismos homeostáticos), es extraño que el pH regrese por debajo del punto
central 7,4. Por lo tanto, una acidosis respiratoria completamente compensada será reflejada por un pH entre 7,35 y 7,4; un CO");
INSERT INTO keywords (name, description) VALUES ("2", "elevado (como causa primaria de la acidosis original) y un aumento de los niveles de bicarbonato (compensación renal para devolver el
pH a sus niveles normales). Alternativamente, una acidosis metabólica totalmente compensada, se reflejará en un nivel bajo de pH, CO 2
bajo (hiperventilación compensatoria) y un bajo nivel de bicarbonato (la causa de un pH reducido). Por ejemplo: pH 7,36; PaCO 2 9,6;
SBC 32 indicaría una compensación total (el pH está dentro de su rango normal, por lo que es totalmente compensado, el nivel debicarbonato está elevado), acidosis respiratoria (un CO 2 elevado causaría la acidosis). Podría no existir una causa metabólica para
hacer al paciente acidótico; el nivel de bicarbonato deberá ser disminuido. Si el pH no se mantiene dentro de sus límites normales pero
los otros parámetros están perturbados, entonces sólo se ha producido una compensación parcial del problema. Por ejemplo: pH 7,3;
PaCO 2 9,6; SBC 30 representa una acidosis respiratoria parcialmente compensada (ya que el pH es aún ácido, a pesar de un nivel de
bicarbonato elevado). La principal causa de la acidosis es el elevado nivel de CO 2 .");
INSERT INTO keywords (name, description) VALUES ("Comprueba tu comprensión", "1. pH 7,4; PaCO 2 5,8; SBC 26 (normal).
2. pH 7,18; PaCO 2 10,8; SBC 35 (acidosis respiratoria parcialmente compensada).
3. pH 7,49; PaCO 2 5,1; SBC 33 (alcalosis metabólica).
4. pH 7,3; PaCO 2 7,1; SBC 30 (acidosis respiratoria parcialmente compensada).
5. pH 7,36; PaCO 2 6,6; SBC 30 (acidosis respiratoria totalmente compensada).
6. pH 7,21; PaCO 2 3,4; SBC 16 (acidosis metabólica parcialmente compensada).");
INSERT INTO keywords (name, description) VALUES ("Gasto cardíaco", "Se define como el volumen de sangre bombeado multiplicado por la frecuencia cardíaca. Se mide en l/min.
Los factores que determinan el gasto cardíaco son: frecuencia cardíaca, precarga, contractilidad miocárdica y poscarga.");
INSERT INTO keywords (name, description) VALUES ("Gastrectomía", "Escisión quirúrgica del estómago.");
INSERT INTO keywords (name, description) VALUES ("Gástrico", "Relativo al estómago.");
INSERT INTO keywords (name, description) VALUES ("Gastroenteritis", "Inflamación del estómago y/o de los intestinos.");
INSERT INTO keywords (name, description) VALUES ("Gastrointestinal (GI)", "Relativo al estómago y los intestinos.");
INSERT INTO keywords (name, description) VALUES ("Gel", "Término electroterápico utilizado para designar una sustancia soluble en agua utilizada para completar un circuito o para unir una salida
a la piel.
Gel de estimulación eléctrica: si está hecho de goma de carbono reutilizable y flexible, se usa entre los electrodos y la piel para
completar el circuito.
Gel de ultrasonido: permite pasar al ultrasonido desde el aplicador hasta la piel; sin ello esto no sería posible debido a la elevada
impedancia acústica del aire al paso de la frecuencia de MHz del ultrasonido. El gel de ultrasonido, a pesar de que suele ser más barato
y tener una resistencia más elevada que el gel eléctrico (normalmente denominado gel de ECG o gel de estimulación eléctrica), no
debería utilizarse como una sustitución de este último.");
INSERT INTO keywords (name, description) VALUES ("Generador del patrón motor", "Patrones de movimiento almacenados que se encuentran en la corteza cerebral y el tallo encefálico.");
INSERT INTO keywords (name, description) VALUES ("Generadores de patrones centrales", "Red de neuronas que pueden generar un circuito de ritmo repetitivo; por ejemplo, dar pasos y respirar sin
encuentran en la médula espinal.
feedback sensorial. Se");
INSERT INTO keywords (name, description) VALUES ("Generalización", "Extensión en la que los resultados de un estudio basado en la medición de un paciente en particular, población y/o contexto específico
siguen teniéndose por ciertos para otra población y/o en un contexto diferente.Género
Identidad social. Las diferencias percibidas entre los dos sexos generan diferenciación social, desigualdad, discriminación y prejuicio. El
término »género« es diferente del de »sexo«, que denota diferencias biológicas entre hombres y mujeres.");
INSERT INTO keywords (name, description) VALUES ("Genoma", "Mapa de ADN que comprende la composición genética completa del ser humano.");
INSERT INTO keywords (name, description) VALUES ("Genu recurvatum", "Véase figura.");
INSERT INTO keywords (name, description) VALUES ("Genu valgo", "Piernas »en forma de X« debido a que las rodillas se juntan y los pies se separan.
Véase figura.");
INSERT INTO keywords (name, description) VALUES ("Genu varo", "Piernas »en forma de O« debido a que las rodillas se separan y los pies se juntan.
Véase figura.");
INSERT INTO keywords (name, description) VALUES ("Gimnasia acuática para embarazadas", "Clases que tienen lugar en una piscina específicamente para mujeres que están embarazadas o en período posnatal.");
INSERT INTO keywords (name, description) VALUES ("Glándula suprarrenal", "Dos glándulas localizadas en la parte superior de los riñones; tienen una corteza y una médula, cada una con funciones separadas.");
INSERT INTO keywords (name, description) VALUES ("Glándulas endocrinas", "Sus funciones se especifican en la siguiente tabla.");
INSERT INTO keywords (name, description) VALUES ("Las cuatro alteraciones primarias del equilibrio ácido-basico", "");
INSERT INTO keywords (name, description) VALUES ("Hipotálamo", "Hormona liberadora de la hormona del crecimiento, que controla la hormona del crecimiento; hormona liberadora de corticotropina, que controla la adrenocortico-tropina
(ACTH); hormona liberadora de tirotropina, que controla la hormona estimuladora del tiroides (TSH); hormona que inhibe la prolactina, que controla la prolactina;
hormona liberadora de gonadotropinas, que controla las gonadotropinas, la hormona luteinizante y la hormona estimuladora del folículo.");
INSERT INTO keywords (name, description) VALUES ("Pituitaria anterior", "La hormona del crecimiento influye en el crecimiento de todas las células; la ACTH controla la corteza adrenal; la hormona estimuladora de tiroides estimula al tiroides
para producir hormonas; la hormona estimuladora del folículo estimula el crecimiento del folículo en las mujeres y la producción de esperma en los hombres, y la hormona
luteinizante controla la ovulación y la producción de estrógenos, progesterona y testosterona.Pituitaria posterior
La hormona antidiurética causa la reabsorción de agua y, por lo tanto, el equilibrio acuoso; la oxitocina está implicada en la lactancia.");
INSERT INTO keywords (name, description) VALUES ("Glándula tiroides", "Controla el metabolismo de las células; la calcitonina está implicada en la monitorización de los niveles de calcio en sangre.");
INSERT INTO keywords (name, description) VALUES ("Paratiroides", "Controla los niveles de calcio en el plasma.");
INSERT INTO keywords (name, description) VALUES ("Corteza suprarrenal", "La aldosterona está implicada en la regulación de sodio y potasio, y el cortisol es un elemento clave del sistema de defensa del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Páncreas", "M etabolismo y equilibrio de los niveles de glucosa.");
INSERT INTO keywords (name, description) VALUES ("Ovarios y testículos", "");
INSERT INTO keywords (name, description) VALUES ("Glaucoma", "Alteración en que existe un aumento de la presión del líquido dentro del ojo, dañando el nervio óptico y ocasionando una pérdida
parcial de la visión que puede progresar hasta la ceguera.");
INSERT INTO keywords (name, description) VALUES ("Gliceriltrinitrato (GTN)", "Fármaco que puede ayudar a dilatar los vasos coronarios temporalmente, así como a reducir la carga sobre el corazón. Normalmente
se administra en aerosol o de forma sublingual.");
INSERT INTO keywords (name, description) VALUES ("Glioma", "Tumor maligno de rápido crecimiento de las células gliales del SNC. Se gradúan del 1 al 4 de acuerdo con su malignidad, siendo el 4 el
más agresivo.");
INSERT INTO keywords (name, description) VALUES ("Globina", "Porción de la proteína hemoglobina.");
INSERT INTO keywords (name, description) VALUES ("Globo de angioplastia", "La angioplastia con globo de la arteria coronaria es un procedimiento no quirúrgico que corrige el estrechamiento y la obstrucción de las
arterias coronarias. Esto permite que una mayor cantidad de sangre y oxígeno alcance el músculo cardíaco.");
INSERT INTO keywords (name, description) VALUES ("Glosofaríngeo", "Perteneciente a la lengua y la faringe.");
INSERT INTO keywords (name, description) VALUES ("Glotis", "Abertura de tamaño variable situada entre las cuerdas vocales. Para que una tos sea de naturaleza explosiva y elimine de manera
efectiva los productos de desecho del tracto respiratorio, la glotis debe estar cerrada.");
INSERT INTO keywords (name, description) VALUES ("Gobernancia clínica", "Tarea legal del NHS para mejorar sus servicios y mantener sus estándares. Los proveedores de servicio tienen la obligación de
implementar estándares nacionales establecidos por el Gobierno. El progreso es monitorizado por una comisión para mejorar la salud.");
INSERT INTO keywords (name, description) VALUES ("Goniómetro", "Instrumento para medir el rango de movimiento de una articulación.Goniómetro. Gracias a J, AI y CB");
INSERT INTO keywords (name, description) VALUES ("Gota", "Enfermedad metabólica reumatológica asociada con hiperuricemia (ácido úrico incrementado en sangre) con síntomas que tienen lugar
como resultado del depósito de cristales de ácido úrico dentro de los tejidos.");
INSERT INTO keywords (name, description) VALUES ("GPM", "Abreviatura de generadores de patrón motor.");
INSERT INTO keywords (name, description) VALUES ("Grados de Maitland", "• Grado I. Movimiento de pequeña amplitud cerca de la posición de inicio del rango de resistencia y usado para tratar el dolor.
• Grado II. Movimiento de gran amplitud que se lleva a cabo bien dentro del rango. Puede ocupar cualquier parte del rango que está
libre de espasmo muscular y resistencia. Se usa comúnmente para tratar el dolor.
• Grado III. Movimiento de gran amplitud pero que llega dentro del rango de espasmo muscular y resistencia. Se usa comúnmente para
tratar tanto el dolor como la resistencia.
• Grado IV. Movimiento de estiramiento de pequeña amplitud en el espasmo muscular y la resistencia. Se usa para tratar el final del
rango de la resistencia.");
INSERT INTO keywords (name, description) VALUES ("Grados en un rango normal con sensación terminal »dura«", "Herramienta de planificación de un proyecto. Se identifican tareas específicas de coordinación anticipada dentro de un proyecto. Las
etapas del proyecto comprenden la columna vertical; las fechas van de izquierda a derecha, y cada tarea se representa con una barra
horizontal cuyo extremo izquierdo hace referencia al comienzo esperado de la tarea, y el derecho a la fecha de finalización planeada.");
INSERT INTO keywords (name, description) VALUES ("Grand mal", "Ataque epiléptico intenso que afecta a todo el cuerpo, con temblores y taquicardias generalizadas, normalmente precedido de un aura.
Frecuentemente se pueden sufrir traumatismos debido a lo violento de los movimientos; existe también riesgo de morderse la lengua.");
INSERT INTO keywords (name, description) VALUES ("Gravedad", "Véase Factores SIN.");
INSERT INTO keywords (name, description) VALUES ("Grupo (cluster)", "Series de hechos o casos de una enfermedad u otro fenómeno relacionado con la salud, estrechamente agrupadas, con una distribuciónde patrones bien definida en relación con el tiempo, el lugar o ambos. También puede ser una unidad agrupada para aleatorización
(NICE, 2004).");
INSERT INTO keywords (name, description) VALUES ("Grupo control", "Término de investigación. Designa a los pacientes de un estudio que no han recibido la maniobra experimental o test.");
INSERT INTO keywords (name, description) VALUES ("Grupo de referencia", "Término de investigación para designar a un grupo de personas que se han reunido para alcanzar una perspectiva con respecto a sus
ideas y actitudes hacia un tema en particular. Es una técnica útil que se usa en combinación con otros métodos de investigación para
lograr la triangulación. Se puede seguir trabajando en el tema utilizando métodos investigación más cuantificables, que pueden ayudar a
aclarar los resultados cuantitativos o a generar hipótesis para investigaciones futuras.");
INSERT INTO keywords (name, description) VALUES ("Grupo postural", "Término usado principalmente por los terapeutas entrenados en Bobath para describir la postura del paciente teniendo en cuenta la
influencia del tono en la postura; por ejemplo, la sedestación sin apoyo es un »grupo postural mixto«, ya que contiene elementos tanto
de flexión como de extensión, mientras que el grupo postural del decúbito supino está dominado por la extensión.
Este término también se puede encontrar en la literatura para describir adaptaciones de la postura o ajustes que preceden y acompañan
al movimiento (Bobath, 1990).");
INSERT INTO keywords (name, description) VALUES ("Guía manual", "Movimiento o tarea que realiza un individuo ayudado por una fuerza externa, normalmente proporcionada por un terapeuta, como parte
de un tratamiento; por ejemplo, si existe debilidad, el paciente requerirá ayuda para alcanzar el objetivo del movimiento.
Observación clínica Es importante retirar la guía manual como parte del proceso de reaprendizaje, de modo que el paciente pueda
reeducar su propio movimiento.H");
INSERT INTO keywords (name, description) VALUES ("Habilidades transferibles", "Habilidades académicas o prácticas que se pueden utilizar en otra situación (diferente) (p. ej., resolución de problemas).");
INSERT INTO keywords (name, description) VALUES ("Habituación", "Acostumbrarse a un estímulo o reducir la conciencia de éste (p. ej., al TENS después de los primeros 10 min).");
INSERT INTO keywords (name, description) VALUES ("Haemophilus influenzae", "Causa común de infección respiratoria, que se observa particularmente en pacientes con patologías pulmonares esenciales como EPOC
o bronquiectasia.");
INSERT INTO keywords (name, description) VALUES ("Hallux rigidus", "Pérdida de movimiento de la articulación metatarsofalángica (MTF) del primer dedo, particularmente en la extensión.");
INSERT INTO keywords (name, description) VALUES ("Hallux valgus", "Deformidad de la articulación MTF del primer dedo, en que el dedo se desvía hacia la parte externa.");
INSERT INTO keywords (name, description) VALUES ("Haloperidol", "Fármaco antipsicótico utilizado como calmante.");
INSERT INTO keywords (name, description) VALUES ("Halotracción", "Aplicación de tracción esquelética en la cabeza utilizando un instrumento circular.");
INSERT INTO keywords (name, description) VALUES ("Haz de His", "Haz de fibras miocárdicas modificadas de la cavidad interventricular responsable de la transmisión del impulso cardíaco desde el nódulo
AV a los ventrículos.");
INSERT INTO keywords (name, description) VALUES ("Juanete en el dedo gordo del pie izquierdo", "");
INSERT INTO keywords (name, description) VALUES ("HDL", "Abreviatura médica común de lipoproteína de alta densidad.");
INSERT INTO keywords (name, description) VALUES ("HEID", "Abreviatura médica común de hiperostosis esquelética idiopática difusa.");
INSERT INTO keywords (name, description) VALUES ("Hemangioblastoma", "Tumor de origen vascular.");
INSERT INTO keywords (name, description) VALUES ("Hemartrosis", "Hemorragia dentro de una articulación. Se encuentra comúnmente después de una rotura del ligamento cruzado anterior; es unaalteración del mecanismo de coagulación normal de la sangre.");
INSERT INTO keywords (name, description) VALUES ("Hematócrito", "Medida de laboratorio que determina el porcentaje de células sanguíneas rojas contenidas en un volumen de sangre dado.");
INSERT INTO keywords (name, description) VALUES ("Hematoma", "Sangrado dentro de los tejidos. Colección localizada de sangre, normalmente coagulada, en un órgano, espacio o tejido, debido a la
rotura de la pared de un vaso sanguíneo.");
INSERT INTO keywords (name, description) VALUES ("Hematoma extradural", "Hemorragia entre la duramadre (membrana externa de las meninges) y el cráneo, después de una lesión cerebral. Dado que no hay
lugar para que se absorba la sangre, es muy grave y da lugar rápidamente a la compresión del cerebro y a la muerte, a menos que se
lleve a cabo neurocirugía de emergencia para detener la hemorragia y eliminar el coágulo. Los pacientes que reciben neurocirugía en las
etapas tempranas pueden recuperarse completamente y, por ello, es esencial que se lleven a cabo observaciones correctas y frecuentes
en todos los pacientes con lesión cerebral, para detectar cualquier deterioro.");
INSERT INTO keywords (name, description) VALUES ("Hematoma suHdural", "Acumulación de sangre debajo de la capa externa (duramadre) del cerebro y la superficie de éste.
Normalmente es el resultado de una lesión cerebral, aunque puede producirse de forma espontánea.");
INSERT INTO keywords (name, description) VALUES ("Hemiapnosia", "Pérdida o defecto de visión en mitad del campo visual de uno o ambos ojos debido a una lesión cerebral. El paciente puede chocar con
cosas situadas en el campo visual del lado afectado o ignorar objetos o personas situados en este mismo lado.");
INSERT INTO keywords (name, description) VALUES ("Hemiparesia", "Paresia que afecta a un lado del cuerpo. Presentación común después de un ACV.");
INSERT INTO keywords (name, description) VALUES ("Hemiplejía", "Parálisis de un lado del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Hemisferios cerebrales", "Los dos lados en que se divide el cerebro dentro del encéfalo.");
INSERT INTO keywords (name, description) VALUES ("Hemodiálisis", "Proceso de depuración de la sangre, pasándola a través de un tuHo permeable a moléculas pequeñas pero no a proteínas y células más
grandes.");
INSERT INTO keywords (name, description) VALUES ("Hemofilia", "Alteración del mecanismo de coagulación de la sangre.");
INSERT INTO keywords (name, description) VALUES ("Hemoglobina (Hb)", "Proteína del interior del eritrocito, formada por la »globina« (cuatro cadenas de polipéptidos unidos) en combinación con el complejo
»hemo« (que contiene un ion de hierro). Las cadenas de polipéptidos se enrollan unas con otras y las alteraciones en su figura
determinan la afinidad de la Hb por el oxígeno. Por lo tanto, cuando la primera molécula de oxígeno se une con la Hb, se hace más fácil
la unión de la segunda, y así sucesivamente. En su estado desoxigenado, la Hb se convierte en una importante bomba sanguínea de H+
y, por lo tanto, es crucial en el transporte de CO
2 . Cuando la unión al oxígeno se ha completado, la Hb pasa a denominarse
oxihemoglobina. En sangre (que tiene una media de contenido de Hb de 15 g/dl), cada gramo de Hb transporta aproximadamente 1,34
ml de oxígeno. Así, la capacidad de la sangre para transportar el oxígeno se incrementa 70 veces en presencia de Hb (en comparación
a la cantidad de oxígeno transportado en su estado de disolución directamente en sangre). La saturación de Hb determina hasta qué
punto se utiliza la capacidad de transportar oxígeno. La saturación de Hb varía con los cambios en la PaO 2 , lo cual se demuestra con la
curva de disociación de la oxihemoglobina.
HemopoyesisProceso por el cual se producen las células sanguíneas.");
INSERT INTO keywords (name, description) VALUES ("Hemoptisis", "Presencia de sangre en los esputos. Puede obedecer a diversas causas, incluyendo carcinoma, traumatismo por intuHación después de
una intervención, infecciones, fibrosis quística y otras alteraciones.");
INSERT INTO keywords (name, description) VALUES ("Hemorragia", "Salida de la sangre de los vasos que la contienen.");
INSERT INTO keywords (name, description) VALUES ("Hemorragia cerebral", "Término utilizado para describir la hemorragia desde un vaso sanguíneo en el cerebro. Se describen normalmente según su localización
en la base; suHaracnoidea, extradural, suHdural e intercerebral dentro de la materia del cerebro. Puede dar lugar a lesión neurológica.");
INSERT INTO keywords (name, description) VALUES ("Hemorragia intracraneal (HIC)", "Hemorragia localizada dentro del tejido cerebral, comúnmente denominada ictus, aunque la causa más común del ictus es un infarto.
Una HIC también puede deberse a un aneurisma, malformación arteriovenosa, traumatismo o hipertensión.");
INSERT INTO keywords (name, description) VALUES ("Hemorroides", "Dilatación de una vena del plexo hemorroidal superior o inferior. Se presenta como una tumefacción dolorosa formada por la dilatación
de los vasos sanguíneos alrededor del margen del ano o dentro de éste. Las hemorroides pueden sangrar ocasionalmente.");
INSERT INTO keywords (name, description) VALUES ("Hemotórax", "Sangre en el interior de la pleura pulmonar.");
INSERT INTO keywords (name, description) VALUES ("Heparina", "Fármaco que previene la coagulación de la sangre; se usa después del diagnóstico de la trombosis venosa profunda, relevante para la
fisioterapia porque afecta a la coagulación, a la formación de hematomas y a la consolidación.");
INSERT INTO keywords (name, description) VALUES ("Hepático", "Perteneciente al hígado.");
INSERT INTO keywords (name, description) VALUES ("Hepatitis", "Inflamación del hígado, a menudo acompañada de ictericia, aumento de tamaño, fiebre, fatiga, náuseas y tests sanguíneos de la función
del hígado anormales (LFT).");
INSERT INTO keywords (name, description) VALUES ("Hepatitis B", "Enfermedad hepática vírica que puede ser aguda o crónica e incluso poner en peligro la vida, particularmente en personas con
resistencia inmunitaria pobre. El virus de la hepatitis B puede transmitirse por contacto sexual, agujas contaminadas o productos
sanguíneos contaminados.");
INSERT INTO keywords (name, description) VALUES ("Hepatitis C", "Enfermedad vírica que causa la inflamación del hígado y puede causar lesión hepática grave que pone en peligro la vida.");
INSERT INTO keywords (name, description) VALUES ("Hepatoesplenomegalia", "Aumento de tamaño del hígado y del bazo.");
INSERT INTO keywords (name, description) VALUES ("Hepatomegalia", "Aumento de tamaño del hígado.");
INSERT INTO keywords (name, description) VALUES ("Hereditario", "Que se transmite genéticamente.
HerniaTumoración formada por la protrusión, salida o deslizamiento de una parte de un órgano o tejido a través de una abertura anormal; la
hernia de hiato, por ejemplo, es la herniación del estómago a través del diafragma.");
INSERT INTO keywords (name, description) VALUES ("Hernia abdominal", "Protrusión visceral a través de un defecto o debilidad de la pared abdominal; por ejemplo, la hernia umbilical es un tipo de hernia
abdominal.");
INSERT INTO keywords (name, description) VALUES ("Hernia de hiato", "Protrusión del estómago hacia arriba, a través de la abertura del diafragma, normalmente ocupada por el esófago.");
INSERT INTO keywords (name, description) VALUES ("Hernia umbilical", "Protrusión de tejidos blandos a través del ombligo.");
INSERT INTO keywords (name, description) VALUES ("Hernia de hiato", "");
INSERT INTO keywords (name, description) VALUES ("Herniación/protrusión del disco", "Interrupción de la integridad normal del disco intervertebral, que hace que el núcleo pulposo rompa el anillo. Hay varios grados, desde
una protrusión menor, que puede ser asintomática, hasta la irrupción a través de las fibras anulares externas dentro del canal espinal,
causando dolor intenso en la pierna y compresión nerviosa.
Las protrusiones se pueden clasificar como se muestra a continuación (American Academy of Orthopaedic Surgeons, 1987).");
INSERT INTO keywords (name, description) VALUES ("Hiato", "Término anatómico que significa »hueco«.");
INSERT INTO keywords (name, description) VALUES ("Hidrocefalia", "Aumento en el volumen del líquido cefalorraquídeo (LCR), normalmente como resultado de una absorción alterada y ocasionalmente desecreciones excesivas. Puede ser congénita o adquirida. La hidrocefalia se clasifica en:
• Obstructiva. Obstrucción del flujo de LCR dentro del sistema ventricular.
• Comunicante. Obstrucción dentro del espacio suHaracnoideo.
Los pacientes pueden presentar aumento del tamaño de la cabeza, frente prominente, atrofia cerebral y convulsiones; también pueden
aparecer confusos y desarrollar una postura en flexión y una marcha arrastrando los pies;");
INSERT INTO keywords (name, description) VALUES ("finalmente se produce la pérdida de", "conciencia. El tratamiento normalmente requiere la inserción de un cortocircuito que desvía el exceso de fluido a la cavidad peritoneal.
La hidrocefalia es una complicación común después de una hemorragia suHaracnoidea.");
INSERT INTO keywords (name, description) VALUES ("Hidrofílico", "Que en seguida absorbe la humedad, o que tiene afinidad por el agua.");
INSERT INTO keywords (name, description) VALUES ("Hidroterapia", "Ejercicios de rehabilitación llevados a cabo en el agua.");
INSERT INTO keywords (name, description) VALUES ("Hidroxicloroquina", "Fármaco utilizado para tratar y prevenir la malaria. También se utiliza para tratar la artritis reumatoide.");
INSERT INTO keywords (name, description) VALUES ("Hiperalgesia", "Umbral disminuido para la interpretación del dolor, o hipersensibilidad.");
INSERT INTO keywords (name, description) VALUES ("Hipercalcemia", "Demasiado calcio en la sangre.");
INSERT INTO keywords (name, description) VALUES ("Hipercapnia", "Exceso de dióxido de carbono en la sangre.");
INSERT INTO keywords (name, description) VALUES ("Hipercinesia", "Movimientos involuntarios excesivos que se ven en algunas alteraciones neurológicas; incluyen fenómenos como temblor, clonus y tics.");
INSERT INTO keywords (name, description) VALUES ("Hipercolesterolemia familiar", "Exceso de colesterol en el plasma.");
INSERT INTO keywords (name, description) VALUES ("Hiperextensión", "Fuerza activa o pasiva que lleva a la articulación a la extensión, pero más allá de su rango fisiológico normal. El movimiento humano
abarca un amplio espectro de variaciones. Un cierto grado de hiperextensión puede considerarse normal en codos y rodillas.");
INSERT INTO keywords (name, description) VALUES ("Hiperinsuflación", "Estado de sobreinflación de los pulmones o la pared torácica, que da lugar a un aumento del espacio muerto, aumento del trabajo
respiratorio y desventaja mecánica de los músculos respiratorios. Las características de la hiperinsuflación incluyen un aumento del
diámetro torácico anteroposterior, costillas elevadas horizontalmente y diafragma aplanado.");
INSERT INTO keywords (name, description) VALUES ("Hiperinsuflación manual", "Hiperinsuflación deliberada del pecho normalmente por medio de un circuito en bolsa. Esta técnica se usa para facilitar la eliminación de
secreciones y reinsuflar áreas de colapso pulmonar en pacientes intuHados.");
INSERT INTO keywords (name, description) VALUES ("Hipermetría", "Alteración del movimiento en la que el paciente tiende a superar el objetivo propuesto.");
INSERT INTO keywords (name, description) VALUES ("Hipermovilidad", "Aumento más allá del rango normal del movimiento de una articulación.
Observación clínica El término »normal« en realidad comprende un amplio espectro, del cual la hipermovilidad constituye un extremo,
por lo que puede no ser un signo de patología y no producir síntomas.Hipernatremia
Exceso de sodio en el plasma sanguíneo.");
INSERT INTO keywords (name, description) VALUES ("Hiperostosis esquelética idiopática difusa (HEID)", "Enfermedad que aparece en hombres de edad avanzada caracterizada por la presencia de ligamentos osificados y grandes osteófitos
que forman puentes entre las vértebras.");
INSERT INTO keywords (name, description) VALUES ("Hiperpnea", "Ventilación aumentada adecuadamente para mantener una PaCO 2 normal.");
INSERT INTO keywords (name, description) VALUES ("Hiperreactividad", "Estado en el que una reacción a un estímulo es mayor que la respuesta normal.");
INSERT INTO keywords (name, description) VALUES ("Hiperreflexia", "Actividad de reflejos exagerada, demostrada en el electromiograma (EMG). Es una parte del síndrome de la neurona motora superior.
Se puede dar después de un ictus o lesión cerebral. Se considera que está relacionada con cambios plásticos en el sistema nervioso.");
INSERT INTO keywords (name, description) VALUES ("Hipertensión", "Presión sanguínea arterial elevada de forma persistente. Puede tener una causa desconocida (hipertensión esencial o idiopática) o puede
asociarse con otras enfermedades primarias (hipertensión secundaria). La presión sanguínea elevada persistente es un factor de riesgo
en la enfermedad cardiovascular, ataque cardíaco e ictus.");
INSERT INTO keywords (name, description) VALUES ("Hipertermia", "Temperatura corporal elevada.");
INSERT INTO keywords (name, description) VALUES ("Hipertonía", "Aumento de tono o tensión dentro de los músculos. Lo contrario de hipotónico. Existen dos tipos de hipertonía: espasticidad y rigidez.");
INSERT INTO keywords (name, description) VALUES ("Comparación entre espasticidad y rigidez", "");
INSERT INTO keywords (name, description) VALUES ("Espasticidad", "");
INSERT INTO keywords (name, description) VALUES ("Rigidez", "Patrón de la implicación muscular Flexores del miembro superior; extensores del miembro inferior Flexores y extensores por igual
Naturaleza del tono Aumento del tono dependiente de la velocidad Constante durante el movimiento");
INSERT INTO keywords (name, description) VALUES ("Reflejos del tendón Aumentados Normales", "Fisiopatología Aumento del beneficio del reflejo de estiramiento espina Componente de larga latencia del reflejo de estiramiento aumentado
Significado clínico Signo de la neurona motora superior (piramidal) Signo extrapiramida");
INSERT INTO keywords (name, description) VALUES ("Hipertrofia", "Aumento de tamaño; lo opuesto de atrofia.");
INSERT INTO keywords (name, description) VALUES ("Hiperventilación", "Estado de exceso de ventilación que da lugar a un nivel anormalmente bajo de PaCO 2 (hipercapnia), es decir, menos de 4,5 kPa (35
mmHg). El síndrome de hiperventilación crónica es una alteración del patrón de la respiración normalmente infradiagnosticado, lo que
hace que los pacientes acudan a diferentes departamentos para la investigación de muchos de los síntomas físicos discapacitantes
experimentados.");
INSERT INTO keywords (name, description) VALUES ("Hipnosis", "Inducción de un estado de sugestión, semejante al sueño, por parte de un hipnotizador. Algunas personas pueden, por ejemplo,
someterse a tratamiento dental bajo hipnosis.");
INSERT INTO keywords (name, description) VALUES ("Hipocalcemia", "Deficiencia de calcio en sangre.Hipocapnia
Deficiencia de dióxido de carbono en sangre; si se prolonga puede finalmente dar lugar a alcalosis.");
INSERT INTO keywords (name, description) VALUES ("Hipocinesia", "Pérdida de velocidad y extensión de los movimientos voluntarios.");
INSERT INTO keywords (name, description) VALUES ("Hipoestesia", "Sensibilidad a la estimulación anormalmente disminuida.");
INSERT INTO keywords (name, description) VALUES ("Hipofaringe", "Área entre la epiglotis y la laringe.");
INSERT INTO keywords (name, description) VALUES ("Hipoglucemia", "Concentración anormalmente disminuida de glucosa en sangre. Tiene lugar cuando una persona con diabetes se ha inyectado demasiada
insulina, ha comido muy poco o ha realizado ejercicio sin ingerir comida suplementaria.");
INSERT INTO keywords (name, description) VALUES ("Hipometría", "Alteración en el movimiento, en la que el paciente tiende a no alcanzar el objetivo que se le propone.");
INSERT INTO keywords (name, description) VALUES ("Hipomovilidad", "Descenso en el rango normal de movimiento de una articulación. Esto puede incluir una pérdida de movimientos accesorios.");
INSERT INTO keywords (name, description) VALUES ("Hiponatremia", "Deficiencia de sodio en el plasma sanguíneo.");
INSERT INTO keywords (name, description) VALUES ("Hipopnea", "Reducción adecuada en la ventilación, que mantiene una PaCO 2 normal. Cuando tiene lugar durante el sueño, la hipopnea se define
como la reducción en la ventilación durante 10 s o más (SIGN, 2003).");
INSERT INTO keywords (name, description) VALUES ("Hipotensión", "Presión sanguínea baja. La hipotensión postural es una presión sanguínea disminuida que sólo aparece cuando la persona adopta una
postura particular.");
INSERT INTO keywords (name, description) VALUES ("Hipotensión postural", "Presión sanguínea baja que sólo aparece cuando la persona adopta una postura concreta.");
INSERT INTO keywords (name, description) VALUES ("Hipotermia", "Disminución de la temperatura corporal.");
INSERT INTO keywords (name, description) VALUES ("Hipótesis", "Término de investigación que se aplica a la respuesta propuesta a una pregunta de investigación.
La formulación de una hipótesis puede ser no direccional (sin dirección implicada) o puede ser más específica e indicar la dirección del
efecto, es decir, ser direccional.
Un ejemplo de hipótesis no direccional sería plantear la existencia de una diferencia de inteligencia entre alumnos y profesores.
Un ejemplo de hipótesis direccional sería plantear que los alumnos son más inteligentes que sus profesores.");
INSERT INTO keywords (name, description) VALUES ("□ Consejo para el estudiante", "No toda investigación requiere una hipótesis; en realidad, muchos estudios cualitativos sólo generan hipótesis en su conclusión");
INSERT INTO keywords (name, description) VALUES ("Hipótesis bilateral", "Término de investigación que implica una diferencia pero no la dirección de cambio; por ejemplo, los alumnos de fisioterapia en el
grupo A tendrán un resultado diferente que los alumnos de fisioterapia del grupo B.Por el contrario, una hipótesis unilateral implica una dirección para un cambio predecible; por ejemplo, los alumnos de fisioterapia en el
grupo A tendrán una puntuación más alta que los del grupo B.");
INSERT INTO keywords (name, description) VALUES ("Hipótesis de doble aplastamiento", "Propone que una lesión proximal a lo largo de un axón hace que éste se halle más predispuesto a lesionarse en un lugar más distal a lo
largo de su transcurso a través de un flujo axoplásmico alterado.");
INSERT INTO keywords (name, description) VALUES ("Hipótesis nula", "Término de investigación que se aplica a la proposición según la cual no hay diferencia entre grupos. Un estudio típico tiene como
objetivo rechazar las hipótesis nulas.");
INSERT INTO keywords (name, description) VALUES ("Hipótesis unilateral", "Término de investigación que implica una dirección para un cambio previsto; por ejemplo, el grupo A obtendrá una puntuación superior
a la del grupo B. Por el contrario, una hipótesis bilateral implica una diferencia, pero no la dirección del cambio; por ejemplo, el grupo
A tendrá una puntuación diferente que el grupo B.");
INSERT INTO keywords (name, description) VALUES ("Hipotonía", "Falta de tono muscular. Resistencia reducida al estiramiento pasivo; los pacientes pueden tener dificultad en el mantenimiento de una
postura dada o una posición contra la gravedad. En el paciente hipotónico, los músculos están flácidos.");
INSERT INTO keywords (name, description) VALUES ("Hipoventilación", "Hipoventilación alveolar o respiración insuficiente, que da lugar a un nivel elevado de PaCO 2 .");
INSERT INTO keywords (name, description) VALUES ("Hipoxemia", "Se define como un contenido insuficiente de oxígeno en la sangre. Hay cuatro causas principales de una presión parcial de oxígeno
reducida en sangre arterial. Éstas son:
1. Hipoventilación.
2. Alteración de la difusión.
3. Shunt.
4. Desigualdades V/Q.");
INSERT INTO keywords (name, description) VALUES ("Hipoxia", "Cantidad inadecuada de disponibilidad de oxígeno a nivel tisular para la respiración celular (Weilitz, 1993).
Si se mantiene, la función celular normal se altera y el resultado pueden ser complicaciones como arritmias cardíacas, hipotensión y paro
cardíaco. La hipoxia ocurre como resultado de un desequilibrio entre la disponibilidad de oxígeno en sangre y las demandas de
consumo de oxígeno.");
INSERT INTO keywords (name, description) VALUES ("Histerectomía", "Proceso quirúrgico por el cual el útero (matriz) es extirpado.");
INSERT INTO keywords (name, description) VALUES ("HIV", "Abreviatura médica común de virus de inmunodeficiencia humana.");
INSERT INTO keywords (name, description) VALUES ("Holístico", "El enfoque holístico en la asistencia de un paciente se da cuando se tiene en consideración, para la selección del tratamiento, el estilo de
vida de un individuo y su funcionamiento social, así como cualquier presentación patológica.");
INSERT INTO keywords (name, description) VALUES ("Hombro congelado", "Nombre alternativo para la capsulitis del hombro.
HomofobiaActitud en que se muestran prejuicios o miedo a personas que son gays o lesbianas.");
INSERT INTO keywords (name, description) VALUES ("Hormona adrenocortitropa (ACTH)", "Hormona producida por la glándula pituitaria anterior. Estimula la corteza adrenal para secretar hormonas glucocorticoides.");
INSERT INTO keywords (name, description) VALUES ("Hospicio", "Institución para las personas que presentan una enfermedad terminal. El movimiento de hospicio comenzó en 1970 y fue fundado por
organizaciones voluntarias. Muchos de sus principios y valores se han extendido ahora al NHS, aunque los hospicios aún permanecen
independientes a ella. Los hospicios proporcionan asistencia residencial y sanitaria.");
INSERT INTO keywords (name, description) VALUES ("Hotpacks", "Forma de aplicación de calor superficial. Los tipos de hotpacks que se calientan en un calentador de compresas incluyen los paquetes
de lona (calor húmedo) y los de plástico (calor seco). Existen otros tipos de hotpacks: paquetes de gel, paquetes de trigo calentados
en un horno o microondas y paquetes químicos que el usuario dobla o rompe para iniciar una reacción exotérmica. La duración del
calor depende del método y de la temperatura inicial. Los peligros son principalmente las quemaduras o los daños tisulares, si el calor
se aplica en un área con aporte sanguíneo insuficiente.");
INSERT INTO keywords (name, description) VALUES ("HSA", "Abreviatura médica común de hemorragia suHaracnoidea.
Tiene lugar cuando se produce una hemorragia en el espacio suHaracnoideo, que se localiza en el encéfalo, entre la aracnoides y la
piamadre. Los aneurismas cerebrales y las malformaciones arteriovenosas son posibles causas de HSA. Los pacientes normalmente
requieren cirugía y pueden presentar un déficit neurológico que necesitará ser tratado por el equipo multidisciplinario.");
INSERT INTO keywords (name, description) VALUES ("HSD", "Abreviatura médica común de hematoma suHdural.
Colección sanguínea en la superficie del cerebro, que se sitúa por debajo de la cuHierta externa (duramadre) y la superficie de éste.
Los HSD agudos son normalmente el resultado de una lesión en la cabeza, aunque pueden producirse de forma espontánea. Los HSD
crónicos ocurren más a menudo en la vejez y en la infancia, siendo los traumatismos su causa principal.");
INSERT INTO keywords (name, description) VALUES ("Hueso esponjoso", "Hueso formado por fibras de colágeno mineralizadas y regularmente ordenadas de forma paralela, más pobremente organizadas que las
del hueso cortical que podemos encontrar en las diáfisis de los huesos largos de los adultos. Se localiza en las epífisis de los huesos
largos como el fémur.");
INSERT INTO keywords (name, description) VALUES ("Hueso sesamoideo", "Hueso pequeño con forma de semilla de sésamo que se localiza junto a un tendón en puntos de gran presión.
Observación clínica Unas personas tienen más huesos sesamoideos que otras. La rótula es el hueso sesamoideo más grande del
cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Huesos del carpo", "Huesos de la mano.M ano derecha, visión anterior");
INSERT INTO keywords (name, description) VALUES ("Húmero", "Hueso del brazo.
(A) Visión posterior. (B) Visión anterior.");
INSERT INTO keywords (name, description) VALUES ("Humidificador", "Aparato que genera humedad en el aire.I");
INSERT INTO keywords (name, description) VALUES ("latrogénico", "Inducido de forma inadvertida por tratamiento o procedimiento médico. Por ejemplo, una infección causada durante la cirugía es
iatrogénica.");
INSERT INTO keywords (name, description) VALUES ("ICAT", "Abreviatura médica común de infarto cerebral arterial total.
Es una apoplejía causada por un infarto que afecta a toda la circulación anterior.");
INSERT INTO keywords (name, description) VALUES ("Iceberg clínico", "Modo de ilustrar la idea de que la mayoría de las enfermedades están ocultas y los profesionales médicos no les prestan atención.");
INSERT INTO keywords (name, description) VALUES ("ICPA", "Abreviatura médica común de infarto cerebral parcial anterior.
Pacientes con este tipo de apoplejía tienen un alto riesgo de sufrir más apoplejías.");
INSERT INTO keywords (name, description) VALUES ("Ictericia", "Coloración amarillenta de la piel y los ojos debida a la acumulación de bilis. Se asocia normalmente con algún tipo de enfermedad o
daño hepático. La esclerótica (parte externa blanca) del ojo también puede volverse amarilla.");
INSERT INTO keywords (name, description) VALUES ("Identidad", "Conocimiento de individuos y grupos teniendo en cuenta lo que son en relación con los demás en su grupo o sociedad. Implica no sólo
sentimientos y comprensión sobre sí mismos en relación con los demás, sino también sentimientos y comprensión sobre otros en
relación con sí mismos. Las personas pueden tener múltiples identidades, por ejemplo británico, padre, fisioterapeuta y músico.");
INSERT INTO keywords (name, description) VALUES ("Idiopático", "Sin causa fisiológica bien definida.");
INSERT INTO keywords (name, description) VALUES ("IgG", "Abreviatura médica común de inmunoglobulina G.");
INSERT INTO keywords (name, description) VALUES ("Igualdad", "Eliminación de las desventajas, por ejemplo, en el acceso a servicios, en oportunidades para lograr metas deseadas socialmente y en los
derechos a recursos, propiedad y poder.");
INSERT INTO keywords (name, description) VALUES ("Íleo", "Obstrucción de los intestinos.");
INSERT INTO keywords (name, description) VALUES ("Ileostomía", "Creación quirúrgica de una abertura en el íleon, con un estoma (orificio) en la pared abdominal.i.m.
Abreviatura médica común de intramuscular.");
INSERT INTO keywords (name, description) VALUES ("IMAO", "Abreviatura médica común de los inhibidores de la monoaminooxidasa. Se emplean en el tratamiento de la depresión.");
INSERT INTO keywords (name, description) VALUES ("Impedancia acústica", "Término utilizado para describir la resistencia de los tejidos al paso del ultrasonido.");
INSERT INTO keywords (name, description) VALUES ("Impétigo", "Infección cutánea común. Es más frecuente en niños. En adultos, puede seguir a otras alteraciones de la piel.");
INSERT INTO keywords (name, description) VALUES ("Implicación del usuario", "Aproximación a los cuidados sociales y de salud donde los usuarios de los servicios están involucrados en la planificación y evaluación
de los servicios. Las políticas gubernamentales del Reino Unido, como el NHS y el Community Care Act (1990) , han favorecido e
incluso hecho obligatorio un cierto grado de implicación por parte del usuario.");
INSERT INTO keywords (name, description) VALUES ("Impulso", "En el contexto electroterápico, es un flujo de corriente interrumpido. Es la unidad básica tanto de la corriente alterna como de la
pulsada.
• Tipo. Monofásico (es decir, el impulso tiene una sola fase; p. ej., EPAV o estimulación pulsada de alto voltaje, galvánica interrumpida,
etc.) o bifásico (es decir, existen dos fases por impulso; p. ej., potencia de la mayoría de estimuladores motores).
• Simetría/asimetría. Bifásico; las fases pueden tener la misma forma o no.
• Forma de fase. Puede ser rectangular, triangular, sinusoidal, dentada, etc.
• Equilibrado/no equilibrado. Bifásico y equilibrado si el cambio en cada fase es igual; desequilibrado si aumenta en una fase.
• Duración. Normalmente medida en μs o ms.
• Frecuencia. Número de impulsos por segundo (herzios, Hz).");
INSERT INTO keywords (name, description) VALUES ("In vitro", "Se refiere a un ambiente artificial creado fuera de un organismo vivo.");
INSERT INTO keywords (name, description) VALUES ("In vivo", "Se refiere a los estudios llevados a cabo en un organismo vivo.");
INSERT INTO keywords (name, description) VALUES ("Inclusión social", "Incorporación completa y participativa de determinadas personas en la sociedad como resultado de cambios fundamentales en las
actitudes, comportamiento y estructuras sociales.");
INSERT INTO keywords (name, description) VALUES ("Incontinencia de urgencia", "Dolencia caracterizada por un goteo involuntario acompañado o inmediatamente precedido de urgencia, es decir, un repentino deseo
irresistible de orinar (ICS, 2002). Esta forma de goteo tiene lugar cuando la vejiga se llena y el detrusor se contrae de forma
inapropiada.Independencia
Asociada predominantemente con la capacidad para realizar las cosas por uno mismo y ser autosuficiente. En algunas culturas, la
independencia también está asociada con transiciones de la vida, particularmente la transición de la infancia a la vida adulta. La
independencia es menos valorada en unas culturas que en otras que pueden tener una orientación colectivista. El significado de
independencia en términos de »hacer las cosas por uno mismo« ha sido cada vez más cuestionado por personas discapacitadas en un
diverso número de campos. El Disabled People's Movement (una asociación de personas discapacitadas) considera la independencia
en términos de autonomía, control y gestión y organización de la asistencia que se requiere. Realmente todos somos dependientes de los
demás para nuestra supervivencia, por lo que nadie es independiente.");
INSERT INTO keywords (name, description) VALUES ("Índice de apnea/hipoapnea (AHI)", "Frecuencia por hora de apneas e hipoapneas durante el sueño. La AHI es la medida comúnmente utilizada para diagnosticar y valorar la
gravedad de la apnea del sueño. El índice se calcula midiendo el número de episodios apneicos (episodios sin flujo de aire) o
hipoapneicos (episodios de flujo aéreo reducido) por hora de sueño. Un índice <5 se considera normal, mientras que un índice >40
refleja una apnea del sueño de moderada a grave (no hay un acuerdo claro con respecto al número exacto de episodios) ( SIGN OSA
Guidelines, 2003).");
INSERT INTO keywords (name, description) VALUES ("Índice de Barthel", "Resultado de la medida genérica de 10 apartados. Valora la capacidad para llevar a cabo actividades de la vida diaria (AVD) y la
movilidad.
Los apartados incluyen alimentación, capacidad para moverse de una silla de ruedas a la cama y viceversa, preparación, traslado a y
desde el baño, aseo, andar en una superficie plana, subir y bajar escaleras, vestirse, y continencia de intestinos y vejiga. Es fácilmente
aplicada con buena fiabilidad, pero tiene limitaciones. Tiene una sensibilidad limitada para el cambio y un efecto de bajo techo, es decir,
se puede lograr la puntuación máxima, pero seguir siendo dependiente, ya que no valora el efecto de la cognición.");
INSERT INTO keywords (name, description) VALUES ("Índice de masa corporal (IMC)", "Sencilla herramienta de medida para evaluar de forma general el estado nutricional de un paciente. Se calcula con:
El rango normal del IMC es 21-25; un IMC <16 es indicativo de una desnutrición grave, un IMC >30 es indicativo de obesidad grave.");
INSERT INTO keywords (name, description) VALUES ("Índice de motricidad", "Medida de la función de una extremidad con una puntuación máxima de 100 para sujetos normales. Utilizado en rehabilitación
neurológica como una medida de función (discapacidad). La parálisis grave se define por una puntuación de 0-32, la moderada de 33-
64 y la leve de 65-99.Índice funcional Basfi bath para la espondilitis anquilosante
Medida útil de referencia de la capacidad funcional de los pacientes con espondilitis anquilosante para realizar las AVD ( Calin y cols.,
1994).");
INSERT INTO keywords (name, description) VALUES ("Inercia", "Resistencia de un cuerpo a empezar a moverse o a dejar dehacerlo una vez ha empezado.");
INSERT INTO keywords (name, description) VALUES ("Inervación recíproca", "Interacción entre grupos de músculos opuestos que permite una cocontracción dinámica para la estabilidad postural y para controlar los
movimientos a fin de realizar la función.");
INSERT INTO keywords (name, description) VALUES ("Inestabilidad", "Término utilizado para describir un rango de movimiento anormal y excesivo para el que no existe control muscular (Maitland, 2001).");
INSERT INTO keywords (name, description) VALUES ("Infarto de miocardio", "Abreviatura médica común de infarto de miocardio.
Se conoce más comúnmente como ataque al corazón. La causa más frecuente es un trombo o coágulo; hay varios grados, que van
desde aquellos que causan cese inmediato del latido cardíaco y muerte, hasta aquellos que pasan sin ser diagnosticados.");
INSERT INTO keywords (name, description) VALUES ("Infarto lacunar", "También puede recibir el nombre de infarto cerebral de tipo lacunar o laguna, que es un tipo de apoplejía.");
INSERT INTO keywords (name, description) VALUES ("Infección oportunista", "Infección en personas inmunodeprimidas, causada por un organismo que normalmente no ocasiona trastornos en personas sanas.
Muchos de estos organismos son portados en estado latente prácticamente por todo el mundo y sólo causan alteraciones cuando
encuentran un sistema inmunitario dañado.");
INSERT INTO keywords (name, description) VALUES ("Inferior", "Término anatómico que, en posición anatómica, significa »en dirección a los pies«.");
INSERT INTO keywords (name, description) VALUES ("Inflamación", "Reacción compleja estereotipada del tejido vivo vascularizado a un traumatismo local. Los cuatro signos cardinales de la inflamación
son:
1. Rubor.
2. Dolor.
3. Calor.
4. Tumefacción.
Algunas autoridades añaden impotencia funcional.Inhalador con dosificador
Envase presurizado que contiene un fármaco en aerosol para su autoadministración en forma de dosis exactas. Cuando es utilizado con
un aparato espaciador por pacientes con enfermedades pulmonares, la deposición pulmonar de los fármacos mejora
considerablemente.");
INSERT INTO keywords (name, description) VALUES ("Inhibición recíproca", "La activación del nervio motor de un músculo es acompañada normalmente por la inhibición de la acción de los músculos antagonistas
que actúan sobre dicha articulación. Así, por ejemplo, si una persona está contrayendo el bíceps, el tríceps será inhibido
recíprocamente.");
INSERT INTO keywords (name, description) VALUES ("Inhibidores ECA", "Medicamentos utilizados para tratar la presión sanguínea alta y la insuficiencia cardíaca congestiva.");
INSERT INTO keywords (name, description) VALUES ("Inmovilidad", "Término general clínicamente utilizado para describir la falta de movimiento, tanto localmente (es decir, en una articulación o músculo)
como globalmente (p. ej., el paciente es incapaz de andar).");
INSERT INTO keywords (name, description) VALUES ("Inmovilización", "Prevención del movimiento, tanto intencional (p. ej., el paciente se ve obligado a llevar una escayola de París para permitir que la
consolidación natural tenga lugar) como no intencional (p. ej., después de una gripe).");
INSERT INTO keywords (name, description) VALUES ("Inmunidad celulomediada (ICM)", "Porción del sistema inmunitario responsable de la reacción frente al material extraño a través de células específicas de defensa (linfocitos
T, células killer, macrófagos y otras células sanguíneas blancas) más que por anticuerpos.");
INSERT INTO keywords (name, description) VALUES ("Inmunoglobulina", "Proteína que actúa como anticuerpo para ayudar al cuerpo a rechazar una enfermedad.
Hay cinco clases: IgG, IgA, IgD, IgM e IgE.");
INSERT INTO keywords (name, description) VALUES ("Institucionalización", "Efectos sociales y psicológicos adversos sobre los individuos que residen en instituciones, incluyendo hospitales de larga estancia para
personas con dificultades de aprendizaje o enfermedades mentales. Los efectos incluyen pasividad, dependencia y depresión. Tanto los
centros de acogida más peque ños como los grandes establecimientos pueden crear una institucionalización si son demasiado rígidos en
la atención de las necesidades de los residentes.");
INSERT INTO keywords (name, description) VALUES ("Instrumento de acuerdo", "Herramienta desarrollada por la AGREE collaboration que facilita la evaluación sistemática de la calidad de la directriz clínica. La
AGREE collaboration es un grupo internacional de investigadores y políticos cuyo objetivo es mejorar la calidad y efectividad de las
directrices de la práctica clínica. Ir a http://www.agreecollaboration.org");
INSERT INTO keywords (name, description) VALUES ("Instrumento médico", "Todos los productos, excepto los medicamentos, que se usan en asistencia sanitaria para el diagnóstico, prevención, monitorización o
tratamiento de enfermedades o incapacidad.");
INSERT INTO keywords (name, description) VALUES ("Insuficiencia activa", "Afecta a músculos que cruzan dos articulaciones. Ocurre cuando el músculo no puede contraerse al máximo en las dos articulaciones al
mismo tiempo. Un ejemplo serían los flexores de los dedos. Cuando se cierra el puño fuertemente se nota que la muñeca está en una
posición neutra o en extensión. Ahora, si pretendemos flexionar activamente la articulación de la muñeca mientras mantenemos los
dedos flexionados, observamos que nuestra fuerza de agarre disminuye considerablemente. Esto ocurre porque los flexores de la
muñeca y los dedos no son capaces de acortarse más y, por lo tanto, los dedos comienzan a extenderse o a perder fuerza de agarre.Insuficiencia activa
Compárese con la insuficiencia pasiva, que es la incapacidad de un músculo para estirarse al máximo en las dos articulaciones al mismo
tiempo.");
INSERT INTO keywords (name, description) VALUES ("Insuficiencia cardíaca congestiva (ICC)", "Alteración normalmente crónica, caracterizada por una congestión circulatoria causada por alteraciones cardíacas, especialmente infarto
de miocardio de los ventrículos. Puede ser aguda tras un infarto de miocardio del ventrículo izquierdo.");
INSERT INTO keywords (name, description) VALUES ("Insuficiencia pasiva", "Incapacidad de un músculo biarticular para estirarse completa y simultáneamente a través de las dos articulaciones; por ejemplo, los
músculos isquiotibiales no podrían estirarse a través de la cadera y la rodilla al mismo tiempo, o el gastrocnemio no permite una
dorsiflexión completa si la rodilla está completamente extendida.");
INSERT INTO keywords (name, description) VALUES ("Insuficiencia pasiva", "");
INSERT INTO keywords (name, description) VALUES ("Insuficiencia respiratoria", "Condición médica común que se produce cuando los pulmones son incapaces de oxigenar adecuadamente la sangre arterial
(insuficiencia respiratoria de tipo I) y/o incapaces de prevenir la retención excesiva de CO
2 (insuficiencia respiratoria de tipo II).
Aunque no se han definido los valores absolutos de PO 2 arterial y PCO 2 en los que se considera que existe insuficiencia respiratoria,
los valores generalmente citados son una PaO 2 de menos de 8,0 kPa y una PaCO 2 mayor de 6,0 kPa (West JB, 1977. Pulmonary gas
exchange. Int Rev Physiol 14: 83-106). Sin embargo, la importancia de cada valor es dependiente de un número de factores pertinentes
a la historia individual y a la variabilidad normal.
A pesar de que varios signos y síntomas físicos como falta de aliento, disnea, cianosis, agitación y empleo de músculos accesorios
suelen acompañar a la insuficiencia respiratoria, ninguno de ellos es diagnóstico de esta condición. El diagnóstico se alcanzará, por
tanto, mediante la medición de las presiones gaseosas arteriales.");
INSERT INTO keywords (name, description) VALUES ("Insuficiencia vertebrobasilar (IVB)", "Véase Test de la arteria vertebral.");
INSERT INTO keywords (name, description) VALUES ("Insulina", "Sustancia de importancia vital en el metabolismo de la glucosa. Los factores que afectan a su secreción y a sus acciones se resumen en
la siguiente figura.Integración sensorial
Organización significativa de la información sensorial recibida por el cuerpo para funcionar de forma global.");
INSERT INTO keywords (name, description) VALUES ("Inteligencia", "Puede evaluarse formalmente mediante tests estandarizados de inteligencia. Estos tests, aunque se utilizan aún de forma amplia, han sido
muy criticados en términos de objetividad, fiabilidad y validez. Existen diferentes modelos psicológicos de inteligencia, aunque
generalmente incluyen capacidad verbal, resolución de problemas e inteligencia práctica. Más recientemente ha emergido la noción de
inteligencia emocional, que se refiere a la capacidad para interpretar y usar las emociones en uno mismo y en otros. La inteligencia,
como concepto universal, nunca ha sido definida satisfactoriamente.");
INSERT INTO keywords (name, description) VALUES ("Interacción neuromuscular", "Término que relaciona la interrelación funcional de los componentes del movimiento: músculos y nervios.");
INSERT INTO keywords (name, description) VALUES ("Intercambio gaseoso", "Intercambio de gases metabólicos, oxígeno y dióxido de carbono, durante la respiración.");
INSERT INTO keywords (name, description) VALUES ("Interleucina", "Hormona química (citocina) secretada por y que afecta a muchas células diferentes en el sistema inmunitario.");
INSERT INTO keywords (name, description) VALUES ("Intervalo de confianza (IC)", "Rango de valores para un parámetro desconocido de población con una confianza fijada que contiene el valor verdadero. El intervalo
se calcula de los datos de muestra y generalmente va de un extremo al otro de la muestra estimada. El concepto de valor de confianza
hace referencia al hecho de que, si el método utilizado para calcular se repite muchas veces, esa proporción de intervalos contendrá el
valor verdadero (NICE, 2004).");
INSERT INTO keywords (name, description) VALUES ("Intervalo entre ráfagas", "Término electroterápico que se aplica al período durante el cual no circula corriente después de una ráfaga de impulsos o entre ráfagas
sucesivas (tren continuo de impulsos alternos). Véase Corriente alterna.");
INSERT INTO keywords (name, description) VALUES ("Intervalo interimpulso", "");
INSERT INTO keywords (name, description) VALUES ("Término electroterápico que se aplica al tiempo entre impulsos separados", "Véase Corriente pulsada.Una frecuencia de 50 Hz significa que hay 50 impulsos/s con intervalos iguales entre los impulsos (excepto en la corriente catchlike).
Para una corriente pulsada con una frecuencia de 50 Hz y una duración del impulso de 300 μs, los intervalos entre los impulsos son:");
INSERT INTO keywords (name, description) VALUES ("Intolerancia a la lactosa", "Trastorno caracterizado por calambres abdominales y diarrea después del consumo de alimentos que contienen lactosa (p. ej., leche,
helado, etc.).");
INSERT INTO keywords (name, description) VALUES ("Intraarticular", "Perteneciente o relativo al interior de la articulación. Por ejemplo, el ligamento cruzado anterior es intraarticular.");
INSERT INTO keywords (name, description) VALUES ("Intramuscular", "Perteneciente o relativo al interior del músculo. Se emplea a menudo en relación con la administración de inyecciones, pero también se
puede referir a un hematoma situado entre los músculos (hematoma intramuscular).");
INSERT INTO keywords (name, description) VALUES ("Intraneural", "Perteneciente o relativo al tejido neural.");
INSERT INTO keywords (name, description) VALUES ("Intubación", "Proceso de introducir un tubo para facilitar la respiración. Existen varios principios para llevarla a cabo, que aparecen listados en la
tabla que sigue, junto con sus indicaciones y ventajas.");
INSERT INTO keywords (name, description) VALUES ("Comparación entre espasticidad y rigidez", "");
INSERT INTO keywords (name, description) VALUES ("Lugar del tubo Indicaciones y ventajas", "");
INSERT INTO keywords (name, description) VALUES ("Tipo de tubo", "");
INSERT INTO keywords (name, description) VALUES ("Tubo endotraquea", "");
INSERT INTO keywords (name, description) VALUES ("Ora", "M ás comúnmente utilizado en adultos. Utilizados en situaciones de emergencia");
