INSERT INTO keywords (name, description) VALUES ("– Sin balón (pediátricos)", "");
INSERT INTO keywords (name, description) VALUES ("Nasa", "Se usa cuando la intubación oral es mposible o no es práctica (p. ej., traumatismo). Se utiliza comúnmente en pediatría");
