INSERT INTO keywords (name, description) VALUES ("– Permanente", "");
INSERT INTO keywords (name, description) VALUES ("– Con o sin balón", "Utilizada para la ventilación a largo plazo. M ayor comodidad, reduce la necesidad de sedación, facilita la nutrición norma – Fenestración para el habla
M antiene y protege la vía aérea cuando existe una anormalidad anatómica o neurológica – Uso a largo plazo");
INSERT INTO keywords (name, description) VALUES ("Intubación endotraqueal", "Procedimiento por el que un tubo se inserta a través de la boca hasta la tráquea.");
INSERT INTO keywords (name, description) VALUES ("Inversión", "Giro de la planta del pie hacia dentro.");
INSERT INTO keywords (name, description) VALUES ("– Cánulas internas", "");
INSERT INTO keywords (name, description) VALUES ("Plata", "");
INSERT INTO keywords (name, description) VALUES ("– Sin balón", "");
INSERT INTO keywords (name, description) VALUES ("– Uso permanente", "");
INSERT INTO keywords (name, description) VALUES ("– Lumen único", "");
INSERT INTO keywords (name, description) VALUES ("– Tubo de fonaciónInvestigación", "Proceso activo de indagación en un área o asignatura.");
INSERT INTO keywords (name, description) VALUES ("Investigación acción", "Forma de investigación social aplicada que implica la implementación sistemática y la revisión del cambio dentro de la situación que se
está investigando. Siguiendo la investigación de un tema, el propósito de acción es llevado a cabo y es después evaluado a través de
futuras investigaciones. La acción de investigación puede, por lo tanto, ser un proceso continuo de investigación y evaluación.");
INSERT INTO keywords (name, description) VALUES ("Investigación cualitativa", "Término de investigación. Investigación no basada en números, útil para valorar opiniones, actitudes, sensaciones, etc.
Observación. La investigación cualitativa está actualmente vigente en el cuidado de la salud, dado que se ha superado el paradigma
reduccionista según el cual los seres humanos se reducen a un conjunto de átomos que pueden medirse objetivamente. Ningún método
cualitativo o cuantitativo es mejor que otro; es simplemente una cuestión para saber cuál es la herramienta correcta para el trabajo
correcto.");
INSERT INTO keywords (name, description) VALUES ("Investigación cuantitativa", "Término de investigación; investigación que está basada en números.");
INSERT INTO keywords (name, description) VALUES ("Investigación en la práctica", "Es aquella en que los resultados validados de una investigación académica son usados para cambiar o modificar las prácticas aceptadas
existentes (p. ej., clínicas o educacionales).");
INSERT INTO keywords (name, description) VALUES ("Investigación primaria", "Estudio que genera datos originales en vez de analizar datos de estudios existentes (lo cual se denomina »investigación secundaria«).");
INSERT INTO keywords (name, description) VALUES ("Iones", "Partículas con carga eléctrica. Pueden ser positivos o negativos.");
INSERT INTO keywords (name, description) VALUES ("Iontoforesis", "Término electroterápico que se aplica al uso de corriente directa para impulsar iones terapéuticamente activos a través de la piel. La
medicación ionizada se coloca debajo del electrodo (cátodo o ánodo) con la misma carga. La repulsión entre las cargas del mismo
signo impulsa directamente a los iones, a través de la piel, hasta el área que está siendo tratada. Se utiliza con algunas anestesias locales,
esteroides, antiinflamatorios, etc.
Irritabilidad (v.Factores SIN)
Cantidad de actividad necesaria para empeorar la alteración, la extensión de la exacerbación y la duración de la respuesta. Forma parte
de la valoración del paciente junto con la irritabilidad y naturaleza. Estos tres factores constituyen lo que se denomina factores SIN, que
son una ayuda valiosa en la planificación de la frecuencia y duración del tratamiento. Esto tiene implicaciones en la valoración y el
tratamiento que se proporciona al paciente.");
INSERT INTO keywords (name, description) VALUES ("Isocinético", "Aplicado a la contracción de un músculo en la que se mantiene una velocidad angular constante de la articulación por medio de una
resistencia acomodada.");
INSERT INTO keywords (name, description) VALUES ("Isométrico", "Contracción de un músculo sin movimiento en la articulación, cuando no hay cambio en la longitud pero la tensión aumenta.");
INSERT INTO keywords (name, description) VALUES ("Isquemia", "Deficiencia de sangre en una parte del organismo; se da, por ejemplo, en la enfermedad cardíaca isquémica o ataque isquémico
transitorio (AIT).
ITRSAbreviatura médica común de infección del tracto respiratorio superior.");
INSERT INTO keywords (name, description) VALUES ("ITU", "Abreviatura médica común de infección del tracto urinario.
i.v.
Abreviatura médica común de intravenoso.J");
INSERT INTO keywords (name, description) VALUES ("Juego normativo", "Juego llevado a cabo por niños y dirigido por ellos, sin objetivos intrínsecos. Es espontáneo y placentero comparado con juegos
terapéuticos, los cuales son dirigidos por profesionales con objetivos específicos que se desea alcanzar.");
INSERT INTO keywords (name, description) VALUES ("Juego terapéutico", "Juego guiado por profesionales con objetivos específicos que se desean alcanzar.
Véase Juego normativo.K");
INSERT INTO keywords (name, description) VALUES ("Kilo-", "Prefijo que significa »mil«.");
INSERT INTO keywords (name, description) VALUES ("Kromayer", "Término electroterápico que se aplica a un tipo de lámpara de rayos ultravioleta (UV) de vapor de mercurio. El tubo de UV es enfriado
con agua para eliminar las radiaciones infrarrojas, por lo que hay un aplicador especial que se usa en contacto con la piel o en las
cavidades.L");
INSERT INTO keywords (name, description) VALUES ("Laberintitis", "Inflamación del oído interno y los canales semicirculares, es decir, las estructuras que normalmente mantienen el equilibrio y la
percepción de la posición del cuerpo. Esta inflamación causa náuseas, vómitos y vértigos, especialmente en el movimiento.");
INSERT INTO keywords (name, description) VALUES ("Labilidad emocional", "Alteración afectiva como resultado de una lesión cerebral que da lugar a que el paciente exhiba un comportamiento muy emocional, por
ejemplo con crisis de llanto, en situaciones en que tal comportamiento no es esperable. Por ejemplo, un paciente puede llorar cada vez
que ve a un determinado miembro de su familia. Esto puede hacer que el funcionamiento social normal sea difícil.");
INSERT INTO keywords (name, description) VALUES ("Lámina", "Lámina plana delgada o capa que normalmente constituye parte de una vértebra.
Lámina de las superficies de la cara supra y subyacente de la vértebra
Se encuentran por encima y por debajo de cada disco intervertebral; presentan un grosor de aproximadamente 1 mm y tienen varias
funciones: permiten la ósmosis de nutrientes entre el cuerpo vertebral y el disco, mantienen al disco en su posición y protegen a la
vértebra de la presión. Se puede producir la herniación o protrusión del núcleo en el cuerpo vertebral a través de la lámina del extremo,
pero a menudo ocurre de forma asintomática (Giles y cols., 1997).");
INSERT INTO keywords (name, description) VALUES ("Laminectomía", "Escisión del arco vertebral posterior.
Supresión quirúrgica de una porción de la lámina, que proporciona más espacio en el canal vertebral. Normalmente se lleva a cabo en
caso de herniación discal o estenosis del canal espinal.");
INSERT INTO keywords (name, description) VALUES ("Laparoscopio", "Tubo flexible de fibra óptica que permite la refracción interna de la luz para examinar estructuras visualmente. Se emplea en cirugía
laparoscópica.");
INSERT INTO keywords (name, description) VALUES ("Laparotomía", "Término general para cirugía abdominal.");
INSERT INTO keywords (name, description) VALUES ("Láser", "Término electroterápico (acrónimo de Light Amplification by Stimulated Emission of Radiation, es decir, amplificación de luz por
emisión estimulada de radiación). Es un tipo de radiación electromagnética. La longitud de onda es de 780-904 nm (GaAlAs láser
diodo) o 904 nm (GaAs láser diodo) o 623,8 nm (láser de gas HeNe). Tres propiedades distinguen el láser de la luz visible o de la
radiación infrarroja: el láser es monocromático (una sola longitud de onda), colimado (divergencia mínima de rayo) y coherente (en
fase). La profundidad de penetración varía desde aproximadamente 3 o 4 mm (GaA1As) hasta 2 mm (HeNe). Se usa clínicamente en
la curación de heridas y control del dolor. Las dosis se miden como densidad de energía, es decir, en J/cm 2 . Su utilidad clínica todavía
se desconoce. El riesgo es principalmente ocular y depende de la clase de láser, de manera que, si la longitud de onda es de 3B, 4 o 5
tanto el paciente como el terapeuta deben utilizar gafas protectoras.");
INSERT INTO keywords (name, description) VALUES ("Lateral", "Término anatómico que indica alejamiento de la línea media.");
INSERT INTO keywords (name, description) VALUES ("Latigazo cervical", "Lesión de la columna cervical resultado de la aceleración o deceleración rápida. Esta patología puede ser compleja y su pronóstico
extraordinariamente variable. En el marco médico legal, el latigazo ha llegado a ser un tema de gran debate.Latigazo cervical");
INSERT INTO keywords (name, description) VALUES ("LCM", "Abreviatura médica común de ligamento colateral medial. Normalmente se refiere al ligamento colateral de la articulación de la rodilla,
pero no hay que olvidar que también existe el colateral medial de las articulaciones del codo y el tobillo.");
INSERT INTO keywords (name, description) VALUES ("LDL", "Abreviatura médica común de lipoproteínas de baja densidad.");
INSERT INTO keywords (name, description) VALUES ("LES", "Abreviatura médica común de lupus eritematoso sistémico.");
INSERT INTO keywords (name, description) VALUES ("Lesión adquirida del cerebro por contragolpe", "Se produce cuando el tejido cerebral se sigue moviendo cuando el cráneo se ha parado, dando lugar a una lesión en el lado contrario a
aquel donde es aplicada la fuerza. Así, un golpe en el lado derecho de la cabeza dará lugar a una lesión adquirida en el lado izquierdo
del cerebro.");
INSERT INTO keywords (name, description) VALUES ("Lesión de Bankart", "Deformidad que puede ocurrir después de dislocaciones anteriores del hombro. Produce un déficit en los mecanismos de estabilización
anteriores del hombro. Consiste en el arrancamiento de los ligamentos glenohumerales inferiores, el rodete y la unión capsular de la
glenoide.");
INSERT INTO keywords (name, description) VALUES ("Lesión de la columna vertebral", "Lesión de la médula espinal que da lugar a déficits neurológicos.");
INSERT INTO keywords (name, description) VALUES ("Lesión incompleta", "Lesión en la que existe una conservación parcial de la función sensitiva y/o motora, se localiza por debajo del nivel neurológico e incluye
al segmento sacro inferior.
Observación clínica. Con el avance de la intervención aguda, más pacientes con lesiones vertebrales presentan lesiones incompletas.Es importante su detección, ya que la rehabilitación tiene un enfoque diferente en las lesiones vertebrales incompletas y las completas.");
INSERT INTO keywords (name, description) VALUES ("Lesión o deformidad de Hill-Sachs", "Se produce después de una luxación anterior del hombro; la cabeza del húmero puede sufrir una fractura por compresión por el
contacto con la glenoide y su rodete. La depresión consecuente de la cabeza humeral se conoce como lesión de Hill-Sachs.");
INSERT INTO keywords (name, description) VALUES ("Lesión SLAP", "Patología de la articulación del hombro. Hace referencia a un desgarro superior del rodete glenoideo en dirección anteroposterior. Las
siglas SLAP hacen referencia a superior labrum anterior posterior.");
INSERT INTO keywords (name, description) VALUES ("Lesiones de la fosa posterior", "Término relativo al daño o lesión que ocurre en la región de la fosa posterior del cerebro.
Observación clínica Tras lesiones en esta área se puede ver comúnmente ataxia.");
INSERT INTO keywords (name, description) VALUES ("Leucemia", "Enfermedad caracterizada por un incremento anormal del número de leucocitos en los tejidos con o sin el correspondiente aumento de
éstos en la circulación sanguínea. Se clasifican de acuerdo con el tipo de leucocitos.");
INSERT INTO keywords (name, description) VALUES ("Levodopa", "Fármaco que atraviesa la barrera hematoencefálica y se emplea en el tratamiento de la enfermedad de Parkinson.");
INSERT INTO keywords (name, description) VALUES ("Ley de asistencia sanitaria invertida", "Esta ley afirma que aquellos que tienen el riesgo más grande de adquirir una enfermedad o dolencia son los que de hecho");
INSERT INTO keywords (name, description) VALUES ("tienen una", "menor probabilidad de recibir servicios médicos y sociales. Esto se debe a una amplia variedad de factores que hacen referencia a las
desigualdades sociales y la disponibilidad de servicios.");
INSERT INTO keywords (name, description) VALUES ("Ley de Ohms", "Término electroterápico:
donde V es el voltaje (voltios) en el circuito, I es la intensidad (amperios) y R es la resistencia (ohmios).
Utilizado para calcular cambios en los circuitos con corriente continua. Para corriente alterna, consúltese un libro de texto de ingeniería
eléctrica.");
INSERT INTO keywords (name, description) VALUES ("Ley de Van't Hoff", "Reacción química que se acelera por un aumento en la temperatura.
Observación clínica El cuerpo desarrolla fiebre para acelerar los procesos fisiológicos implicados. Este concepto es también de
importancia clave para los fisioterapeutas, particularmente cuando tratan con modalidades electroterápicas.");
INSERT INTO keywords (name, description) VALUES ("Ley de Wolf", "Cuando los huesos se someten a estrés cambiarán su arquitectura interna como corresponda.
Dicho de un modo sencillo, un hueso gana masa cuando se necesita y la absorbe cuando no se utiliza.
Observación clínica Esto tiene una gran importancia para los fisioterapeutas, pues una persona que esté encamada un tiempo
prolongado empezará a perder rápidamente masa ósea; en cambio, una persona que haga jogging o levantamiento de pesas empezará
a depositar hueso adicional: el hueso está vivo.");
INSERT INTO keywords (name, description) VALUES ("Leyes de Newton", "");
INSERT INTO keywords (name, description) VALUES ("Primera ley de Newton", "Si un objeto está inmóvil permanecerá inmóvil; si se está moviendo a velocidad constante en línea recta, continuará haciéndolo mientras
no actúe una fuerza externa sobre él. En otras palabras, si un objeto no está experimentando la acción de una fuerza externa continuará
moviéndose o no se moverá en absoluto.
Esta ley expresa el concepto de inercia. La inercia de un cuerpo puede describirse como la resistencia a empezar un movimiento o a
parar un movimiento una vez empezado.Segunda ley de Newton
La tasa de cambio de la velocidad de un cuerpo es directamente proporcional a la acción de la fuerza externa aplicada sobre él y
ocurre en la misma dirección de la fuerza. Por tanto, dicha fuerza puede causar la aceleración o desaceleración de un objeto. La
aceleración es normalmente definida como positiva y la desaceleración como negativa.");
INSERT INTO keywords (name, description) VALUES ("Aceleración de un objeto con una Fuerza constante", "");
INSERT INTO keywords (name, description) VALUES ("Tercera ley de Newton", "Si la caja mostrada en el siguiente diagrama ejerce una fuerza sobre la superficie de la mesa (acción), la mesa ejercerá una fuerza igual
en sentido opuesto sobre la caja (reacción). Esto no quiere decir que las fuerzas se anulen entre sí, ya que actúan sobre objetos
diferentes. El siguiente diagrama muestra las fuerzas que actúan sobre un objeto inmóvil en el suelo.
La acción de una fuerza sobre el suelo recibe una fuerza de reacción igual en sentido opuesto, que se conoce como fuerza de reacción
del suelo (Richards, 2003).");
INSERT INTO keywords (name, description) VALUES ("Liberación lateral", "División quirúrgica del retináculo patelar lateral desde el tendón rotuliano hasta las fibras musculares del vasto lateral. Se emplea
normalmente como un tratamiento de la disfunción patelofemoral, una vez que las medidas conservadoras han fallado.Libro de conferencias
Compilación de trabajos presentados en una conferencia.");
INSERT INTO keywords (name, description) VALUES ("Ligamento anular", "Ligamento en forma de cinta o banda semicircular que existe en diferentes articulaciones y alrededor de ellas.
El ligamento anular del radio tiene la forma de una banda que rodea una parte del perímetro articular de la cabeza del radio,
insertándose en los extremos de la escotadura sigmoidea menor, y manteniendo la cabeza del radio en su sitio.");
INSERT INTO keywords (name, description) VALUES ("Ligamento coronario", "Ligamento que une el cuerno anterior del menisco interno con el platillo tibial.");
INSERT INTO keywords (name, description) VALUES ("Superficies articulares de la articulación radiocubital superior expuesta", "");
INSERT INTO keywords (name, description) VALUES ("Ligamento cruzado anterior (LCA)", "Uno de los principales ligamentos estabilizadores de la rodilla. Descansa en el interior de la articulación y desempeña un importante
papel, proporcionando propiocepción. Se inserta en la porción anterior de la meseta tibial, se extiende hacia arriba y hacia atrás, para
insertarse finalmente en el aspecto medial del cóndilo femoral lateral. Suele verse dañado durante la práctica de deportes que implican
giros y deceleraciones rápidas. Los ligamentos cruzados desempeñan un papel muy importante en la propiocepción, que es
imprescindible para el control de la rodilla.");
INSERT INTO keywords (name, description) VALUES ("Ligamento cruzado posterior (LCP)", "Es uno de los dos principales ligamentos estabilizadores y propioceptivos de la rodilla. El LCP impide principalmente el movimiento
posterior de la tibia respecto al fémur pero tiene otras funciones, incluyendo la propiocepción.
Test para una rotura: véase Test del cajón posterior (AP).
Véase LCA para observar la representación de los ligamentos cruzados anterior y posterior.");
INSERT INTO keywords (name, description) VALUES ("Ligamento deltoideo", "Nombre alternativo para el ligamento lateral interno de la articulación del tobillo; es de forma triangular, de ahí su nombre (la letra griega
delta mayúscula es un triángulo [Δ]). Es mucho más resistente que el ligamento lateral externo; de hecho, es tan resistente que es común
que en las lesiones de eversión se produzcan fracturas de la cabeza del maléolo en vez de la rotura del propio ligamento.Partes del ligamento deltoideo");
INSERT INTO keywords (name, description) VALUES ("Ligamento talofibular anterior (LTFA)", "El más anterior de los tres ligamentos laterales externos del tobillo y el más afectado tras movimientos lesivos de inversión.");
INSERT INTO keywords (name, description) VALUES ("Ligamentos deltoideos (A) y lateral externo (B) del tobillo", "Los tres ligamentos del complejo son:
1. Ligamento talofibular posterior o ligamento peroneoastragalino posterior.
2. Ligamento calcaneofibular o calcaneoperoneo.
3. Ligamento talofibular anterior o peroneoastragalino anterior.");
INSERT INTO keywords (name, description) VALUES ("Ligamentos alares", "Ligamentos de la columna cervical superior que se extienden desde cada lado del diente del axis hasta el cóndilo occipital medial. Se
puede romper después de ciertas alteraciones, como la artritis reumatoide.");
INSERT INTO keywords (name, description) VALUES ("Límites de estabilidad", "Trayecto dentro del cual una persona puede conseguir el movimiento más amplio en cualquier dirección sin perder el equilibrio o realizar
ajustes posturales, es decir, stepping.Línea alba
Banda que discurre verticalmente a lo largo de toda la longitud de la pared abdominal y que recibe las inserciones de los músculos
abdominales oblicuos y transverso.");
INSERT INTO keywords (name, description) VALUES ("Línea de Nelaton", "Línea que va desde la espina ilíaca anterosuperior hasta la tuberosidad isquiática; el trocánter mayor debería estar en esta línea, pero en
casos de fractura de cadera o del cuello femoral, pasa por encima de ella.");
INSERT INTO keywords (name, description) VALUES ("Línea media", "Línea imaginaria que atraviesa el centro del cuerpo y, por lo tanto, proporciona un punto de referencia para la valoración del
alineamiento rotatorio y anteroposterior de las partes individuales del cuerpo, es decir, cabeza, cintura escapular y tronco.");
INSERT INTO keywords (name, description) VALUES ("Línea Z", "En el músculo, son las estructuras en las que se insertan los filamentos. Las líneas Z definen los límites del sarcómero.");
INSERT INTO keywords (name, description) VALUES ("Linfedema", "Tumefacción progresiva y crónica causada por un bajo rendimiento del sistema linfático.");
INSERT INTO keywords (name, description) VALUES ("Linfocito T", "Linfocitos formados por el timo.");
INSERT INTO keywords (name, description) VALUES ("Linfomas no hodgkinianos (LNH)", "Grupo de linfomas que difieren de forma importante de la enfermedad de Hodgkin.");
INSERT INTO keywords (name, description) VALUES ("Líquido cefalorraquídeo (LCR)", "Fluido producido por el plexo coroideo en el cerebro, que fluye a través del sistema ventricular dentro del espacio subaracnoideo.
Cuando se produce demasiado fluido o cuando hay un bloqueo del flujo del fluido, puede tener lugar una hidrocefalia.
Véase Punción lumbar.");
INSERT INTO keywords (name, description) VALUES ("Líquido sinovial", "Líquido producido por la membrana sinovial que está presente en pequeñas cantidades en todas las articulaciones sinoviales.
Un aumento del volumen del líquido sinovial suele tener lugar después de un traumatismo, presencia de infección, cuerpos desprendidos
o como respuesta a otra patología. Una gran cantidad de líquido sinovial en una articulación se conoce como efusión. El líquido sinovial
es un líquido transparente o amarillento, que es tixotrópico. Esta cualidad inusual significa que, cuanto más rápido se mueva una
articulación, menos fluido se vuelve su líquido sinovial. El líquido sinovial contiene nutrientes y la glucoproteína hialurónica.
Baña y nutre la articulación, y también desempeña un papel muy importante en la absorción de las cargas de la articulación. Los
estudios muestran que el 90% de esta carga puede ser transmitida por la presión hidrostática dentro del fluido sinovial entre las
superficies articulares. Esto protege la matriz del cartílago de presiones catastróficas (Makirowski y cols., 1994).");
INSERT INTO keywords (name, description) VALUES ("Lisis", "Proceso de destrucción de las células.");
INSERT INTO keywords (name, description) VALUES ("Literatura gris", "Informes que no son publicados o tienen una distribución limitada y no están incluidos en los sistemas de recuperación de bibliografía
común.");
INSERT INTO keywords (name, description) VALUES ("LLE", "Abreviatura médica común de ligamento lateral externo.");
INSERT INTO keywords (name, description) VALUES ("Lobectomía", "Extirpación de un lóbulo; normalmente se refiere al pulmón o al cerebro.Lóbulo frontal
Lóbulo más anterior del encéfalo.");
INSERT INTO keywords (name, description) VALUES ("Lóbulos", "Divisiones de los pulmones. El pulmón derecho consta de tres (superior, medio e inferior) y el izquierdo de dos (el superior, que tiene
una subdivisión llamada el segmento singular, y el inferior).
Tráquea y distribución de los bronquios principales y segmentarios. Segmentos bronquiopulmonares: 1, apical; 2, posterior; 3, anterior; 4, lateral; 5, medial; 6, basal
apical; 7, basal medial; 8, basal anterior; 9, basal lateral; 10, basal posterior; 11, superior; 12, inferior.");
INSERT INTO keywords (name, description) VALUES ("Locus de control", "Término de la teoría psicológica que hace referencia al sentido generalizado de las personas de responsabilidad y control sobre sus
vidas. Las personas que tienen un locus de control interno se sienten responsables de sus vidas y esperan que su comportamiento tenga
algún efecto sobre los acontecimientos. Las personas con
locus de control externo tienen más tendencia a creer que los
acontecimientos de la vida ocurren gracias al destino o al azar y no por sus propias acciones. Las personas pueden tener un locus de
control interno o externo en diferentes esferas de su vida. El locus de control puede medirse mediante un cuestionario estandarizado.");
INSERT INTO keywords (name, description) VALUES ("Longitud de la pierna", "Medición desde la espina ilíaca anterosuperior hasta la punta del maléolo medial; suele ser imprecisa en presencia de rotación pélvica o
asimetría. Las discrepancias en la longitud de las piernas no serán significativas si son de menos de 6 mm, y muchos pacientes
asintomáticos tienen una diferencia de hasta 12 mm.Longitud verdadera y aparente de la pierna
Con la persona de pie o tumbada con los pies separados 45 cm:
• Longitud verdadera de la pierna. Medida desde la EIAS hasta el maléolo medial.
• Longitud aparente de la pierna. Medida desde el ombligo hasta el maléolo medial.");
INSERT INTO keywords (name, description) VALUES ("Lordosis", "Curvatura de la columna que causa un ahuecamiento. La lordosis normal se ve en la columna lumbar, aunque existen variaciones.
Véase Cifosis.");
INSERT INTO keywords (name, description) VALUES ("Lupus", "Enfermedad sistémica autoinmune. Los individuos con
lupus producen anticuerpos contra sus tejidos corporales. La inflamaciónresultante puede causar daño renal, pericarditis, vasculitis y artritis.");
INSERT INTO keywords (name, description) VALUES ("Luxación congénita de la cadera", "Defecto congénito ortopédico en el que la cabeza del fémur no se articula con el acetábulo porque es anormalmente plana.
Observación clínica Muchas personas con luxación congénita de la cadera acaban necesitando una prótesis de cadera cuando son
adultos.M");
INSERT INTO keywords (name, description) VALUES ("Malformación de Arnold-Chiari", "Defecto del tubo neural en el cual se produce una hernia del tallo del cerebro y parte del cerebelo a través del agujero de la base del
cráneo conocido como foramen magnum.");
INSERT INTO keywords (name, description) VALUES ("Malformaciones arteriovenosas (MAV)", "Anormalidades del desarrollo de la vascularización. Pueden ser asintomáticas. Cuando tienen lugar en el cerebro o en la médula espinal
pueden causar déficits neurológicos y, si producen escapes o revientan, pueden dar lugar a una hemorragia subaracnoidea.");
INSERT INTO keywords (name, description) VALUES ("Maligno", "Término que describe un tumor de crecimiento incontrolado y progresivo. Compárese con benigno, que se aplica a tumores no
peligrosos para la salud ni progresivos.");
INSERT INTO keywords (name, description) VALUES ("Mamografía", "Test de rayos X que produce una imagen del tejido pectoral. La mamografía se usa para visualizar estructuras normales y anormales
dentro del pecho.");
INSERT INTO keywords (name, description) VALUES ("Manejo", "Término terapéutico común utilizado para describir el movimiento asistido y el contacto físico con el paciente.");
INSERT INTO keywords (name, description) VALUES ("Manguito de los rotadores", "Formado por cuatro músculos: subescapular, supraespinoso, infraespinoso y redondo menor. Sus tendones convergen en su trayectoria
entre las inserciones en escápula y húmero para formar un »manguito« sobre la articulación del hombro. Una de sus funciones
principales es controlar la rotación del hombro. Se pueden considerar como ligamentos dinámicos, cambiando continuamente su tensión
relativa para mantener la estabilidad de la cabeza del húmero.
Acción de los músculos del manguito de los rotadores en la estabilización de la articulación del hombro");
INSERT INTO keywords (name, description) VALUES ("Maniobra de Epley", "Esta maniobra, que también se conoce como maniobra de recolocación de la partícula (mrp) o el procedimiento de recolocación del
canal (prc), consta de un ciclo de 5 posiciones para el tratamiento del VPPB (vértigo posicional paroxísmico benigno). El ciclo de
maniobras consiste en asegurarse de que todos los productos de desecho de los canales semicirculares se transfieren a la parte más
dependiente del canal.");
INSERT INTO keywords (name, description) VALUES ("Maniobra de Hallpike", "Test diagnóstico para vértigo posicional paroxístico benigno, si el nistagmo de los ojos es positivo y se provoca el vértigo. La cabeza y
el cuello se rotan 45° y se extienden luego hasta 30°.
Observación clínica Debe tenerse especial cuidado a la hora de excluir una patología en el cuello antes de llevar a cabo este
procedimiento específico.
ManipulaciónMaitland (2001) define el término manipulación como cualquier tipo de movimiento pasivo o, más específicamente, como un tirón
(thrust) de escasa amplitud realizado con velocidad, sin contar con el control del paciente.");
INSERT INTO keywords (name, description) VALUES ("Manipulación bajo anestesia", "Si una persona tiene limitación de movimiento debido a adherencias u otras causas y no puede ser corregida por medidas fisioterápicas
convencionales, puede ser apropiado inducir una ligera anestesia a la persona y luego mover enérgicamente la articulación para
recuperar el movimiento. Suele ser necesario posteriormente a cirugías de reemplazo de la rodilla o a hombros congelados. El papel del
fisioterapeuta es fundamental después de una MBA para mantener el rango de movimiento que ha conseguido el cirujano.");
INSERT INTO keywords (name, description) VALUES ("Manitol", "Fármaco administrado para reducir la inflamación cerebral y reducir la presión intracraneal. Se suele usar temporalmente para
interrumpir la barrera hematoencefálica antes de algunas formas de quimioterapia.");
INSERT INTO keywords (name, description) VALUES ("Mapa corporal", "El mapa corporal es una herramienta útil que ayuda a visualizar e informar de los problemas o síntomas de una persona. Véase el dibujo
para un ejemplo típico.");
INSERT INTO keywords (name, description) VALUES ("Marcapasos", "Estimulador implantado para el control de la función cardíaca. El rendimiento puede alterarse en presencia de una radiación de
radiofrecuencia de alta intensidad, así como diatermia de onda corta (DOC) o microondas.
Véase Diatermia de onda corta (DOC) y Microondas.
Asegurarse de que los pacientes con algún tipo de marcapasos no estén dentro de un radio de 3-5 m de estos equipos si están en
funcionamiento.");
INSERT INTO keywords (name, description) VALUES ("Marcha", "Patrón de locomoción.
Típicamente se divide en las siguientes etapas:
• Respuesta a la carga. Postura inicial de doble apoyo.
• Posición media. Desde el momento en que el miembro opuesto abandona el suelo hasta que el peso del cuerpo se alinea sobre el
antepié.
• Posición final. Desde el momento en que el talón se eleva hasta que el otro miembro tiene contacto con el suelo.
• Preoscilación. Desde el momento de contacto inicial con el miembro contralateral hasta la retirada ipsolateral de los dedos.
• Oscilación inicial. Desde la retirada de los dedos hasta que el miembro oscilante se opone al miembro fijo.
• Oscilación media. Desde el momento en que el pie oscilante se opone al miembro fijo cuando la tibia está vertical.
• Oscilación terminal. Desde el momento en que la tibia está vertical hasta el contacto inicial.
• Despegue. Momento en que se produce una flexión plantar del tobillo.Marcha de Trendelenburg
Alteración intrínseca de los abductores de la cadera debido tanto a debilidad como a una inhibición de la función. Como resultado, los
abductores de la cadera son incapaces de estabilizarla, ya que el peso corporal se transfiere al lado afectado, dando lugar a una caída
de la pelvis o inclinación de ésta hacia el lado opuesto.");
INSERT INTO keywords (name, description) VALUES ("Marcha festinante", "Marcha caracterizada por el arrastre de los pies. El centro de gravedad permanece centrado con predominancia del apoyo bipodal,
típicamente exhibido por una persona con la enfermedad de Parkinson. Los pacientes se inclinan demasiado hacia delante y parecen
estar buscando su propio centro de gravedad.");
INSERT INTO keywords (name, description) VALUES ("Máscara PEP", "Máscara de presión espiratoria positiva. Es una máscara usada para generar una presión espiratoria positiva para facilitar la limpieza de
las secreciones pulmonares, como demostraron por primera vez Falk y cols. (1984).");
INSERT INTO keywords (name, description) VALUES ("Mastectomía", "Extirpación quirúrgica de todo el pecho, normalmente para tratar enfermedades como el cáncer de mama.");
INSERT INTO keywords (name, description) VALUES ("MCM", "Abreviatura médica común de movilización con movimiento.");
INSERT INTO keywords (name, description) VALUES ("Mecanorreceptor", "Receptor que responde a la presión mecánica o distorsión; por ejemplo, los receptores del tacto en la piel.");
INSERT INTO keywords (name, description) VALUES ("Meconio", "Materia de color verde oscuro que aparece en el intestino al nacimiento; es la primera sustancia que evacua el recién nacido.");
INSERT INTO keywords (name, description) VALUES ("Media", "Término de investigación que significa promedio numérico en un grupo de valores.");
INSERT INTO keywords (name, description) VALUES ("Medial", "Término anatómico que se aplica a estructuras cercanas a la línea media.");
INSERT INTO keywords (name, description) VALUES ("Mediana", "Término de investigación; cuando los valores son ordenados según la magnitud, la mediana es el valor medio en caso de un número
impar de valores, y el promedio de dos valores medios en el caso de un número par de valores.");
INSERT INTO keywords (name, description) VALUES ("Mediastino", "Espacio entre los dos sacos pleurales en el tórax.");
INSERT INTO keywords (name, description) VALUES ("Medicalización", "Predominio u ortodoxia de un grupo de ideas, conocido como modelo biomédico, que conceptualiza la salud y la enfermedad, así
como todo un abanico de fenómenos sociales como pueden ser la incapacidad, el duelo o la homosexualidad. Procesos que una vez
fueron considerados parte ordinaria de la vida, como el parto, han pasado a medicalizarse y a ser controlados por profesionales de la
salud.Medicina alternativa
Tratamiento y práctica médica que se encuentra fuera de los servicios médicos y paramédicos ortodoxos. Las prácticas médicas
alternativas pueden, sin embargo, pasar con el tiempo a ser ortodoxas; por ejemplo, los fisioterapeutas practican ahora la acupuntura
dentro del National Health Service (NHS) y los médicos generales pueden proporcionar servicios de asesoramiento. La medicina
alternativa puede, por tanto, ser definida como la práctica que no es respaldada por la medicina ortodoxa.");
INSERT INTO keywords (name, description) VALUES ("Medicina basada en la evidencia/práctica basada en la evidencia (MBE/PBE)", "Uso consciente, explícito y juicioso de la mejor evidencia actual en la toma de decisiones sobre el cuidado de pacientes. La práctica de
la medicina basada en la evidencia implica la integración de la destreza clínica individual con la evidencia clínica externa más fiable
procedente de la investigación. La destreza clínica individual es la capacidad y opinión que los médicos individuales adquieren a través
de la experiencia y la práctica clínica (Sackett y cols., 1996). Este método ha sido criticado por no atender a otros factores implicados
en el desarrollo de la práctica, incluyendo los recursos financiaros y las opiniones basadas en la experiencia, y por ignorar facetas
importantes de la práctica de difícil medición.");
INSERT INTO keywords (name, description) VALUES ("Medicina centrada en el paciente", "Enfoque de la medicina en el que el punto de vista, opiniones y valores de los pacientes y clientes son tratados como centrales. Los
profesionales renuncian al control, con lo que el poder dentro de la relación puede ser compartido.");
INSERT INTO keywords (name, description) VALUES ("Medicina preventiva", "Intervenciones diseñadas para prevenir que se produzca una enfermedad o detectar enfermedades en fase temprana. El cribado
genético y las mamografías rutinarias son ejemplos de medicina preventiva.");
INSERT INTO keywords (name, description) VALUES ("Medicines and healthcare products regulatory agency (MHRA)", "La Executive Agency of the Department of Health (en UK) protege y promociona la salud pública y la seguridad del paciente
asegurando que los productos de asistencia sanitaria y equipamiento médico reúnan criterios apropiados de seguridad, calidad,
ejecución y efectividad, y sean usados con prudencia.");
INSERT INTO keywords (name, description) VALUES ("Medida de la calidad de vida", "Medida que está normalmente basada en el auto-estudio y determina la calidad definida por la medida de vida de las personas. Una
medida extensa normalmente cubre el campo físico, mental (emocional y cognitivo), social y el papel funcional además de su propio
bienestar.");
INSERT INTO keywords (name, description) VALUES ("Medida de la independencia funcional (MIF)", "Medida de resultados ampliamente utilizada en el tratamiento de pacientes neurológicos. Existe una versión pediátrica denominada
WeeFIM. Se han desarrollado más aspectos que conducen a la valoración de la MVF, que a menudo es preferida por equipos que
tratan a pacientes neurológicos, ya que comprende aspectos cognitivos y comunicativos.Medida de los resultados
Test o escala dirigida a documentar la información sobre atributo(s) particulares de interés. Antes de usarlo, debería evaluarse para
comprobar el grado de validez para el uso previsto y determinar si puede emplearse fiablemente, es suficientemente sensible, resulta
aceptable para el uso que pretende dársele, puede utilizarse en el marco previsto, y sus resultados son interpretables y suficientemente
familiares para el usuario.
El uso de las medidas de resultados (v. Escala de valoración motora y Escala de Ashworth) favorece la estandarización de medidas
objetivas y la evaluación de la práctica. Los resultados de las medidas deben tener unas cualidades clave:
• Fiabilidad.
• Validez.
• Sensibilidad.");
INSERT INTO keywords (name, description) VALUES ("Medida de utilidad", "Recurso para determinar la solidez de la preferencia de un individuo por un estado de salud específico en relación con estados de salud
alternativos. Una medida utilitaria designa valores numéricos en una escala de 0 (muerte) a 1 (salud óptima o »perfecta«). Dado que hay
estados de salud que pueden ser considerados peores que la muerte, existen valores negativos.");
INSERT INTO keywords (name, description) VALUES ("Medida de valoración funcional (MVF)", "Es empleada principalmente por equipos que trabajan en rehabilitación. Se desarrolla en base a la MIF (medida de independencia
funcional), e incluye aspectos cognitivos y del habla, por lo que es particularmente útil para pacientes neurológicos. Cada ítem tiene siete
niveles. Con la práctica y usando los manuales de algoritmos de decisión, tiene buena fiabilidad y por ello es muy utilizado, tanto
clínicamente como para estudios de investigación.");
INSERT INTO keywords (name, description) VALUES ("MEDLARS (medical literature analysis retrieval system)", "Ordenador en el cual se encuentran Medline y AIDS Line en la National Library of Medicine (Biblioteca nacional de medicina del
Reino Unido).");
INSERT INTO keywords (name, description) VALUES ("Medline", "Base de datos electrónica que contiene información relacionada con la medicina y la asistencia sanitaria.");
INSERT INTO keywords (name, description) VALUES ("Melanoma maligno", "Tumor que se forma a partir de las células productoras de pigmento (melanocitos) de las capas más profundas de la piel. El melanoma
es la causa más importante de muerte atribuida a lesiones de la piel.");
INSERT INTO keywords (name, description) VALUES ("Memoria", "Función mental que almacena sensaciones y experiencias aprendidas para recordar.");
INSERT INTO keywords (name, description) VALUES ("Memoria a corto plazo", "Capacidad de retener y recordar información y experiencias de hechos recientes.
Observación clínica Si está afectada, por ejemplo después de un ictus o un traumatismo craneoencefálico, ello hará que sea más
difícil el reaprendizaje de las tareas, siendo en este caso de gran importancia la vinculación con el terapeuta ocupacional o el psicólogo
para desarrollar estrategias compensatorias.");
INSERT INTO keywords (name, description) VALUES ("Memoria a largo plazo", "Información retenida de forma relativamente permanente.");
INSERT INTO keywords (name, description) VALUES ("Meningioma", "Crecimiento lento de tumores intracraneales primarios que se originan en las granulaciones aracnoideas. Son más comunes en mujeres
de entre 40 y 60 años. Normalmente son benignos pero existen formas malignas.");
INSERT INTO keywords (name, description) VALUES ("Meningitis", "Inflamación aguda de las meninges, esto es, de las membranas que recubren el cerebro y la médula espinal. Normalmente se debe a unainfección que puede ser vírica o bacteriana. Los signos clásicos son fiebre, dolor de cabeza y rigidez del cuello. También puede causar
fotofobia y erupción o sarpullido en la piel. Va a menudo precedida por una infección del tracto respiratorio superior.");
INSERT INTO keywords (name, description) VALUES ("Meningitis meningocócica", "Enfermedad infecciosa aguda que afecta a niños y adultos jóvenes, y que cursa con dolor de cabeza, vómitos, convulsiones, fotofobia,
cuello rígido, estreñimiento, sensibilidad cutánea y sarpullido.");
INSERT INTO keywords (name, description) VALUES ("Meningocele", "Tipo de lesión observada en la espina bífida; otra forma es el mielomeningocele.
Véase Espina bífida y Mielomeningocele.
Tipos de lesión espinal en la espina bífida. (A) M eningocele: no hay tejido neural fuera del canal vertebral. (B) M ielomeningocele: el tejido neural y las raíces nerviosas
pueden estar fuera del canal vertebral. Puede existir tejido graso o una espuela ósea (C) Raquisquisis: no hay saco y el tejido neural descansa abierto sobre la superficie
de la placa aplastada.");
INSERT INTO keywords (name, description) VALUES ("Meniscectomía", "Extirpación completa o parcial de una parte desgarrada del menisco (o de su totalidad). Normalmente se realiza mediante artroscopia.");
INSERT INTO keywords (name, description) VALUES ("Menisco", "Estructuras fibrocartilaginosas cuya función es incrementar la congruencia articular de las facetas articulares, actuando como
amortiguadores, contribuyendo a la lubricación articular y proporcionando estabilidad. Se lesionan con frecuencia, particularmente en la
rodilla, cuando existen fuerzas rotatorias.");
INSERT INTO keywords (name, description) VALUES ("Menopausia", "Cese de la menstruación. Tiene implicaciones significativas para la salud de la mujer y su calidad de vida y es, por tanto, de gran
relevancia para el fisioterapeuta.Los cambios metabólicos y bioquímicos que siguen a la menopausia pueden causar síntomas angustiantes que afectan adversamente a la
calidad de vida (Brook, 2003).");
INSERT INTO keywords (name, description) VALUES ("Meralgia parestésica", "Neuropatía de compresión del nervio cutáneo lateral del muslo.");
INSERT INTO keywords (name, description) VALUES ("Mercado interno", "Estimulación de las condiciones del mercado dentro de los servicios del estado, como el NHS y los servicios sociales. Existe una
separación entre el comprador y el que proporciona los servicios (separación comprador-vendedor). Los servicios se compran en
nombre de pacientes y clientes a través de directores asistenciales (normalmente trabajadores sociales) y provienen de una variedad de
proveedores dentro de los servicios privados, voluntarios y reglamentarios.
Véase División comprador/proveedor y Economía mixta de bienestar.");
INSERT INTO keywords (name, description) VALUES ("MESH", "Siglas de medical subject heading. Término usado por la National Library of Medicine del Reino Unido.");
INSERT INTO keywords (name, description) VALUES ("Mesotelioma", "Enfermedad pleural poco frecuente, asociada con exposición previa al amianto, que no responde a ninguna intervención conocida.");
INSERT INTO keywords (name, description) VALUES ("Metaanálisis", "Técnica estadística que combina los resultados de un determinado número de estudios dirigidos a responder a la misma pregunta para
elaborar un resumen de todos los resultados obtenidos. El objetivo es obtener una información más precisa y clara partiendo de un gran
fondo común de datos. Se considera que un metaanálisis es más fiable para confirmar o refutar una hipótesis que los ensayos
individuales.");
INSERT INTO keywords (name, description) VALUES ("Metáfisis", "Final de la diáfisis en crecimiento activo de un hueso largo por debajo de la placa epifisaria.");
INSERT INTO keywords (name, description) VALUES ("Metástasis", "Transferencia de una enfermedad desde un órgano a otro con el que no está conectado. Tiende a referirse a tumores malignos.");
INSERT INTO keywords (name, description) VALUES ("Método llizarov", "El método de Ilizarov de fijación de una fractura tiene sus orígenes en Rusia en la década de 1940. Incorpora un sistema axial de
alambres o clavijas encajados en el hueso y conectados a un anillo circular. A veces se usa en casos de no consolidaciones. Este
método también incorpora el principio de osteogénesis de distracción y puede ser utilizado en la restauración de defectos esqueléticos
grandes, en alargamiento del miembro y en la corrección de deformidades esqueléticas (Schwartsmann y cols., 1990).");
INSERT INTO keywords (name, description) VALUES ("Fijación Ilizarov para una fractura de húmero y escápulaMialgia", "Dolor que se experimenta en el interior de un músculo.");
INSERT INTO keywords (name, description) VALUES ("MIAP", "Abreviatura médica común de movimientos intervertebrales accesorios pasivos.
Son movimientos intervertebrales pasivos y movimientos accesorios oscilatorios que están graduados del I al IV; se emplean para
valorar y tratar síntomas vertebrales, como dolor, resistencia y espasmo.");
INSERT INTO keywords (name, description) VALUES ("M IAP de la columna lumbar central utilizando el pisiforme", "");
INSERT INTO keywords (name, description) VALUES ("Columna lumbar unilateraTransversa de columna torácica baja", "");
INSERT INTO keywords (name, description) VALUES ("Miastenia gravis", "Trastorno infrecuente que afecta a la transmisión de impulsos en la unión neuromuscular. Las principales características son debilidad y
fatigabilidad de los miembros, ojos y otros músculos; los síntomas empeoran además con los movimientos repetidos o mantenidos y al
final del día (Stokes, 1998).");
INSERT INTO keywords (name, description) VALUES ("Microcefalia", "Cerebro anormalmente pequeño.");
INSERT INTO keywords (name, description) VALUES ("Microcirculación (torrente celular)", "Fenómeno que se produce en ciertas modalidades electroterápicas, en particular los ultrasonidos. Afecta a la permeabilidad de la
membrana celular y, por tanto, a la reparación de los tejidos.");
INSERT INTO keywords (name, description) VALUES ("Microondas", "Término electroterápico que se aplica a la radiación electromagné-tica con un rango de frecuencia de entre 2.450 MHz a
aproximadamente 43 MHz. Actualmente la frecuencia más comúnmente usada es de 2.450 MHz; es la menos efectiva para el
calentamiento con una longitud de onda electromagnética que es inversa a la penetración. Las frecuencias más bajas pueden resultar
más disponibles, dejando las de frecuencia más elevada para las comunicaciones. Se usa para un calentamiento profundo pero menos
frecuentemente que el ultrasonido o la diatermia de onda corta (DOC). Al igual que con DOC, está contraindicada en un radio de 3-5
m de un paciente con un implante, estimulador o bomba y hay riesgo de quemadura si se usa sobre implantes metálicos. Los riesgos
comunes a todos los métodos empleados en la clínica para calentar son también relevantes.");
INSERT INTO keywords (name, description) VALUES ("Mielina", "Sustancia grasa que forma una vaina aislante alrededor de los nervios en el sistema nervioso central y la sustancia blanca en el cerebro.
Para una conducción nerviosa sin problemas se necesita que la vaina de mielina esté intacta.
Observación clínica La vaina de mielina está afectada en la esclerosis múltiple.");
INSERT INTO keywords (name, description) VALUES ("Mielinización", "Proceso de formación de la envoltura de mielina que rodea los axones de las células nerviosas y la sustancia blanca del cerebro.");
INSERT INTO keywords (name, description) VALUES ("Mielitis transversa", "Alteración poco frecuente asociada con infecciones como el sarampión, las paperas y el herpes zóster/simple. La parálisis con pérdida
sensitiva e incontinencia puede ir precedida de fiebre y dolor en la espalda y/o miembros.");
INSERT INTO keywords (name, description) VALUES ("Mieloma", "Tipo de cáncer que surge en las células plasmáticas, es decir, un tipo de células blancas sanguíneas.
MielomeningoceleOcurre cuando el arco posterior en la columna no se cierra durante el desarrollo. La médula espinal y las raíces sobresalen a través de
los defectos óseos y ello puede acarrear un grado variable de daños neurológicos y pérdidas de función.");
INSERT INTO keywords (name, description) VALUES ("Miembro fantasma", "Sensación de que la parte amputada del cuerpo está todavía presente.");
INSERT INTO keywords (name, description) VALUES ("Minusvalía", "Término utilizado para describir la incapacidad de un individuo para desenvolverse en situaciones de la vida normal, dentro de la
sociedad. Solía ser una categoría dentro del modelo de salud de la OMS: deficiencia, discapacidad, minusvalía. La OMS redefinió
estos términos en 1997, con el resultado de que el término »participación« se usa actualmente en vez de »minusvalía«.");
INSERT INTO keywords (name, description) VALUES ("Terminología previa Terminología actual", "");
INSERT INTO keywords (name, description) VALUES ("Deficiencia Función", "");
INSERT INTO keywords (name, description) VALUES ("Discapacidad Actividad", "");
INSERT INTO keywords (name, description) VALUES ("M inusvalía Participación", "");
INSERT INTO keywords (name, description) VALUES ("Miocardiopatía", "El término miocardiopatía designa un síndrome no inflamatorio de lesión del músculo cardíaco o cambios que afectan al desarrollo del
bombeo cardíaco. A pesar de que otras formas de enfermedad cardíaca, como la enfermedad cardíaca coronaria, pueden acabar
dando lugar a una miocardiopatía, el término se reserva generalmente a cambios miocárdicos independientes de otras formas de
enfermedad cardíaca; algunos médicos utilizan los términos primaria y secundaria según las causas.
Puede dividirse en tres clases principales: dilatada, hipertrófica y restrictiva.");
INSERT INTO keywords (name, description) VALUES ("Miocardiopatía dilatada (MCD)", "También conocida como miocardiopatía congestiva, la MCD se caracteriza principalmente por un corazón aumentado de tamaño con
baja contractilidad. El estiramiento o dilatación de las paredes del corazón hace que se vuelvan delgadas y blandas, por lo que el
corazón se vuelve débil y no es capaz de bombear la sangre como debería. Se manifiesta por una reducción en la fracción de eyección.");
INSERT INTO keywords (name, description) VALUES ("Miocardiopatía hipertrófica (MCH)", "El signo más notable de la miocardiopatía hipertrófica, también conocida como miocardiopatía hipertrófica obstructiva (MCHO), es un
engrosamiento excesivo del músculo cardíaco. Este engrosamiento de la pared, o hipertrofia, puede dar lugar a problemas de
obstrucción de flujo y problemas con la relajación de los ventrículos, lo que afectará a la capacidad del corazón para llenarse. La
distribución de la hipertrofia es variable; el ventrículo izquierdo está afectado la mayoría de las veces y, en algunos individuos, el
músculo del ventrículo derecho también se engrosa.");
INSERT INTO keywords (name, description) VALUES ("Miocardiopatía restrictiva (MCR)", "La característica de la MCR es la existencia de ventrículos con función de bombeo ventricular normal o casi normal, pero un rellenado
anormal debido a la fibrosis o la cicatrización del miocardio. Como un ventrículo rígido y entumecido tiene dificultad para llenarse, se
acumula sangre por detrás de una o ambas válvulas y las aurículas se distienden y agrandan. Los ventrículos conservan un tamaño
normal o cerca de lo normal. La MCR produce un aumento de la frecuencia respiratoria, a menudo asociado con una enfermedad
respiratoria, resfriados, bronquitis y neumonía. Otros síntomas son los de la insuficiencia cardíaca izquierda o derecha, incluyendo
congestión sistémica y pulmonar. La MCR es una forma muy rara de miocardiopatía; la padecen alrededor del 5% de los pacientes.
Puede ser idiopática o secundaria a otras enfermedades sistémicas.
Reproducido con autorización de Porter S 2003 Tidy's physiotherapy, 13. a ed. Elsevier Ltd, Edinburgh.");
INSERT INTO keywords (name, description) VALUES ("Mioclonus", "Contracciones tipo sacudida de un músculo o grupo de músculos.");
INSERT INTO keywords (name, description) VALUES ("Miopatías inflamatorias", "Es una alteración del músculo en la que existe evidencia clínica y de laboratorio de un proceso inflamatorio. Es una alteración muscular
adquirida.");
INSERT INTO keywords (name, description) VALUES ("Miositis osificante", "Osificación de un hematoma secundario a un traumatismo. Si un hematoma no se resuelve completamente, la calcificación y la
consiguiente osificación pueden aparecer después de 3 semanas aproximadamente. Después puede ser necesaria una intervención
quirúrgica.Miotoma
Músculo inervado por un nivel de raíz nerviosa en concreto. Véase la tabla siguiente.");
INSERT INTO keywords (name, description) VALUES ("M iotomas", "");
INSERT INTO keywords (name, description) VALUES ("C1 Flexión cervical superior", "");
INSERT INTO keywords (name, description) VALUES ("C2 Extensión cervical superior", "");
INSERT INTO keywords (name, description) VALUES ("C3 Flexión lateral cervica", "");
INSERT INTO keywords (name, description) VALUES ("C4 Encogimiento de hombros", "");
INSERT INTO keywords (name, description) VALUES ("C5 Rotación externa, abducción del hombro", "");
INSERT INTO keywords (name, description) VALUES ("C6 Flexión de codo, extensión de muñeca", "");
INSERT INTO keywords (name, description) VALUES ("C7 Extensión de codo, flexión de muñeca", "");
INSERT INTO keywords (name, description) VALUES ("C8 Extensión de pulgar, flexión de los dedos", "");
INSERT INTO keywords (name, description) VALUES ("T1 Abducción/adducción de los dedos", "");
INSERT INTO keywords (name, description) VALUES ("L2 Flexión de cadera", "");
INSERT INTO keywords (name, description) VALUES ("L3 Extensión de rodilla", "");
INSERT INTO keywords (name, description) VALUES ("L4 Dorsiflexión de tobillo", "");
INSERT INTO keywords (name, description) VALUES ("L5 Dorsiflexión (extensión) del dedo gordo", "");
INSERT INTO keywords (name, description) VALUES ("S1, S2 Flexión plantar de tobillo, flexión de rodilla", "");
INSERT INTO keywords (name, description) VALUES ("S3, S4 Esfínter recta", "");
INSERT INTO keywords (name, description) VALUES ("Mitocondria", "»Central energética« de la mayoría de las células del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Moda", "Término de investigación. La moda es el valor que se da con más frecuencia.");
INSERT INTO keywords (name, description) VALUES ("Modelo biomédico", "Modelo de salud y enfermedad que concibe el cuerpo como una máquina. Está basado en un entendimiento de la fisiología que no tiene
en cuenta las influencias psicológicas, sociológicas, culturales y espirituales.");
INSERT INTO keywords (name, description) VALUES ("Modelo biopsicosocial", "Modelo terapéutico que reconoce que los factores psicológicos y sociales deben ser incluidos, desde el principio, con los biológicos,
para comprender la enfermedad médica de una persona.
Observación clínica Este modelo es particularmente importante en el tratamiento de personas con dolor crónico.");
INSERT INTO keywords (name, description) VALUES ("Modelo de creencia de la salud", "La característica central de este modelo es que las personas no tienden a adoptar comportamientos de salud a menos que piensen que
sean susceptibles a la enfermedad o alteración en cuestión, que ésta sea grave, que las recomendaciones sean efectivas y que las
ventajas de seguir el consejo no superen a las desventajas. El individuo puede también necesitar un »detonante« (p. ej., el diagnóstico
de un amigo con la enfermedad) antes de introducir cambios en su comportamiento.");
INSERT INTO keywords (name, description) VALUES ("Modificación del comportamiento", "Describe un acercamiento al cambio de conducta. Se usa cuando los pacientes exhiben conductas que son inapropiadas, como por
ejemplo los pacientes con daño cerebral que pegan a sus asistentes o son sexualmente desinhibidos. La conducta deseada es
recompensada y la conducta indeseada es o bien ignorada o bien castigada. Entre otros métodos se pueden utilizar tablas de estrellas y
la técnica de la economía de fichas. Un psicólogo muchas veces elabora los programas, pero requiere del apoyo de todo el equipo para
hacer que sean efectivos.");
INSERT INTO keywords (name, description) VALUES ("Modulación", "Término electroterápico que se utiliza para designar las variaciones sistemáticas en una o más características de una corriente. Por
ejemplo: la modulación de la amplitud ocurre con corrientes sinusoidales cruzadas con terapia interferencial premodulada y cuadripolar;
la amplitud de impulsos sucesivos en cada pulso aumenta sistemáticamente hasta el punto más alto y luego disminuye. El proceso serepite en los siguientes pulsos. Algunas máquinas de TENS ofrecen la posibilidad de modulaciones de frecuencia o pulsos o una
combinación de ambos para reducir la adaptación a la estimulación eléctrica.");
INSERT INTO keywords (name, description) VALUES ("Molde", "Véase Escayola de París.
El término »escayola/molde de yeso« suele aplicarse a una tablilla hecha tanto de escayola de París como de resina de poliuretano o
fibra de vidrio. Se realizan de manera individual para cada paciente. Además de ser utilizados en alteraciones musculoesqueléticas y
ortopédicas, los moldes son utilizados en el tratamiento de pacientes neurológicos como algo accesorio a:
• Incrementar o mantener el rango de movimiento.
• Corregir el desequilibrio muscular.
• Permitir la función.");
INSERT INTO keywords (name, description) VALUES ("Monofásico", "Término electroterápico que se aplica a un impulso con una fase. Véase Fases.");
INSERT INTO keywords (name, description) VALUES ("Monoparesia", "Paresia que afecta a un único miembro o parte de éste.");
INSERT INTO keywords (name, description) VALUES ("Morbilidad", "Condición de estar enfermo. Algunas veces se emplea para hacer referencia a complicaciones.");
INSERT INTO keywords (name, description) VALUES ("Motivación", "Término general que denota la dirección y regulación de los comportamientos, emociones y pensamientos dirigidos a la satisfacción de
necesidades y a la búsqueda de objetivos.
Es de vital importancia en el proceso de rehabilitación y en el aprendizaje de habilidades. La motivación puede ser aumentada a través
del logro de objetivos y un entorno de aprendizaje positivo.
Observación clínica. La motivación puede verse afectada después de una lesión cerebral debido a factores tales como pérdida de
memoria, depresión y deficiencia perceptiva y cognitiva.");
INSERT INTO keywords (name, description) VALUES ("Motoneurona alfa", "Nervio que inerva las fibras extrafusales del músculo esquelético.");
INSERT INTO keywords (name, description) VALUES ("Movilidad pasiva continua (MPC)", "Forma de movilización pasiva.");
INSERT INTO keywords (name, description) VALUES ("Movilización", "Movimiento pasivo desarrollado de tal modo que pueda ser controlado por el paciente. Incluye movimientos fisiológicos pasivos y
movimientos accesorios pasivos que van del grado I al IV.
Posición del paciente grado IDemostración de la técnica de grado I
Posición del paciente grado IIDemostración de la técnica de grado II
Posición del paciente grado IIIDemostración de la técnica de grado III
Posición del paciente grado IVDemostración de la técnica de grado IV");
INSERT INTO keywords (name, description) VALUES ("Movilización neural", "Técnicas mediante las cuales el tejido nervioso es »movilizado«, bien mediante un movimiento relativo respecto a los tejidos adyacentes
o bien desarrollando tensión.");
INSERT INTO keywords (name, description) VALUES ("Movimiento", "Véase Movimiento activo, Movimiento asistido, Movimiento resistido y Movimientos pasivos.");
INSERT INTO keywords (name, description) VALUES ("Movimiento accesorio", "Movimiento que no puede ser llevado a cabo de manera voluntaria por el paciente (p. ej., la rotación de la articulación MCF) pero que
es necesario para el normal funcionamiento de la articulación. Incluye movimientos como giros, rodamientos y deslizamientos.");
INSERT INTO keywords (name, description) VALUES ("Movimiento activo", "Movimiento llevado a cabo por una persona sin ayuda de ningún factor externo. Véase Movimiento asistido, Movimiento resistido y
Movimientos pasivos.");
INSERT INTO keywords (name, description) VALUES ("Movimiento asistido", "Movimientos que se realiza con la ayuda del terapeuta o de un aparato. En los movimientos autoasistidos es la propia persona la que se
ayuda a sí misma en el movimiento de una parte del cuerpo. Por ejemplo, cuando una persona se ayuda a elevar un brazo lesionado o
afectado usando el brazo no afectado.");
INSERT INTO keywords (name, description) VALUES ("Movimiento balístico", "Movimientos de alta velocidad y de gran amplitud que requieren actividad recíproca entre grupos musculares agonistas y antagonistas.
Tienen lugar normalmente durante movimientos rápidos, como por ejemplo durante un servicio en tenis.");
INSERT INTO keywords (name, description) VALUES ("Movimiento de las costillas", "Durante la respiración las costillas tienen dos tipos diferentes de movimiento: en asa de bomba, con aumento del diámetro anteropos-
terior del pecho, y en asa de cubo, con aumento del diámetro lateral del tórax.M ovimientos de la pared torácica");
INSERT INTO keywords (name, description) VALUES ("Movimiento resistido", "Realización de un movimiento al que se le añade una resistencia adicional además del peso del propio segmento corporal; por ejemplo,
la flexión del brazo con un peso de 5 kg es un ejercicio resistido.");
INSERT INTO keywords (name, description) VALUES ("Movimiento social", "Esfuerzos organizados de un número significativo de personas oprimidas (incluyendo mujeres, personas de color y personas
discapacitadas) para cambiar un aspecto fundamental de la sociedad. Un movimiento social es una fuerza generada y comprometida
políticamente que se opone al status quo. El movimiento social opera normalmente fuera de los canales políticos establecidos.");
INSERT INTO keywords (name, description) VALUES ("Movimiento voluntario", "Término usado comúnmente por fisioterapeutas para describir el movimiento que es llevado a cabo por los pacientes bajo su propio
control.");
INSERT INTO keywords (name, description) VALUES ("Movimientos asociados", "Existe una gran variedad de usos de este término en la literatura (
Stephenson y cols., 1998 ). Bobath (1985) los describe como
movimientos normales coordinados, que normalmente acompañan a movimientos realizados con un esfuerzo considerable como cuando
se aprende una nueva tarea. Otros autores usan el término para describir tanto movimientos normales como patológicos.
Véase Reacciones asociadas.");
INSERT INTO keywords (name, description) VALUES ("Movimientos intervertebrales accesorios pasivos (MIAP)", "Véase MIAP.");
INSERT INTO keywords (name, description) VALUES ("Movimientos orofaciales", "Movimientos de la cara y la boca. En esta área pueden presentarse problemas como consecuencia de lesiones cerebrales o después de
una parálisis de Bell.
Observación clínica La restauración de la función orofacial debe ser de suprema importancia para el fisioterapeuta y para el
logopeda. Los problemas en esta área pueden llevar a incapacidad para cerrar los labios o para mover la comida en la boca, con lo
cual la acción de comer puede llegar a ser embarazosa para el paciente. Si el cierre del ojo está afectado, el cuidado de éste es crucial
y podría tener que suturarse el párpado para mantenerlo protegido.");
INSERT INTO keywords (name, description) VALUES ("Movimientos pasivos", "Movimiento desarrollado por una fuerza llevada a cabo por otra persona o una máquina, es decir, máquinas de movimiento pasivo
continuo (MMPC), pero sin requerir actividad voluntaria de los propios músculos del paciente.
Los beneficios de los movimientos pasivos son:
• Mantienen la integridad de articulaciones y tejidos blandos.
• Fomentan la extensión sinovial sobre el cartílago articular y por tanto su nutrición.
• Mantienen el rango de movimientos existente.
• Minimizan el riesgo de contracturas articulares (rango completo necesario).
• Mantienen la elasticidad de los tejidos blandos.
• Ayudan a la circulación si se realizan rápidamente (estimulación de la bomba muscular).
• Inhibición del dolor (los movimientos pueden actuar como analgésico).• Relajación.
• Promueven la circulación y, por tanto, la curación.
• Preservan la memoria de patrones de movimientos normales.
• Beneficios psicológicos.");
INSERT INTO keywords (name, description) VALUES ("Movimientos selectivos", "Término utilizado por los fisioterapeutas para describir un movimiento que es preciso, coordinado, con un objetivo definido y que está
basado en el plano de estabilidad apropiado.");
INSERT INTO keywords (name, description) VALUES ("MPC", "Véase Movilidad pasiva continua.");
INSERT INTO keywords (name, description) VALUES ("Muerte cerebral", "Aquella en la que han cesado las funciones neurológicas normales pero en la que se mantienen, por medios mecánicos externos, la
circulación y la respiración.
Los reflejos del tallo cerebral son valorados para averiguar si hay muerte cerebral. Estos tests incluyen la respuesta de la pupila a la luz,
el reflejo corneal, el reflejo de arcada, la respuesta motora en músculos inervados por los nervios craneales, reflejos de respiración y
vestibulooculares. Para que se declare la muerte cerebral de un paciente, estos tests deben ser llevados a cabo por dos médicos y ser
repetidos tras un período de tiempo determinado. Este procedimiento es requerido si los pacientes están conectados a una máquina que
mantiene sus constantes vitales, antes de que la máquina se apague.");
INSERT INTO keywords (name, description) VALUES ("Muestra", "Término de investigación que se aplica a los individuos que cumplen con los criterios de inclusión y que realmente forman parte del
estudio de investigación.");
INSERT INTO keywords (name, description) VALUES ("Muestra intencional", "Término de investigación que se aplica a una muestra que se toma teniendo un grupo particular en mente. Por ejemplo, si quisiéramos
emprender una investigación de razones de no asistencia a las sesiones de fisioterapia, deberíamos usar una muestra intencional, ya que
no tiene sentido tomar una muestra al azar que incluya pacientes que asisten y pacientes que no asisten a las sesiones, puesto que
nuestra pregunta de investigación se refiere exclusivamente a los pacientes que no asisten a las sesiones.");
INSERT INTO keywords (name, description) VALUES ("Muestreo »en bola de nieve«", "Término de investigación en que la selección de encuestados adicionales está basada en la referencia de los encuestados iniciales,
continuando de este modo hasta que no se identifican nuevos encuestados.");
INSERT INTO keywords (name, description) VALUES ("M uestreo aumentado rápidamente (»en bola de nieve«)", "");
INSERT INTO keywords (name, description) VALUES ("Multidisciplinario", "Que implica un número diverso de disciplinas/profesiones.Multífido
Músculo profundo de la columna lumbar. Su función primaria es estabilizar la columna lumbar.");
INSERT INTO keywords (name, description) VALUES ("Muñeca caída", "Véase Parálisis del nervio radial.
Parálisis de los dedos y los extensores de la muñeca que se produce tras una lesión del nervio radial; esto es particularmente frecuente
después de una fractura de la diáfisis del húmero (el nervio radial pasa por el surco radial en la diáfisis del húmero).");
INSERT INTO keywords (name, description) VALUES ("Murmullo cardíaco", "Sonido causado por la turbulencia que se produce a medida que la sangre pasa a través de una válvula cardíaca defectuosa.");
INSERT INTO keywords (name, description) VALUES ("Músculo del sastre", "Nombre antiguo del músculo sartorio (los sastres solían sentarse con las piernas cruzadas, de ahí el nombre de sartorio: las acciones
combinadas del sartorio son la flexión, abducción y rotación externa de la cadera).");
INSERT INTO keywords (name, description) VALUES ("Músculo denervado", "Interrupción de la inervación de un nervio periférico a un músculo. Las respuestas a la estimulación eléctrica están notablemente
reducidas; la cronaxia aumenta, y la reobase generalmente también está incrementada.
Véase Axonotmesis, Neuropraxia y Neurotmesis.");
INSERT INTO keywords (name, description) VALUES ("Músculo detrusor", "Músculo de la vejiga.");
INSERT INTO keywords (name, description) VALUES ("Músculo extrafusal", "Fibra de músculo estriado localizada fuera del huso muscular.");
INSERT INTO keywords (name, description) VALUES ("Músculos inspiratorios", "Músculos que se emplean durante la inspiración; son el diafragma y los músculos intercostales.");
INSERT INTO keywords (name, description) VALUES ("Músculos intercostales", "Músculos situados entre las costillas, que participan en la respiración.N");
INSERT INTO keywords (name, description) VALUES ("Narcolepsia", "Alteración del sueño asociada con excesiva somnolencia a lo largo del día y dificultad para dormir durante la noche.");
INSERT INTO keywords (name, description) VALUES ("Narcótico", "Sustancia que produce narcosis. Se aplica especialmente a fármacos que tienen una acción similar a la morfina.");
INSERT INTO keywords (name, description) VALUES ("Nasofaríngeo", "Relativo a la nasofaringe o parte superior de la garganta detrás de la nariz.");
INSERT INTO keywords (name, description) VALUES ("National Health Service (NHS) (Reino Unido)", "Sistema sanitario dirigido y fundado por el Estado británico en 1948. Su objetivo es proporcionar atención sanitaria a todos los
ciudadanos; es financiado a través de impuestos y gratuito en el punto de aplicación del servicio. Sin embargo, se introdujo un sistema
de tarifas antes de 1950 y éste ha aumentado gradualmente. La NHS cambió considerablemente bajo el gobierno de Margaret
Thatcher, cuando se introdujeron los conceptos de »mercado interno« y »economía mixta del bienestar«.
Véase Economía mixta de bienestar y Mercado interno.");
INSERT INTO keywords (name, description) VALUES ("National Institute for Clinical Excellence (NICE)", "Se trata de una organización independiente responsable de proporcionar una guía nacional de atención y tratamiento sanitario para los
usuarios del NHS en Inglaterra y Gales. La guía está dirigida a profesionales sanitarios, pacientes y cuidadores, y tiene por objetivo
ayudarlos a tomar decisiones sobre el tratamiento y el cuidado de la salud. El NICE fue establecido como autoridad sanitaria en abril de
1999, para promocionar la calidad clínica y el uso efectivo de recursos dentro del NHS. Con la publicación de la guía NICE, se espera
proporcionar a profesionales de la salud una orientación fiable en el ejercicio de su juicio clínico. Actualmente, el NICE aporta guías en
tres áreas de salud:
1. Uso de fármacos y tratamientos nuevos y convencionales dentro del NHS en Inglaterra y Gales. Evaluaciones tecnológicas.
2. Tratamiento y cuidado apropiado de pacientes con enfermedades y condiciones específicas dentro del NHS en Inglaterra y Gales.
Directrices clínicas.
3. Determinar si los procesos de intervención utilizados para el diagnóstico o tratamiento son suficientemente seguros y eficaces para su
uso rutinario. Procedimientos intervencionistas.
El NICE también patrocina tres investigaciones que emprenden estudios sobre los pacientes tratados, para identificar la manera de
mejorar la calidad de la atención sanitaria. (Estas investigaciones son conocidas como investigaciones
confidenciales.) Las guías y
recomendaciones del NICE están preparadas por grupos independientes que incluyen profesionales que trabajan en el NHS y personas
familiarizadas con los temas que afectan a los pacientes y cuidadores.
Ir a http://www.nice.org.uk
Nuestro agradecimiento a: Louise Fish, Senior Communications Manager, National Institute for Clinical Excellence.");
INSERT INTO keywords (name, description) VALUES ("National Service Framework (NSF)", "Iniciativa de gobierno que tiene por objetivo proporcionar al NHS estándares y principios explícitos para el patrón y nivel de servicios
requeridos en un servicio o grupo de cuidados específicos. Con objeto de dirigirse al »sistema sanitario integral«, cada uno determina
dónde se proporcionan mejor los cuidados y los estándares de cuidados que se deberían ofrecer a los pacientes en cada lugar.
Proporcionan »una clara serie de prioridades en las cuales se puede enmarcar la acción local«, y tratan de garantizar que los pacientes
gocen de una asistencia sanitaria pública de mejor disponibilidad y calidad (NHS, 1998).");
INSERT INTO keywords (name, description) VALUES ("Nebulizador", "Equipo utilizado para administrar medicación en forma de aerosol, para la inhalación y depósito de fármacos en el pulmón. Entre los
fármacos que se administran a través de nebulizadores se incluyen broncodilatadores y algunos antibióticos (");
INSERT INTO keywords (name, description) VALUES ("BTS, 1997 ; European", "Respiratory Society Task Force, 2001).
Necesidades especialesEl concepto de necesidades está ampliamente extendido dentro de las ciencias sociales y en la política, la práctica y la administración de
servicios. Puede denotar la falta de algo requerido o necesario para una persona, en especial para su supervivencia. Aunque se puede
llegar a un acuerdo respecto a las necesidades humanas básicas, como comida, sueño y hogar, hay necesidades más amplias tanto
sociales como psicológicas que todavía se discuten. Cuando se aplica a grupos especiales, sobre todo a personas discapacitadas,
dentro de un modelo individual o médico de discapacidad, la noción de necesidades recibe el calificativo de »especial«. De acuerdo
con la necesidad de provisión de servicios, »especial« ha significado separado o segregado,");
INSERT INTO keywords (name, description) VALUES ("y es considerado por parte de muchas", "personas discapacitadas como una expresión y justificación de opresión. Puede argumentarse que las necesidades de las personas
discapacitadas son centrales en vez de »especiales«.");
INSERT INTO keywords (name, description) VALUES ("Necrosis", "Muerte del tejido.");
INSERT INTO keywords (name, description) VALUES ("Necrosis aséptica", "Véase Necrosis avascular.");
INSERT INTO keywords (name, description) VALUES ("Necrosis avascular", "Muerte del tejido debido a una reducción del aporte sanguíneo.
Observación clínica Sigue comúnmente a fracturas del escafoides del carpo y del escafoides del tarso, y a fracturas del cuello del
fémur, donde dará lugar a la necrosis de la cabeza del fémur. Por esta razón puede ser necesaria la eliminación de la cabeza del fémur y
la realización de una artroplastia.");
INSERT INTO keywords (name, description) VALUES ("Nefrectomía", "Extirpación del riñón.");
INSERT INTO keywords (name, description) VALUES ("Negligencia", "Véase Negligencia unilateral.");
INSERT INTO keywords (name, description) VALUES ("Negligencia unilateral", "Síndrome que puede darse en pacientes con lesiones cerebrales y que se caracteriza por un fallo significativo en la respuesta,
información u orientación de los estímulos presentados en el lado contralateral a la lesión cerebral (Heilman y cols., 1993).
Observación clínica La consecuencia puede ser que el paciente no utilice su brazo, que coma sólo la comida de la mitad de su plato
o que choque contra los objetos situados en el lado afectado.");
INSERT INTO keywords (name, description) VALUES ("Negligencia visuoespacial", "Véase Negligencia unilateral.");
INSERT INTO keywords (name, description) VALUES ("Neoplasia", "Crecimiento anormal del tejido, que podría ser benigno o maligno.Nervio accesorio
Nervio que inerva los músculos esternocleidomastoideo y trapecio.");
INSERT INTO keywords (name, description) VALUES ("Nervio axilar", "Nace de la raíz posterior del plexo braquial, pasa a través del espacio cuadrangular y rodea el cuello quirúrgico del húmero, inervando
los músculos deltoides y redondo menor.");
INSERT INTO keywords (name, description) VALUES ("Nervio ciático", "Gran nervio que recorre la parte posterior de la pierna, y se divide en los nervios tibial y peroneo común.
(A) Curso del nervio ciático(B) M úsculos inervados por el nervio ciático y sus ramas
Nervio cubitalTrayecto del nervio cubitalM úsculos inervados por el nervio cubital");
INSERT INTO keywords (name, description) VALUES ("Nervio facial", "Séptimo nervio craneal; su compresión o lesión da lugar a la parálisis de Bell.");
INSERT INTO keywords (name, description) VALUES ("Nervio femoralNervios obturador y femoral", "");
INSERT INTO keywords (name, description) VALUES ("Nervio mediano", "Nervio de gran tamaño que comprende segmentos de la columna cervical y que está involucrado en la función neural del miembro
superior. Comúnmente encontramos atrapamientos en el túnel carpiano de la muñeca, lo cual provoca el síndrome del túnel carpiano.Trayecto del nervio medianoM úsculos inervados por el nervio mediano");
INSERT INTO keywords (name, description) VALUES ("Nervio musculocutáneoM úsculos inervados por el nervio musculocutáneo", "");
INSERT INTO keywords (name, description) VALUES ("Nervio obturador", "Véase Nervio femoral.");
INSERT INTO keywords (name, description) VALUES ("Nervio peroneo común", "Nervio que acompaña al nervio tibial; los dos juntos forman el nervio ciático. El nervio peroneo común se divide en los nervios peroneo
profundo y superficial.");
INSERT INTO keywords (name, description) VALUES ("Nervios peroneos", "");
INSERT INTO keywords (name, description) VALUES ("Nervio radial", "El nervio radial controla la extensión de los dedos y la muñeca y proporciona inervación sensorial al dorso de la mano.(A) Ruta del nervio radial. (B) M úsculos inervados por los nervios radial y axilar");
INSERT INTO keywords (name, description) VALUES ("Nervio sinovertebral", "Desde el nervio espinal, después de su formación a partir de la unión de los nervios ventral y dorsal, se origina un pequeño filamento
nervioso, al que se une una rama del tronco simpático.");
INSERT INTO keywords (name, description) VALUES ("Nervio tibial", "Véase Nervio ciático.");
INSERT INTO keywords (name, description) VALUES ("Nervios craneales", "Se trata de doce pares de nervios que emanan del tejido nervioso del cerebro y emergen del cráneo a través de pequeños orificios. Son
los siguientes:
1. Oftálmico.
2. Óptico.
3. Oculomotor.
4. Troclear.
5. Trigémino.
6. Abducens.
7. Facial.
8. Vestibulococlear.
9. Glosofaríngeo.
10. Vago.
11. Espinal accesorio.
12. Hipogloso.
Nervios frénicosNervios que proporcionan la inervación del diafragma surgiendo de las raíces cervicales de los niveles 3, 4 y 5. Cuando esta inervación
está interrumpida, puede estar indicado un paso diafragmático (es decir, una estimulación eléctrica del diafragma que provoca una
contractura y mantiene la respiración).");
INSERT INTO keywords (name, description) VALUES ("Neumoconiosis", "Enfermedad pulmonar medioambiental u ocupacional causada por inhalación repetida de polvos inorgánicos (p. ej,. carbón en el
pulmón de minero).");
INSERT INTO keywords (name, description) VALUES ("Neumomediastino", "Acumulación de aire en el mediastino; puede ser indicativo de barotrauma o rotura esofágica (menos común).");
INSERT INTO keywords (name, description) VALUES ("Neumonectomía", "Extirpación quirúrgica de un pulmón entero.");
INSERT INTO keywords (name, description) VALUES ("Neumonía", "Inflamación del parénquima pulmonar, normalmente como resultado de una infección que puede ser bacteriana o vírica, pero
ocasionalmente fúngica o parasitaria. La neumonía se clasifica en grupos etiológicos, es decir, puede ser o bien adquirida en un hospital
o bien en la comunidad (si bien con anterioridad se clasificaba de acuerdo con el lugar de la infección, p. ej., »lobular« o »bronquial«).
Las características clínicas consisten normalmente en la aparición rápida de fiebre, tos (inicialmente no productiva) y dolor torácico
pleural, con respiración poco profunda y rápida y posible cianosis. La porción afectada del pulmón a menudo muestra características de
consolidación radiológica, con sonidos respiratorios bronquiales y matidez a la percusión como hallazgos comunes. Se deben obtener
esputos y sangre tan pronto como sea posible. Es necesario monitorizar estrechamente a estos pacientes ya que la");
INSERT INTO keywords (name, description) VALUES ("neumonía grave", "conlleva un riesgo significativo de mortalidad (BTS 2001, 2002).");
INSERT INTO keywords (name, description) VALUES ("Neumonía por Legionella pneumophila", "Neumonía bacteriana aguda caracterizada por una enfermedad similar a la gripe, con fiebre, escalofríos, dolor muscular y dolor de
cabeza.");
INSERT INTO keywords (name, description) VALUES ("Neumonitis", "Inflamación del pulmón.");
INSERT INTO keywords (name, description) VALUES ("Neumotórax", "Presencia de aire en el espacio pleural, que puede aparecer espontáneamente (como en caso de rotura espontánea de una bulla) o por
inducción (p. ej., a través de intervención quirúrgica, secundario a un traumatismo o como complicación de la línea de inserción
subclavia).
El neumotórax normalmente se presenta con un comienzo repentino de dolor torácico pleural acompañado por falta de aliento, y puede
confirmarse mediante radiología torácica. Cuando el neumotórax es pequeño pueden no existir síntomas, mientras que cuando existen
enfermedades pulmonares subyacentes o neumotórax más graves se puede experimentar dificultad respiratoria. Ocasionalmente, se
puede desarrollar un neumotórax tensional (es decir, si el neumotórax es lo bastante amplio, causa una desviación del mediastino
alejándose del pulmón afectado y causando colapso en el corazón además del pulmón). Requerirá intervención médica de urgencia
inmediata. (v. BTS guidelines, 1993 para más información).");
INSERT INTO keywords (name, description) VALUES ("Neuralgia del trigémino", "Alteración muy dolorosa del quinto nervio craneal. Causa episodios de dolor similar a un shock eléctrico intenso en labios, ojos, nariz,
cuero cabelludo y frente.");
INSERT INTO keywords (name, description) VALUES ("Neurilema", "Vaina externa de una fibra nerviosa.");
INSERT INTO keywords (name, description) VALUES ("Neuritis óptica", "Está causada por una lesión del nervio óptico y puede provocar pérdida de la visión; además, el movimiento ocular puede ser doloroso.
Observación clínica. Es un signo de aparición temprana y común en la esclerosis múltiple y está causado por la desmielinización del
nervio óptico. También puede denominarse neuritis retrobulbar.Neurocirugía
Cirugía del sistema nervioso, normalmente el cerebro.");
INSERT INTO keywords (name, description) VALUES ("Neurodinámica", "La movilidad del sistema nervioso se examina mediante procesos conocidos como tests neurodinámicos. Estos tests evalúan las
respuestas mecánicas (p. ej., movimientos neurales como el deslizamiento) y las respuestas fisiológicas (incluyendo el flujo sanguíneo
intraneural, los impulsos nerviosos y el transporte axonal) (Shacklock, 1995).
Para más información sobre los procedimientos de este tipo de tests, véase Tests neurodinámicos .");
INSERT INTO keywords (name, description) VALUES ("Neurofarmacología", "Disciplina que estudia los efectos de los medicamentos sobre el sistema nervioso.");
INSERT INTO keywords (name, description) VALUES ("Neurofibromatosis", "Véase Enfermedad de von Recklinghausen.");
INSERT INTO keywords (name, description) VALUES ("Neurogénico", "De origen nervioso; por ejemplo, una persona con ciática como resultado de la irritación de una raíz nerviosa padece dolor neurológico.");
INSERT INTO keywords (name, description) VALUES ("Neuroglía", "Estructura de soporte del sistema nervioso formada por astrocitos, oligodendrocitos y microglía.");
INSERT INTO keywords (name, description) VALUES ("Neurólisis", "Liberación de un nervio de adherencias. Normalmente hace referencia a un procedimiento quirúrgico.");
INSERT INTO keywords (name, description) VALUES ("Neuroma acústico", "Schwannoma en el octavo nervio craneal. Es un tumor (de la sustancia blanca de Schwann) benigno y normalmente cursa con pérdida
de audición en el lado afectado. Otros síntomas pueden tener lugar, especialmente, a medida que crece y presiona el nervio trigémino;");
INSERT INTO keywords (name, description) VALUES ("éstos son mareos, problemas de equilibrio, dolor facial y", "tinnitus. Normalmente se elimina exitosamente con una intervención
quirúrgica, pero en muchos casos la pérdida auditiva es permanente. La principal complicación de la intervención es el daño del nervio
facial; si ésta tiene lugar, el paciente es referido a fisioterapia.");
INSERT INTO keywords (name, description) VALUES ("Neuroma de Morton", "Tumefacción dolorosa de una de las ramas digitales de los nervios plantares. Se produce normalmente en la bifurcación del nervio que
se encuentra entre las dos cabezas metatarsianas contiguas. La localización más común es entre las cabezas del tercer y cuarto
metatarsiano.");
INSERT INTO keywords (name, description) VALUES ("Neuroma de M orton", "");
INSERT INTO keywords (name, description) VALUES ("Neurona", "Célula del sistema nervioso.Neurona motora
Nervios que inervan el músculo. Cada músculo está inervado por al menos un nervio motor que contiene cientos de axones motores.");
INSERT INTO keywords (name, description) VALUES ("Neuronas motoras", "α, β, γ.
Véase Tipos de fibras nerviosas.");
INSERT INTO keywords (name, description) VALUES ("Neuropatía", "Estado degenerativo y anormal del sistema nervioso. Ciertos estados o enfermedades pueden causar neuropatología periférica,
marcada por sensación de hormigueo o quemazón en las extremidades, pérdida de los reflejos tendinosos profundos y disminución de
la sensibilidad en la estimulación táctil. Ejemplos: neuropatología diabética y alcohólica.");
INSERT INTO keywords (name, description) VALUES ("Neuroplasticidad", "Capacidad de experimentar cambios funcionales en el sistema nervioso central en respuesta a las demandas del entorno externo e
interno.
Observación clínica La evidencia de cambios neuroplásticos observados mediante resonancia magnética ha ayudado a demostrar
los beneficios de la terapia en la reeducación del movimiento tras una lesión cerebral.");
INSERT INTO keywords (name, description) VALUES ("Neuropraxia", "Medida de la extensión del daño del nervio periférico (categoría de Seddon; tipo 1 de Sunderland). Pérdida transitoria de la función
nerviosa posterior a una lesión. Mecanismo normal: comprensión prolongada, traumatismo directo o inflamación. Bloqueo de
conducción localizado, daño no permanente de la vaina de mielina o degeneración del axón. El pronóstico es bueno, y normalmente la
recuperación es completa en 6-8 semanas. Ejemplo: parálisis del ciclista, consistente en una compresión de la rama sensitiva y motora
del nervio cubital en el canal de Guyon.");
INSERT INTO keywords (name, description) VALUES ("Neurotmesis", "Medida de la extensión de la lesión nerviosa periférica (categoría de Seddon; tipos 3, 4 y 5 de Sunderland). Interrupción del axón y
daño de una o más capas del tejido conectivo en el nervio periférico. Mecanismo normal: sección transversal, seguida de degeneración
walleriana de la vaina mielínica al 7. o día. El pronóstico no es bueno, pero puede mejorarse con cirugía y especialmente con
microcirugía.");
INSERT INTO keywords (name, description) VALUES ("Neurotransmisor", "Agente químico especial liberado por las células presinápticas; se propaga a través de la sinapsis y dirige tanto la excitación como la
inhibición de las células postsinápticas.");
INSERT INTO keywords (name, description) VALUES ("Neurotrófico", "Nutrición y mantenimiento de los tejidos regulados por influencia nerviosa.");
INSERT INTO keywords (name, description) VALUES ("Nistagmo", "Oscilación involuntaria (movimientos de un lado a otro) de uno o ambos ojos en dirección horizontal, vertical, rotatoria o variada.
Puede ser resultado de una alteración laberíntica o de la retina, o de trastornos del cerebelo o de parte del tallo cerebral.");
INSERT INTO keywords (name, description) VALUES ("Nivel de significancia", "Término de investigación que se aplica a la probabilidad de negar de forma incorrecta la hipótesis nula, esto es, afirmar que hay
diferencia entre dos grupos cuando realmente no es así. También se conoce como la probabilidad de que haya un error de tipo I. Por
convención, el nivel de significancia se sitúa en un valor p de 0,01 (99% de nivel de significancia o 0,05 (95% de nivel de significancia).");
INSERT INTO keywords (name, description) VALUES ("Niveles gaseosos de sangre venosa", "Véase Gases sanguíneos arteriales.");
INSERT INTO keywords (name, description) VALUES ("Nociceptivo", "Relativo a los procesos de transmisión del dolor.Nociceptores
Extremo de un nervio periférico que transmite un impulso doloroso.");
INSERT INTO keywords (name, description) VALUES ("Nódulo de Ranvier", "Pequeñas partes estrechadas de la vaina mielínica de la neurona. Estos espacios son más permeables a los iones de sodio y potasio que
el resto del cuerpo. Consecuentemente, facilitan la transmisión de los impulsos nerviosos.");
INSERT INTO keywords (name, description) VALUES ("Nódulo de Schmorl", "Fenómeno de desprendimiento de una parte de un disco y su herniación intravertebral o movimientos ascendentes o descendentes por
el canal espinal. Cursa con fracturas de los extremos de las láminas, a menudo lo suficientemente grandes como para permitir al núcleo
pulposo extruir dentro del cuerpo vertebral. Es normalmente una característica de las columnas dorsal baja y lumbar alta. Véase
Láminas; Enfermedad de Scheuermann.
(A) Espondilosis lumbar en el nivel L4. (B) Imagen de un escáner lumbar");
INSERT INTO keywords (name, description) VALUES ("Nódulos de Bouchard", "Tumefacción ósea de las articulaciones interfalángicas intermedias frecuente en la osteoartritis primaria.
Véase Nódulos de Heberden.
Nódulos de Heberden y Bouchard (tumefacciones óseas de las articulaciones interfalángicas distal e intermedia, respectivamente) en la osteoartritis primaria.
Nódulos de HeberdenTumefacciones óseas que afectan a los dedos.
Véase Nódulos de Bouchard.");
INSERT INTO keywords (name, description) VALUES ("Nódulos de Heberden", "");
INSERT INTO keywords (name, description) VALUES ("Normalidad", "Expectativa dominante y compartida del comportamiento y las características personales que definen lo que se considera culturalmente
deseable y apropiado.");
INSERT INTO keywords (name, description) VALUES ("Normalización", "Este principio ha desempeñado un papel crucial en el paso de la vida institucional a la vida comunitaria en personas con dificultades de
aprendizaje. Cuando fue concebido originariamente, su primer objetivo fue defender el derecho de las personas con dificultades de
aprendizaje a vivir y ser asistidos para vivir vidas con un valor social, elegidas por ellos mismos dentro de la comunidad. Conforme se
ha desarrollado, el principio ha sido blanco de muchas críticas, particularmente como un intento de »normalizar« a las personas
imponiendo estándares de comportamiento tradicionales y de clase media.
Véase Valoración del papel social.");
INSERT INTO keywords (name, description) VALUES ("NOS", "National Osteoporosis Society (Reino Unido).
Ir a www.nos.org.uk");
INSERT INTO keywords (name, description) VALUES ("Notas de campo/diario de trabajo de campo", "Término de investigación utilizado para designar los informes o reflexiones del investigador, que enriquecen los datos obtenidos y los
sitúan en contexto. Este término se utiliza comúnmente en la investigación cualitativa.");
INSERT INTO keywords (name, description) VALUES ("Núcleo caudado", "Parte de los ganglios basales implicada en el control del movimiento.");
INSERT INTO keywords (name, description) VALUES ("Núcleo pulposo", "Sustancia semigelatinosa contenida en el anillo fibroso del disco intervertebral. Un trastorno interno del disco puede dar lugar a un
escape del núcleo pulposo a través de las fibras anulares rotas.
Está compuesto principalmente de colágeno de tipo 11, es hidrófilo (afinidad con el agua) y está mantenido por el anillo. No posee
ninguna terminación nerviosa.
Véase Anillo fibroso.");
INSERT INTO keywords (name, description) VALUES ("Número necesario para tratar (NNT)", "Número de pacientes que, por término medio, debe ser tratado para prevenir un único acontecimiento de interés. Es lo inverso a la
reducción de riesgo absoluto (RRA).O");
INSERT INTO keywords (name, description) VALUES ("OA", "Abreviatura médica común de osteoartritis.");
INSERT INTO keywords (name, description) VALUES ("Objetividad", "Estado mental que no es influenciado por sentimientos personales, opiniones o prejuicios. La noción de objetividad ha sido refutada por
el hecho de que toda actividad humana es dependiente de procesos subjetivos. Por ejemplo, la investigación »objetiva« está
influenciada por factores relativos a la cultura y la historia, incluyendo lo que se considera que es digno de investigar.
Las operaciones mentales no objetivas son las que nos permiten llegar a ser »objetivos«. Los cambios no objetivos pueden dar lugar a
una visión objetiva del mundo. (Laing RD, 1983. The voice of experience. Penguin Books. Harmondsworth.)");
INSERT INTO keywords (name, description) VALUES ("Ocultación de la asignación", "Término de investigación que se refiere al proceso utilizado para evitar tener conocimientos previos a la asignación de un grupo en un
ensayo aleatorio controlado (EAC). El proceso de asignación debe ser impermeable a cualquier influencia del individuo que la hace,
siendo administrado por alguien que no sea responsable de contratar a los participantes (NICE, 2004).");
INSERT INTO keywords (name, description) VALUES ("Oligodendrocitos", "Células productoras de mielina en el sistema nervioso central.");
INSERT INTO keywords (name, description) VALUES ("Onda P", "Fragmento del trazo de un electrocardiograma (ECG) que es debido a la despolarización de los atrios.
Véase ECG.");
INSERT INTO keywords (name, description) VALUES ("Onda Q", "Desviación inicial del complejo QRS cuando ésta es negativa (descendente).");
INSERT INTO keywords (name, description) VALUES ("Ontología", "Término de investigación que se aplica al estudio de las categorías fundamentales del tipo o la clase de cosas que pueden existir. Por
ejemplo, propuestas, hechos, números, conexiones casuales, valores éticos, fuerzas, sustancias, seres espirituales y propósitos.
Es también la rama de la metafísica que se ocupa de las categorías fundamentales de las cosas.");
INSERT INTO keywords (name, description) VALUES ("Opresión interna", "La opresión se interioriza cuando aquellos que la experimentan (p. ej., a través de la injusticia, discriminación, acoso, etc.) aceptan los
puntos de vista y las creencias de aquellos que los oprimen. Por lo tanto, el niño con dificultades de aprendizaje que es tratado de forma
despreciativa, llega a pensar que él o ella es despreciable. La opresión interna es raramente completa y puede, a menudo, ser disipada
si al individuo se le presentan ideas alternativas.");
INSERT INTO keywords (name, description) VALUES ("Opresión simultánea", "Hace referencia al modo en que las diferencias sociales, de género, edad, clase, raza, orientación sexual y discapacidad se combinan
para exacerbar la experiencia de la opresión.");
INSERT INTO keywords (name, description) VALUES ("Opsonización", "Parte de la respuesta inmunitaria por la cual los antígenos son cubiertos por otras sustancias con el fin de hacerlos más vulnerables a la
fagocitosis.");
INSERT INTO keywords (name, description) VALUES ("Órgano tendinoso de Golgi (OTG)", "Receptor propioceptivo localizado dentro de los tendones. Responde a la excesiva tensión muscular inhibiendo la futura contracción
muscular. De ese modo protege de una posible lesión muscular. Está formado por fibras musculares extrafusales, que se introducen en
una cápsula parecida a un embudo que a su vez está lleno de haces de fibras de colágeno. Las terminaciones nerviosas se estimulan
cuando la tensión en el músculo se transfiere a las fibras de colágeno del órgano tendinoso de Golgi. Los órganos tendinosos de Golgi
se disponen en serie con las fibras musculares extrafusales y están diseñados para monitorizar la carga o tensión en un músculo,independientemente de su longitud.");
INSERT INTO keywords (name, description) VALUES ("Órganos finales de Ruffini", "Sensores subcutáneos que responden al estiramiento de la piel.");
INSERT INTO keywords (name, description) VALUES ("Orientación", "Conciencia que tiene una persona del tiempo, del lugar y de sí misma. La orientación puede alterarse debido a enfermedades o lesiones
cerebrales.");
INSERT INTO keywords (name, description) VALUES ("Orofaringe", "Área detrás de la garganta que va de la úvula a la epiglotis y a la base de la lengua.");
INSERT INTO keywords (name, description) VALUES ("Ortesis", "Aparato externo que está fabricado a medida para una parte del cuerpo, facilitando/manteniendo o previniendo un movimiento
generado por la aplicación de fuerzas externas (p. ej., una ortesis de tobillo).");
INSERT INTO keywords (name, description) VALUES ("Ortesis de bisagra pie-tobillo (OBPT)", "Es una ortesis de pie y tobillo (OPT) con una bisagra en la articulación del tobillo, de tal manera que el paciente puede efectuar una
flexión dorsal de tobillo, pero no una flexión plantar más allá del grado plantar. Permite un patrón de marcha más normal que una OPT
fijada, pero puede resultar pesada y voluminosa para los pacientes.");
INSERT INTO keywords (name, description) VALUES ("Ortesis de pie y tobillo", "Es una férula para el complejo pie-tobillo generalmente diseñada para permitir la función. Son útiles en pacientes con una dorsiflexión
insuficiente, para salvar el suelo durante la oscilación en la marcha, o con inestabilidad de las articulaciones del tobillo subtalar. Esto
significa que el paciente puede caminar sin tropezar. La estabilidad proporcionada por la ortesis permite a menudo a los pacientes andar
de manera más rápida y segura, y tener más confianza. Normalmente están hechas de un material de plástico. Como con todos los
aparatos externos, hay que tener especial cuidado para asegurarse de que existe una correcta adaptación y así prevenir daños cutáneos.");
INSERT INTO keywords (name, description) VALUES ("Ortopnea", "Es la presencia de disnea en posición de decúbito; es común en pacientes con fallo cardíaco. Se cree que ocurre como resultado de una
congestión vascular pulmonar causada por la incapacidad del ventrículo izquierdo ante un repentino incremento del retorno venoso, lo
cual tiene lugar cuando se está tumbado. Otra causa de ortopnea es la parálisis o debilidad del diafragma.");
INSERT INTO keywords (name, description) VALUES ("Oscilación oral de alta frecuencia", "Hace referencia a la aplicación de vibraciones de alta frecuencia en las vías aéreas para facilitar la evacuación del esputo (ya sea
externamente, aplicando un compresor de la pared torácica de alta frecuencia, o bien internamente, mediante aparatos como el flutter).
Los movimientos vibratorios rápidos de pequeño volumen de aire en las vías respiratorias dan como resultado un aumento de la tos y
de la evacuación de la mucosidad.");
INSERT INTO keywords (name, description) VALUES ("Osificación heterotópica (OH)", "Cuando el hueso se fija en los tejidos blandos. Existen numerosos tipos; la OH neurogénica se da después de una alteración
neurológica. El mantenimiento del movimiento activo y la medicación pueden prevenirla. Cuando aparece, puede ser necesaria una
intervención (Knight y cols., 2003).");
INSERT INTO keywords (name, description) VALUES ("Osteítis púbica", "Reacción inflamatoria en la sínfisis púbica.");
INSERT INTO keywords (name, description) VALUES ("Osteoartritis", "A menudo denominada enfermedad articular degenerativa (EAD), incluye diversos signos y síntomas, como formación de osteófitos,
rigidez, deformidad (p. ej., nódulos de Heberden) y dolor. Puede ser primaria o secundaria.(A) Radiografía: orteoartritis del compartimiento medial de la rodilla. (B) Osteoartritis del compartimiento medial de la rodilla");
INSERT INTO keywords (name, description) VALUES ("Osteoartritis primaria", "No hay una causa evidente. Es debida a una alteración intrínseca del propio tejido articular. Afecta a las articulaciones con un patrón
clásico y es común en mujeres posmenopáusicas, que típicamente exhiben nódulos de Bouchard y Heberden. Las articulaciones
afectadas por OA primaria de forma característica se muestran en la siguiente figura.
Articulaciones comúnmente afectadas por osteoartritis (OA) primariaNódulos de Heberden y Bouchard en osteoartritis primaria");
INSERT INTO keywords (name, description) VALUES ("Osteoartritis secundaria", "Aparece como consecuencia de otra patología. Las causas de OA secundaria pueden ser metabólicas, anatómicas, traumáticas o
inflamatorias. La OA parece más común en pacientes con fracturas o lesiones previas de articulaciones concretas (
Coggon y cols.,
2001). Los microtraumatismos repetidos pueden dar lugar a microfracturas y OA. Se cree que los factores ocupacionales son
importantes en el desarrollo de OA secundaria. Los mineros corren riesgo de desarrollar OA secundaria en las rodillas, los sastres en
las primeras articulaciones metacarpofalángicas y carpometacarpianas, los operadores de taladros neumáticos en codos y hombros, etc.
Las infecciones articulares aumentan el riesgo de una articulación de sufrir OA secundaria, al igual que ocurre con las deformaciones
que aparecen por ejemplo tras fracturas que causan anomalías biomecánicas o daño directo del cartílago si la fractura incluye la
superficie articular. La relación entre obesidad y OA es compleja y todavía no se comprende completamente. Estar obeso se relaciona
con el desarrollo de OA en algunas articulaciones pero no en otras. Existe una correlación entre un índice de masa corporal elevado y
OA en las rodillas, lo cual puede deberse a la deformidad en varo característica de las personas obesas ( Sharma y cols., 2000 ); no
obstante, la correlación es menos clara entre la obesidad y la OA de la cadera o la OA generalizada (
Sturmer y cols., 2000 ). La
obesidad da lugar a fatiga muscular prematura, lo cual a su vez ocasiona una cinemática anormal y el desarrollo subsiguiente de OA. La
relación parece ser más marcada en mujeres. El aumento de la carga en las articulaciones desempeña un claro papel, pero las
anormalidades hormonales asociadas con la obesidad también podrían ser en parte responsables, tal como sugiere el aumento, aunque
modesto, de la aparición de OA en las manos en mujeres obesas.
Rasgos clínicos de la osteoartritis (OA) en relación con la patología");
INSERT INTO keywords (name, description) VALUES ("con la causa patológica subyacente", "");
INSERT INTO keywords (name, description) VALUES ("Espasmo muscular", "Un espasmo prolongado causa dolor debido a la acumulación de metabolitos, así como fatiga. Puede limitar el movimiento de la articulación;");
INSERT INTO keywords (name, description) VALUES ("Inestabilidad articular", "Puede ir desde un ligero crujido (que puede indicar también sinovitis) hasta fuertes chasquidos en casos graves
El cartílago resquebrajado chirría de forma característica contra el hueso eburnado
La pérdida de propiocepción, de control ligamentoso y de presión negativa intraarticular a causa de un derrame son factores que contribuyen a la");
INSERT INTO keywords (name, description) VALUES ("Osteoblastos", "Células responsables de la formación de los huesos.");
INSERT INTO keywords (name, description) VALUES ("Osteoclastos", "Células responsables de la reabsorción del hueso.");
INSERT INTO keywords (name, description) VALUES ("Osteocondritis disecante", "Fragmento de cartílago y hueso subcondral que se desinserta, parcial o completamente, del hueso subyacente. Es común en la
articulación de la rodilla.");
INSERT INTO keywords (name, description) VALUES ("Osteófito", "Sobrecrecimiento del hueso observado en la osteoartritis, normalmente como reacción a procesos patológicos articulares. A menudo se
forma como resultado de una tracción en el margen óseo.
Radiografía lateral de la columna lumbar de un varón de 55 años con espondilosis lumbar. Las flechas indican osteófitos anterioresOsteogénesis imperfecta
Enfermedad genética que da lugar a huesos quebradizos y frágiles, que se rompen con el mínimo traumatismo.
No es la misma alteración que la osteoporosis.
Para más información sobre la osteogénesis imperfecta, contactar con: The Brittle Bone Society en www.brittlebone.org");
INSERT INTO keywords (name, description) VALUES ("Osteogénesis por distracción", "Procedimiento quirúrgico diseñado para aumentar las dimensiones del hueso. Sus orígenes se remontan a un ortopedista ruso llamado
Ilizarov.
Véase Método Ilizarov .");
INSERT INTO keywords (name, description) VALUES ("Osteomalacia", "Implica debilitamiento de los huesos causado por una deficiencia de vitamina D, o problemas con el metabolismo de esta vitamina.");
INSERT INTO keywords (name, description) VALUES ("Osteoporosis", "Trastorno óseo progresivo caracterizado por pérdida de masa ósea y deterioro de la microarquitectura del tejido óseo, que lleva a un
aumento consiguiente de la fragilidad ósea y de la susceptibilidad a fracturas (OMS, 1991).");
INSERT INTO keywords (name, description) VALUES ("Factores de riesgo de osteoporosis para la mujer", "Falta de estrógenos, causada por:
• Menopausia temprana (antes de los 45 años).
• Histerectomía temprana (antes de los 45 años), particularmente cuando ambos ovarios son extirpados por ooforectomía.
• Pérdidas del período durante 6 meses o más (excluyendo por embarazo) como resultado de un exceso de ejercicio o dieta.");
INSERT INTO keywords (name, description) VALUES ("Factores de riesgo de osteoporosis para el hombre", "• Niveles bajos de testosterona (hipogonadismo).
Factores de riesgo de osteoporosis para el hombre y la mujer
• Ingestión de corticoides a largo plazo a dosis altas (p. ej., en problemas de artritis reumatoide o asma).
• Historia familiar cercana de osteoporosis (materna o paterna), particularmente con historia de fractura de cadera de la madre.
• Patologías médicas como síndrome de Cushing, problemas de tiroides e hígado.
• Problemas de malabsorción (enfermedad celíaca, enfermedad de Crohn, enfermedades intestinales o cirugía gástrica).
• Largos períodos de inmovilización.
• Consumo excesivo de alcohol y tabaco.
• Dieta pobre.
• Bajo peso corporal en proporción a la altura (Carne, 2003).
(A) Vértebra normal. (B) Vértebra osteoporóticaOsteotomía
Cirugía realizada para cortar un hueso, normalmente a fin de realinear la articulación.");
INSERT INTO keywords (name, description) VALUES ("Osteotomía de Mitchell", "Osteotomía distal del primer metatarsiano. Suele emplearse en casos de hallux valgus.
El procedimiento supone:
• Desplazamiento lateral de la zona distal del primer metatarsiano.
• Ligero acortamiento del hueso.
• Tensión de los tejidos blandos mediales para corregir el ángulo de valgo de la primera articulación metatarsofalángica.");
INSERT INTO keywords (name, description) VALUES ("Oxigenación membranosa extracorpórea (OMC)", "Método de oxigenación de la sangre que usa un pulmón artificial (fuera del cuerpo), permitiendo así que el pulmón verdadero descanse.");
INSERT INTO keywords (name, description) VALUES ("Oxígeno hiperbárico", "Administración de terapia de oxígeno a presiones superiores a 1 atmósfera, por ejemplo para la embolia aérea y para la enfermedad de
descompresión.");
INSERT INTO keywords (name, description) VALUES ("Oxigenoterapia", "Desempeña un papel vital en situaciones de hipoxemia y fallo respiratorio. Es un método potente que presenta riesgos potenciales
asociados, como incendio o toxicidad por oxígeno (que puede ocurrir si se respira > 60% O 2 durante > 48 h). La progresión a SDRA
se asocia a una alta mortalidad y atelectasias de absorción, mientras que las respuestas de los pacientes a su administración son
variadas. Una inspección en un hospital demostró que el 21% de las prescripciones de oxígeno eran inapropiadas y el 85% de los
pacientes fueron inadecuadamente supervisados. Estudios similares en centros de atención primaria muestran prescripciones
inadecuadas. La seguridad y la efectividad podrían lograrse controlando el flujo, modo de administración, duración y monitorización del
tratamiento (Bateman y Leach, 1998).
La cantidad de oxígeno en la sangre arterial (es decir, el contenido de oxígeno) es un factor vital para el bienestar de los pacientes,
puesto que, junto con el gasto cardíaco, determina el reparto de oxígeno (es decir, la cantidad de oxígeno repartido para los tejidos por
unidad de tiempo). Esto a su vez depende del flujo sanguíneo que llega a los tejidos (es decir, del gasto cardíaco) y de la cantidad de
oxígeno contenido en la sangre (es decir, el contenido de oxígeno arterial).
El oxígeno es transportado en combinación con la hemoglobina (Hb) y disuelto en el plasma. El porcentaje de saturación de oxígeno de
la hemoglobina determina la cantidad que puede transportar, mientras que el volumen en disolución depende de la presión parcial de
oxígeno.
El consumo de oxígeno normal se sitúa en torno a los 250 ml.min −1 ; se utiliza sólo una cuarta parte del oxígeno disponible, lo cual
proporciona un margen seguro en caso de que el consumo de oxígeno aumentase, como ocurre por ejemplo durante el ejercicio. Elvalor normal de la PO 2 arterial es de 11-15 KPa en adultos, pero este valor desciende a ritmo constante con la edad (probablemente
debido al incremento de la diferencia entre ventilación y perfusión [V/Q]).
La oxigenoterapia debe destinarse a la corrección de la hipoxemia arterial. Cuando la hipoxemia del tejido se produce sin hipoxemia
arterial, el tratamiento debe orientarse a la causa esencial (p. ej., insuficiencia cardíaca). El tratamiento debe consistir en la
administración de una concentración suficientemente alta de oxígeno para estabilizar una PaO 2 mayor de 8 kPa. La exactitud de la
dosificación es de vital importancia en el manejo de pacientes pulmonares crónicos ( North-West Oxygen Group, 2001 ). El desarrollo
de un aparato fijo (como el Venturi) asegura la administración de una concentración fija, mientras que variables normales, como la
velocidad y profundidad de la respiración o el pico de demanda de flujo inspiratorio, afectarán a las concentraciones administradas por
aparatos de bajo flujo (como cánulas nasales), proporcionando entre el 24 y el 90% de concentración de oxígeno.
En estadios agudos, la dosificación del oxígeno puede ser vital. Una oxigenación inadecuada dará lugar a más casos de muerte e
incapacidad de las que podrían justificarse por los riesgos, relativamente menores, asociados a dosis más altas (");
INSERT INTO keywords (name, description) VALUES ("Bateman y Leach,", "1998).
Debe tenerse especial cuidado cuando se administra oxígeno a los pacientes con PaCO 2 alta e hipoxemia (v. Oxígeno hiperbárico).
Una publicación reciente proporciona orientaciones para la administración segura de oxígeno a pacientes con enfermedad pulmonar
obstructiva crónica (North West Guidelines, 2001).");
INSERT INTO keywords (name, description) VALUES ("Oximetría", "Los oxímetros se utilizan para medir la saturación de oxígeno de la hemoglobina. Esto se consigue empleando un oxímetro, que es un
aparato fotoeléctrico especialmente diseñado para este propósito. El oxímetro puede aplicarse al oído o al dedo. Esta medida se basa
en el concepto de absorción de luz infrarroja. La ventaja es que la monitorización constante de la saturación de oxígeno puede llevarse
a cabo de forma no invasiva. Sin embargo, muchos factores pueden perjudicar la precisión; por ejemplo, una insuficiente perfusión del
tejido periférico, la interferencia óptica y el movimiento excesivo de los pacientes.P");
INSERT INTO keywords (name, description) VALUES ("PA", "Abreviatura médica común de posteroanterior.");
INSERT INTO keywords (name, description) VALUES ("PaCO 2", "Presión parcial de dióxido de carbono en la sangre arterial. El rango normal es de 4,5-6,0 kPa.");
INSERT INTO keywords (name, description) VALUES ("Pagos directos", "Proceso por el cual las personas que requieren asistencia en la vida diaria pueden recibir una suma de dinero para contratar su propia
ayuda. Fue introducido en el Direct Payment Act (1996) y proporciona una alternativa para los trabajadores estatutarios para apoyar y
repartir ayudas. Un precursor fue la Independent Living Fund, que fue introducida en 1988. Ésta fue cerrada en 1993 debido a la
excesiva demanda.");
INSERT INTO keywords (name, description) VALUES ("Paladar hendido", "Abertura en el techo del paladar que se produce debido a que las partes palatinas no consiguen fusionarse durante el desarrollo en el
útero.");
INSERT INTO keywords (name, description) VALUES ("Palpación", "Examen médico llevado a cabo mediante el tacto.");
INSERT INTO keywords (name, description) VALUES ("Paniculitis", "Reacción inflamatoria de los tejidos grasos subcutáneos.");
INSERT INTO keywords (name, description) VALUES ("Pannus", "Tejido granuloso derivado del tejido sinovial, que crece sobre las superficies articulares de las articulaciones con artritis reumatoide y
está asociado con su subsiguiente descomposición.");
INSERT INTO keywords (name, description) VALUES ("Papel del discapacitado", "Papel que tienen las personas discapacitadas y que a menudo se espera que desempeñen, en perjuicio de sus propios intereses. Implica esforzarse por conseguir la »normalidad« e »independencia« y »ajustarse« y »aceptar« su situación dentro de la sociedad");
INSERT INTO keywords (name, description) VALUES ("Papel del enfermo", "Papel que se espera que asuma una persona enferma. Dependerá de factores históricos y culturales. En Gran Bretaña, en la actualidad,
las obligaciones del paciente son obtener ayuda médica competente y cumplir con el tratamiento médico. En cambio, se libera al
individuo y no se le culpa de su enfermedad. El concepto se aplica más para enfermedades agudas que crónicas. Esta conceptualizacióndel papel del enfermo fue formulada por Parsons en 1951.");
INSERT INTO keywords (name, description) VALUES ("Par de fuerzas", "En fisioterapia, se refiere a dos o más músculos que se combinan para trabajar juntos y producir un único movimiento; un buen ejemplo
es la rotación escapular:
(A) A, dirección de la fuerza de las fibras superiores del trapecio; B, dirección de la fuerza de las fibras inferiores del trapecio; C, dirección de la fuerza del serrato
anterior. (B) El resultado del par de fuerzas combinadas es la rotación escapular, como al conducir un coche usando dos movimientos opuestos en cualquiera de los dos
lados del volante.");
INSERT INTO keywords (name, description) VALUES ("Par de torsión iniciado eléctricamente (PTIE)", "Término electroterápico que se aplica al par de torsión producido por la estimulación eléctrica de un músculo. El PTIE es normalmente
menor que el par de torsión voluntario máximo (PTVM), pero también puede ser mayor. Fue desarrollado como un modo de comparar
la comodidad y la efectividad de diferentes tipos de corrientes, por ejemplo comparando las corrientes pulsantes con las alternas en un
rango de parámetros. Se usa como una relación con el par de torsión voluntario máximo para indicar un cambio en la fatiga y la
efectividad de la colocación de los electrodos, pero no es una medida fiable (PTIE/PTVM).");
INSERT INTO keywords (name, description) VALUES ("Par de torsión máximo", "Medida del rendimiento isocinético a través del cual se consigue el mayor par de torsión.");
INSERT INTO keywords (name, description) VALUES ("Par de torsión voluntario máximo (PTVM)", "Par de torsión máximo usado en la contracción muscular voluntaria. Puede ser isométrico (par de torsión isométrico voluntario máximo
(PTIVM), isotónico o isocinético. Se usa en una ratio con el par de torsión iniciado eléctricamente (PTIE), pero no es fidedigno ni
recomendable.");
INSERT INTO keywords (name, description) VALUES ("Paradigma positivista de investigación", "Esta filosofía asume una medida objetiva mundial.");
INSERT INTO keywords (name, description) VALUES ("Paradigma reduccionista", "Término de investigación que se aplica a la creencia de que la medida y cuantificación de un fenómeno puede ser replicada por un
observador independiente. Fragmentación de un fenómeno en sus partes constituyentes.");
INSERT INTO keywords (name, description) VALUES ("Parálisis cerebral", "Alteración de la función motora causada por un defecto cerebral no progresivo y permanente, o por una lesión en el nacimiento o poco
después. El déficit neurológico puede dar lugar a hemiplejía espástica, monoplejía, diplejía o cuadriplejía, atetosis o ataques de ataxia,
paratesia junto con grados variados de discapacidades en aprendizaje, habla, visión y audición.");
INSERT INTO keywords (name, description) VALUES ("Parálisis de Bell", "Alteración causada por la lesión del nervio craneal VII, que da lugar a una repentina »caída« de la expresión facial y a una disminuciónde la capacidad para mover la cara. Las características clínicas incluyen:
• Dolor detrás o delante del oído.
• Pérdida del gusto.
• Sensibilidad al sonido en el lado afectado.
• Dolores de cabeza.
• Sensación de que la cara es estirada hacia un lado.
• Problemas para comer y beber.
• »Caída« facial.
• Dificultad con algunas expresiones faciales.
• Parálisis de un lado de la cara.
• Dificultad en el cierre de un ojo.
• Dificultad en los movimientos faciales finos.
• Babeo debido a la incapacidad para controlar los músculos de la cara.
• Sequedad ocular secundaria a la incapacidad para cerrar correctamente el ojo debido a la debilidad facial.
Parálisis de Erb (también conocida como parálisis braquial obstétrica o PBO, o parálisis de Klumpke)
Parálisis o debilidad del brazo en el recién nacido causada por una lesión en el plexo braquial.");
INSERT INTO keywords (name, description) VALUES ("Parálisis del nervio radial", "El nervio radial puede ser lesionado, especialmente en la parte externa del brazo por encima del codo, ya sea por un traumatismo
directo, por presión prolongada o por una fractura de la diáfisis del húmero. Normalmente el resultado es la aparición de una muñeca
caída.");
INSERT INTO keywords (name, description) VALUES ("Parálisis seudobulbar", "Parálisis debida a la degeneración de las vías corticobulbares al núcleo motor de los nervios craneales V, VII, X, XI y XII.");
INSERT INTO keywords (name, description) VALUES ("Observación clínica", "Los pacientes presentan debilidad manifiesta cuando mastican y realizan expresiones faciales, y pueden mostrarse emocionalmente
volubles (llanto o risa). Esta condición puede observarse en la enfermedad de la neurona motora.");
INSERT INTO keywords (name, description) VALUES ("Parámetros", "Término electroterápico que se aplica a las variables que describen con precisión los ajustes empleados. Los parámetros de ultrasonido
incluyen frecuencia, BMW, tamaño y ERA del aplicador, intensidad (SATA, SATP), duración y frecuencia del tratamiento, continuo o
pulsado, localización y tamaño del área tratada, tipo o modelo de máquina, etc. Los parámetros de estimulación eléctrica dependen de
si la corriente es pulsada, alterna o continua, pero generalmente incluyen frecuencia, duración y forma del impulso, intensidad, duración");
INSERT INTO keywords (name, description) VALUES ("2", "y frecuencia del tratamiento, tamaño y localización del electrodo. Los parámetros del láser incluyen frecuencia, tipo de láser, J/cm
aplicados, tamaño y localización del área de tratamiento, método y aplicador, duración y frecuencia de tratamiento, etc. Los parámetros
de SWD incluyen método de campo capacitativo o magnético, pulsado (PSWD) o continuo (CSWD), duración y frecuencia de
tratamiento, tamaño y localización del electrodo o bobina. Los parámetros de UV incluyen lámpara, distancia a la piel, duración y fecha
de tratamiento, etc. Los parámetros de calor/frío superficial incluyen método empleado y duración y frecuencia de los tratamientos.");
INSERT INTO keywords (name, description) VALUES ("Paraparesia", "Debilidad o pérdida parcial del movimiento y/o de la sensibilidad en la mitad inferior del cuerpo como consecuencia de una lesión
medular en la región torácica, lumbar o sacra.");
INSERT INTO keywords (name, description) VALUES ("Paraplejía", "Pérdida del movimiento y/o función sensorial en la mitad inferior del cuerpo, normalmente como resultado de una lesión medular en la
región torácica, lumbar o sacra.Sensaciones anormales: entumecimiento, hormigueo, quemazón.");
INSERT INTO keywords (name, description) VALUES ("Pars interarticularis", "Segmento de hueso entre las facetas articulares superior e inferior, especialmente en la columna lumbar.");
INSERT INTO keywords (name, description) VALUES ("Parto de nalgas", "Extracción del recién nacido que tiene lugar cuando éste emerge con las nalgas o con los pies por delante.");
INSERT INTO keywords (name, description) VALUES ("Paso atáxico", "Tipo de marcha que es torpe y descoordinada, normalmente de base amplia.");
INSERT INTO keywords (name, description) VALUES ("Patelectomía", "Extirpación quirúrgica de la rótula.");
INSERT INTO keywords (name, description) VALUES ("Paternalismo", "Relación condescendiente en la que una persona se siente superior a otra como en una relación tradicional entre un padre y su hijo. La
relación profesional-paciente se ha criticado por considerarla paternalista.");
INSERT INTO keywords (name, description) VALUES ("Patogénesis", "Evolución natural de una enfermedad en el cuerpo sin intervención, es decir, sin tratamiento. Descripción del desarrollo de una
enfermedad concreta.");
INSERT INTO keywords (name, description) VALUES ("Patrón capsular", "La cápsula de una articulación afectada por artritis durante un período prolongado de tiempo se comporta de un modo predecible. Los
movimientos se pierden siguiendo un patrón carcaterístico, ya que la cápsula de la articulación se retrae. El conocimiento de los
patrones capsulares puede ayudar en el diagnóstico de diferentes patologías artríticas (patología capsular).");
INSERT INTO keywords (name, description) VALUES ("PEEP (presión espiratoria positiva al final de la espiración)", "Aplicación de presión positiva en las vías aéreas al final de la espiración. Actúa como una férula que presiona las vías aéreas, de forma
que las mantiene abiertas. Al actuar de este modo, se aumenta la capacidad residual funcional y se mejora la oxigenación.");
INSERT INTO keywords (name, description) VALUES ("Pelotas de gimnasia", "Son grandes pelotas rellenas de aire que pueden utilizarse como parte de un tratamiento para proporcionar un apoyo móvil, permitiendo
movimientos suaves y la estimulación de los mecanismos posturales. Las pelotas deben hincharse correctamente para aguantar el peso
de la persona con una deformación mínima.");
INSERT INTO keywords (name, description) VALUES ("Percepción", "Capacidad para procesar e interpretar la información sensorial.");
INSERT INTO keywords (name, description) VALUES ("Observación clínica", "Los problemas de percepción pueden seguir a lesiones cerebrales y requerir una valoración prudente por un equipo multidisciplinario,
especialmente terapeutas ocupacionales y psicólogos. Si hay problemas leves no diagnosticados, pueden causar dificultades en la
recuperación de la función.");
INSERT INTO keywords (name, description) VALUES ("Percusión torácica", "Técnica respiratoria usada en la valoración clínica del paciente. Esta técnica permite la localización de algunas estructuras clave (p. ej.,
el hígado y el corazón) y permite la evaluación de la transmisión de aire a través de los pulmones. Los sonidos de percusión deberían
compararse en los dos lados y en toda la longitud de los pulmones. La ausencia de sonidos se asocia con una ventilación deficiente, por
ejemplo en caso de efusión pleural, colapso pulmonar, consolidación o, menos frecuentemente, diafragma elevado, tumor o pleura
engrosada. Sin embargo, las alteraciones más profundas pueden no ser detectadas mediante cambios en la resonancia de percusión,
por lo que su uso es limitado.
Este término también hace referencia a la técnica de clapping/cupping, una técnica fisioterápica usada para facilitar la eliminación del
exceso de secreciones bronquiales. Se ha demostrado que la técnica aumenta la presión intratorácica. Sin embargo, su eficacia debe ser
todavía probada científicamente. La técnica debe llevarse a cabo golpeando la pared torácica con la mano ahuecada a fin de atrapar el
aire; ello causa una ola de shock vibratorio que atraviesa de la pared torácica y desprende las secreciones, pero evitando el contacto
con estructuras óseas.
Cuando el paciente está delgado, demacrado o débil, la técnica puede realizarse de forma más cómoda, colocando una toalla doblada
sobre la pared torácica antes de realizar la percusión del área. No debe llevarse a cabo sobre fracturas costales. Esta técnica debe ser
aplicada con cuidado, con una o dos manos, rápida o lentamente. Cuando es llevada a cabo por un practicante experimentado, a una
velocidad lenta y con una mano, permite reducir la tensión muscular y promover la relajación de un paciente ansioso y estresado.");
INSERT INTO keywords (name, description) VALUES ("Percutáneo", "Aplicado a través de la piel directamente a los tejidos subcutáneos (p. ej., algunos estimuladores óseos tienen una fuente de energía
externa y la corriente pasa a través de cables que penetran en la piel. Se utiliza una aguja electromiográfica de forma percutánea; de
esta manera pasa a través de la piel directamente a la unidad motora examinada).");
INSERT INTO keywords (name, description) VALUES ("Perfil de salud de Nottingham", "Medida principalmente usada para medir estados de salud percibidos en encuestas de población. Es autoinformado y dirigido a la
medición de la calidad de vida general. Fue desarrollado en poblaciones con discapacidades y podría ser más apropiado utilizarlo enestos grupos que en otros con una salud normal; este último grupo tiende a mostrar incapacidad para demostrar receptividad en esta
medida (Hunt y McKenna, 1991).");
INSERT INTO keywords (name, description) VALUES ("Pericardio", "Membrana que rodea el corazón.");
INSERT INTO keywords (name, description) VALUES ("Pericarditis", "Inflamación del pericardio.");
INSERT INTO keywords (name, description) VALUES ("Perimisio", "Capa de tejido conectivo que rodea un músculo y envía divisiones entre los haces de las fibras musculares.");
INSERT INTO keywords (name, description) VALUES ("Período refractario", "Período que sigue a un potencial de acción (PA) en el que la sensibilidad del nervio para la estimulación es inexistente o reducida. En el
período inmediato (período de refracción absoluta) ninguna respuesta es posible con independencia de la intensidad del estímulo.
Inmediatamente después de este período (período refractario relativo), el nervio sigue siendo me nos excitable que antes del potencial
de acción, pero con un estímulo suficientemente alto puede responder. La implicación clínica es que con una corriente alterna (p. ej.,
rusa), si la intensidad es suficientemente alta, puede aparecer más de un potencial de acción por ráfaga. Si no se produce ninguna
estimulación posterior, el nervio vuelve al estado de reposo pre-PA.");
INSERT INTO keywords (name, description) VALUES ("Periostitis", "Proceso inflamatorio en la inserción muscular sobre el hueso. Se observa comúnmente en la parte inferior de la pierna, conocida en este
caso como »periostitis tibial«.");
INSERT INTO keywords (name, description) VALUES ("Perjuicios", "Efectos adversos de una intervención.");
INSERT INTO keywords (name, description) VALUES ("Personalidad", "Amalgama de rasgos y características del individuo a través de las cuales él o ella es reconocido como ser único.");
INSERT INTO keywords (name, description) VALUES ("PES", "Abreviatura médica común de potencial evocado sensorial. Respuesta registrada en la región parietal del cerebro como consecuencia a
la estimulación de un nervio periférico.");
INSERT INTO keywords (name, description) VALUES ("Observación clínica", "Permite calcular el tiempo de conducción de un nervio y, por lo tanto, ayuda a detectar lesiones en los trayectos sensoriales.");
INSERT INTO keywords (name, description) VALUES ("pH", "Término utilizado para describir la acidez o alcalinidad de una solución. Mide directamente la concentración de hidrógeno de una
solución. Si el pH está por debajo de 7, la solución es ácida; si es superior a 7, es alcalina.");
INSERT INTO keywords (name, description) VALUES ("Piartrosis", "Término para hablar de la presencia de pus en una articulación.");
INSERT INTO keywords (name, description) VALUES ("PIC", "Abreviatura médica común de presión intracraneal.");
INSERT INTO keywords (name, description) VALUES ("Pie cavo", "Deformidad del pie caracterizada por una elevación aumentada del arco longitudinal medial del pie.");
INSERT INTO keywords (name, description) VALUES ("Pie plano", "Caracterizado por una disminución del arco longitudinal medial del pie. También conocido como »pie pronado«.Véase Deformidad en varo.");
INSERT INTO keywords (name, description) VALUES ("Piógeno", "Que produce pus.");
INSERT INTO keywords (name, description) VALUES ("Pirexia", "Aumento de la temperatura corporal frecuentemente debido a una infección.");
INSERT INTO keywords (name, description) VALUES ("Placa", "Término utilizado para describir áreas con pérdida de mielina y endurecimiento del tejido en la esclerosis múltiple, o para referirse a los
depósitos grasos que revisten las arterias en las enfermedades vasculares periféricas.");
INSERT INTO keywords (name, description) VALUES ("Placa motora", "Membrana postsináptica en la unión neuromuscular.");
INSERT INTO keywords (name, description) VALUES ("Placebo", "Sustancia o procedimiento sin propiedades médicas conocidas que puede modificar o eliminar los síntomas de la enfermedad si el
paciente y el profesional sanitario creen que lo hará. El contexto en el se administra puede ser también un importante aspecto del efecto
placebo.Plagio
Situación en la que el trabajo (académico) de otros es usado sin el reconocimiento adecuado; se trata de una seria ofensa académica.");
INSERT INTO keywords (name, description) VALUES ("Plano coronal", "Plano que divide el cuerpo en las porciones anterior y posterior.
Véase Posición anatómica.");
INSERT INTO keywords (name, description) VALUES ("Plano inclinado", "Instrumento mecánico de bipedestación que permite ponerse de pie a los pacientes que no son capaces de hacerlo. Los pacientes,
incluso aquellos que están inconscientes y con respiración asistida, pueden colocarse en bipedestación usando uno de estos
instrumentos, controlados externamente a través de un rango de horizontalidad a verticalidad casi completa y que puede ser detenido en
cualquier punto.");
INSERT INTO keywords (name, description) VALUES ("Plano medial (sagital)", "Plano vertical que pasa a través del centro del cuerpo, dividiéndolo en izquierda y derecha.");
INSERT INTO keywords (name, description) VALUES ("Plano transversal", "Plano que divide el cuerpo en las porciones superior e inferior.");
INSERT INTO keywords (name, description) VALUES ("Plasma", "Componente líquido (no celular) de la sangre.");
INSERT INTO keywords (name, description) VALUES ("Plasmaféresis", "Extracción del plasma del paciente a fin de ser tratado para extraer los anticuerpos que se piensa que están atacando la vaina de
mielina.
Observación clínica. Este proceso debe emplearse en el tratamiento del síndrome Guillain-Barré (SGB).");
INSERT INTO keywords (name, description) VALUES ("Plasticidad", "Capacidad para cambiar.
Véase Neuroplasticidad.");
INSERT INTO keywords (name, description) VALUES ("Plataforma de equilibrio", "Aparato utilizado para la reeducación de la propiocepción y el equilibrio.");
INSERT INTO keywords (name, description) VALUES ("Platipnea", "Disnea en posición vertical.
PleuraFina capa de tejido que recubre los pulmones (pleura visceral) y la cara interna de la pared torácica y mediastino (pleura parietal).
Aunque tiene diferentes nombres, constituye un único »forro« continuo.");
INSERT INTO keywords (name, description) VALUES ("Pleurectomía", "Extirpación de la pleura parietal del pulmón.");
INSERT INTO keywords (name, description) VALUES ("Pleuresía", "Inflamación de la pleura con el subsiguiente dolor. Normalmente resulta de una infección vírica, pero el término ha sido generalizado a
cualquier patología causante de dolor pleural (p. ej., neumonía). El dolor aumenta con respiraciones profundas, tos y movimientos
torácicos. La superficie pleural, que se vuelve áspera por la inflamación, roza con cada respiración y puede producir un sonido irritante
llamado »fricción por roce«. Puede escucharse con el estetoscopio.");
INSERT INTO keywords (name, description) VALUES ("Pleurodesis", "Fusión de las superficies pleurales. Puede llevarse a cabo cuando el neumotórax es persistente o para evitar la nueva formación de
líquido pleural.");
INSERT INTO keywords (name, description) VALUES ("Plexo", "Término que hace referencia a la reunión de ramas ventrales interconectadas. A continuación se muestran los plexos principales del
cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Principales plexos nerviosos somáticos del cuerpo", "");
INSERT INTO keywords (name, description) VALUES ("Plexo braquial", "Conjunto de nervios espinales (C5-C8 y D1) que se unen en el cuello y dan lugar a los nervios de los miembros superiores. Es
responsable de la sensibilidad y movilidad de toda la extremidad superior y del hombro (deltoides y escápula). También inerva parte del
cuello (músculo escaleno) y las regiones anteriores y laterales del tórax (músculos pectorales y serratos).Diagrama esquemático del plexo braquial");
INSERT INTO keywords (name, description) VALUES ("Plexo lumbosacro", "Véase Plexo sacro.");
INSERT INTO keywords (name, description) VALUES ("Plexo sacro (plexo lumbosacro)", "Conjunto de nervios que se ramifican en los nervios principales del miembro inferior.Plica
Pliegue sinovial que se encuentra ocasionalmente en la articulación de la rodilla, y que puede llegar a ser patológico y doloroso; las
plicas más comunes son la mediorrotuliana y la suprarrotuliana.");
INSERT INTO keywords (name, description) VALUES ("Pliegue epicantal o epicanto", "Pliegue cutáneo sobre el ángulo interno del ojo. El epicanto es más común en niños con síndrome de Down.");
INSERT INTO keywords (name, description) VALUES ("PME", "Abreviatura de potencial motor evocado.");
INSERT INTO keywords (name, description) VALUES ("Población", "Término de investigación que se aplica a las personas que cumplen los criterios de inclusión para el estudio que se desea realizar.");
INSERT INTO keywords (name, description) VALUES ("Pobreza", "Falta de recursos materiales que se asocia a menudo con carencia de recursos emocionales y sociales. Implica gastar menos en comida,
vivienda, ropa, transporte, vacaciones y otras necesidades sociales y humanas. Cuando las personas son pobres en comparación con
otras de la misma sociedad se habla de »pobreza relativa« porque no son capaces de integrarse totalmente en la sociedad de la que
forman parte. La pobreza, en términos de falta de recursos emocionales y sociales, no se asocia necesariamente con falta de recursos
materiales. Existen definiciones gubernamentales oficiales (en términos de recursos materiales) con el propósito de recoger datos
estadísticos y proporcionar beneficios financieros.");
INSERT INTO keywords (name, description) VALUES ("Poder", "Concepto central dentro de las ciencias sociales definido de formas diferentes por teóricos distintos. Es visto generalmente como una
característica de toda vida social y relaciones interpersonales y es de vital importancia para la comprensión de la desigualdad. Quienes
tienen poder tienen autoridad e influencia sobre otros. Poseen y pueden acumular recursos valiosos como riqueza y propiedad. El poder
es una dimensión importante en la relación profesional-paciente/cliente con servicios definidos, planeados y aplicados por profesionales.");
INSERT INTO keywords (name, description) VALUES ("Polaridad", "Término electroterápico que se aplica a la carga de un conductor, positivo (ánodo) o negativo (cátodo).");
INSERT INTO keywords (name, description) VALUES ("Policitemia", "Aumento del número de eritrocitos. Está asociada con enfermedad pulmonar crónica. En respuesta a estados hipoxémicos crónicos, se
producen más eritrocitos para aumentar la capacidad de transporte de oxígeno de la sangre. Sin embargo, los pacientes con policitemia
sufren un aumento del riesgo de cor pulmonale o embolias pulmonares.");
INSERT INTO keywords (name, description) VALUES ("Polifarmacia", "Empleo excesivo e innecesario de medicamentos o fármacos por una persona.");
INSERT INTO keywords (name, description) VALUES ("Polígono de Willis", "Estructura vascular localizada en el suelo de la cavidad craneal. El polígono de Willis da la vuelta alrededor del tallo cerebral, por
encima del puente, ramificándose en los vasos mayores que irrigan el cerebro.");
INSERT INTO keywords (name, description) VALUES ("Polimiositis", "Tipo de enfermedad muscular adquirida.");
INSERT INTO keywords (name, description) VALUES ("Política de igualdad de oportunidades", "Conjunto de prácticas o procedimientos dentro de organizaciones e instituciones diseñadas para asegurar que ciertos grupos de
personas, como las mujeres y las personas discapacitadas, no están en situación de desventaja en términos de empleo, vivienda, acceso
a servicios y demás. A menos que estas políticas de igual oportunidad sean sólidas, pueden servir como una pantalla de humo para
ocultar la discriminación.
Política socialProceso de desarrollo de medidas para reducir los problemas sociales e implementación de éstas. »Política social« es también el
nombre de la disciplina académica que analiza estos procesos.");
INSERT INTO keywords (name, description) VALUES ("Porfiria", "Patología caracterizada por anormalidades del metabolismo porfirínico y que da lugar a la excreción de grandes cantidades de porfirias
en la orina. Algunos casos pueden dar lugar a una notable fotosensibilidad; coloración marrón rojiza de orina y dientes; mutilación de
nariz, orejas y párpados, y un exceso de vello corporal. No es sorprendente, por tanto, que algunas personas piensen que esta
enfermedad es la base de la leyenda del vampiro.");
INSERT INTO keywords (name, description) VALUES ("Poros de Kohn", "Canales de ventilación interconectados entre los alvéolos (canales de ventilación colateral).");
INSERT INTO keywords (name, description) VALUES ("Poscarga", "Se refiere a la posición de un músculo cuando el tejido elástico »en serie« está relajado: menos que en la longitud de reposo. Durante la
contracción la relajación debe ser eliminada.");
INSERT INTO keywords (name, description) VALUES ("Posgraduado", "Término usado para describir trabajos, niveles o estudios en un nivel posterior a la obtención del título de licenciado.");
INSERT INTO keywords (name, description) VALUES ("Posición anatómica", "Posición vertical del cuerpo, con la cabeza mirando al frente, brazos a los lados, palmas hacia delante y pies juntos. Se utiliza como
mapa para describir todas las direcciones y estructuras anatómicas.
Posición anatómica que muestra los planos cardinales y la terminología direccional
PosicionamientoTérmino usado para describir el manejo terapéutico activo del efecto de posiciones diferentes en el tono muscular del tronco y los
miembros. Por ejemplo, la posición de decúbito supino está dominada por un tono extensor y, por lo tanto, los terapeutas aliviarán esta
posición con el uso de cuñas (v. Cuñas) para introducir un elemento de flexión.
Observación clínica Es importante valorar a cada individuo para encontrar su posición terapéutica óptima y asegurar que todos los
miembros del equipo multidisciplinario refuercen las posturas durante un período de 24 h");
INSERT INTO keywords (name, description) VALUES ("Postalimentación sensoriomotora", "Implica la integración e interacción de información aferente (sensorial) previas a la actividad motora para permitir que tenga lugar la
adaptación antes de la ejecución del movimiento.");
INSERT INTO keywords (name, description) VALUES ("Posterior", "Relativo o perteneciente a la parte dorsal del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Postura", "Relativo a la posición del cuerpo o de parte del cuerpo en relación con el espacio u otro objeto o parte del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Según Edwards", "(2002), una buena postura es la actitud del cuerpo que facilita la eficacia máxima de una actividad específica sin causar daño.");
INSERT INTO keywords (name, description) VALUES ("Postura de rectificación vertebral", "Postura de extensión de la columna cervical, flexión de la columna dorsal superior, ausencia de lordosis lumbar, retroversión de la
pelvis, extensión de la cadera y ligera flexión plantar del tobillo.
Postura de espalda plana. Elongada y débil: flexores de la cadera, músculos paravertebrales. Tendones cortos y fuertes.");
INSERT INTO keywords (name, description) VALUES ("Postura lordótica", "Postura tipificada por la extensión de la columna cervical, flexión aumentada de la parte superior del tronco, flexión lumbar, báscula
pélvica posterior, caderas y rodillas hiperextendidas.Postura predominante posterior");
INSERT INTO keywords (name, description) VALUES ("Potencia angular", "Trabajo realizado/tiempo empleado.");
INSERT INTO keywords (name, description) VALUES ("Potencia/energía", "En el contexto electroterápico se aplica a la tasa de flujo energético o disipación, medido en vatios (W). Concepto aplicado
clínicamente para el uso de la estimulación eléctrica y el láser. Por ejemplo, P (potencia, vatios) = VI o P = I 2 R donde V = voltaje (V),
I = intensidad (A) y R = resistencia (Ω). Véase Energía.");
INSERT INTO keywords (name, description) VALUES ("Potencial de acción (PA)", "Nombre dado al impulso eléctrico transmitido a lo largo del axón de un nervio. Es iniciado por un receptor (p. ej., receptores del dolor
en la piel, nervio aferente) o de forma central (p. ej., a nivel espinal si es
nervio motor, nervio eferente). El impulso es un cambio
electroquímico, un potencial de acción, que puede viajar en sentido proximal o distal a lo largo del axón. El potencial de acción tiene
cinco fases diferentes: estado normal (diferencia de potencial de aproximadamente − 70 mV dentro del axón con respecto al exterior
del mismo); despolarización (si el aumento del nivel de iones de sodio es suficiente dentro de la membrana del axón y
proporcionalmente hay menos iones de potasio, el nervio alcanza el umbral y el potencial de acción es inevitable: ley de todo o nada);
pico (carga excesiva; al mismo nivel independientemente de la fuerza del estímulo); período refractario absoluto (estimulación no posible
porque el equilibrio de iones empieza a regresar al estado normal); período refractario relativo (estimulación posible, pero requiere un
estímulo de alta intensidad); estado normal (nivel de equilibrio de iones estable).");
INSERT INTO keywords (name, description) VALUES ("Potencial de excitación postsináptico (PEP)", "Término fisiológico que hace referencia al efecto que se produce cuando un estímulo excitatorio causa en la neurona una ligera
despolarización que se extiende al axón; el equilibrio entre éste y el potencial de inhibición postsináptica determina la respuesta final de
la neurona.");
INSERT INTO keywords (name, description) VALUES ("Potencial postsináptico inhibitorio (PPI)", "Término que hace referencia al efecto que se produce cuando una entrada excitatoria a una neurona causa una ligera hiperpolarización
que se extiende por el axón. El equilibrio entre esto y el potencial excitatorio postsináptico determina la salida neuronal final.Potenciales de evocación visual
Test eléctrico que utiliza una ráfaga estroboscópica para estimular la retina del ojo o, alternativamente, un diseño en forma de tablero de
ajedrez para estimular la mácula del ojo. La señal visual evocada se graba en la corteza occipital. Este test proporciona información
sobre las propiedades de conducción de los trayectos visuales.
Observación clínica El nervio óptico es uno de los primeros en dar lugar a signos en el desarrollo de la esclerosis múltiple, y los PEV
pueden utilizarse para el diagnóstico de esta enfermedad desmielinizante.");
INSERT INTO keywords (name, description) VALUES ("Potenciales motores evocados (PME)", "Consiste en la estimulación de un nervio, del cerebro o la médula espinal normalmente por un impulso eléctrico (o magnético) que
queda registrado con el uso del EMG.");
INSERT INTO keywords (name, description) VALUES ("Práctica antidiscriminatoria", "Política profesional, práctica y de prevención que activamente busca reducir la discriminación institucional experimentada por individuos
y grupos por edad, raza, género, discapacidad, clase social y orientación sexual. La práctica antidiscriminatoria está respaldada por
legislación específica, como el Sex Discrimination Act (1975) y el Disability Discrimination Act (1995).");
INSERT INTO keywords (name, description) VALUES ("Práctica antiopresiva", "Término normalmente utilizado de forma intercambiable con el término »práctica antidiscriminatoria«. La práctica antiopresiva enfatiza la
necesidad de cambiar las relaciones de poder, minimizando las diferencias de poder en la sociedad. Esto requiere desafíos y cambios
fundamentales en los valores sociales y dentro de las relaciones e instituciones.");
INSERT INTO keywords (name, description) VALUES ("Práctica mental", "Parte del proceso de rehabilitación que está aumentando su popularidad (también se emplea a menudo en el ámbito deportivo). Se cree
que, si alguien piensa en llevar a cabo una tarea y repite mentalmente el proceso en su cabeza, ello es suficiente para causar la
modulación de la actividad neural en el cerebro.");
INSERT INTO keywords (name, description) VALUES ("Práctica reflexiva", "Capacidad de un médico o profesional, que piensa, habla o escribe sobre un aspecto de su práctica y examina la interacción con
clientes, pacientes u otros participantes. El propósito de la reflexión es desarrollar o aumentar las habilidades y competencias del
profesional, así como aumentar los conocimientos médicos cotidianos en la práctica.");
INSERT INTO keywords (name, description) VALUES ("Precarga", "Fuerza aplicada a un músculo en reposo para que se estire hasta su longitud inicial. En el corazón, la precarga corresponde a la presión
de llenado diastólico final.");
INSERT INTO keywords (name, description) VALUES ("Prednisolona", "Fármaco esteroideo comúnmente utilizado en la práctica clínica.");
INSERT INTO keywords (name, description) VALUES ("Pregraduado", "Término utilizado para describir trabajos, niveles o alumnos que se realizan o encuentran en la situación previa a la concesión de un
grado honorífico.");
INSERT INTO keywords (name, description) VALUES ("Pregunta de investigación", "Término de investigación que se aplica a la pregunta sobre la que se va a investigar y que incluye la población, la maniobra, el estudio
de la población y el resultado. La pregunta de investigación debe especificar un resultado medible, además de todas las condiciones y
otras variables importantes.");
INSERT INTO keywords (name, description) VALUES ("Pregunta dicotómica", "Término de investigación. Pregunta que permite sólo elegir una de dos respuestas: sí/no, verdadero/falso.");
INSERT INTO keywords (name, description) VALUES ("Prejuicio", "Literalmente implica el hecho de juzgar de antemano. Normalmente hace referencia a una actitud de hostilidad hacia una persona o ungrupo. La gente puede, por ejemplo, tener prejuicios contra las personas mayores. Los prejuicios pueden, sin embargo, ser positivos.");
INSERT INTO keywords (name, description) VALUES ("Prenda de compresión", "Pueden emplearse después de quemaduras u otros problemas, como el linfedema. Se adaptan estrechamente al cuerpo y ejercen
presión en los tejidos a fin de limitar la formación de líquido.");
INSERT INTO keywords (name, description) VALUES ("Presentación", "Término normalmente empleado para describir el proceso mediante el cual un miembro de un grupo da una información al resto del
grupo; por ejemplo, en una presentación de un estudiante. Puede ser evaluada como parte de un curso.");
INSERT INTO keywords (name, description) VALUES ("Presión aérea positiva binivelada (BIPAP®)", "Véase Ventilación no invasiva .");
INSERT INTO keywords (name, description) VALUES ("Presión continua positiva de los conductos aéreos (PCPCA)", "Véase Ventilación no invasiva .
Es la aplicación de una presión positiva de las vías aéreas en el tracto respiratorio de un paciente que respira espontáneamente. Puede
ser aplicada tanto de forma invasiva (a través de un tubo endotraqueal o de traqueotomía) como de forma no invasiva (con una máscara
facial o nasal). El efecto de la PCPCA se mantiene en el tracto respiratorio, haciendo que la presión");
INSERT INTO keywords (name, description) VALUES ("intratorácica se sostenga en un", "estado positivo constante, incluso al final de la espiración, es decir, la presión no vuelve a ser la presión atmosférica al final del ciclo
respiratorio. Por lo tanto, las vías aéreas se mantienen abiertas y proporcionan al oxígeno más tiempo para difundirse a través de la
membrana capilar alveolar, mejorando el estado de oxigenación del paciente.
La PCPCA fue en principio utilizada de manera no invasiva en el tratamiento de la apnea obstructiva del sueño (AOS), una alteración
en la que el tracto respiratorio superior se colapsa durante el sueño, causando obstrucción orofaríngea y dando lugar a la desaturación
de oxígeno, a pesar de la presencia de esfuerzos respiratorios. Desde el principio, en esta área clínica se observaron cambios en los
gases sanguíneos arteriales durante el día. Las investigaciones sobre su aplicación en la EPOC en combinación con un elemento
intermedio permitieron el desarrollo de instrumental para una respiración de presión positiva no invasiva en forma de terapia binivelada.");
INSERT INTO keywords (name, description) VALUES ("Presión espiratoria máxima (PEM)", "Medida dependiente del esfuerzo espiratorio estático máximo mantenido durante un segundo, medido en centímetros de presión de
agua utilizando un circuito respiratorio con un manómetro adjunto y una boquilla en forma de pestaña. Se emplea como un índice de
debilidad muscular global.");
INSERT INTO keywords (name, description) VALUES ("Presión inspiratoria máxima (PIM)", "Medida dependiente del esfuerzo del esfuerzo inspiratorio máximo mantenido durante un segundo, medido en centímetros de presión de
agua utilizando un circuito respiratorio con un manómetro adjunto y una boquilla en forma de pestaña. Se emplea como un índice de
fuerza muscular global.");
INSERT INTO keywords (name, description) VALUES ("Presión intracraneal", "Es la presión que existe en el interior del cráneo. Si se considera el cráneo como una caja, básicamente consta de tres componentes:
tejido cerebral, sangre y líquido cefalorraquídeo. Un aumento de cualquiera de estos tres componentes dará lugar a un aumento de la
presión intracraneal. Un aumento en la presión intracraneal es común después de una lesión cerebral cuando el tejido cerebral aumenta
de tamaño y da lugar a un incremento de la presión. Es una alteración grave, que se monitoriza clínicamente utilizando la Glasgow Coma
Scale o mediante comunicación ventricular en los casos críticos en la UCI o en unidades de alta dependencia. El cerebro puede
inicialmente »compensar« un pequeño aumento en el volumen de sus componentes, pero un aumento continuo da lugar a una
»descompensación« rápida (es decir, cuando el cerebro ya no puede acomodarse a más aumento) y provoca la muerte. Los valores
normales se encuentran entre 0 y 15 mmHg, y el tratamiento del aumento de la presión intracraneal se requiere por encima de los 20
mmHg.
Observación clínica La principal consideración para la fisioterapia es no llevar a cabo un tratamiento que pueda aumentar la presión
intracraneal (PIC) en pacientes en que ésta se halla aumentada. Por lo tanto, es importante minimizar el uso de la succión, evitar
posiciones que puedan elevar la PIC (los pacientes deberán tener cabeza y tronco elevados 30°) y evitar otros estímulos nocivos. Sin
embargo, la PIC se ve afectada por cambios en los gases sanguíneos respiratorios, por lo que el mantenimiento de una buena función
pulmonar es también muy importante. Por esta razón, se requiere una decisión clínica cuidadosa para cada paciente a fin de decidir si el
tratamiento respiratorio está indicado.Presión pleural
Presión negativa dentro del espacio pleural. Es fundamental para mantener el pulmón inflado y es más negativa en el ápex que en la base
(en posición vertical). La interrupción de la pleura (p. ej., traumatismo y neumotórax) causa un aumento en la presión pleural por encima
de la atmosférica y da lugar a colapso y compresión del pulmón.");
INSERT INTO keywords (name, description) VALUES ("Presión sanguínea", "Medida de la fuerza aplicada sobre las paredes de las arterias cuando el corazón bombea sangre al cuerpo. Resistencia de la pared de
los vasos sanguíneos, que depende de la presión que ejerce la sangre circulante y del tono y elasticidad de los vasos. La presión se
determina por la fuerza y la cantidad de sangre y el tamaño y flexibilidad de las arterias. En la práctica clínica, la presión sanguínea se
expresa mediante dos números: por ejemplo, 120 sobre 80 (escrito, 120/80). El primer número indica la presión sanguínea sistólica (la
presión ejercida cuando el corazón se contrae), el segundo número indica la presión sanguínea diastólica (la presión de las arterias
cuando el corazón está en reposo).");
INSERT INTO keywords (name, description) VALUES ("Presión transpulmonar", "Diferencia entre las presiones alveolar y pleural.");
INSERT INTO keywords (name, description) VALUES ("Presión venosa central (PVC)", "Presión sanguínea en las venas grandes del cuerpo, distinta de la presión de las venas periféricas de los brazos y piernas. Un catéter
insertado dentro de la vena cava del paciente puede medir la presión.");
INSERT INTO keywords (name, description) VALUES ("Presión venosa yugular (PVY)", "Reflejo de la presión en el lado derecho del corazón. Se estima valorando la columna de sangre en las venas yugulares con un examen
llevado a cabo con el paciente en decúbito supino y el cabecero de la cama elevado hasta un ángulo de 45°. Cuando la PVY se eleva,
las venas del cuello pueden distendirse hasta llegar a la altura del ángulo de la mandíbula. En la posición descrita anteriormente, una
distensión venosa unos 4 cm por encima del ángulo esternal se considera anormal. Sin embargo, el examen y la valoración en un
paciente obeso puede ser difícil. Una PVY elevada se puede dar en la hiperinsuflación, en la insuficiencia cardíaca derecha y en los
casos de hipervolemia.");
INSERT INTO keywords (name, description) VALUES ("Primum non nocere", "Principio ético que dicta que debemos evitar hacer daño o perjudicar a otros.");
INSERT INTO keywords (name, description) VALUES ("Principio de justicia", "Principio ético que dicta que deberíamos tratar a todas las personas del mismo modo, a menos que existan diferencias relevantes entre
ellos. Se puede considerar justo, por ejemplo, esperar en una fila de autobús basándose en que »el que primero llega es el primero en
subir«. Pero si alguien en la fila se encuentra mal y necesita sentarse cuanto antes, puede considerarse justo permitir a esa persona que
se salte la fila.");
INSERT INTO keywords (name, description) VALUES ("PRN", "Abreviatura médica común de »según sea necesario« (pro re nata).");
INSERT INTO keywords (name, description) VALUES ("Profecía de autorrealización", "Proceso por el cual las personas se pueden convertir en lo que otros piensan que son o esperan que sean. Por ejemplo, un niño que es
etiquetado de ser muy brillante por personas importantes en su vida es probable que pretenda cumplir con tal expectativa.");
INSERT INTO keywords (name, description) VALUES ("Profesión", "Organización de un trabajo con una serie de características, las cuales incluyen un cuerpo regulador central, código de conducta,
manejo y control de conocimiento y habilidad, y control del número, selección y formación de aquellos que integran la profesión. Las
profesiones pueden ser consideradas como motivadas por el altruismo, como monopolios de autointerés, o como »agentes del estado«
cuya función es el control del comportamiento »desviado«.");
INSERT INTO keywords (name, description) VALUES ("Profundidad de penetración", "Término electroterápico que se aplica a la profundidad en la cual el 37% de la energía aplicada a un objeto o cuerpo permanece (esdecir, el 63% de la energía ha sido absorbida). La extensión de la absorción de energía por niveles sucesivamente más profundos del
tejido corporal es una función exponencial. El valor real dependerá del tipo e intensidad de energía (p. ej., si es ultrasonido, frío, láser o
infrarrojo) y del tipo y adaptación del tejido y otras estructuras a través de las que pasa la energía. Por ejemplo, el ultrasonido con una
frecuencia de 1 MHz tiene una mayor profundidad de penetración que un ultrasonido de 3 MHz. Es por ello que la frecuencia de 3
MHz suele elegirse para tratar tejidos superficiales y la de 1 MHz para tejidos más profundos. Para asegurar que la energía llega a los
tejidos más profundos, el principio general es emplear ultrasonidos de baja frecuencia (p. ej., 0,8-1 MHz) y alta intensidad, de modo
que la cantidad suficiente de energía esté disponible en profundidad.
Profundidades de penetración media de una emisión de ultrasonido de 1 y 3 M Hz. Véase cómo la emisión de 1 M Hz penetra casi el doble que la de 3 M Hz antes de
que pierda la mitad de su intensidad.");
INSERT INTO keywords (name, description) VALUES ("Profundidad de penetración media (profundidad media)", "Véase también Profundidad de penetración.
Término de electroterapia que se aplica a la profundidad a la que permanece el 50% de la energía aplicada a un objeto o cuerpo.
Actualmente se prefiere el término profundidad de penetración. El valor medio de profundidad de penetración de una emisión de 1
MHz es de 4 cm, mientras que para una emisión de 3 MHz es de 2,5 cm. Los fisioterapeutas utilizan este conocimiento seleccionando
la frecuencia apropiada para que penetre hasta la profundidad deseada. Señalemos aquí que la piel se trata con 1 W/cm.");
INSERT INTO keywords (name, description) VALUES ("Promoción de la salud", "Amplio abanico de actividades cuyo objetivo es mejorar la salud. Incluyen la educación en la salud, como la enseñanza de técnicas de
elevación correctas, medidas medioambientales como el control de la contaminación, medicina preventiva como el escáner cervical,
medidas fiscales como los beneficios financieros y medidas legales como la legislación del cinturón de seguridad.");
INSERT INTO keywords (name, description) VALUES ("Pronación", "Movimiento del antebrazo que hace que la palma de la mano quede hacia abajo. También aplicado en el pie, en el que la cara plantar
queda hacia abajo.");
INSERT INTO keywords (name, description) VALUES ("Prono", "Término utilizado para describir la posición de una persona tumbada en el suelo sobre el abdomen, encarada hacia la superficie de
apoyo.");
INSERT INTO keywords (name, description) VALUES ("Prono sentado", "Posición de media bipedestación, donde un alto plinto sirve de soporte al tronco, la cabeza y los miembros superiores. Las caderas
están normalmente en un ángulo de 90°, si bien ello depende de cada paciente.
Observación clínica Esta posición puede ser utilizada cuando se está tratando a pacientes neurológicos. Es una posición de gran
utilidad, en la que el peso de la parte superior del cuerpo es soportado por el plinto y, por tanto, permite al terapeuta concentrarse en la
pelvis y la cadera.");
INSERT INTO keywords (name, description) VALUES ("Pronóstico", "Resultado o trayectoria probable de una enfermedad. Los factores pronósticos son las características del paciente o de la enfermedadque influyen en el transcurso de ésta. Un buen pronóstico se asocia con una baja frecuencia de resultados indeseables; un mal
pronóstico está asociado con una alta frecuencia de resultados indeseables.");
INSERT INTO keywords (name, description) VALUES ("Propiocepción", "Mecanismo de feedback que permite cobrar conciencia de la posición en el espacio de nuestro cuerpo o parte de éste. Es esencial
para el equilibrio y la función normal y se consigue a través de diversos medios.
Hay muchos receptores dentro de las articulaciones, músculos y la piel que transmiten continuamente la información al sistema nervioso
central (SNC). Usando esta información, hacemos continuamente modificaciones conscientes e inconscientes de cómo nos movemos,
lo que nos permite llevar a cabo una actividad funcional normal. Cada receptor proporciona un tipo diferente de información (p. ej.,
presión intraarticular, aceleración/deceleración articular y velocidad articular). Cuando los receptores son estimulados por el movimiento
u otras fuerzas, actúan como transductores y convierten esta deformación mecánica en un impulso eléctrico. El impulso sensorial luego
pasa al SNC provocando una respuesta motora adecuada.
Cuando caminamos sobre un terreno irregular, los músculos del pie y el tobillo tienen que ir continuamente ajustándose para mantener el
cuerpo vertical y prevenir una caída. Los músculos peroneo y tibial anterior, por ejemplo, estarán continuamente controlando el
movimiento del pie y el tobillo, respondiendo a cambios posturales continuos. La propiocepción es un proceso continuo que ocurre en
diferentes niveles del SNC al mismo tiempo.
Si pensamos en todas las tareas potenciales que podemos llevar a cabo mientras caminamos (p. ej., llevar una mochila, usar un bastón,
pasear al perro, etc.), veremos que todas estas tareas estarán bombardeando el SNC con todo tipo de información aferente.
Imaginemos que las respuestas a esta información fuesen todas a nivel consciente: la marcha sería de lo más lenta.");
INSERT INTO keywords (name, description) VALUES ("Representación mediante un diagrama del mecanismo de propiocepción", "Esto es un punto clave que debemos tener en cuenta cuando aplicamos un tratamiento de rehabilitación a un paciente con
propiocepción deficiente: muchas acciones necesitan funcionar a nivel subconsciente.
De: Mason D, Kilmurray S 2003. En: Porter S (ed.). Tidy's physiotherapy, 13 th ed. Elsevier Ltd., Edinburgh.
Observación clínica Los pacientes con propiocepción escasa o ausente tienden a confiar mucho en otros sentidos (a menudo la
visión) y a menudo tienen que mirarse los pies cuando caminan para compensar. Por tanto, tendrán dificultad para moverse en la
oscuridad.");
INSERT INTO keywords (name, description) VALUES ("Propiocepción articular", "Conciencia de las articulaciones en el espacio. Se suele valorar pidiéndole al paciente que cierre los ojos; a continuación el terapeuta
coloca el miembro alterado en una posición y el paciente trata de hacer lo mismo con el otro miembro. Está normalmente alterada en
pacientes neurológicos.Prostaglandina
Sustancia potente que se encuentra en muchos tejidos, producida en respuesta a un traumatismo. Puede afectar a la presión sanguínea y
al metabolismo, así como a la actividad de la musculatura lisa.");
INSERT INTO keywords (name, description) VALUES ("Proteína de fase aguda", "Mediador químico que es segregado en respuesta al daño tisular.");
INSERT INTO keywords (name, description) VALUES ("Prótesis", "Dispositivo utilizado para reemplazar una parte ausente del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Prótesis de Neer", "Tipo de artroplastia de hombro.");
INSERT INTO keywords (name, description) VALUES ("Protocolo", "Proceso estándar que es utilizado repetidas veces para asegurar que un experimento (o actividad similar) se realiza siempre de la misma
manera.");
INSERT INTO keywords (name, description) VALUES ("Proximal", "Próximo al esqueleto axial.");
INSERT INTO keywords (name, description) VALUES ("Prueba de »peloteo« de la rótula", "Test empleado para determinar la presencia de un derrame en la articulación de la rodilla. Se realiza con el paciente en decúbito supino.
Cualquier exceso de fluido será exprimido de la bolsa suprarrotuliana mediante el deslizamiento del dedo índice y el pulgar desde 15 cm
por encima la rótula hasta el nivel del borde superior de ésta. A continuación se coloca la yema del pulgar y de tres dedos de la mano
libre directamente en la rótula y se empuja hacia abajo rápidamente.
Resultado anormal Un sonido de tipo »click« indica derrame. Los datos del test serán negativos si el derrame es grande y existe tensión;
por ejemplo, una hemartrosis de la rodilla (sangre dentro de la articulación) consecutiva a una rotura del ligamento cruzado anterior.");
INSERT INTO keywords (name, description) VALUES ("Prueba de »peloteo« de la rótula", "");
INSERT INTO keywords (name, description) VALUES ("Pruebas de esfuerzo", "Estas pruebas proporcionan información valiosa relativa a las capacidades de los sistemas cardiorrespiratorios para cubrir los
incrementos en las demandas del intercambio de gas y el transporte de oxígeno durante los niveles aumentados de actividad, de la
capacidad del sistema musculoesquelético para generar esfuerzo y actividad muscular y de la capacidad para soportar las necesidades
adicionales en el tiempo. Estas pruebas pueden administrarse en numerosos formatos, incluyendo prueba con tapiz rodante y prueba
con cicloergonómetros, prueba en campo de marcha, como las prue bas de marcha de 6 y 12 min, prueba de lanzamiento andando ylanzamiento corriendo, etc.
Las pruebas tienen por objetivo la detección de limitaciones en la actividad, identificación de los niveles de actividad que producen
signos y síntomas, obtención de valores basales para permitir la revalorización y observación de la progresión o regresión en respuesta
a una intervención, y elaboración de la base para una prescripción de ejercicio individualizada.");
INSERT INTO keywords (name, description) VALUES ("Prurito", "Picor, sensación desagradable que provoca el deseo de frotar o rascar la piel para obtener alivio.");
INSERT INTO keywords (name, description) VALUES ("PS", "Abreviatura médica común que corresponde a presión sanguínea.");
INSERT INTO keywords (name, description) VALUES ("Pseudomonas aeruginosa", "Especie de bacterias en forma de bacilo, comúnmente aisladas de muestras clínicas (heridas, quemaduras e infecciones del tracto
urinario).");
INSERT INTO keywords (name, description) VALUES ("Psicología", "Estudio del proceso mental y el comportamiento de los seres humanos y los animales.");
INSERT INTO keywords (name, description) VALUES ("Psoriasis", "Condición crónica común caracterizada por la presencia de manchas secas, eritematosas y redondeadas cubiertas por escamas blancas
grisáceas, que tienden a aparecer en las superficies extensoras del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Ptosis", "Caída de los párpados.");
INSERT INTO keywords (name, description) VALUES ("Puerperio", "Período que abarca las 6 semanas posteriores al parto. Algunos sistemas anatómicos vuelven al estado anterior al embarazo mientras
que se inician cambios como la lactancia. Durante este período el útero involuciona (vuelve al tamaño y posición anteriores al
embarazo). Como el lugar de la placenta cicatriza y el endometrio se regenera, la mujer experimenta una descarga (loquios),
inicialmente cruenta, pasadas 8 semanas (Brook y cols., 2003).");
INSERT INTO keywords (name, description) VALUES ("Puesta en tensión del nervio femoral", "Véase Neurodinámica.
El paciente se coloca en decúbito prono. El fisioterapeuta flexiona la rodilla del paciente y después extiende la cadera.
Resultado anormal El dolor en la espalda o en la zona de distribución del nervio femoral indica irritación nerviosa femoral. Se realiza una
comparación con el otro lado.");
INSERT INTO keywords (name, description) VALUES ("Pulso paradójico", "Pulso débil que se observa durante la inspiración espontánea. Está asociado con problemas tanto respiratorios como cardíacos; por
ejemplo, cuando hay restricción de la acción de bombeo del miocardio y patologías pulmonares obstructivas agudas (p. ej., asma).Puntos de pulso");
INSERT INTO keywords (name, description) VALUES ("Pulsos alternantes", "Pulso anormal asociado con fallo cardíaco izquierdo, caracterizado por una serie de latidos fuertes y rápidos, seguidos de una serie de
latidos débiles.");
INSERT INTO keywords (name, description) VALUES ("Punción lumbar", "Consiste en la inserción de una aguja en el fluido interno del canal espinal. Se usa para analizar el líquido cefalorraquídeo. Se usa en el
diagnóstico de muchas condiciones neurológicas; por ejemplo, en la hemorragia subaracnoidea (HSA) se dice que es xantocrómico si
hay presencia de sangre, lo que confirma la HSA, y en la esclerosis múltiple revela la producción local de inmunoglobulina en el sistema
nervioso central.");
INSERT INTO keywords (name, description) VALUES ("Punto de igual presión", "Punto dentro de las vías aéreas donde las presiones de los conductos aéreos y la presión pleural son iguales. Este concepto se usa en la
aplicación de la técnica de espiración forzada (TEF) para facilitar la expulsión de las secreciones pulmonares (v. TEF) (West, 1982).");
INSERT INTO keywords (name, description) VALUES ("Punto gatillo miofascial", "Se trata de puntos muy localizados de hiperirritabilidad dentro del músculo esquelético. Producen dolor local, dolor referido y
frecuentemente acompañan a trastornos musculoesqueléticos crónicos. Los microtraumatismos repetidos pueden dar lugar al desarrollode estrés en fibras musculares y a la formación de puntos gatillo. Los pacientes a menudo sufren un dolor persistente que da como
resultado una disminución del rango del movimiento en los músculos afectados. Puede afectar a los músculos utilizados para el
mantenimiento de la postura corporal, como los de cuello, hombros y cintura pélvica. Los puntos gatillo pueden también manifestarse
como cefalea tensional, tinnitus, dolor en la articulación temporomandibular, disminución del rango de movimiento en las piernas y
dolor en la zona lumbar. En la palpación de un punto gatillo es frecuente encontrarse con nódulos de fibras musculares cuya consistencia
tiende a ser más dura de lo normal (Alvarez y Rockwell, 2002).");
INSERT INTO keywords (name, description) VALUES ("Punto motor", "Punto de un músculo o vientre muscular por el que el músculo recibe la inervación del nervio motor. La pauta normal es que se halle en
la unión entre los tercios medio y superior del cuerpo muscular. El umbral para la estimulación eléctrica en el punto motor es más bajo
que en otro lugar del músculo. Se usa clínicamente como el lugar de colocación del electrodo activo cuando se emplean técnicas de
estimulación unipolar y durante la realización de la curva intensidad-tiempo.");
INSERT INTO keywords (name, description) VALUES ("Puntos clave de control", "Fueron descritos por Bobath (1990) como áreas del cuerpo desde las que se puede controlar, de la manera más fácil, el movimiento.
Un punto en la región torácica superior se describe como el punto clave central; las cinturas pélvica y escapular son consideradas como
los puntos clave proximales, y las manos y los pies como puntos clave distales.");
INSERT INTO keywords (name, description) VALUES ("Puntos de Cloward", "Áreas de dolor referido en la columna dorsal, cerca de la escápula, a menudo en asociación con alteraciones degenerativas de la
columna cervical.");
INSERT INTO keywords (name, description) VALUES ("Puntuación PAE", "Puntación de la actividad de la enfermedad. Es una herramienta útil para medir la actividad de la enfermedad en una escala de 1 a 10
basada en el número de articulaciones entumecidas y sensibles y en la velocidad de sedimentación globular (VSG).");
INSERT INTO keywords (name, description) VALUES ("Punzada en la cadera", "Contusión de la cresta ilíaca. Normalmente debida a algún tipo de traumatismo.Q");
INSERT INTO keywords (name, description) VALUES ("Q (perfusión)", "Flujo sanguíneo determinado por el gasto cardíaco.");
INSERT INTO keywords (name, description) VALUES ("QAA", "Quality Assurance Agency. Cuerpo responsable de garantizar estándares académicos en educación superior mediante inspección e
informes, así como de emitir comunicados profesionales de referencia.
q.d.
Abreviatura médica común de »cada día« (quotidie).
q.i.d.
Abreviatura médica común de »cuatro veces al día« (quater in die).
q.o.d.
Abreviatura médica común »de cada dos días«.");
INSERT INTO keywords (name, description) VALUES ("Queloide", "Tejido cicatricial aumentado en el lugar de una lesión cutánea.");
INSERT INTO keywords (name, description) VALUES ("Quemadura", "Lesión del tejido corporal causada por exposición a electricidad, productos químicos, fuego, radiación o gases calientes. Se clasifican
como sigue:
• Quemadura de primer grado. Superficial y con características similares a una quemadura solar; la piel tiene un color rojizo y la
sensibilidad está intacta.
• Quemadura de segundo grado. Similar a la de primer grado, pero cursa con la aparición de ampollas y dolor normalmente más
intenso.
• Quemaduras de tercer grado. Lesión que ha progresado hasta el punto de muerte cutánea. La piel está blanca y con pérdida de la
sensibilidad.
Un método para calibrar el área corporal total es »la regla del 9«. Se divide la superficie corporal en 11 áreas, y cada una de ellas
constituye el 9% del total. El periné cuenta como el 1%. También pueden ser utilizados otros mapas como por ejemplo el mapa de
Lund y Browder.
Véase Área de superficie total quemada.");
INSERT INTO keywords (name, description) VALUES ("Queratina", "Proteína que es el principal constituyente de pelo, uñas y piel.");
INSERT INTO keywords (name, description) VALUES ("Queratodermia blenorrágica", "Pústulas y costras asociadas con el síndrome de Reiter (un tipo de artritis reactiva).");
INSERT INTO keywords (name, description) VALUES ("Quilotórax", "Acumulación o derrame de quilo en el tórax, después de una lesión del conducto torácico.");
INSERT INTO keywords (name, description) VALUES ("Quimiorreceptor", "Receptor sensorial que responde a una sustancia química.");
INSERT INTO keywords (name, description) VALUES ("Quimiotaxis", "Proceso por el que células fagocíticas son atraídas a una sustancia, y después siguen el gradiente de concentración desde un área de
baja concentración hacia otra de alta concentración.
Se sabe que ciertos factores químicos estimulan la quimiotaxis de leucocitos, como por ejemplo el factor activador plaquetario (PAF)anafilatoxina C5a y el leucotrieno B 4 (LTB 4 ).");
INSERT INTO keywords (name, description) VALUES ("Quimioterapia", "Tratamiento de una enfermedad mediante agentes químicos; normalmente se refiere al tratamiento del cáncer.");
INSERT INTO keywords (name, description) VALUES ("Quiste de Baker (también conocido como quiste poplíteo)", "Bursitis del semimembranoso o de la bolsa del gastrocnemio medial. A menudo se presenta como una masa blanda en la parte posterior
de la rodilla.
Quiste de Baker. Nuestro agradecimiento a Harry Clifford ArlowR");
INSERT INTO keywords (name, description) VALUES ("Rabdomiólisis", "Excreción de mioglobina en la orina como resultado de un proceso de degeneración muscular.");
INSERT INTO keywords (name, description) VALUES ("Racionalización del material", "Proceso por el cual se racionan los recursos, restringiendo el acceso al material o a los servicios. Por ejemplo, los médicos de cabecera
gestionarían los servicios médicos especializados, y los fisioterapeutas las sillas de ruedas y otros materiales.");
INSERT INTO keywords (name, description) VALUES ("Racismo", "Tratamiento desigual y discriminación institucional experimentada por grupos de personas basados en el aspecto físico y en otras
características socialmente definidas que designan una raza particular o minoría étnica.");
INSERT INTO keywords (name, description) VALUES ("Radiación infrarroja (RIR)", "La radiación infrarroja es una forma de radiación electromagnética que se sitúa en el espectro electromagnético entre la luz visible y las
microondas. Las longitudes de onda se encuentran entre 760 nm y 1,0 mm y se subdividen en:
Existen focos naturales y artificiales, aunque a efectos terapéuticos el foco artificial es el habitual. Se utilizaba anteriormente de forma
amplia en terapia, pero es mucho menos común en la actualidad. Los generadores de infrarrojos pueden ser «luminosos» o «no
luminosos» La salida del espectro del foco no luminoso es de 760-15.000 nm (normalmente con pico en 4.000 nm). El generador
luminoso tiende a producir un espectro con longitud de onda más corta de RIR y también produce alguna emisión visible. El espectro
de emisión se encuentra normalmente entre 350-4.000 nm (con pico en 1.200 nm). La bombilla roja (que es común) filtra las luces
visibles cortas y UV, por lo que el paciente está expuesto a RIR y a luz roja visible.
La radiación cerca del RIR (p. ej., 1.200 nm, foco luminoso) penetra en la dermis (pocos milímetros).
El RIR lejano (> 1.200 nm, foco no luminoso) puede solamente penetrar hasta la superficie de la epidermis (1 mm o menos). Las ondas
EM penetran en el tejido y son absorbidas, y como resultado de la absorción se genera calor en los tejidos. Los efectos terapéuticos
del infrarrojo incluyen: alivio del dolor, relajación muscular y un aumento del flujo sanguíneo local.");
INSERT INTO keywords (name, description) VALUES ("Radiación ultravioleta (UV)", "Término electroterápico que se aplica a una radiación electromagnética. Existen tres tipos de radiaciones ultravioleta (UVA, UVB y
UVC), según su longitud de onda; de ahí las diferencias en sus efectos y por tanto en sus usos clínicos. La radiación UVA tiene una
longitud de onda de 400-315 nm, también se denomina UV de onda larga y se utiliza con sensibilizadores (p. ej., psoraleno, método
PUVA, etc.) para el tratamiento de la psoriasis. Es el principal componente de la radiación UV solar. La radiación UVB tiene unalongitud de onda de 315-280 nm; se denomina también radiación UV media, y provoca eritema. Es la principal causante de los daños
en la piel provocados por el sol. La radiación UVC tiene una longitud de onda de 280-100 nm; también se denomina radiación UV de
onda corta o abiótica, y se utiliza en el tratamiento de heridas. Su principal efecto es bactericida, y no interviene en las radiaciones UV
solares, ya que se absorbe en la capa de ozono.");
INSERT INTO keywords (name, description) VALUES ("Radiculopatía", "Daño o inflamación de los nervios periféricos y raíces espinales, acompañada de debilidad y entumecimiento.");
INSERT INTO keywords (name, description) VALUES ("Radio y cúbito", "Los dos huesos del antebrazo.
Huesos del antebrazo: (A) visión posterior; (B) visión anterior");
INSERT INTO keywords (name, description) VALUES ("Radiografía horizontal", "Tipo de visión radiográfica que muestra la rótula entre los cóndilos femorales; es útil para detectar una posible mala alineación de la
rótula.");
INSERT INTO keywords (name, description) VALUES ("RAFI", "Abreviatura médica común de reducción abierta con fijación interna. La intervención quirúrgica para poner una placa y tornillos en una
fractura se conoce como reducción abierta y fijación interna; a menudo se abrevia como RAFI.");
INSERT INTO keywords (name, description) VALUES ("Ventajas", "• Permite una inspección detallada y una valoración quirúrgica apropiada del lugar de la lesión y del procedimiento que debe llevarse a
cabo.");
INSERT INTO keywords (name, description) VALUES ("Desventajas", "• La cirugía inevitablemente causará traumatismos adicionales y una exposición potencial a microorganismos.
• Puede convertir una fractura cerrada en una fractura abierta.
• Como toda cirugía, conlleva secuelas y complicaciones potenciales.
Paradojicamente, las fijaciones rígidas pueden eliminar el estímulo para la formación del callo.
Los implantes se podrán quitar a los 12-18 meses o en caso de complicaciones (p. ej., el tornillo puede provocar irritación).Se quitarán en los pacientes jóvenes porque, mientras están colocados, el hueso no crecerá ni responderá al estrés con normalidad,
dado que éste es soportado por los propios implantes.
Fijación interna en reducción abierta (radiografía) de una fractura de tibia y peroné");
INSERT INTO keywords (name, description) VALUES ("Raíz posterior", "Grupo de axones sensitivos, desde el nervio espinal, que se unen a la parte posterior de la columna vertebral.");
INSERT INTO keywords (name, description) VALUES ("Rampa", "En el contexto electroterápico, se aplica a la relación del cambio en la amplitud de una serie de impulsos o ráfagas de impulso. La
rampa ascendente indica que la amplitud está aumentando y la rampa descendente que está descendiendo.");
INSERT INTO keywords (name, description) VALUES ("Rango de movimiento articular", "Valores normales.");
