INSERT INTO keywords (name, description) VALUES ("Flexión interfalángica proximal 100°", "");
INSERT INTO keywords (name, description) VALUES ("Flexión interfalángica distal 80-90°", "");
INSERT INTO keywords (name, description) VALUES ("Rayos X", "Radiografías simples, normalmente tomadas cuando hay historia de traumatismo, para excluir fracturas. También se usan para confirmar
procesos de enfermedades degenerativas.");
INSERT INTO keywords (name, description) VALUES ("Razón o cociente ventilación/perfusión (V/P)", "Es la razón entre la ventilación alveolar y el flujo sanguíneo (perfusión). En el individuo normal, esta razón es aproximadamente del 80%,
ya que varía de un punto a otro del pulmón. Éste es un importante factor determinante que afecta a la presión parcial de O 2 y CO 2 en la
sangre arterial.
En la posición normal vertical del pulmón, debido a los efectos de la gravedad, aumentan los gradientes de perfusión y ventilación del
ápex a la base. La ventilación aumenta hacia la base de los pulmones, ya que en este punto se intercambia más volumen con cada
respiración que en el ápex del pulmón (donde existe un volumen de inflación en reposo mayor), mientras que el efecto de gravedad en
el peso de la columna de sangre en los vasos aumenta la perfusión en la base. Por supuesto, ésta se modifica si varía la posición del
cuerpo; así, la posición puede emplearse para corregir un cociente V/P inadecuado (p. ej., drenaje postural para eliminar secreciones
excesivas o un posi-cionamiento adecuado para facilitar el reinflado de segmentos o lóbulos pulmonares atelectásicos).");
INSERT INTO keywords (name, description) VALUES ("Reacción adversa", "Efectos indeseados de la medicación u otra terapia; por ejemplo, una persona en la que aparece un sarpullido después de haber
tomado antibióticos ha sufrido una reacción adversa.");
INSERT INTO keywords (name, description) VALUES ("Reacción alérgica", "Respuesta del cuerpo a un estímulo alérgico. Puede ser localizada o generalizada y puede incluir sarpullido, picor y tumefacción; la
reacción puede también ser mucho más grave.");
INSERT INTO keywords (name, description) VALUES ("Reacción de apoyo positivo", "Término empleado por Magnus en 1926 para describir una respuesta a través de la cual la pierna se transforma en un pilar rígido.
Cuando el paciente intenta aguantar el peso con la pierna afectada se observa un patrón complejo de flexión plantar e inversión del pie.
Observación clínica La presencia de una reacción de apoyo positivo puede llevar al acortamiento del tejido blando del pie y la pierna
afectados y puede interferir en las actividades funcionales, como andar y pasar de sentado a de pie. Se puede emplear una inyección
local de toxina botulínica para obtener un buen efecto a corto plazo, mientras que las técnicas manuales pueden funcionar para
recuperar longitud en los grupos musculares acortados (Magnus, 1926).");
INSERT INTO keywords (name, description) VALUES ("Reacción de enderezamiento", "Reacciones automáticas que se producen en respuesta a la alteración del alineamiento corporal, destinadas al mantenimiento y
restablecimiento de la posición de la cabeza en la línea media y con una relación normal respecto al tronco y los miembros. Pueden
observarse en el niño en desarrollo, pero en el adulto normalmente es difícil distinguirlas de las reacciones de equilibrio.");
INSERT INTO keywords (name, description) VALUES ("Reacción de Lewis", "Véase Crioterapia.");
INSERT INTO keywords (name, description) VALUES ("Reacciones asociadas", "Este término fue utilizado por Walshe (1923) para describir reacciones posturales de músculos fuera del control neurológico normal.
Aparecen como patrones de movimiento involuntario estereotipado, como por ejemplo, el brazo se flexiona, aduce y rota internamente.Normalmente se producen cuando a un paciente le cuesta un gran esfuerzo realizar una tarea o encuentra dificultades al intentar
mantener el equilibrio; sin embargo, también pueden ocurrir cuando el paciente estornuda o bosteza.");
INSERT INTO keywords (name, description) VALUES ("Reacciones de equilibrio", "Pequeños cambios involuntarios en el tono o en los movimientos que tienen lugar para permitir el equilibrio. Por ejemplo, cuando se
eleva el brazo hay un aumento en la actividad de los extensores de la espalda para estabilizar el tronco. A veces están alteradas en las
patologías neurológicas.");
INSERT INTO keywords (name, description) VALUES ("Receptores intrapulmonares", "Receptores localizados en los pulmones que facilitan la regulación de la respiración; por ejemplo, los receptores J, que detectan el
estiramiento.");
INSERT INTO keywords (name, description) VALUES ("Receptores yuxtacapilares", "Son receptores de estiramiento localizados en el parénquima pulmonar, cerca de los capilares pulmonares, estimulados por pro-cesos
inflamatorios, congestión y edema. La taquipnea, la disnea y el estrechamiento glótico son resultado del estímulo de estos receptores.");
INSERT INTO keywords (name, description) VALUES ("Rechazo al discapacitado", "Creencias negativas y estereotipadas acerca de las personas discapacitadas, que pueden conducir a su discriminación. El rechazo a las
personas discapacitadas lleva frecuentemente a la no adecuación de los servicios necesarios y a una falta de igualdad de oportunidades
en comparación con el resto de ciudadanos.");
INSERT INTO keywords (name, description) VALUES ("Recuento sanguíneo completo (RSC)", "Cálculo de los elementos celulares de la sangre.");
INSERT INTO keywords (name, description) VALUES ("Reducción", "Colocación de una fractura o dislocación en su alineamiento correcto. El término también se usa para describir la recolocación de una
dislocación protésica articular.");
INSERT INTO keywords (name, description) VALUES ("Reducción absoluta de riesgo", "Término de investigación que se refiere a la diferencia en la frecuencia de presentación del acontecimiento estudiado entre dos grupos
en un estudio comparativo: el grupo control (GC) y el grupo tratado (GT):");
INSERT INTO keywords (name, description) VALUES ("Reducción de fracturas", "Realineamiento hacia una posición anatómicamente normal. La reducción puede ser de una fractura abierta o cerrada.
No se utilizan medios quirúrgicos para la reducción de una fractura cerrada, sino que es tratada manualmente con anestesia general o
local.
Para la reducción de la fractura abierta se emplean medios quirúrgicos para abrir y reducir. La reducción no siempre es necesaria
incluso cuando hay desplazamiento; por ejemplo, las fracturas de la clavícula cicatrizarán con un bulto que únicamente será un problema
de tipo estético.");
INSERT INTO keywords (name, description) VALUES ("Reemplazo articular (artroplastia)", "No existe un paciente típico que sea apropiado para el reemplazo articular. Como en toda la medicina moderna, la decisión debe
adoptarse sopesando los riesgos de la cirugía frente a las mejoras potenciales. La edad del paciente es una herramienta clínica
inaceptable para la toma de decisiones. Generalmente, el equipo quirúrgico esperará hasta que el dolor o la discapacidad sean losuficientemente graves como para causar un impacto significativo en la calidad de la vida de la persona; en este caso, la cirugía hará que
la situación mejore considerablemente o prevendrá un deterioro mayor. Es bastante factible, por ejemplo, sustituir las caderas de una
persona de 16 años con artritis reumatoide grave. En la práctica, una articulación artificial aún no es tan eficiente como una orgánica. Si
una articulación sintética se desgasta o se daña, no se repara por sí misma como lo hace una articulación normal. Tampoco será tan
eficiente en la absorción del estrés y fuerzas de las actividades de la vida diaria como una articulación orgánica. Sin embargo, en el
campo de las prótesis articulares se están realizando notables avances.");
INSERT INTO keywords (name, description) VALUES ("REF", "Abreviatura médica común de relación espiratoria forzada.
Es un término espirométrico utilizado para detallar la relación entre FEV 1 y FVC. Esta relación sirve para diagnosticar enfermedades
pulmonares restrictivas, obstructivas y combinadas. Cuando la relación es < 70% se diagnostica la obstrucción del flujo aéreo.
Véase Espirometría.");
INSERT INTO keywords (name, description) VALUES ("Referencia", "Indicación clara en un trabajo de que una de las fuentes proviene del trabajo de otras personas.");
INSERT INTO keywords (name, description) VALUES ("Referencia secundaria (cita)", "Cuando la fuente del material es tomada de una referencia usada en otro trabajo, es decir, sin llegar a la referencia primaria original. Es
desaconsejable en tareas académicas.");
INSERT INTO keywords (name, description) VALUES ("Referencia de Harvard", "Estilo de referencia utilizado en un trabajo académico, en el que operan protocolos estrictos. El nombre de los autores precede al texto,
y va seguido del año de publicación, y las referencias se nombran alfabéticamente en una lista al final del trabajo. Es el sistema utilizado
en la revista profesional Physiotherapy y en los cursos de fisioterapia.");
INSERT INTO keywords (name, description) VALUES ("Referencia lega", "Proceso por el que aquellos que presentan signos y síntomas de enfermedades o patologías buscan el consejo de personas legas en el
tema (p. ej., familiares y amigos) en lugar de acudir al médico. Si se acude al médico, puede que el paciente recurra al sistema de
referencia lega para evaluar el consejo médico recibido.");
INSERT INTO keywords (name, description) VALUES ("Reflejo", "Reacción automática a cierta clase de estímulos.");
INSERT INTO keywords (name, description) VALUES ("Reflejo tendinoso profundo", "Todos los músculos tienen un reflejo tendinoso profundo, de modo que, cuando se golpea repentinamente el músculo o tendón, aparece
una contracción refleja. Se trata de reflejos monofásicos que sirven para comprobar la integridad del sistema nervioso.Raíces nerviosas y columna vertebra");
INSERT INTO keywords (name, description) VALUES ("Análisis de los reflejos", "• Reflejo disminuido/hipoactivo. Puede indicar problemas de compresión de la raíz nerviosa.
• Reflejo aumentado/hiperactivo. Puede indicar un componente de la neurona motora superior.
Nivel de la raíz C5-C6. Reflejo del bícepsNivel de la raíz C7-C8. Reflejo del tríceps
La alteración refleja no puede ser utilizada como evidencia completa de anormalidad del sistema nervioso, pero debería emplearse junto
con otros hallazgos neurológicos objetivos. Véanse las siguientes figuras para una ilustración de los reflejos tendinosos comunes.
Nivel de la raíz L3-L4. Reflejo del tendón patelar
Nivel de la raíz S1-S2. Reflejo del tendón de AquilesReflejo de Babinski (también conocido como respuesta plantar)
Es una respuesta anormal que tiene lugar cuando un objeto punzante roza el lateral de la planta del pie:
• Un resultado normal sería que el dedo gordo se flexione.
• Un resultado anormal sería que el dedo gordo se extienda; esto indica lesión de motoneurona primaria.
Observación clínica Este reflejo primitivo se ve en los recién nacidos, pero desaparece con el tiempo.");
INSERT INTO keywords (name, description) VALUES ("Reflejo de flexión (también conocido como reflejo de retirada)", "Cuando se aplica un estímulo nocivo a un brazo o pierna, el miembro se retira automáticamente como mecanismo de protección: los
músculos flexores se contraen al mismo tiempo que los extensores se relajan. Puede extenderse de forma simultánea del miembro
opuesto, lo cual se conoce como reflejo de extensión cruzada (Davies y cols., 2001).Reflejo de flexión (retirada) al estímulo nocivo");
INSERT INTO keywords (name, description) VALUES ("Reflejo de Hering-Breuer", "Reflejo inspiratorio inhibitorio iniciado por el sobreestiramiento o estiramiento de los receptores en la musculatura lisa de las vías aéreas
grandes y pequeñas. Este reflejo se activa solamente por volúmenes corrientes grandes (alrededor de 900 ml), por lo que no es
importante en la respiración corriente silenciosa, pero es vital para la regulación de la respiración en el ejercicio moderado o intenso.");
INSERT INTO keywords (name, description) VALUES ("Reflejo de náuseas", "También conocido como reflejo faríngeo. Consiste en una contracción involuntaria de la faringe y una elevación del paladar blando para
proteger el conducto aéreo. Puede estar alterado en algunas patologías neurológicas y se asocia con disfagia.");
INSERT INTO keywords (name, description) VALUES ("Reflejo de prensión", "Cuando se toca la palma de la mano, se induce un reflejo flexor; se puede ver en la infancia, en pacientes con lesión neurológica y en
pacientes ancianos con demencia.");
INSERT INTO keywords (name, description) VALUES ("Reflejo profundo del tendón", "Véase Reflejos.");
INSERT INTO keywords (name, description) VALUES ("Reflejos laberínticos de enderezamiento", "Estimulación de los propioceptores laberínticos que causa una contracción de los músculos del cuello, haciendo que la cabeza regrese a
su posición natural en el espacio.");
INSERT INTO keywords (name, description) VALUES ("Refuerzo funcional (escayola de refuerzo)", "Los refuerzos funcionales tienen bisagras para permitir el movimiento. Los tejidos blandos del miembro quedan perfectamente
comprimidos por la escayola; el uso conjunto de una talonera permite que el peso se reparta a través de todo el refuerzo. Esto ha
reducido muchos de los problemas que resultaban de la inmovilización prolongada. Otro beneficio de permitir el movimiento de las
articulaciones es el hecho de que, al no estresar excesivamente el lugar de fractura, puede promover la unión, mejorando el área de
aporte sanguíneo.Refuerzo funcional. Fotografía cortesía de M ike Somervell y Julie Butler, Senior Occupational Therapists");
INSERT INTO keywords (name, description) VALUES ("Regeneración neuronal", "Proceso de regeneración del nervio en respuesta a una herida o lesión.");
INSERT INTO keywords (name, description) VALUES ("Registro", "Requerimiento para todos los profesionales de la salud que trabajan en la NHS, incluyendo fisioterapeutas, de estar en el registro del
Health Professions Council (HPC) como medida de protección de la población.");
INSERT INTO keywords (name, description) VALUES ("Regla de los nueves", "Véase Quemadura.");
INSERT INTO keywords (name, description) VALUES ("Reglas de conducta profesional", "En el Reino Unido, las reglas de conducta profesional fueron aprobadas en la primera reunión del consejo de la Chartered Society of
Physiotherapists (CSP) en 1895 (Barclay J, 1994. In Good Hands: History of the Chartered Society of Physiotherapists, 1984-94.
Butterworth-Heinemann) y han sido revisadas y adaptadas en distintas ocasiones desde entonces. Las reglas de conducta profesional
fijaron un marco para las bases legales, éticas y morales de la profesión, explicitando la conducta esperada por parte de fisioterapeutas
y estudiantes. Las reglas actuales (consúltese
www.csp.org.uk) marcan un cierto número de principios cuya base común es
salvaguardar al paciente. Incluyen una serie de requisitos para el fisioterapeuta:
• Respetar la dignidad y sensibilidad individual de cada paciente.
• Trabajar de forma segura y competente.
• Asegurar la confidencialidad de la información del paciente.
• Informar de las circunstancias que puedan poner al paciente en peligro.
• No explotar al paciente.
• Actuar de forma que refleje la credibilidad de la profesión y no causar ofensa al paciente.
Aunque la Sociedad ha tenido reglas de conductas profesionales desde sus principios, los Standards of Physiotherapy Practice no
fueron publicados hasta 1990. Esto proporciona declaraciones sobre la aplicación práctica de los principios éticos dispuestos en las
reglas. La tercera edición (CSP, 2000 ) ha evolucionado poniendo énfasis en los siguientes puntos:
• Los profesionales deben involucrar a los pacientes en la toma de decisiones.
• Deben disponer continuamente de información actualizada acerca de la efectividad de los diversos tratamientos para poder informar a
los pacientes y proponerles las intervenciones más eficaces.
• Deben evaluar su propio trabajo y medir la mejoría en la salud del paciente como resultado del tratamiento aplicado.");
INSERT INTO keywords (name, description) VALUES ("Regresión", "Término de investigación que se aplica a las técnicas estadísticas relacionadas con la predicción de una variable conociendo las otras.
La regresión se usa para responder preguntas como ¿con qué fiabilidad podemos predecir los valores de una variable (como la
supervivencia) conociendo los valores de otras variables (como la técnica de tratamiento)?Regurgitación mitral
Lesión más común de la enfermedad cardíaca reumática. Las alteraciones en las cuerdas tendinosas del corazón y en el músculo papilar
de una o ambas cúspides, o la dilatación del anillo valvular, provocan que la válvula permanezca abierta durante la sístole. Una válvula
cerrada de manera incompleta permite el reflujo de sangre desde el ventrículo izquierdo a la aurícula izquierda durante la sístole (Moore,
2003).");
INSERT INTO keywords (name, description) VALUES ("Rehabilitación", "Proceso limitado en el tiempo cuyo propósito es devolver a una persona su máximo nivel de funcionamiento físico, mental y social.
Puede orientarse a la recuperación de la función o a la compensación de la pérdida funcional, o proporcionar al paciente las
herramientas para suplir su cambio en la función.");
INSERT INTO keywords (name, description) VALUES ("Rehabilitación cardíaca", "Amplia forma de tratamiento para personas con enfermedad cardíaca. Pretende restablecer totalmente los estados físico, psicológico y
social, y promover y llevar a cabo una prevención secundaria para lograr un pronóstico óptimo y duradero.");
INSERT INTO keywords (name, description) VALUES ("Rehabilitación vestibular", "Tipo de rehabilitación indicado para personas que padecen vértigo (v. Vértigo). Los fisioterapeutas pueden ayudar en la rehabilitación
vestibular, valorando los problemas y prescribiendo ejercicios específicos como los de Cawthorne Cooksey, así como actividades para
aumentar la independencia.
Observación clínica En la valoración de los pacientes se debe distinguir entre desencadenantes de posición y desencadenantes de
movimiento. Los problemas periféricos responden mejor a estos ejercicios de habituación; en el caso del vértigo central, normalmente
tienen un éxito limitado.");
INSERT INTO keywords (name, description) VALUES ("Relación de datos", "Término de investigación que se aplica a los datos continuos cuyas diferencias y relaciones son interpretables. La relación de datos tiene
un «cero natural». Un buen ejemplo es el peso en kilogramos en el momento del nacimiento.");
INSERT INTO keywords (name, description) VALUES ("Relación de Frank-Starling", "Según esta relación, cuanto mayor sea el grado de tensión en las fibras miocárdicas al final de la diástole, más fuerte será la contracción
miocárdica subsiguiente.");
INSERT INTO keywords (name, description) VALUES ("Relación de inervación", "Término utilizado para describir la relación entre el número de neuronas α motoras y el número total de fibras musculoesqueléticas.
• Relación de inervación pequeña: músculos como los músculos del ojo que necesitan un control muy fino.
• Relación de inervación grande: músculos de los miembros.
La relación de inervación aumenta con la edad a medida que las neuronas mueren; es una de las razones de la pérdida del control
manual en personas mayores.");
INSERT INTO keywords (name, description) VALUES ("Relación longitud-tensión", "La tensión isométrica generada en el sistema musculoesquelético es una función de la magnitud del solapamiento entre los filamentos de
actina y miosina. La fuerza máxima se genera dentro del músculo cuando existe un solapamiento máximo entre los filamentos de actina y
miosina.");
INSERT INTO keywords (name, description) VALUES ("Relación on/off", "Término electroterápico que se aplica al tiempo durante el cual la corriente (o producción de otros impulsos como ultrasonidos o SWD)
fluye y desaparece en un ciclo completo, medido en segundos o milisegundos normalmente. Puede usarse como un coeficiente o para
calcular el ciclo de trabajo.");
INSERT INTO keywords (name, description) VALUES ("Relación profesional-paciente", "Puede entenderse como la relación de poder mediante la cual los problemas sociales son concebidos y definidos, por los profesionales,
como las necesidades y problemas de los pacientes y clientes. La relación también permite a los profesionales definir las soluciones deestos problemas. La relación profesional-paciente ha sido criticada considerablemente, y actualmente se aboga a menudo por el
enfoque «centrado en el paciente», que confiere a los pacientes y clientes más poder y control.
Véase Medicina centrada en el paciente.");
INSERT INTO keywords (name, description) VALUES ("Relación trabajo/reposo", "Término electroterápico; normalmente sólo se utiliza para el ultrasonido pulsátil.
Véase Relación on/off.");
INSERT INTO keywords (name, description) VALUES ("Relaxina", "Hormona liberada durante el embarazo; produce cambios en el colágeno de áreas diana proporcionando mayor flexibilidad y
extensibilidad. También se cree que tiene un efecto suavizante sobre el tejido conectivo, por ejemplo del suelo pélvico y la fascia
abdominal, aumentando su extensibilidad. La sínfisis del pubis y la articulación sacroilíaca se ven particularmente afectadas para permitir
el parto del bebé. La laxitud de estos ligamentos continúa durante 6 meses después del parto.
Observación clínica Esto tiene implicaciones obvias para el fisioterapeuta, y la relaxina puede ser una de las razones por las que el
dolor lumbar bajo es tan común durante el embarazo.");
INSERT INTO keywords (name, description) VALUES ("Reobase", "Término electroterápico que hace referencia a la medida aplicada a una gráfica intensidad/tiempo para evaluar la función nerviosa
periférica. Se define como la intensidad de corriente requerida para obtener la mínima respuesta perceptible (motora o sensorial,
dependiendo del test) usando un impulso monofásico con una duración de 100 ms y una frecuencia de aproximadamente 1 Hz. Los
valores normales varían si se usa corriente constante o estimulador de voltaje constante (interpretando corriente o voltaje dependiendo
del equipo).
Véase un libro de texto para consultar los valores normales.");
INSERT INTO keywords (name, description) VALUES ("Resistencia aérea", "Presión requerida para permitir el flujo aéreo entre la boca y los alvéolos. La resistencia aérea aumenta a medida que el calibre de los
conductos aéreos se reduce, por ejemplo, por la inflamación, la suave contracción muscular bronquial o el engrosamiento de las
paredes de los conductos como sucede en algunas enfermedades. La resistencia de los conductos aéreos se calcula por el cambio en la
presión a lo largo del tubo dividido por el flujo.");
INSERT INTO keywords (name, description) VALUES ("Resonancia magnética funcional (RMF)", "Técnica de escáner que permite observar la actividad del cerebro durante su funcionamiento.");
INSERT INTO keywords (name, description) VALUES ("Respiración", "Intercambio de los gases metabólicos (oxígeno y dióxido de carbono). La respiración externa implica el movimiento del oxígeno desde
el aire a los pulmones y el del dióxido de carbono desde los pulmones al medio ambiente exterior. La respiración interna implica el
movimiento del oxígeno desde las arteriolas a los tejidos y el del dióxido de carbono desde los tejidos a los vasos sanguíneos, que lo
transportarán de vuelta a los pulmones.");
INSERT INTO keywords (name, description) VALUES ("Respiración con labios fruncidos", "Respiración a través de los labios fuertemente apretados, que da lugar a la generación de una contrapresión que evita la compresión de
los segmentos pulmonares colapsables (es decir, el punto de igual presión se desplaza hacia la boca). Los pacientes enfisematosos a
menudo adoptan esta respiración en momentos de extrema disnea.");
INSERT INTO keywords (name, description) VALUES ("Respiración de Cheyne-Stokes", "Patrón anormal de respiración caracterizado por episodios de apnea alternados con respiraciones profundas y rápidas. El ciclo");
INSERT INTO keywords (name, description) VALUES ("respiratorio comienza con una respiración lenta y superficial, y", "");
INSERT INTO keywords (name, description) VALUES ("gradualmente aumenta hasta alcanzar una profundidad y rapidez", "anormales.");
INSERT INTO keywords (name, description) VALUES ("Respiración de Kussmaul", "Sobrerrespiración asociada con cetoacidosis diabética (una acidosis metabólica que resulta de la formación de excesivas cetonas a
partir de un metabolismo de los carbohidratos alterado).Respiración paradójica
Cambio en el patrón respiratorio que resulta de la pérdida de la integridad de la pared torácica o fallo/debilidad de la musculatura
gruesa. El pecho se ve oprimido durante la inspiración y se relaja en espiración.");
INSERT INTO keywords (name, description) VALUES ("Respiro del cuidador", "Servicios para personas minusválidas o enfermas que son principalmente designados para permitir descansar a sus cuidadores. El
cuidado puede proporcionarse en una institución o en el propio domicilio. Se ha argumentado que el acceso al respiro del cuidador
debería ser un derecho para todos los cuidadores. Otras personas argumentan que el respiro del cuidador supone un menosprecio para
minusválidos y personas enfermas al considerarlos como una carga, y que es prueba de la incapacidad de proporcionar otras formas de
asistencia más apropiadas.");
INSERT INTO keywords (name, description) VALUES ("Responsabilidad", "Provisión de explicaciones y justificaciones. Los fisioterapeutas son responsables ante sus pacientes y clientes, las organizaciones en las
que trabajan y su cuerpo profesional. La incompatibilidad de intereses de estos grupos pueden hacer de la responsabilidad algo difícil
de lograr.");
INSERT INTO keywords (name, description) VALUES ("Respuesta extensora", "Se inicia por el contacto de la parte posterior de la cabeza con una superficie de apoyo, dando como resultado la extensión del cuerpo
y los miembros. Normalmente se observa en las lesiones cerebrales graves o en la esclerosis múltiple; esta postura se ve de manera más
marcada en decúbito supino.");
INSERT INTO keywords (name, description) VALUES ("Respuesta plantar", "Véase Reflejo de Babinski.");
INSERT INTO keywords (name, description) VALUES ("Respuesta triple de Lewis", "Los cambios que constituyen este componente vascular fueron descritos en 1927 por Lewis y son conocidos como respuesta triple de
Lewis. El rubor, reacción «en llama» y efecto de pápula (flush, flare, wheal) pueden ser demostrados arrastrando con firmeza un
instrumento romo sobre la piel (habitualmente se usa el antebrazo por una cuestión de comodidad) y observando la siguiente secuencia
de eventos, que son similares independientemente del tipo de lesión:
1. Instantáneamente se forma una línea blanca siguiendo la lesión. Esto es debido a la vasoconstricción de las arteriolas subyacentes
como una respuesta directa a la lesión y es sólo transitoria. Esta vasoconstricción no es considerada como parte completa del proceso
inflamatorio.
2. A continuación aparece rápidamente el rubor (flush), que se observa como una línea roja apagada que aparece al dilatarse los
capilares. A simple vista, con la vasodilatación puede dar la impresión de que los tejidos afectados contienen un alto número de vasos
sanguíneos. Esta dilatación persistirá durante todo el proceso inflamatorio.
3. Aparece a continuación una «reacción en llama» (flare), esto es, una zona roja irregular. Esto ocurre debido a la respuesta de las
arteriolas circundantes, las cuales se ven afectadas tanto por mediadores químicos como nerviosos.
4. Formación de una pápula (wheal) (área abultada de la piel). Ocurre debido al fluido que se extravasa de los vasos sanguíneos hacia
el espacio extravascular, llevando a la aparición de edema.
En segundo lugar (aunque ocurre al mismo tiempo que el proceso anterior), las células endoteliales que forman la pared interna de los
vasos sanguíneos se retraen de modo que dejan de formar una cubierta interna continua del vaso. Consecuentemente, los vasos
comienzan a perforarse hasta tal punto que puede extravasarse el fluido contenido en el plasma (es decir, agua y algunas de las sales y
proteínas más pequeñas, una de las cuales es el fibrinógeno) directamente al espacio extracelular del área dañada.
En tercer lugar, el fluido exudado comienza a transformarse en exudado celular. Esto ocurre debido a la migración de neutrófilos, que
dejan los vasos sanguíneos para entrar en el espacio extracelular del área de tejido dañado. En las primeras 6 a 24 h de una respuesta
inflamatoria son los neutrófilos los que predominan; entre las 24 y 48 h, sin embargo, éstos son sustituidos por monocitos y linfocitos
que actúan de forma similar (Court y Lea, 2003).");
INSERT INTO keywords (name, description) VALUES ("Resumen", "Término de investigación; resumen sucinto de un artículo de investigación. Un buen resumen debe sintetizar exactamente el artículo.
Consejo para el estudiante Se debe leer el artículo y no sólo el resumen cuando se estudia un tema.Retención urinaria
En vejigas hipotónicas (blandas), la respuesta normal al incremento de la presión, que tiene lugar durante el llenado, puede estar ausente
y el detrusor no conseguir contraerse. La retención está asociada a la obstrucción de flujo (p. ej., en los hombres con enfermedad de
próstata), neuropatías, lesiones en la columna vertebral lumbar, intervención pélvica radical y esclerosis múltiple, o puede ser secundaria
a la terapia con determinados fármacos (especialmente los psicotrópicos). La incontinencia, en ocasiones, aunque no siempre, sucede
con retención (Brook y cols., 2003).");
INSERT INTO keywords (name, description) VALUES ("Retículo endoplásmico", "Sistema de membranas que se extiende a través del citoplasma.");
INSERT INTO keywords (name, description) VALUES ("Retículo sarcoplásmico", "Retículo endoplásmico liso de las fibras musculares; constituye una reserva de calcio, que se libera y capta durante y después de las
contracciones.");
INSERT INTO keywords (name, description) VALUES ("Retináculo", "Término anatómico para una red de tejido que rodea a los tendones; se localizan en la muñeca y el pie.");
INSERT INTO keywords (name, description) VALUES ("Retináculo del tobillo", "");
INSERT INTO keywords (name, description) VALUES ("Retirada de la escayola", "Una parte de la escayola se corta para permitir que el paciente pueda llevar a cabo un movimiento mientras se previene el movimiento
en la dirección opuesta. Se usa comúnmente para la corrección de contracturas, ya que permite al paciente fortalecer el grupo muscular
opuesto al de la contractura.
En el brazo, si éste está contraído en flexión, la parte posterior de la tablilla se corta por encima del codo para que el brazo pueda
extenderse pero no pueda flexionarse debido a la tablilla.En una pierna con una posición mantenida en flexión, la parte anterior de la tablilla se corta por debajo de la rodilla para que ésta pueda
extenderse, pero no pueda flexionarse debido a la tablilla.");
INSERT INTO keywords (name, description) VALUES ("Retorno venoso", "Proceso por el cual la sangre retorna al corazón; se lleva a cabo por medio de:
• Bombeo respiratorio.
• Válvulas venosas a través de bombeo muscular.
• Tono venomotor.
Observación clínica Los fisioterapeutas suelen encontrar, entre sus pacientes, a personas con una deficiencia del bombeo muscular,
por ejemplo, después de lesiones del miembro inferior.");
INSERT INTO keywords (name, description) VALUES ("Retraso del extensor", "Si una articulación se extiende pasiva pero no activamente, la caída resultante de la articulación se conoce como retraso del extensor.");
INSERT INTO keywords (name, description) VALUES ("Retroalimentación sensoriomotora", "Implica la integración e interacción de información aferente (sensorial) durante la actividad motora, que puede después alterar el
movimiento o dar lugar a la adaptación de la respuesta motora. La retroalimentación permite corregir los errores.");
INSERT INTO keywords (name, description) VALUES ("Retrolistesis", "Cajón posterior de una vértebra respecto a otra. Véase Espondilolistesis.");
INSERT INTO keywords (name, description) VALUES ("Revisión", "Proceso académico por el que se reseña un trabajo escrito o práctico.");
INSERT INTO keywords (name, description) VALUES ("Revisión bibliográfica", "Véase Software de bibliografía electrónica.
Una revisión de bibliografía es un intento de clasificar y evaluar lo que los investigadores han escrito sobre un tema en particular; debe
ser organizado de acuerdo a un tema guiado según nuestro proyecto de investigación, tesis o problema. Una buena revisión bibliográfica
no se limita a un listado del mayor número de artículos posibles; más bien debería reconocer la infomación relevante y sintetizarla y
evaluarla de acuerdo al tema guiado que se ha determinado, es decir, debe constituir una evaluación informada de la literatura. Los
estudiantes de fisioterapia deben ser capaces de seleccionar la literatura eficientemente, usando manuales o métodos computarizados
para identificar libros y artículos útiles. Será necesario tener la capacidad de aplicar principios de análisis para identificar estudios
imparciales y válidos. Los lectores o examinadores querrán más que una simple lista descriptiva de artículos y libros.
Debe organizarse la revisión realizada en secciones informativas lógicas que presenten temas o identifiquen tendencias, y no empezar
cada párrafo de la revisión con una lista de nombres de investigadores.");
INSERT INTO keywords (name, description) VALUES ("Consejos para la gestión de una buena revisión bibliográfica", "• Organizar la información y relacionarla con la pregunta de investigación que se está planteando.
• Sintetizar resultados en un resumen, distinguiendo lo que es generalmente aceptado de las áreas que aún no se comprenden de forma
adecuada.
• Identificar las controversias siempre que aparezcan en la literatura.
• Desarrollar cuestiones para investigaciones futuras.Revisión clínica
Iniciativa que procura mejorar los resultados del cuidado del paciente a través de una revisión estructurada. Implica que los médicos
examinen su propia práctica y comparen y establezcan una relación de estos resultados con un grupo de directrices estandarizadas.
Florence Nightingale, durante la guerra de Crimea, emprendió la primera revisión clínica a mediados del siglo XIX. Desde el tiempo de
Florence Nightingale en 1850 hasta 1988, la actividad de auditoría en el National Health Service británico (NHS) fue muy fragmentaria.
Aunque un número de profesionales del cuidado de la salud dentro del NHS estaban interesados en la calidad del servicio que
prestaban a los pacientes, muy pocos revisaban sistemáticamente su trabajo. De hecho, durante este período de tiempo, sólo los
entusiastas llevaron a cabo la actividad de revisión.
De 1989 a 1998, la auditoría evolucionó considerablemente. La principal razón por la que la auditoría comenzó a ganar ímpetu en 1989
fue que el gobierno conservador de la época decidió poner más énfasis en evaluar la calidad del cuidado que se impartía en el NHS. El
libro blanco Working for patients («Trabajando para los pacientes») del Gobierno de 1989 estableció el departamento de auditoría en
hospitales y el Medical Audit Advisory Group (MAAG), para ayudar a los médicos generales en la revisión de su propio trabajo.
Ambos equipos, el MAAG y la auditoría del hospital, estaban implicados en la ayuda al personal de cuidados de la salud para que
participasen en la revisión del trabajo. Inicialmente a comienzos de 1990, el trabajo se centraba en la auditoría médica, pero a
mediados de la década de 1990 la auditoría implicaba a muchas disciplinas y, por tanto, su nombre se cambió por el de auditoría
clínica. Desde 1998 ha alcanzado un auge considerable y está ahora firmemente integrada en el NHS, debido, principalmente, al hecho
de que es un componente central de la gobernancia clínica. A diferencia de lo que ocurría en la década de 1990, cuando el trabajo de
auditoría era mucho más voluntario, actualmente se espera que los profesionales del cuidado de la salud conduzcan auditorías clínicas
regulares. Por ejemplo, el Coronary Heart Disease National Service Framework afirmaba formalmente que para antes de 2003 las
prácticas clínicas debían revisar datos de no más de 12 meses de antigüedad. Además, desarrollos recientes dentro del NHS, como las
investigaciones de Shipman y Bristol, han elevado el perfil de la auditoría.");
INSERT INTO keywords (name, description) VALUES ("Definiciones de auditoría clínica", "El Leicestershire Primary Care Audit Group ha definido la auditoría clínica como sigue:
La auditoría clínica es un proceso estructurado que confirma que estamos llevando a cabo la mejor práctica posible comparando lo que
hacemos con lo que deberíamos estar haciendo.");
INSERT INTO keywords (name, description) VALUES ("Etapas del ciclo de auditoría", "");
INSERT INTO keywords (name, description) VALUES ("Seleccionar un tema de auditoría apropiado", "La primera etapa de cualquier auditoría es seleccionar un tema apropiado para que sea revisado. Sin embargo, el seleccionar un tema
apropiado de revisión no es tan sencillo como puede parecer. Es importante que el tema de revisión se centre en un problema real, que
sea también medible y relevante para nuestro campo/práctica.");
INSERT INTO keywords (name, description) VALUES ("Elegir los criterios y estándares apropiados", "Los criterios y los estándares son dos términos de auditoría que pueden llevar a confusión. Ello es desafortunado, ya que los criterios y
estándares no son difíciles de entender. Si volvemos a la anterior definición de auditoría, los criterios y estándares se relacionan con «lo
que deberíamos estar haciendo».
Un criterio es, esencialmente, un punto de los cuidados o un aspecto de la práctica que podemos utilizar para valorar la calidad. Cada
criterio debería ser registrado como una declaración sucinta. Por lo tanto, un ejemplo de un criterio sería: «Los informes muestran que
los pacientes con enfermedad cardíaca coronaria son revisados anualmente».
Un estándar es una declaración de la proporción de ocasiones o pacientes que debe cumplir cada criterio. Se expresan en porcentajes.
Por ejemplo, podemos fijar un estándar que indique que el 100% de los pacientes con enfermedad cardíaca coronaria deberían
someterse a una revisión anual recogida en sus informes.
Los criterios y estándares deberían basarse en la última evidencia e investigación disponible. Si la evidencia no está disponible, es
aceptable aprobar los criterios y estándares con el consenso acordado por los miembros del equipo.");
INSERT INTO keywords (name, description) VALUES ("Recoger datos", "Una vez hemos fijado los criterios y estándares para la auditoría (es decir, se ha decidido qué es lo que se va a medir), será preciso
recoger datos de revisión. Existe una serie de factores que deben considerarse en este momento. Los datos de revisión deben ser
representativos y, por lo tanto, es necesario asegurarse de que se incluyan suficientes pacientes en la auditoría para que los datos
recogidos sean representativos. En segundo lugar, es importante asegurarse de que cualquier método utilizado de recogida de datos es
inteligible, coherente y fundamentado. Si dos personas que utilizan el mismo método de recogida de datos interpretan las preguntas y los
datos de diferente manera, la revisión estará condenada al fracaso; por lo tanto, para asegurarnos de que el método de recogida de
datos es válido, es aconsejable que el equipo dirija las herramientas de trabajo de recogida de datos. Desde hace tiempo, el personalelectrónico de datos es mucho más rápido y preciso. Sin embargo, es importante que las herramientas electrónicas de revisión sean
actualizadas continuamente, ya que pueden ir surgiendo problemas.");
INSERT INTO keywords (name, description) VALUES ("Análisis de los datos", "Una vez todos los datos han sido recogidos, es necesario analizarlos.
En la mayoría de los casos, el análisis de datos simples implica calcular porcentajes básicos. Por ejemplo, usando nuestro ejemplo
anterior, el equipo debería, en primer lugar, centrarse en el porcentaje real de pacientes con enfermedad cardíaca coronaria que no
tienen un informe de revisión anual en su historial clínico. Este cálculo informaría sobre si se están cumpliendo los estándares.
Los datos también deben analizarse para identificar tendencias y problemas particulares. Por ejemplo, volviendo otra vez a nuestro
ejemplo de la enfermedad cardíaca coronaria, el análisis de los datos podría revelar que un grupo particular de pacientes no se está
sometiendo a revisiones anuales, o que pacientes recientemente diagnosticados de esta enfermedad no están siendo citados para una
revisión un año después.");
INSERT INTO keywords (name, description) VALUES ("Aplicar cambios", "La penúltima etapa del ciclo de auditoría es una de las más cruciales y a menudo una de las más difíciles.
Una vez todos los datos han sido analizados y los resultados de la auditoría calculados, el equipo de la auditoría necesita decidir qué
cambios deben aplicarse. Obviamente, los cambios deberían ser designados para rectificar cualquier problema grave que la auditoría
haya identificado.
Los cambios aplicados que serían efectivos y que darían lugar a mejoras son complejos. En algunos casos, pequeños cambios pueden
dar lugar a mejoras considerables. Sin embargo, en otros casos, son necesarios cambios más importantes.
Cualesquiera que sean los cambios resultantes de una auditoría, es vital que el proceso de cambio quede perfectamente definido. En
otras palabras, un plan de acción detallado debería realizarse de manera que especificase claramente quién, cuándo, qué y cómo deben
aplicarse los cambios. Más adelante, todos los miembros del equipo deberían estar informados de los cambios propuestos y alguien
debería asumir el papel de líder, supervisando que los cambios tengan lugar.");
INSERT INTO keywords (name, description) VALUES ("Reauditoría", "La última fase del ciclo de auditoría es la de emprender una reauditoría, es decir, recoger datos y analizarlos. El principal propósito de
la fase de reauditoría es comprobar si los cambios que fueron aplicados han dado lugar a una mejora.
Con la autorización de Stephen Ashmore, Leicester Primary Care Audit Group, Manager Tracy Johnson, Leicester Primary Care Audit
Group, Deputy Manager.");
INSERT INTO keywords (name, description) VALUES ("Revisión Cochrane", "Una revisión sistemática de la evidencia que hace referencia a un problema particular de la salud o intervención del cuidado de la salud
elaborada por la Cochrane Collaboration. Disponible, vía internet, como parte de la Cochrane Library.");
INSERT INTO keywords (name, description) VALUES ("Revisión por pares", "Proceso académico en el que los trabajos son examinados por miembros eminentes de la misma profesión que realizan un juicio y
sentencian si es digno de publicación.");
INSERT INTO keywords (name, description) VALUES ("Revisión sistemática", "Proceso de investigación que resume la evidencia en una pregunta claramente formulada de acuerdo con un protocolo previamente
definido y utilizando una aproximación detallada. El informe debería hacer explícitos los métodos utilizados para identificar, seleccionar
y evaluar los estudios relevantes y para extraer, recopilar y publicar sus descubrimientos. Puede o no utilizar el metaanálisis.");
INSERT INTO keywords (name, description) VALUES ("RICE (reposo, hielo, compresión y elevación)", "Tratamiento de lesiones agudas para prevenir que el proceso inflamatorio evolucione incontroladamente y acelerar el proceso de
recuperación, eliminando la inflamación. Véase Crioterapia.");
INSERT INTO keywords (name, description) VALUES ("Rigidez", "Fenómeno neurológico en el que existe un aumento de la resistencia al movimiento pasivo lento; a diferencia de la espasticidad, no
depende de la velocidad. La tabla siguiente muestra más información sobre espasticidad y rigidez.
Observación clínica La rigidez en rueda dentada se observa en la enfermedad de Parkinson, y la rigidez de descerebración y
decorticación en casos de traumatismo craneoencefálico.
Comparación de espasticidad y rigidezPatrón del compromise) muscular Flexores del miembro superior; extensores del miembro inferior");
INSERT INTO keywords (name, description) VALUES ("Rigidez", "");
INSERT INTO keywords (name, description) VALUES ("Flexores y extensores por igua", "Naturaleza del tono Aumento de tono dependien-te de la velocidad; »navaja« M ovimiento totalmente constante; »tubería de plomo«");
INSERT INTO keywords (name, description) VALUES ("Reflejos del tendón Aumentados Normales", "Fisiopatología Reflejo de estiramiento vertebral aumentado Componente de larga latencia del reflejo de estiramiento aumentado
Importancia clínica Signo de la neurona motora superior (piramidal) Signo extrapiramida");
INSERT INTO keywords (name, description) VALUES ("Rigidez de decorticación", "Postura anormal que puede darse después de un traumatismo craneoencefálico que haya ocasionado una lesión por encima del colículo
superior, es decir, en el tálamo o cápsula interna. El paciente normalmente adopta una postura rígida, con el cuerpo y los miembros en
una posición de extensión marcada y respuesta flexora en los miembros superiores. Los pacientes con rigidez de decorticación
presentan un alto riesgo de desarrollar contracturas.");
INSERT INTO keywords (name, description) VALUES ("Rigidez de descerebración", "Postura anormal que puede darse después de un traumatismo craneoencefálico que haya ocasionado una lesión del cerebro medio. El
paciente normalmente adopta una postura rígida con la mandíbula en oclusión, el cuello retraído y ambos miembros, superior e inferior,
en extensión marcada. Los pacientes con rigidez de descerebración corren un elevado riesgo de desarrollar contracturas.");
INSERT INTO keywords (name, description) VALUES ("Rigidez en rueda dentada", "Resistencia que es disminuida de modo intermitente, dando la sensación de un mecanismo de rueda. Es común en la enfermedad de
Parkinson y en otras alteraciones de los ganglios basales.");
INSERT INTO keywords (name, description) VALUES ("Rigidez en tubo de plomo", "Fenómeno que se observa en personas con enfermedad de Parkinson u otras enfermedades extrapiramidales; se manifiesta como una
resistencia uniforme al movimiento en todo el rango disponible.");
INSERT INTO keywords (name, description) VALUES ("Rigidez matinal", "Característica común de las alteraciones inflamatorias, particularmente de la artritis reumatoide; se refiere a la lentitud o dificultad para
mover las articulaciones al levantarse de la cama o después de haber permanecido mucho tiempo en una misma posición. Mejora con el
movimiento.");
INSERT INTO keywords (name, description) VALUES ("Ritmo escapulohumeral", "Movimientos de la rotación clavicular, rotación escapular y elevación glenohumeral, durante el movimiento del complejo del hombro.");
INSERT INTO keywords (name, description) VALUES ("RM", "Abreviatura médica común de resonancia magnética.
Este tipo de escáner es una técnica radiológica que emplea magnetismo y un ordenador para producir imágenes. La RM es un tubo
rodeado por un imán circular gigante. El paciente es colocado en una cama móvil que puede entrar y salir del imán. El imán alinea los
protones de los átomos de hidrógeno. Producen una señal débil que es detectada por la porción receptiva de la RM. Un ordenador
procesa la información recibida y luego genera la imagen.");
INSERT INTO keywords (name, description) VALUES ("RMC(A)", "Abreviatura médica común que corresponde a rango de movimiento completo (activo).");
INSERT INTO keywords (name, description) VALUES ("Roce pleural", "Sonido similar a un crujido que se escucha durante la auscultación; indica inflamación de la pleura.");
INSERT INTO keywords (name, description) VALUES ("Rodete", "Término anatómico que significa borde o labio.");
INSERT INTO keywords (name, description) VALUES ("Rodete acetabular", "Anillo fibrocartilaginoso unido al margen del acetábulo en la pelvis; sirve para hacer más profunda la fosa y añade estabilidad articular.
La glenoide del hombro también posee rodete.Rodilla de monja
Inflamación de la bolsa infrarrotuliana.");
INSERT INTO keywords (name, description) VALUES ("Rodilla de saltador", "Alteración musculoesquelética. Se asocia con una pequeña área de degeneración en la unión del tendón con el polo inferior de la rótula;
los síntomas son dolor y sensibilidad localizados.");
INSERT INTO keywords (name, description) VALUES ("Rodillas hacia dentro", "Véase Genu valgo.");
INSERT INTO keywords (name, description) VALUES ("Rol", "Concepto clave en la teoría sociológica. Se centra en las expectativas sociales asociadas a estados particulares o posiciones sociales.");
INSERT INTO keywords (name, description) VALUES ("Rollo «en T»", "Pieza de material en forma de T, que se utiliza como ayuda para que los pacientes adopten una posición determinada, rompiendo con
los patrones establecidos del tono y distribuyendo el peso de forma más equitativa en pacientes con acortamiento de los tejidos
blandos.");
INSERT INTO keywords (name, description) VALUES ("Paciente tumbado en decúbito supino con un rollo en T", "");
INSERT INTO keywords (name, description) VALUES ("Roncus", "Sonido vibratorio, pitido o silbido escuchado en la auscultación del pecho cuando las vías aéreas están parcialmente obstruidas.");
INSERT INTO keywords (name, description) VALUES ("Ronquido", "Ruido respiratorio anormal que se oye durante la espiración (más común en niños). Indica que existe un esfuerzo respiratorio, que se
piensa que tiene lugar para generar una presión de retorno (presión espiratoria positiva) cerrando la glotis y previniendo así el colapso
alveolar.");
INSERT INTO keywords (name, description) VALUES ("Rotación", "Movimiento sobre el eje longitudinal que requiere una respuesta coordinada entre flexión y extensión.
Observación clínica La alteración de los movimientos de rotación se observa a menudo en pacientes con desequilibrio y acortamiento
muscular. La pérdida de rotación en el tronco puede observarse durante la marcha por la falta de balanceo del brazo.");
INSERT INTO keywords (name, description) VALUES ("Rótula", "Se trata del hueso sesamoideo más grande del cuerpo.(A) Rodilla sin rótula. (B) Rodilla con rótula");
INSERT INTO keywords (name, description) VALUES ("Rótula alta", "Hace referencia a una rótula relativamente elevada en relación al fémur; puede dar como resultado una dislocación y subluxación de la
rótula.");
INSERT INTO keywords (name, description) VALUES ("Rótula baja", "Rótula anormalmente baja.");
INSERT INTO keywords (name, description) VALUES ("RPPI", "Abreviatura médica común de respiración con presión positiva intermitente.
Este instrumento se popularizó como «Bird» (el nombre de su fabricante). El instrumento es un simple mecanismo de respiración que
responde a un impulso espontáneo o programado para liberar presión positiva a la vía aérea a través de la inspiración con una máscara
o pieza bucal. Sus usos incluyen la administración de medicamentos broncodilatadores inhalados, la reducción del esfuerzo de la
respiración y la reinsuflación de áreas pulmonares atelectásicas mediante aumentos de la capacidad pulmonar residual funcional. El
instrumento puede utilizarse en conjunto con otras terapias, como las posturas y los ejercicios de expansión torácica.
Diagrama que muestra un ejemplo de dispositivo de respiración con presión positiva intermitente (RPPI)");
INSERT INTO keywords (name, description) VALUES ("RTC", "Abreviatura médica común de reemplazo total de la cadera.RTR
Abreviatura médica común de reemplazo total de la rodilla.");
INSERT INTO keywords (name, description) VALUES ("RTU de próstata", "Abreviatura médica común de resección transuretral de la próstata.");
INSERT INTO keywords (name, description) VALUES ("Rx", "Abreviatura médica común de radiografía.");
INSERT INTO keywords (name, description) VALUES ("Rx torácica", "Interpretación de una radiografía torácica normal: 1, tráquea; 2, fisura horizontal; 3, ángulo costofrénico; 4, hemidiafragma derecho; 5, hemidiafragma izquierdo; 6,
psombra del corazón; 7, arco aórtico; 8, hilio derecho; 9, hilio izquierdo");
INSERT INTO keywords (name, description) VALUES ("RxT", "Abreviatura médica común de radiografía de tórax.S");
INSERT INTO keywords (name, description) VALUES ("Salbutamol (Ventolin®)", "Fármaco utilizado como vasodilatador en el asma.");
INSERT INTO keywords (name, description) VALUES ("Salud", "Las definiciones difieren según los individuos, grupos culturales y clases sociales. Una visión es que la salud es la ausencia de dolencia o
enfermedad. Dentro del modelo médico de la salud, se puede definir como la referencia a ciertos parámetros físicos y biomecánicos.
Desde perspectivas más amplias, la salud incluye los aspectos físicos, psicológicos, comportamentales, sociales y espirituales de un
estado de bienestar, y reconoce a los individuos la importancia de la satisfacción de sus aspiraciones y necesidades.");
INSERT INTO keywords (name, description) VALUES ("Sanitario", "Profesional del cuidado de la salud, por ejemplo, enfermera o fisioterapeuta.");
INSERT INTO keywords (name, description) VALUES ("Sarcoidosis", "Enfermedad granulomatosa de origen desconocido que afecta a muchos órganos, pero más comúnmente a piel, pulmones y ojos. Los
órganos afectados contienen grupos de nódulos formados por células epitelioides (similares a los de la tuberculosis pero sin un centro
necrótico). Los síntomas respiratorios son comunes en los adultos jóvenes y, si bien la enfermedad se caracteriza normalmente por
síntomas restrictivos y el 90% de los pacientes se recuperan sin tratamiento, el 10% pueden desarrollar un proceso recidivante o
crónico. Inicialmente se debe mantener un período de control para comprobar si se produce una recuperación espontánea, pero si esto
no ocurre y se observa un deterioro en la función pulmonar, se pueden utilizar corticoides. Véase Enfermedad pulmonar intersticial.
Los síntomas respiratorios son tos y disnea, con más del 25% de los pacientes diagnosticados accidentalmente a través de resultados
radiológicos anormales. Las manifestaciones respiratorias incluyen la linfoadenopatía hiliar (nódulos linfáticos hiliares aumentados de
tamaño), opacidades pulmonares y fibrosis pulmonar irreversible. Las investigaciones pueden revelar enfermedad pulmonar restrictiva
con volúmenes pulmonares bajos y un factor de transferencia reducido. Si se desea evidencia histológica, se puede llevar a cabo una
biopsia transbronquial. Debido a la relación multiorgánica de la enfermedad, las manifestaciones no respiratorias también incluyen uveítis
(inflamación de la cavidad ocular), hepatoesplenomegalia, miocarditis (inflamación del miocardio), eritema nudoso (lesiones cutáneas
elevadas y rojas), meningitis, hipercalcemia y letargia.");
INSERT INTO keywords (name, description) VALUES ("Sarcolema", "Membrana plasmática que rodea a la célula muscular.");
INSERT INTO keywords (name, description) VALUES ("Sarcoma de Kaposi (SK)", "Tumor en las paredes de los vasos sanguíneos o del sistema linfático. Se presenta en forma de pequeñas manchas moradas en la
pero también puede localizarse en los órganos internos, junto con lesiones o independientemente de ellas.");
INSERT INTO keywords (name, description) VALUES ("piel,", "");
INSERT INTO keywords (name, description) VALUES ("Sarcómeras", "Subunidades de miofibrillas que contienen filamentos gruesos y finos organizados, unidos por las líneas Z. Véase Estructura muscular.");
INSERT INTO keywords (name, description) VALUES ("SARM", "Staphylococcus aureus resistente a la meticilina. Bacteria que ha desarrollado resistencia a numerosos antibióticos modernos. El
contagio parece estar actualmente relacionado con el contacto con el sistema de asistencia sanitaria (Johnstone y cols., 2003).");
INSERT INTO keywords (name, description) VALUES ("Saturación de oxígeno (SaO 2 )", "Porcentaje de hemoglobina saturada con oxígeno.");
INSERT INTO keywords (name, description) VALUES ("Saturación teórica (saturación de datos)", "Término de investigación utilizado en la investigación cualitativa para designar el punto en el que no emergen nuevos temas o conceptos
de los datos que se han recogido.");
INSERT INTO keywords (name, description) VALUES ("Sedestación alta", "Consiste en sentarse con los pies planos en el suelo, al borde de un taburete alto con un asiento angulado, ligeramente descendente, queayuda a mantener la pelvis en una posición de inclinación anterior, facilitando la actividad extensora de la parte superior del cuerpo.
Observación clínica Los pacientes pueden sentarse en esta posición mientras realizan las actividades de la vida diaria, maximizando
así el efecto terapéutico.");
INSERT INTO keywords (name, description) VALUES ("Segmento broncopulmonar", "Subdivisiones de los lóbulos de los pulmones, cada uno de los cuales contiene su propio bronquio segmental. Véase Lóbulos.");
INSERT INTO keywords (name, description) VALUES ("Semana de acogida del estudiante", "Período de tiempo que se asigna a los nuevos estudiantes en una universidad para que se matriculen y se familiaricen con el centro y con
sus compañeros.");
INSERT INTO keywords (name, description) VALUES ("Semana de estudio", "Término empleado para describir un período de tiempo dado a los estudiantes para estudiar fuera de la universidad.");
INSERT INTO keywords (name, description) VALUES ("Semestre", "Período de tiempo académico que corresponde normalmente a 15 semanas.");
INSERT INTO keywords (name, description) VALUES ("Seminario", "Sesión de aprendizaje donde los alumnos realizan una presentación (normalmente sobre algo que han leído) a un pequeño grupo de
compañeros y a un tutor como base para una futura discusión realizada por el grupo.");
INSERT INTO keywords (name, description) VALUES ("Sensación", "Término utilizado para describir la entrada aferente desde el mundo que nos rodea o desde el propio cuerpo. Nos permite funcionar de
forma segura y adaptarnos en cualquier circunstancia. Los receptores sensoriales convierten la información en actividad eléctrica que es
después procesada por el SNC. La sensación requiere que los sistemas nerviosos central y periférico estén intactos.
Observación clínica El movimiento es posible sin la sensación pero es torpe y lento y depende de la información visual.");
INSERT INTO keywords (name, description) VALUES ("Sensación terminal", "Durante los movimientos pasivos, se percibe una sensación terminal. Las diferentes articulaciones y patologías tienen diferentes
sensaciones terminales. La calidad de la resistencia notada al final del rango de movimiento fue clasificada por Cyriax (1982):
• El bloqueo óseo al movimiento o la sensación terminal dura es característica de las articulaciones artríticas.
• Una sensación terminal vacía o ninguna resistencia ofrecida al final del rango de movimiento puede ser debida a un fuerte dolor
asociado con infección, inflamación activa y tumores.
• Un bloqueo elástico se caracteriza por una sensación de rebote al final del rango de movimiento y se asocia con arrancamiento
meniscal que bloquea la extensión de la rodilla.
• Si se experimenta espasmo de forma súbita, la sensación terminal será relativamente dura y estará asociada a una defensa muscular.
• La sensación capsular supone un freno más fuerte al movimiento.");
INSERT INTO keywords (name, description) VALUES ("Sensibilidad (de un test)", "Proporción de individuos clasificados como positivos por el estándar de referencia, que son identificados correctamente por el test de
estudio. Proporción de individuos con enfermedad que presentan un test positivo.");
INSERT INTO keywords (name, description) VALUES ("Sensibilidad (de una medida)", "Extensión para la cual el instrumento de medida detecta cambios clínicamente importantes en el tiempo. Estos cambios son a menudo
definidos en términos de la importancia que tienen para los pacientes. No existe un único método acordado para expresar la
sensibilidad del instrumento.");
INSERT INTO keywords (name, description) VALUES ("Sentido cinestésico", "Sentido por el cual se percibe la posición, el peso y el movimiento. Una persona debería ser capaz de notar las diferencias entre la
posición estática y la posición dinámica.Septicemia
Infección grave que progresa rápidamente y puede llegar a ser mortal. A veces es secundaria a infecciones que aparecen en pulmones,
abdomen y tracto urinario.");
INSERT INTO keywords (name, description) VALUES ("Series de casos", "Estudio de un número de casos de una enfermedad dada o con un resultado de interés, que normalmente cubren el curso de la
enfermedad y la respuesta al tratamiento. Ningún grupo control está implicado.");
INSERT INTO keywords (name, description) VALUES ("Sesamoiditis", "Alteración inflamatoria que afecta a los huesos sesamoideos, normalmente en el tendón del flexor del dedo gordo. Está generalmente
causada por un traumatismo. Las fracturas de estrés de un hueso sesamoideo son comunes por sobreuso.");
INSERT INTO keywords (name, description) VALUES ("Sesgo", "Término de investigación que se utiliza para designar la desviación de los resultados de sus valores verdaderos.");
INSERT INTO keywords (name, description) VALUES ("Sesgos confundidos", "Ocurren cuando dos factores están estrechamente asociados y los efectos de uno confunden o distorsionan los efectos del otro factor.
El factor distorsionador se denomina variable de confusión.");
INSERT INTO keywords (name, description) VALUES ("Sesgo de medida", "El hecho de ser estudiado o medido puede afectar a los resultados.");
INSERT INTO keywords (name, description) VALUES ("Sesgo de recuerdo", "El recuerdo de los hechos puede diferir en casos y controles. Las preguntas pueden formularse más veces y más intensamente en los
casos que en los controles.");
INSERT INTO keywords (name, description) VALUES ("Sesgo de atribución", "Los estudios referentes a cuidados de la salud pueden atraer a individuos con alteraciones o exposiciones específicas.");
INSERT INTO keywords (name, description) VALUES ("Sesgo de espectro o de la muestra", "La muestra de la población escogida no representa a la población general; por ejemplo, un espectro apropiado de alumnos no fue
incluido en el estudio de los resultados de su examen.");
INSERT INTO keywords (name, description) VALUES ("Sesgo del voluntario", "Los voluntarios pueden exhibir resultados que difieran de los no voluntarios (p. ej., los voluntarios tienden a estar más sanos).");
INSERT INTO keywords (name, description) VALUES ("Sesgo de retirada", "Los pacientes que se retiran del estudio pueden diferir sistemáticamente de aquellos que permanecen.");
INSERT INTO keywords (name, description) VALUES ("Sesgo del investigador", "Término de investigación; se produce cuando el investigador es consciente («no ciego») de la variable del resultado. Un entrevistador
«no ciego» puede ser más insistente en la búsqueda de la exposición de interés.");
INSERT INTO keywords (name, description) VALUES ("Sexismo", "Creencias estereotipadas y negativas, normalmente acerca de las mujeres, que pueden dar lugar a discriminación (p. ej., sueldo desigual
y escasas oportunidades de acceso a la educación). Los hombres también pueden estar sujetos al sexismo; por ejemplo, algunos
colegios de fisioterapia estaban en un principio cerrados a ellos.");
INSERT INTO keywords (name, description) VALUES ("Shock", "1. En el contexto médico, es una alteración grave que ocurre cuando el sistema cardiovascular es incapaz de suministrar flujo sanguíneo
suficiente al cuerpo, lo que normalmente va asociado con presión sanguínea baja y lesión celular o tisular. 2. En el contexto
electroterápico, se aplica al shock eléctrico: macroshock (v. Áreas protegidas del cuerpo) o microshock (utilizado principalmente en
unidades de alta dependencia o unidades de cuidados intensivos). Existe el riesgo de un pequeño shock con estimulación eléctrica: la
máquina debe ser encendida antes de probar su salida y de conectarla al paciente, y apagada sólo después de que la intensidad se ha
bajado al mínimo y el circuito del paciente está desconectado. La razón de esto es que un circuito microprocesador que no está
completamente sustentado no es del todo predecible.");
INSERT INTO keywords (name, description) VALUES ("Shock anafiláctico o anafilaxis", "Reacción sistémica grave y potencialmente letal frente a una sustancia sensibilizante como, por ejemplo, un fármaco, vacuna, comida,
suero, veneno o sustancia química. Los síntomas incluyen ansiedad, sudoración, malestar y dificultad para respirar. A medida queavanza el shock los síntomas pueden incluir hipotensión (descenso de la presión sanguínea), náuseas y diarrea.");
INSERT INTO keywords (name, description) VALUES ("Shock hipovolémico", "Shock causado por un descenso en la cantidad de sangre circulante.");
INSERT INTO keywords (name, description) VALUES ("Sibilancia", "Sonido musical continuo de tono elevado, que se escucha dentro de vías aéreas cuando hay una obstrucción.
Véase Sonidos respiratorios.");
INSERT INTO keywords (name, description) VALUES ("Sigmoidoscopia", "Procedimiento que permite la valoración del recto y del colon descendente. El instrumento es un tubo flexible.");
INSERT INTO keywords (name, description) VALUES ("Significancia estadística", "Probabilidad del grado de asociación observado entre las variables. Así pues, la significancia estadística puede expresarse generalmente
en términos del valor p. Por ejemplo: p < 0,05 significa que, para los resultados obtenidos, hay un 95% de posibilidades de que no
hayan ocurrido sólo por casualidad; p < 0,01 significa que para los resultados obtenidos existe un 99% de posibilidades de que no
hayan ocurrido sólo por casualidad.
Para la mayor parte de la investigación en fisioterapia, un valor p de 0,05 es suficiente, pero para la investigación (en la que el error en
la interpretación tiene consecuencias desastrosas, p. ej. para la investigación de un nuevo tipo de terapia para el cáncer) un valor p de
0,01 sería más apropiado.");
INSERT INTO keywords (name, description) VALUES ("Signo", "Evidencia objetiva de enfermedad o anormalidad que es perceptible por el examinador; por ejemplo, la existencia de un reflejo
rotuliano positivo es un signo, mientras que la queja «me duele la rodilla todo el tiempo» revela un síntoma.");
INSERT INTO keywords (name, description) VALUES ("Signo de Froment", "Test para la parálisis del nervio radial.
La persona coge un trozo de papel entre el pulgar y el dedo índice; se tira del papel y si el test es positivo, la articulación interfalángica
del pulgar se flexiona.");
INSERT INTO keywords (name, description) VALUES ("Signo de Homan", "Prueba para detectar la trombosis venosa profunda (TVP). La persona se coloca en decúbito supino, prono o sedestación; el
fisioterapeuta extiende pasivamente la rodilla y realiza una flexión dorsal del tobillo. También se puede palpar el gemelo, ya que el dolor
en el gemelo sugiere una TVP; esta prueba puede dar falsos positivos ya que el movimiento puede ser doloroso por otras razones.");
INSERT INTO keywords (name, description) VALUES ("Signo de Hoover", "El paciente se tumba en decúbito supino; cuando se le pide que eleve una pierna, involuntariamente realiza una presión opuesta con el
talón de la pierna contraria. Este signo no está presente en casos de enfermedad.");
INSERT INTO keywords (name, description) VALUES ("Signo de Kernig", "Signo de irritación meníngea; con la cadera en flexión completa, el intento de extensión pasiva de la rodilla provoca dolor y espasmo de
los isquiotibiales.");
INSERT INTO keywords (name, description) VALUES ("Signo de Piedellos", "Test para valorar la cantidad de movimiento en la articulación sacroilíaca. Con el paciente sentado, se le pide que se doble hacia
delante. El fisioterapeuta palpa las espinas ilíacas posterosuperiores (EIPS) bilateralmente.
Resultado normal Ambas EIPS deben moverse igualmente hacia la cabeza.
Resultado anormal Una elevación excesiva en un lado indica hipomovilidad en esa articulación sacroilíaca.");
INSERT INTO keywords (name, description) VALUES ("Signo de Tinel", "Test para medir el daño o inflamación del nervio cubital. El examinador palpa el nervio en el surco cubital. El test es positivo cuando hay
hormigueo.Signo/síntoma de hundimiento
Fenómeno que se observa en una persona con rotura del ligamento cruzado posterior, en que la tibia se desliza más hacia dorsal que en
la extremidad no afectada.");
INSERT INTO keywords (name, description) VALUES ("Signos de la motoneurona inferior", "Factores que indican que puede haber daños en las estructuras descritas como motoneurona inferior. Los signos pueden incluir la
pérdida de los reflejos, ausencia de tono y actividad muscular.");
INSERT INTO keywords (name, description) VALUES ("SII", "Abreviatura médica común de síndrome del intestino irritable.");
INSERT INTO keywords (name, description) VALUES ("Símbolos de Maitland", "");
INSERT INTO keywords (name, description) VALUES ("Sindesmófito", "Véase Columna en caña de bambú.
Crecimiento del hueso que se ve en la espondilitis anquilosante, con apariencia y dirección diferente a la de los osteófitos.");
INSERT INTO keywords (name, description) VALUES ("Síndrome", "Grupo de síntomas y enfermedades que es característico de una alteración específica.");
INSERT INTO keywords (name, description) VALUES ("Síndrome compartimental", "Condición patológica que se observa después de un traumatismo de un músculo o tejido blando, causada por compresión arterial
progresiva y reducción del aporte sanguíneo. Si no se trata, puede dar lugar a deformidades permanentes como la contractura
isquémica de Volkman.
Los signos y síntomas son:1. Palidez.
2. Dolor.
3. Ausencia de pulso.
4. Parestesia.
5. Parálisis.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de apnea obstructiva del sueño (SAOS)", "Trastorno caracterizado por una excesiva somnolencia durante el día con respiración irregular durante el sueño. Durante el sueño, el
enfermo experimenta una pérdida del tono muscular en la parte superior de la faringe, lo que da como resultado la pérdida de la
permeabilidad de las vías aéreas y su estrechamiento, con la consiguiente limitación del flujo aéreo. Se aumenta el esfuerzo inspiratorio
para compensar el estrechamiento, de modo que se experimenta un despertar transitorio de sueño profundo a sueño ligero o vigilia.
Esta situación suele repetirse varias veces durante la noche, dando lugar a un sueño deficiente y fragmentado. Las características clínicas
del SAOS incluyen: escasa capacidad de concentración, excesiva somnolencia durante el día, apnea y episodios de ahogo durante el
sueño (evidenciado por los compañeros), ronquidos, irritabilidad y cambios en la personalidad, y reducción de la libido. Los
procedimientos diagnósticos incluyen polisomnografías completas, oximetría nocturna y electroencefalografía. La gravedad se calcula
mediante el índice de hipopnea/apnea (IHA). El tratamiento de la enfermedad incluye intervenciones comportamentales (p. ej., higiene
del sueño, dejar de fumar, control del peso, etc.), intervenciones no quirúrgicas (p. ej., CPAP, aparatos intraorales e intervenciones
farmacológicas) e intervenciones quirúrgicas (uvulopalatofaringoplastia [UPFP]).
Véase SIGN guidelines (2003) para detalles completos en www.sign.ac.uk
Otras direcciones web útiles: www.sleep-apnoea-trust.org ; www.sleepapnea.org ; www.users.cloud9.net/~thorpy");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Brown-Séquard", "Lesión de la médula espinal en la que el daño a un lado de ésta provoca, por debajo del nivel de la lesión, pérdida de sensibilidad
dolorosa y térmica en el lado contralateral, y pérdida de propiocepción y parálisis motora en el lado homolateral.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Cushing", "Alteración en que los niveles de ACTH se hallan elevados; se presenta como miopatía, intolerancia a la glucosa e hipertensión y, a
veces, cambios psicológicos (Davies y cols., 2001).");
INSERT INTO keywords (name, description) VALUES ("Síndrome de distrés respiratorio agudo (SDRA)", "Es una forma grave y aguda de insuficiencia respiratoria ocasionada por un amplio rango de eventos catastróficos incluyendo shock,
septicemia, traumatismo mayor, aspiración o inhalación de sustancias nocivas (Barnard y cols, 1994).");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Ehlers-Danlos", "Alteración del tejido conectivo caracterizada, entre otros signos y síntomas, por hiperlaxitud de la piel, articulaciones y tejidos blandos.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de enclaustramiento", "Situación en la que una persona tiene actividad intelectual pero es incapaz de expresarla verbalmente o mediante el movimiento debido
a daño neurológico. Los pacientes son descritos como «enclaustrados», ya que están cerrados en sí mismos y son incapaces de
expresar pensamientos o emociones. A menudo estos pacientes pueden aprender a comunicarse a través de movimientos de los ojos u
otros pequeños movimientos. Puede tratarse de una etapa transitoria.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Felty", "Complicación de la artritis reumatoide en la que existe un aumento de tamaño del bazo y leucopenia.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Guillain-Barré (SGB)", "También conocido como polineuropatía desmielinizante inflamatoria aguda.
Tipo agudo de inflamación nerviosa que daña partes de la célula nerviosa, dando lugar a debilidad muscular o parálisis y pérdida
sensorial. La debilidad inicial puede progresar rápidamente y dar lugar a una parálisis completa que requiere ventilación. El SGB va
precedido normalmente de un trastorno respiratorio o gástrico antes del comienzo de los síntomas. Hoy en día los avances médicos han
hecho posible prevenir este tipo de deterioro. La recuperación completa se consigue en muchos pacientes, aunque en algunos persisteuna debilidad residual.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de hipermovilidad articular", "Estado frecuente en la infancia, que implica articulaciones hipermóviles (que se pueden mover más allá del rango normal de
movimiento).");
INSERT INTO keywords (name, description) VALUES ("Síndrome de hombro-mano", "También llamado síndrome de dolor regional complejo; puede presentarse sin razón aparente o después de un traumatismo. Los
síntomas y signos incluyen dolor y pérdida de movimiento en las articulaciones del hombro y la muñeca, con inflamación de la mano; la
piel se puede volver roja y brillante. Normalmente se desarrolla 1-6 meses después del golpe. Se considera su desarrollo en tres fases: I
(aguda), II (distrófica) y III (atrófica).
Observación clínica. Es importante conservar el mayor rango posible de movimiento, pero puede ser necesario el alivio del dolor. A
veces puede producirse bloqueo nervioso simpático (Zyluk y Zyluk, 1999).");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Horner", "Causado por la interrupción del impulso nervioso de los nervios simpáticos que llegan hasta la cara y el ojo. Una característica común
es la ptosis (caída) del párpado.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de inmunodeficiencia adquirida (sida)", "Síndrome causado por la infección por el virus de la inmunodeficiencia humana (VIH).");
INSERT INTO keywords (name, description) VALUES ("Síndrome de la neurona motora superior", "Término utilizado para describir un conjunto de signos positivos y negativos que están asociados a lesiones cerebrales. Las
características positivas incluyen espasticidad, incrementada en los reflejos tendinosos, clonus y resistencia al movimiento pasivo. Las
características negativas incluyen debilidad muscular, pérdida de destreza y coordinación y enlentecimiento del movimiento.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Marfan", "Condición hereditaria que afecta al tejido conectivo. Los síntomas y signos incluyen una constitución corporal alta y delgada,
extremidades largas y movilidad articular anormal; pueden aparecer aneurismas aórticos. Como curiosidad, algunas autoridades creen
que el faraón Akhenaten, padre de Tut-ankh-amum, sufrió este síndrome toda su vida. Algunos creen que el presidente Abraham
Lincoln también padeció el síndrome de Marfan.");
INSERT INTO keywords (name, description) VALUES ("Síndrome de Reiter", "Artritis reactiva normalmente compuesta por la tríada de uretritis, conjuntivitis y artritis. Cualquier articulación periférica puede verse
implicada, si bien normalmente afecta a las del miembro inferior, con una sinovitis a menudo intensa y asimétrica. La tendinitis calcánea
es muy común, y causa problemas en el tendón o en su vaina.");
INSERT INTO keywords (name, description) VALUES ("Síndrome del complejo regional doloroso (SCRD)", "Síndrome de dolor crónico en dos formas. El SCRD1 actualmente sustituye al término de síndrome de distrofia simpática refleja. Se
trata de una alteración nerviosa crónica que tiene lugar la mayoría de las veces en los brazos o piernas después de una lesión mayor o
menor. El SCRD1 está asociado con dolor intenso, cambios en las uñas, hueso y piel, y sensibilidad aumentada al tacto en el miembro
afectado. El SCRD2 sustituye al término causalgia y resulta de una lesión identificada del nervio.");
INSERT INTO keywords (name, description) VALUES ("Síndrome del desfiladero torácico", "Compresión del paquete neurovascular, que comprende el plexo braquial y la arteria subclavia. Comprende una gran variedad de
síntomas, que van desde dolor en el hombro o brazo, hasta alteraciones neurológicas o vasculares. La compresión normalmente se
localiza en el desfiladero torácico del cuello.");
INSERT INTO keywords (name, description) VALUES ("Síndrome del piriforme", "El piriforme está implicado en la irritación del nervio ciático, ya que pasa a través o por debajo del músculo. A menudo va acompañado
de dolor de nalga profundo.
Síndrome del túnel carpianoCompresión del nervio mediano en el túnel carpiano que da lugar a alteraciones sensitivas y motoras de la mano.
Véase Test de Phalen.");
INSERT INTO keywords (name, description) VALUES ("Síndrome parkinsoniano", "Término usado para describir un grupo de enfermedades cerebrales degenerativas que cursan con lentitud del movimiento, inmovilismo
de la musculatura facial, rigidez, temblor y marcha en festinación; suelen denominarse también «parkinsonismo».");
INSERT INTO keywords (name, description) VALUES ("Síndrome pusher («empujador»)", "Término usado para describir a pacientes, normalmente personas que han sufrido una grave apoplejía, que tienen tendencia a empujar
hacia su lado hemipléjico y resisten el intento de corregir su
postura hacia la línea media. Tienden a extender el brazo y pierna no
afectados empujando sobre ellos, pero su percepción es que se están cayendo sobre su lado bueno.
Observación clínica Esta presentación va a menudo acompañada de problemas de percepción y cognición.");
INSERT INTO keywords (name, description) VALUES ("Síndrome respiratorio agudo grave (SARS)", "Forma grave de neumonía que da lugar a dolor respiratorio agudo y a veces puede ser letal.");
INSERT INTO keywords (name, description) VALUES ("Síndrome T4", "Síntomas asociados con una lesión de hipomovilidad en T4 (+/- 1-2 niveles). La persona se queja de dolor vago o molestia en el brazo,
acompañado de parestesia, que no sigue ningún patrón de dermatoma. Los síntomas en la mano también se consideran parte integral de
este síndrome. La patología es desconocida, pero el control de la inervación autónoma puede verse afectado.");
INSERT INTO keywords (name, description) VALUES ("Sinergista", "Músculo que se asocia con otro para producir un movimiento que no podría realizar solo.");
INSERT INTO keywords (name, description) VALUES ("Sínfisis del pubis", "Articulación anterior de la pelvis.");
INSERT INTO keywords (name, description) VALUES ("Sinovitis", "Inflamación de la membrana sinovial.");
INSERT INTO keywords (name, description) VALUES ("Síntoma", "Cualquier cambio perceptible, subjetivo, en el cuerpo o en sus funciones, que indica enfermedad o fases de la misma, como lo relatado
por el paciente; por ejemplo, si el paciente dice que le duele constantemente la rodilla, esto es un síntoma. En cambio, si se observa la
existencia de un reflejo rotuliano positivo, esto es un signo.");
INSERT INTO keywords (name, description) VALUES ("Sir John Charnley", "Pionero en la técnica de sustitución de cadera que hoy recibe su nombre: la artroplastia de baja fricción de Charnley. La mayor parte de
su trabajo fue realizado en el Wrightington Hospital de Lancashire, Reino Unido.");
INSERT INTO keywords (name, description) VALUES ("Siringomielia", "Enfermedad de la médula espinal en la que se forman cavidades dentro de la materia gris. Se caracteriza por una pérdida de las
sensaciones de dolor y temperatura.");
INSERT INTO keywords (name, description) VALUES ("Sistema inmunitario", "Elementos del cuerpo que reconocen agentes extraños o sustancias, las eliminan o neutralizan, y recuerdan la respuesta cuando se
enfrentan en el futuro al mismo agente.");
INSERT INTO keywords (name, description) VALUES ("Sistema límbico", "Término colectivo para un grupo de estructuras cerebrales en o cerca del borde (limbo) de la pared medial del hemisferio cerebral;
incluye el hipocampo, la amígdala y la circunvolución callosa. El sistema límbico ejerce una importante influencia sobre el sistema motor
autonómico y endocrino; sus funciones también parecen afectar al estado anímico y emocional.
Sistema nervioso autónomoNeuronas que no se encuentran bajo control voluntario y forman los sistemas nerviosos simpático y parasimpático. El sistema nervioso
autónomo consta de dos divisiones; sus efectos en los sistemas del cuerpo se exponen en la siguiente tabla:
Efectos de la estimulación nerviosa simpática y parasimpática en varios tejidos");
