INSERT INTO keywords (name, description) VALUES ("Glándulas lagrimales", "");
INSERT INTO keywords (name, description) VALUES ("Sistema nervioso central", "Comprende el encéfalo, la médula espinal y los nervios espinales.");
INSERT INTO keywords (name, description) VALUES ("Sistema nervioso parasimpático", "Véase Sistema nervioso autónomo.
Una de las dos divisiones del sistema nervioso autónomo vertebral.Sistema nervioso periférico
Relativo a las estructuras del sistema nervioso que no incluyen el encéfalo ni la médula espinal (es decir, los nervios).");
INSERT INTO keywords (name, description) VALUES ("Sistema nervioso simpático", "Véase Sistema nervioso autónomo.");
INSERT INTO keywords (name, description) VALUES ("Sistema Vancouver", "Sistema de referencia bibliográfica usado en publicaciones académicas, que usa números insertados en los textos. La referencia citada
en el texto es numerada con un 1 y es citada como 1 en la lista de referencia al final. Este sistema de referencia se usa en algunas
publicaciones médicas.");
INSERT INTO keywords (name, description) VALUES ("SMART", "Acrónimo inglés que define los objetivos de tratamiento:
• ESpecífico.
• Medible.
• Alcanzable.
• Realista.
• OporTuno.
Algunos ejemplos típicos de objetivos ortopédicos que cumplen los objetivos SMART son los siguientes.");
INSERT INTO keywords (name, description) VALUES ("Buenos objetivos", "• El señor X será capaz de subir y bajar de forma segura las escaleras y de soportar el peso parcial de su cuerpo con los codos sobre
las muletas en un período de cuatro días.
• La señora Y habrá conseguido 50° de flexión activa de rodilla en una semana a partir de hoy.
• La señora Z será capaz de pasar de forma segura de la cama a la silla en dos días.");
INSERT INTO keywords (name, description) VALUES ("Malos objetivos", "Cada uno de los siguientes objetivos no cumple con uno o más de un criterio de EMARO:
1. Al señor X le desaparecerá completamente el dolor al cabo de un día de fijar su fémur, tibia y húmero fracturados.
2. El señor X será capaz de andar en 8 meses.
3. El señor X estará mucho mejor en una semana.
4. El señor X será capaz de soportar totalmente el peso de su cuerpo sobre su fractura inestable dentro de una semana.
5. El señor X podrá flexionar más la rodilla dentro de una semana.");
INSERT INTO keywords (name, description) VALUES ("¿Por qué razón cada uno de esos objetivos es inaceptable?", "1. No es realista. Es extremadamente improbable que al señor X le desaparezca totalmente el dolor un día después de haber sufrido
esas tres fracturas.
2. No es oportuno. La meta final está demasiado lejana temporalente.
3. No es específico. ¿Qué significa «mucho mejor»?
4. No es alcanzable. El protocolo ortopédico no permite esto.
5. No es medible ni específico. ¿Qué significa «más»?");
INSERT INTO keywords (name, description) VALUES ("SMSI", "Abreviatura médica común de síndrome de muerte súbita de la infancia, conocido como síndrome de muerte en la cuna.");
INSERT INTO keywords (name, description) VALUES ("Sobrepresión", "Es una presión pasiva aplicada en el final del rango activo de una articulación cuando está libre de dolor. Un movimiento no puede
clasificarse como normal a menos que el rango esté libre de dolor tanto pasiva como activamente y con la adición de una sobrepresiónpasiva en el límite del rango activo. Se recomienda hacer el registro de un movimiento normal con relación a su rango, calidad y
respuesta de síntomas mediante el símbolo √√ (Maitland, 2001, pág. 124).");
INSERT INTO keywords (name, description) VALUES ("Socialización profesional", "Proceso por el cual aquellos que se convierten en miembros de una profesión interiorizan las normas, valores e ideologías dominantes
de esa profesión.");
INSERT INTO keywords (name, description) VALUES ("Sociología", "Estudio de las sociedades humanas.");
INSERT INTO keywords (name, description) VALUES ("Software de bibliografía electrónica", "En la actualidad, muchos estudiantes eligen sistemas de tratamiento electrónicos de referencia como End Note, Reference Manager o
ProCite, que les ayudan a buscar bibliotecas en internet para localizar referencias relevantes a fin de crear su base de datos y generar y
formatear citas y referencias bibliográficas de forma automática. En vez de invertir horas en encontrar y gestionar referencias usando
métodos tradicionales o creando y editando bibliografías manualmente, los alumnos pueden utilizar herramientas de tratamiento de
referencia para ahorrar tiempo, mejorar su precisión y racionalizar todo el proceso de escritura.
Para aquellos que ya utilizan software bibliográfico, el tratamiento de referencia tiene una versión nueva en RefViz: un recién creado
paquete de software para el análisis y visualización de textos que permite al usuario evaluar visualmente la relevancia de las referencias.
Si los documentos presentan contenido técnico o científico, vale la pena considerar invertir en sciPROOF: la herramienta del autor
científico para la corrección de pruebas.");
INSERT INTO keywords (name, description) VALUES ("Solución isotónica", "Disolución con la misma concentración que el plasma.");
INSERT INTO keywords (name, description) VALUES ("Sonidos cardíacos", "Los sonidos cardíacos normales se corresponden con el cierre de las cuatro válvulas del corazón.
• Primer sonido cardíaco. «Sonido LUB», cierre de las válvulas mitral y tricúspide.
• Segundo sonido cardíaco. «Sonido DUP», cierre de las válvulas aórtica y pulmonar.
• Tercer sonido cardíaco. Insuficiencia cardíaca en adultos (puede ser normal en niños y se corresponde con la vibración de las paredes
ventriculares).
• Cuarto sonido cardíaco. Vibración de las paredes ventriculares en la diástole tardía; se escucha en caso de insuficiencia cardíaca,
hipertensión y enfermedad de la válvula aórtica (Pryor y Prasad, 2002).");
INSERT INTO keywords (name, description) VALUES ("Sonidos respiratorios", "");
INSERT INTO keywords (name, description) VALUES ("Sonidos respiratorios normales", "Representan la filtración de sonidos respiratorios bronquiales generados en vías aéreas mayores. Pueden ser escuchados en toda la
pared torácica durante la inspiración y durante un tiempo limitado de la espiración.");
INSERT INTO keywords (name, description) VALUES ("Sonidos respiratorios bronquiales", "Sonidos normales que son transmitidos a través de un pulmón sin aire, que no atenúa las altas frecuencias.");
INSERT INTO keywords (name, description) VALUES ("Sonidos bronquiales disminuidos", "Aparecen cuando hay una reducción en la génesis del sonido o un aumento en la atenuación del sonido.");
INSERT INTO keywords (name, description) VALUES ("Silbido o ronquido", "Cualquier alteración que ocasiona un estrechamiento de las vías aéreas puede dar lugar a un silbido.");
INSERT INTO keywords (name, description) VALUES ("Crepitaciones", "Chasquidos escuchados durante la inspiración; pueden ser tempranos, tardíos, gruesos, finos, localizados o extendidos.");
INSERT INTO keywords (name, description) VALUES ("Sonido pleural", "Crujido que se produce cuando la pleura se inflama (Pryor y Prasad, 2002).");
INSERT INTO keywords (name, description) VALUES ("Sonoforesis", "Término electroterápico que se aplica al uso de ultrasonidos terapéuticos para transportar un compuesto activo a través de la barrera
de la piel; por ejemplo, los analgésicos y las cremas antiinflamatorias se usan como medio de contacto entre el aplicador y la piel.Soportes ortopédicos
Ortesis externas que se usan para ayudar a los pacientes a andar, estabilizando mecánicamente las articulaciones y proporcionando
apoyo para el peso intrínseco del miembro. Son usados normalmente por pacientes parapléjicos.");
INSERT INTO keywords (name, description) VALUES ("SPR", "Abreviatura médica común de sarampión-paperas-rubéola (vacuna).");
INSERT INTO keywords (name, description) VALUES ("Subcostal", "Localizado por debajo de las costillas.");
INSERT INTO keywords (name, description) VALUES ("Subcutáneo", "Localizado debajo de la piel (el marcapasos, sus baterías y electrodos se insertan de forma subcutánea).");
INSERT INTO keywords (name, description) VALUES ("Subdiafragmático", "Localizado debajo del diafragma.");
INSERT INTO keywords (name, description) VALUES ("Subjetividad", "Estado mental que emana de los sentimientos personales, opiniones y emociones.");
INSERT INTO keywords (name, description) VALUES ("Subluxación", "Dislocación parcial de la articulación. La articulación del hombro es particularmente vulnerable debido a la movilidad inherente de su
anatomía estructural y el soporte proporcionado por el manguito de los rotadores. En la hemiplejía u otras lesiones neurológicas, el
hombro puede subluxarse debido a una falta de tono en los músculos que rodean la articulación o, en algunos casos, la presencia de un
aumento de tono puede hacer que algunos músculos traccionen más que otros, causando así la subluxación.
Observación clínica Se debe tener especial cuidado al tratar un hombro hemipléjico para prevenir el traumatismo, pero es
importante recordar que la subluxación no necesariamente provoca dolor.");
INSERT INTO keywords (name, description) VALUES ("Subluxación del tendón peroneo", "Ocurre comúnmente después de una lesión por inversión, normalmente debido a la existencia de un surco peroneal poco profundo que
predispone a una subluxación o dislocación. El paciente a menudo se queja de un sonido o sensación de «chasquido» detrás del
maléolo lateral.");
INSERT INTO keywords (name, description) VALUES ("Subluxación/dislocación de la rótula", "Inestabilidad de la articulación femororrotuliana, por la cual la rótula se disloca lateralmente.");
INSERT INTO keywords (name, description) VALUES ("Succión", "1. En el contexto de los cuidados respiratorios, hace referencia a la forma de eliminación del exceso de secreciones bronquiales en una
persona incapaz de expectorar por sí misma. La succión nasofaríngea implica la inserción de un catéter a través de la nariz o la succión
a través de la boca. La succión también puede administrarse a través de una vía aérea, en una persona intubada o con traqueotomía.
Los inconvenientes de la succión incluyen la hipoxia, ya que se interrumpe la ventilación, presión intracraneal elevada, traumatismo de la
mucosa bronquial y arritmia cardíaca (Pryor y Prasad, 2002).
2. En el contexto de la electroterapia, se utiliza para mantener los electrodos contra la piel. Puede haber un nivel de succión constante o
variable. Existe riesgo de aparición de hematomas si se utiliza excesiva presión o en pacientes con riesgo de hemorragia, como aquellos
que toman medicación anticoagulante.");
INSERT INTO keywords (name, description) VALUES ("Sumisión", "Acción de obedecer y entregarse a otros. Los profesionales de los cuidados de la salud han esperado frecuentemente que los pacientes
y clientes obedezcan sus deseos sin apenas consultar o negociar. Actualmente se aboga por un mejor enfoque en la relación entre los
profesionales del cuidado de la salud y los clientes. Así, el término «cumplimiento del paciente» ha sido sustituido en gran medida por el
término menos autoritario «adhesión del paciente».
SupinaciónMovimiento del antebrazo de tal manera que la mano mira hacia arriba.");
INSERT INTO keywords (name, description) VALUES ("Supositorio", "Método de administración de un fármaco o medicación a través del recto o de la vagina.");
INSERT INTO keywords (name, description) VALUES ("Surfactante", "Sustancia secretada por los neumocitos de tipo II que forma una fina capa de fluido en la superficie alveolar. Reduce la tensión
superficial para mantener la estabilidad de la pared alveolar y prevenir el colapso.");
INSERT INTO keywords (name, description) VALUES ("Sustentaculum tali", "El astrágalo se localiza sobre el calcáneo pero no descansa sobre él por completo, sino que el calcáneo necesita una superficie elevada
para sostener o mantener el astrágalo arriba.");
INSERT INTO keywords (name, description) VALUES ("Sustitución de cadera (sustitución total de cadera, STC)", "La articulación de la cadera es la más grande y profunda del cuerpo; es esferoidea y multiaxial, con tres grados de libertad de
movimiento, altos niveles de congruencia (estabilidad y área de superficie para la transmisión del estrés) y un extenso rango de
movimiento.
• Aleación de metal en la cabeza y cuello femoral (p. ej., acero inoxidable cobalto cromado) con una cabeza de polietileno de alto peso
molecular (alta densidad). Cuando se utiliza la cabeza pequeña de la prótesis de Charnley, el procedimiento se denomina artroplastia de
baja fricción (ABF).
• Tiempo de la operación: 90 min.
• El enfoque quirúrgico de la articulación de la cadera depende de la preferencia del cirujano y del impacto en la rehabilitación
postoperatoria; las aproximaciones más utilizadas incluyen la división transtrocantérea lateral, que necesita la instalación trocantérea en
el cierre y en la división intermuscular posterolateral. Se divide el cuello femoral, se disloca la articulación (en la medida de lo posible) y
se extirpa la cabeza.Sustitución de cadera
• El canal femoral y el acetábulo se perforan para limpiar el hueso hemorrágico, y se preparan para el implante del componente. El
tamaño de la cavidad depende de la técnica de fijación.
• Si los componentes se van a cementar in situ, se insertan primero componentes de prueba y se determina el tamaño y la forma
idóneos. Éstos son entonces retirados y el cemento de rápida fijación (impregnado con antibióticos en su formulación comercial) se
introduce dentro de las cavidades. Los implantes (con sus superficies protegidas) se introducen dentro del cemento; una capa de
cemento completa entre el implante y el hueso es esencial para la distribución de fuerzas y, por lo tanto, para que el procedimiento de
implante tenga éxito. Se aplica una presión importante para asegurar la reconstrucción.
• La articulación entonces se recoloca y se valora su estabilidad. Una vez el cirujano está satisfecho, la articulación se aduce, flexiona y
se rota internamente para dislocarla. La superficie de protección se elimina, la articulación se recoloca y comienza el cierre.
• Si el trocánter mayor fuera recortado para el acceso, entonces se implantaría de nuevo en el fémur con técnicas de cerclaje con
alambre especializadas, desarrolladas para resistir la rotura.
• Los tejidos blandos son reparados en sus capas.
• Pueden utilizarse o no drenajes profundos y superficiales.
• El paciente es cateterizado normalmente para medir el equilibrio de fluidos en los primeros días.
• El paciente recibe fluidos intravenosos y posiblemente un ADCP (método de alivio del dolor controlado por el paciente) a través de
un catéter que se inserta en una vena de la mano o el antebrazo.
• Muchas personas se someten ahora a anestesia epidural para las sustituciones de cadera, con lo cual se mejora el período
postoperatorio, y en muchas unidades de «seguimiento rápido» el paciente es enviado a casa normalmente a los 5 días ( Birch y Price,
2003).T");
INSERT INTO keywords (name, description) VALUES ("Tabla posterior", "Férula que se coloca en la cara posterior de un miembro. Se ajusta con vendas e inmoviliza una articulación. Con los nuevos materiales
es posible que al encajar el miembro en ella, la parte anterior sea flexible y la parte posterior firme. Se usa normalmente para inmovilizar
la rodilla con una férula desde el tobillo hasta la cadera. Puede ser utilizada para prevenir contracturas mediante el mantenimiento de la
posición, así como método accesorio de tratamiento. Por ejemplo, un paciente podría mantenerse de pie con la pierna débil sobre una
tabla posterior, ya que ello le permitiría apoyar el peso en la pierna afectada.");
INSERT INTO keywords (name, description) VALUES ("Tablillas de espinilla/espinillera", "Término para un conjunto de problemas comunes que afectan tanto a atletas profesionales como aficionados. Los corredores se suelen
ver afectados. La periostitis tiene lugar más hacia la parte anterior que posterior de la pierna y además el hueso está sensible. El
síndrome compartimental anterior afecta a la parte anterior y externa de la pierna. Las fracturas de estrés de la tibia pueden tener lugar
debajo de la rodilla y provocar un dolor localizado y agudo. Las fracturas de estrés suelen ocurrir después de varias semanas de un
programa de entrenamiento nuevo o después de haber comenzado un régimen de entrenamiento más intenso.");
INSERT INTO keywords (name, description) VALUES ("Tablillas de Johnstone", "Tablillas rellenas de aire que envuelven un miembro o una parte de éste; se utilizan en la aproximación terapéutica de Johnstone para
tratar pacientes con déficit neurológico.
Observación clínica También pueden utilizarse como medida temporal de ayuda en miembros que presentan signos de contracturas.
Como todas las tablillas, requieren una monitorización cuidadosa.");
INSERT INTO keywords (name, description) VALUES ("Talasemia", "Forma genética de anemia en la que existe una anormalidad en la globina de la hemoglobina. Los individuos afectados no pueden
sintetizar correctamente la hemoglobina.");
INSERT INTO keywords (name, description) VALUES ("Taller", "Experiencia de aprendizaje centrada en el estudiante, en la que los alumnos y tutores trabajan juntos usando una gama de
materiales/fuentes para conseguir resultados específicos de aprendizaje.");
INSERT INTO keywords (name, description) VALUES ("Tallo cerebral", "Término utilizado para describir el encéfalo medio, puente y médula.");
INSERT INTO keywords (name, description) VALUES ("Taponamiento cardíaco", "Nombre dado a la alteración que implica la compresión del corazón ocasionada por sangre u otro fluido que se acumula en el espacio
entre el miocardio y el pericardio.");
INSERT INTO keywords (name, description) VALUES ("Taquicardia", "Ritmo rápido del corazón (superior a 100 lat./min).");
INSERT INTO keywords (name, description) VALUES ("Taquipnea", "Incremento del ritmo respiratorio.");
INSERT INTO keywords (name, description) VALUES ("Tasa de flujo espiratorio máximo", "Máximo flujo en el comienzo de la espiración forzada. Esta tasa es una medida para saber con qué rapidez puede una persona exhalar
el aire de los pulmones. Es un test útil para evaluar la función de las vías respiratorias, la cual se ve frecuentemente afectada en
enfermedades como el asma o la enfermedad pulmonar obstructiva crónica (EPOC). En estas enfermedades pulmonares, el flujo de
aire durante la exhalación se ve disminuido por el estrechamiento o bloqueo de las vías aéreas. La gravedad del asma y de la EPOC
puede cambiar con el tiempo, y la monitorización del flujo espiratorio máximo es empleada por muchos pacientes para monitorizar su
función pulmonar a lo largo del tiempo.
Tasa de mortalidadMedida del número de muertos por año en una población. Por ejemplo, la tasa de mortalidad infantil es el número de muertos en el
primer año de vida por cada 1.000 nacimientos vivos. La tasa de mortalidad infantil es un indicador poco exacto pero útil de la pobreza
y el índice de desarrollo.");
INSERT INTO keywords (name, description) VALUES ("Tasa metabólica basal", "Cantidad de energía necesaria para mantener el funcionamiento del cuerpo en reposo. La tasa metabólica aumenta con el ejercicio, el
estrés, el miedo y/o la enfermedad.");
INSERT INTO keywords (name, description) VALUES ("TB", "Abreviatura médica común de tuberculosis. Enfermedad pulmonar infecciosa causada por Mycobacterium tuberculosis. El miedo y el
estigma social continúan formando parte de la tuberculosis, pero hay que saber que es una enfermedad que puede llegar a curarse con
una apropiada terapia antituberculosa. La tuberculosis abierta es el único tipo de tuberculosis que se considera una infección de riesgo
para el personal sanitario y pacientes (DoH, 1998).");
INSERT INTO keywords (name, description) VALUES ("TC", "Abreviatura médica común de tomografía computarizada.");
INSERT INTO keywords (name, description) VALUES ("TCE", "Abrevitura médica común de traumatismo craneoencefálico. Véase Traumatismo craneoencefálico.");
INSERT INTO keywords (name, description) VALUES ("Técnica de Delphi", "Técnica de investigación que utiliza un grupo de personas identificadas como expertos en el campo de interés. Un grupo de expertos es
invitado a dar sus opiniones sobre un tema específico utilizando un cuestionario. Después del análisis de los datos, se agrupan en series
de afirmaciones que después se envían de nuevo a los participantes, a los que se les pide que indiquen su nivel de conformidad con
cada afirmación. Posteriormente, se devuelven al investigador, que proporciona una clasificación general de las afirmaciones que
después es distribuida.");
INSERT INTO keywords (name, description) VALUES ("Técnica de Doman delecato", "Técnica de terapia pediátrica. Los diseños pasivos repetidos, acompañados de ejecución inversa y secuencias de movimientos
desarrollados, facilitan el uso de los patrones inactivos en el SNC y el cerebro.");
INSERT INTO keywords (name, description) VALUES ("Tecnología de salud", "Cualquier método utilizado por aquellos que trabajan en los servicios sanitarios para promover la salud, prevenir y tratar la enfermedad
y mejorar la rehabilitación y la asistencia a largo plazo.");
INSERT INTO keywords (name, description) VALUES ("TEF", "Abreviatura médica común de técnica de espiración forzada o huff.
La técnica de espiración forzada se usa para facilitar la expectoración de las secreciones pulmonares y consiste en un aumento del
movimiento normal del árbol bronquial durante la espiración (Pryor, 1991). Las presiones intratorácicas que se producen durante la
TEF son menores que aquellas que se producen con la tos y, por tanto, menos agotadoras.
La TEF o huff está basada en el principio del punto de igual presión (PIP) de West (1982). El PIP es el punto en el que las presiones
aérea y pleural son iguales. Así, durante la espiración forzada, el colapso y la compresión de las vías aéreas tienen lugar hacia la boca,
para de esta manera mover las secreciones en dirección periférica mientras el volumen pulmonar disminuye. Por lo tanto, la TEF con
volúmenes pulmonares bajos desplazará las secreciones de las vías aéreas más periféricas, mientras que una TEF a un volumen
pulmonar alto despejará las secreciones de las vías respiratorias superiores.
Esta técnica es esencial para las técnicas del ciclo activo de respiración que fue descrito por primera vez por Webber (1988).");
INSERT INTO keywords (name, description) VALUES ("Tejido conjuntivo", "Tejido que apoya y une otros tejidos y partes del cuerpo.");
INSERT INTO keywords (name, description) VALUES ("Telangiectasia", "Dilatación permanente de los vasos sanguíneos que crea pequeñas lesiones en forma de red, en la piel o en las membranas mucosas.Oscilación que tiene lugar durante el movimiento.");
INSERT INTO keywords (name, description) VALUES ("Temblor de intención", "Temblor que tiene lugar cuando el individuo intenta un movimiento voluntario, causado por una alteración del sistema nervioso.
Observación clínica Puede observarse en pacientes con esclerosis múltiple. Este temblor es más incapacitante que un temblor de
reposo (como el que aparece en los pacientes de Parkinson), ya que interfiere con la función que se desea realizar.");
INSERT INTO keywords (name, description) VALUES ("Temblor postural", "Temblor patológico (de 3 a 5 Hz) que ocurre cuando el cuerpo o los miembros están trabajando en contra de la gravedad.");
INSERT INTO keywords (name, description) VALUES ("Tendencia central", "Término estadístico; las tres maneras más habituales de medirla son la media, la mediana y la moda.");
INSERT INTO keywords (name, description) VALUES ("Tendinitis", "Alteración inflamatoria del tendón. Se produce el dolor con los movimientos resistidos y el estiramiento del tendón, con rango activo de
movimiento a menudo normal, pero con la aparición del dolor al final del movimiento.");
INSERT INTO keywords (name, description) VALUES ("Tendinitis aquílea", "Inflamación del tendón de Aquiles.");
INSERT INTO keywords (name, description) VALUES ("Tendinitis del supraespinoso", "Inflamación del tendón del supraespinoso. Se observa comúnmente cuando hay un grado de degeneración o degradación del tendón.
La contracción activa del supraespinoso provocará dolor, y normalmente existe un arco de dolor en abducción, de 60-120° según la
mayoría de los libros de texto.
Véase Arco doloroso .");
INSERT INTO keywords (name, description) VALUES ("Tendinitis rotuliana", "Proceso inflamatorio del ligamento rotuliano.");
INSERT INTO keywords (name, description) VALUES ("Tendón de Aquiles", "Tendón que une los músculos gastrocnemio y sóleo al calcáneo.
Observación clínica El test que diagnostica la rotura del tendón de Aquiles es el test de Thompson (no confundir con el test de
Thomas, que valora una contractura en la flexión de cadera).
Véase Test de Thompson.");
INSERT INTO keywords (name, description) VALUES ("Tenosinovitis", "Inflamación de la vaina del tendón. Puede ocurrir después de un traumatismo, sobrecarga o alteraciones inflamatorias. Aparece dolor,
inflamación y/o restricción de los movimientos. La inflamación tiene una aparición característica de tipo lineal, a lo largo de los tendones.");
INSERT INTO keywords (name, description) VALUES ("Tenosinovitis de De Quervain", "Inflamación de los tendones y las vainas del músculo abductor largo del pulgar y el extensor corto del pulgar.");
INSERT INTO keywords (name, description) VALUES ("Tenotomía", "La división de un tendón o la acción de dividir un tendón.");
INSERT INTO keywords (name, description) VALUES ("Tenovaginitis", "Engrosamiento de la vaina fibrosa del tendón.");
INSERT INTO keywords (name, description) VALUES ("Tensión", "Medida de la fuerza desarrollada por un músculo durante la contracción cuando no se le permite acortarse, es decir, en la contracción
isométrica.
Tensión neuralTérmino empleado al realizar la valoración de la movilidad y la extensibilidad nerviosa; resulta más adecuado denominarlo
neural.");
INSERT INTO keywords (name, description) VALUES ("movilidad", "");
INSERT INTO keywords (name, description) VALUES ("Tensión neural adversa", "Término que se refiere al movimiento restringido del sistema nervioso, como se aprecia en el caso del roce de la raíz nerviosa que sigue
a un disco intervertebral prolapsado.");
INSERT INTO keywords (name, description) VALUES ("Teoría basada en datos", "Término de investigación que se aplica a un enfoque de la investigación que genera teorías a partir de datos.");
INSERT INTO keywords (name, description) VALUES ("Teoría de acción razonada", "Esta teoría está apoyada por la creencia de que los seres humanos normalmente se comportan de un modo racional. Las intenciones de
comportamiento, por ejemplo dejar de fumar, están influenciadas por la creencia del individuo de que ocurrirá el resultado deseado y
que este resultado será beneficioso. También son importantes las creencias acerca de lo que otras personas piensan que el individuo
debería hacer, la motivación del individuo para intentar satisfacer los deseos de otras personas, y cuánto control cree que tiene el
individuo.");
INSERT INTO keywords (name, description) VALUES ("Teoría de la puerta de entrada del dolor", "La teoría de la puerta de entrada fue inicialmente propuesta en 1965 por Melzack y Wall basada en el hecho de que las fibras nerviosas
de pequeño diámetro transportan estímulos dolorosos a través de la »puerta de entrada«, pero las fibras nerviosas de gran diámetro que
pasan a través de ésta pueden inhibir la transmisión de la señal dolorosa transportada por los nervios pequeños. Esta interrupción de la
vía del dolor medida por las fibras C gracias a las fibras A β es la que actualmente se conoce como teoría de la puerta de entrada. Las
sustancias químicas liberadas como respuesta al estímulo doloroso también influyen en que la puerta esté abierta o cerrada por el
cerebro para recibir la señal dolorosa. Esto lleva a la teoría de que las señales dolorosas pueden ser interferidas con la estimulación de
la periferia del lugar doloroso, el apropiado transporte de la señal nerviosa a la médula espinal, o a su área correspondiente en el tallo
cerebral o en la corteza cerebral.");
INSERT INTO keywords (name, description) VALUES ("Teoría de la puerta de entrada del dolor", "");
INSERT INTO keywords (name, description) VALUES ("M odelo de compartimentalización del dolor", "Observación clínica Este concepto es de gran importancia para el fisioterapeuta puesto que dedica un gran esfuerzo para aliviar eldolor. La »puerta de entrada« debe ser cerrada por la estimulación de los mecanorreceptores, los cuales permiten el alivio del dolor
mediante masaje, packs de frío y fricción transversa profunda. La acupuntura y analgesia eléctrica (TENS) pueden estimular también la
liberación de opiáceos; de ese modo inhiben la transmisión de la señal dolorosa.");
INSERT INTO keywords (name, description) VALUES ("Teoría del etiquetaje", "Teoría sociológica antigua, criticada y muy discutida. Su hipótesis central es que la propia sociedad genera desviación, ya que los
grupos sociales crean unas reglas y quien las infringe es »etiquetado« como intruso. Exactamente quién y por qué razón es etiquetado
depende del contexto social. Una conducta concreta puede, por ejemplo, considerarse criminal en una cierta época o en una
determinada cultura pero no en otras. Los pacientes y clientes pueden ser etiquetados como »difíciles« si no siguen las instrucciones de
los profesionales de la salud.");
INSERT INTO keywords (name, description) VALUES ("Teoría del filamento corredizo", "Véase Actina y Miosina.
Concepto basado en que, en el interior de las miofibrillas, los filamentos de actina y miosina se deslizan cruzándose entre sí e induciendo
de ese modo el acortamiento. Es el mecanismo fundamental subyacente a la contracción del músculo.");
INSERT INTO keywords (name, description) VALUES ("Teoría del filamento corredizo", "");
INSERT INTO keywords (name, description) VALUES ("Terapia biológica", "Tratamiento con sustancias que pueden estimular el sistema inmunitario para luchar contra las enfermedades de manera más efectiva. Es
especialmente útil en patologías reumatológicas.");
INSERT INTO keywords (name, description) VALUES ("Terapia cognitiva comportamental (TCC)", "Terapia basada en el uso de procesos de pensamiento para cambiar la conducta.");
INSERT INTO keywords (name, description) VALUES ("Terapia de combinación", "La aplicación simultánea de ultrasonidos con estimulación eléctrica es la forma de terapia de combinación más comúnmente aplicada,
aunque el término no es exclusivo de esta combinación. Las modalidades combinadas más frecuentes son los ultrasonidos con la terapia
interferencial, o a veces, ultrasonidos con corriente diadinámica. La evidencia científica que apoya la modalidad es muy limitada, aunque
hay claros argumentos para explicar cómo los ultrasonidos pueden ser capaces de »sensibilizar« un nervio justo cuando la estimulación
eléctrica se libera. Se requiere una intensidad de corriente más baja para alcanzar el umbral y así hacer que el nervio se dispare. No se
sabe con seguridad si la terapia de combinación tiene efectos fisiológicos o terapéuticos superiores a los que se obtendrían con
modalidades de terapia simples, es decir, no combinadas. La evidencia empírica apoya su uso en lesiones particularmente rebeldes.");
INSERT INTO keywords (name, description) VALUES ("Terapia de fuerza inducida", "Véase Uso forzado.Terapia de grupo
El ejercicio de grupo es un método de ejercicio muy extendido. Especialmente utilizado por los fisioterapeutas que trabajan en atención
primaria como parte de su papel educacional y consultivo. Como con cualquier técnica, existen ventajas y desventajas.");
INSERT INTO keywords (name, description) VALUES ("Ventajas de la terapia de grupo", "• El elemento competitivo puede ser útil para la realización personal.
• Es posible realizar una mayor variedad de ejercicios.
• La terapia de grupo puede ser divertida si se organiza adecuadamente.
• Ayuda a que el individuo se sienta menos aislado si coincide con personas que tienen problemas similares.
• Proporciona al fisioterapeuta una buena oportunidad para educar e informar al grupo sobre su condición.
• Los grupos especializados, como los pacientes con espondilitis anquilosante o rehabilitación cardíaca, proporcionan apoyo social.");
INSERT INTO keywords (name, description) VALUES ("Desventajas de la terapia de grupo", "• No hay dos personas idénticas, lo que significa que es difícil encontrar ejercicios de un nivel que sea adecuado para todos los
miembros del grupo.
• Puede existir una tentación de incluir individuos inapropiados en el grupo para ahorrar tiempo y aliviar a los empleados
sobrecargados.
• Es difícil monitorizar a todas las personas durante todo el tiempo.
• Puede ser difícil que todos los miembros del grupo progresen adecuadamente.
• El elemento comparativo puede ser contraproducente o peligroso.
• Algunas personas no responden bien en una situación de grupo, pueden sentirse avergonzadas o tener miedo a pedir consejo.");
INSERT INTO keywords (name, description) VALUES ("Terapia de inhalación", "Uso de fármacos administrados a través del tracto respiratorio. Comúnmente, los broncodilatadores (fármacos utilizados para abrir los
conductos aéreos, relajando la musculatura bronquial lisa) se administran siguiendo este método. Para que lleguen hasta los pulmones, el
tamaño de la partícula es de extrema importancia: debería, idealmente, ser de 5");
INSERT INTO keywords (name, description) VALUES ("μm de diámetro (es decir, del grosor de un pelo", "humano) para asegurar la adecuada deposición pulmonar. Las partículas más grandes chocarán con el tracto respiratorio superior,
mientras que las más pequeñas serán exhaladas.");
INSERT INTO keywords (name, description) VALUES ("Terapia de neurodesarrollo", "Término empleado para describir un determinado enfoque de la rehabilitación de pacientes neurológicos, basado en principios
derivados de la investigación del desarrollo motor y de la neurofisiología.");
INSERT INTO keywords (name, description) VALUES ("Terapia diadinámica", "Las corrientes diadinámicas (de acuerdo con Bernard) han sido utilizadas durante más de 50 años, aunque su popularidad ha oscilado
notablemente. En el Reino Unido y Estados Unidos se utilizan de manera relativamente infrecuente, mientras que en los demás países
europeos son muchos más los practicantes que las utilizan. Hay dos tipos básicos de forma de onda basadas en una rectificación media
o completa de la forma de onda sinusoidal (normalmente a 50 Hz, aunque puede ser de 60 Hz).
Si la aplicación del tratamiento está basada en una corriente sinusoidal de 50 Hz con una rectificación media de la onda (MF o
aplicación monofásica fija), habrá una serie de impulsos de 10 ms intercalada con intervalos de 10 ms. Cada impulso será una forma de
onda sinusoidal media. La segunda aplicación básica consiste en usar una rectificación completa de la onda para generar 100 impulsos
por segundo, cada uno en 10 ms y, por lo tanto, sin presentar intervalo entre los impulsos. Esta aplicación se denomina DF (o difásica
fija). Las otras dos formas de terapia diadinámica implican la combinación de las formas de onda básicas. En la aplicación CP (módulo
en cortos períodos) las corrientes MF y DF son aplicadas alternativamente (durante 1 s cada una). La forma final es aplicar dos
corrientes MF con una corriente a una intensidad constante y la otra elevada. La corriente elevada ocupa los intervalos de impulso de la
primera forma de onda, de manera que cada impulso dura 10 ms; efectivamente no hay intervalos entre los impulsos, pero las ondas
son liberadas con una duración de 5 s.");
INSERT INTO keywords (name, description) VALUES ("Terapia interferencial (TIF)", "Término electroterápico que se aplica a la TIF »verdadera« o »tetrapolar«. Se cruzan dos canales de corriente alterna, produciendo unacorriente de amplitud modulada en el área subcutánea entre los cuatro electrodos. Alternativamente, la corriente puede ser
premodulada, por lo que sólo se requiere un canal con dos electrodos. Cada tren de corriente modulada se denomina »latido«. Aunque
no es tan popular, la investigación sugiere que la TIF premodulada es tan efectiva como la TIF verdadera si se utilizan electrodos
grandes, y supone menos riesgos y una corriente media considerablemente más baja.");
INSERT INTO keywords (name, description) VALUES ("Terapia manual", "Engloba muchas modalidades terapéuticas, entre las que se incluyen la manipulación, la movilización y las técnicas del tejido blando.");
INSERT INTO keywords (name, description) VALUES ("Terbutalina (Bricanyl®)", "Medicamento utilizado para aliviar el broncoespasmo. Funciona estimulando los receptores β 2 , que están extendidos a lo largo de todo
el sistema respiratorio.");
INSERT INTO keywords (name, description) VALUES ("Tercer sonido cardíaco", "Ocurre en la fase inicial de la diástole y corresponde al final de la primera fase de llenado rápido ventricular.");
INSERT INTO keywords (name, description) VALUES ("Termoplásticos", "Materiales que pueden volverse blandos mediante la aplicación de calor y que se endurecen al enfriarse. Muchos brazaletes y férulas se
fabrican actualmente de este material.
Véase Refuerzo funcional.");
INSERT INTO keywords (name, description) VALUES ("Termoterapia", "Véase Crioterapia.
Efectos físicos de aplicar calor a un cuerpo u objeto:
1. Aumento en la temperatura (la media de energía cinética de las moléculas aumenta).
2. Expansión del material (las moléculas vibran más y se mueven más lejos. Los gases se expanden más que los sólidos y los líquidos
más que los sólidos).
3. Cambio en el estado físico.
4. Aceleración de las reacciones químicas (ley de Van't Hoffs, cualquier reacción química capaz de ser acelerada, se acelera por un
aumento de la temperatura). Es de gran importancia para los fisioterapeutas.
5. Descenso en la viscosidad de los fluidos (p. ej., líquido sinovial).
La distribución del calor depende de:
1. Tamaño del área calentada.
2. Profundidad de absorción de la radiación específica.
3. Duración del calentamiento.
4. Intensidad del calentamiento y método de aplicación.");
INSERT INTO keywords (name, description) VALUES ("Test de aglutinación", "Test sanguíneo que es usado para demostrar la presencia de anticuerpos. Depende de la agrupación o aglutinación de las células o
partículas cuando se mezclan con un antisuero específico.");
INSERT INTO keywords (name, description) VALUES ("Test de alcance funcional", "Medida utilizada para valorar el control postural dinámico usada clínicamente como un test que valora las respuestas posturales cuando
el paciente se inclina hacia delante. Es esencial que el procedimiento se estandarice apropiadamente para que los datos sean fiables. Se
utiliza principalmente en la valoración de pacientes neurológicos y pacientes con problemas de equilibrio.");
INSERT INTO keywords (name, description) VALUES ("Test de Apgar", "Método de estudio de la salud física del recién nacido, que se determina después de la valoración de la respiración, acción cardíaca,tono muscular, color de la piel y reflejos. La puntuación numérica total es 10.");
INSERT INTO keywords (name, description) VALUES ("Test de Apley (AKA grind test)", "Valora los meniscos de la rodilla. Consiste en la compresión de la rodilla (en 90° de flexión con el paciente en prono) y la realización de
ambas rotaciones, medial y lateral, de la tibia sobre el fémur.");
INSERT INTO keywords (name, description) VALUES ("Test de aprensión", "Test en el que se coloca la articulación en una posición que favorece la subluxación o luxación; una visible expresión de aprensión en la
cara del paciente sería un signo positivo.");
INSERT INTO keywords (name, description) VALUES ("Test de Clarke", "Compresión de la rótula con una resistencia simultánea a la extensión de la rodilla. Se usa normalmente como test para la condromalacia
patelar.");
INSERT INTO keywords (name, description) VALUES ("Test de Clarke", "Test para detectar un desgarro en la glenoide del hombro.");
INSERT INTO keywords (name, description) VALUES ("Test de conducción nerviosa", "El test de conducción nerviosa es una prueba eléctrica que se emplea para detectar la transmisión de impulsos nerviosos sensitivos y
motores. En este test, el nervio es estimulado eléctricamente mientras un segundo electrodo detecta el impulso descendente.");
INSERT INTO keywords (name, description) VALUES ("Test de crank", "Test para evaluar la estabilidad de la articulación del hombro.");
INSERT INTO keywords (name, description) VALUES ("Test de derivación del pivote", "Test para valorar la inestabilidad anterolateral de la articulación de la rodilla. Con el pie en rotación interna y la rodilla en 30° de flexión,
se aplica a la rodilla un estrés en valgo mientras se va extendiendo simultáneamente.
Resultado anormal Un sonido de tipo »clunk« indica un test positivo y sugiere patología del ligamento cruzado anterior (LCA).");
INSERT INTO keywords (name, description) VALUES ("Test de diferenciación", "Los tests de diferenciación ayudan a determinar el origen de los síntomas del paciente valorando objetivamente las diferentes estructuras
que pueden ser la causa de la queja del paciente.");
INSERT INTO keywords (name, description) VALUES ("Diferenciación de estructuras", "");
INSERT INTO keywords (name, description) VALUES ("Test de Ely", "Test musculoesquelético que se lleva a cabo en casos de acortamiento del músculo recto femoral. El paciente descansa en decúbitoprono mientras el fisioterapeuta le flexiona la rodilla. Si el fisioterapeuta logra la flexión pasiva completa de la rodilla, después llevará
pasivamente la cadera a la extensión. Si, durante el procedimiento, el paciente simultáneamente flexiona la cadera, entonces el recto
femoral está acortado.
Test de estrés en valgo (ligamento colateral medial de la rodilla)
Test que se realiza con el paciente en decúbito supino. El terapeuta tira de la articulación de la rodilla hacia valgo.
Resultado anormal Excesiva apertura en el lado medial de la articulación o dolor.
Normalmente se realiza con la rodilla en 20-30° de flexión. Si el test es llevado a cabo con la rodilla en extensión completa, un signo
positivo sugerirá importante lesión ligamentosa que implica al lateral interno, cruzado posterior y potencialmente al cruzado anterior.");
INSERT INTO keywords (name, description) VALUES ("Test de estrés en valgo", "Test de estrés en varo (ligamento colateral lateral de la rodilla)
Test que se realiza con el paciente en decúbito supino. Los fisioterapeutas aplican una fuerza en varo (es decir, el fémur se presiona
lateralmente y la pierna hacia medial) sobre la articulación de la rodilla. Se observa un signo positivo ante un excesivo esbozo o dolor en
el lado lateral de la articulación. El test es normalmente llevado a cabo con la rodilla en 20-30° de flexión.
Resultado anormal Con la rodilla en extensión, un signo positivo sugiere una lesión ligamentosa importante que implica al colateral
lateral, cruzado posterior y posiblemente cruzado anterior. El test es llevado a cabo otra vez con la rodilla en flexión de 20-30°.");
INSERT INTO keywords (name, description) VALUES ("Test de estrés en varo", "Test de Faber (también conocido como test número 4 o test cuatro)
FABER es un acrónimo de Flexión, ABducción y Rotación Externa de la cadera.1. El paciente se dispone en decúbito supino.
2. El pie del lado afectado se coloca cruzado sobre la rodilla opuesta.
3. El fisioterapeuta presiona hacia abajo la rodilla flexionada y la cresta ilíaca anterosuperior opuesta.
Un signo positivo es el dolor en el área sacroilíaca, que indica un problema con los ligamentos de esta articulación.");
INSERT INTO keywords (name, description) VALUES ("Test de Faber", "");
INSERT INTO keywords (name, description) VALUES ("Test de Finkelstein", "Test para el síndrome de De Quervain, por el cual el paciente aprieta sus dedos sobre el pulgar y lleva a cabo una desviación cubital. Si
aparece dolor en la región el resultado es positivo.");
INSERT INTO keywords (name, description) VALUES ("Test de Finkelstein para la sinovitis de De Quervain", "");
INSERT INTO keywords (name, description) VALUES ("Test de función hepática (TFH)", "Mide los niveles en suero sanguíneo de varias enzimas producidas por el hígado. Si los resultados del test de la función hepática son
elevados, ello puede ser signo de daño hepático.");
INSERT INTO keywords (name, description) VALUES ("Test de inclinación talar", "Test musculoesquelético que valora la integridad del ligamento calcaneoperoneo. El sujeto se sitúa en decúbito supino o lateral con el
pie relajado. Se mueve el calcáneo en abducción y aducción.
Una inclinación excesiva significa que existe excesiva laxitud o rotura de este ligamento.");
INSERT INTO keywords (name, description) VALUES ("Test de la arteria vertebral", "Permite comprobar si existe obstrucción de las arterias vertebrales, que pueden obstruirse por patologías como la arteriosclerosis,
artritis y deformidades de la columna, y también por ciertos movimientos de la columna cervical, como la rotación y la extensión. Los
cinco síntomas que son consecuencia de la insuficiencia arterial vertebral son los siguientes:
1. Diplopía.
2. Vértigo.
3. Disfagia.
4. Disartria.
5. Caídas.
Antes de llevar a cabo una movilización, manipulación o tracción de la columna cervical, es esencial preguntarle al paciente si presenta
alguno de los síntomas descritos anteriormente. Si el paciente presenta signos positivos en la valoración subjetiva, es necesario llevar a
cabo los tests de la arteria vertebral para corroborar o descartar una insuficiencia de la arteria vertebral. Del");
INSERT INTO keywords (name, description) VALUES ("mismo modo, si un", "paciente está siendo sometido a una técnica que puede afectar a la arteria vertebral, como una rotación de grado III/IV de la columna
cervical, es necesario descartar la insuficiencia de la arteria vertebral.
La siguiente tabla muestra los tests de la arteria vertebral para aquellas personas que presentan síntomas y para aquellas en las que,
antes de recibir un tratamiento, es preciso descartar la alteración de la arteria vertebral.");
INSERT INTO keywords (name, description) VALUES ("Test de la arteria vertebral (Grant, 1994)", "El paciente no se queja de síntomas relacionados con IVB y la
manipulación El paciente se queja de síntomas es la elección de tratamiento relacionados con");
INSERT INTO keywords (name, description) VALUES ("IVB", "");
INSERT INTO keywords (name, description) VALUES ("S entado o tumbado S entado", "");
INSERT INTO keywords (name, description) VALUES ("Extensión mantenida Extensión mantenida", "");
INSERT INTO keywords (name, description) VALUES ("Rotación I mantenida Rotación I mantenida", "");
INSERT INTO keywords (name, description) VALUES ("Rotación D mantenida Rotación D mantenida", "");
INSERT INTO keywords (name, description) VALUES ("Rotación/extensión I mantenidas Rotación/extensión I mantenidas", "");
INSERT INTO keywords (name, description) VALUES ("Rotación/extensión D mantenidas M ovimientos rápidos", "");
INSERT INTO keywords (name, description) VALUES ("Posición de premanipulación M ovimientos mantenidos (más de 10 s)", "");
INSERT INTO keywords (name, description) VALUES ("Cualquier otro movimiento", "IVB, insuficiencia vertrebrobasilar; I, izquierda; D, derecha.");
INSERT INTO keywords (name, description) VALUES ("Test de la bufanda (scarf test)", "Test para evaluar los problemas de la articulación acromioclavicular (AAC).
Este test se realiza con aducción forzada en 90° de flexión; el dolor al final del movimiento indica patología en la AAC.
El test de la bufanda para la patología de la articulación acromioclavicularTest de la lata vacía (también conocido como test del supraespinoso)
Se realiza en sedestación o bipedestación, en 90° de abducción bilateral de hombro, toda la rotación interna posible y 30° de flexión
horizontal. El supraespinoso es el principal soporte del brazo suspendido en esta posición. El fisioterapeuta resiste la abducción del
hombro.
Resultado anormal El dolor a la resistencia es un signo positivo de lesión del músculo o tendón del supraespinoso.");
INSERT INTO keywords (name, description) VALUES ("Test de Lachman (test modificado del cajón anterior)", "El paciente está en decúbito supino con la rodilla sobre el muslo del terapeuta, flexionada unos 20-30°. El terapeuta sujeta el área
proximal medial de la tibia con la mano derecha, mientras con la izquierda estabiliza el área lateral del fémur del paciente. El
fisioterapeuta realiza una traslación anterior y posterior de la tibia con la mano derecha. El test de Lachman ha demostrado buena
sensibilidad para el diagnóstico de lesión del ligamento cruzado anterior (Kim y Kim, 1995).");
INSERT INTO keywords (name, description) VALUES ("Test de Lachman", "");
INSERT INTO keywords (name, description) VALUES ("Test de las clavijas y nueve agujeros", "Test para medir la destreza y rapidez de la mano y el miembro superior. El equipo consiste en una base de madera con nueve agujeros
y nueve clavijas de madera; se utiliza un cronómetro para medir el tiempo que se tarda en colocar las clavijas en los agujeros.");
INSERT INTO keywords (name, description) VALUES ("Test de las uñas blanquecinas", "Test efectuado en el lecho de las uñas para valorar la perfusión del tejido (cantidad de sangre que fluye por los tejidos). Se aplica
presión en el blanco de la uña, apretando hasta que la uña se vuelva blanca, lo que indica que se ha hecho salir la sangre del tejido. Una
vez el tejido ha quedado blanquecino, se elimina la presión y se mide el tiempo que tarda la sangre en volver al tejido, indicado por el
retorno del color rosa al lecho de la uña.");
INSERT INTO keywords (name, description) VALUES ("Test de McMurray", "Test de la integridad del menisco de la articulación de la rodilla. El test es positivo si se produce dolor o un ruido seco o chasquido en la
articulación, lo cual ocurre si el menisco está roto o desgarrado.Test de M cM urray");
INSERT INTO keywords (name, description) VALUES ("Técnica", "Paciente en decúbito supino con rodilla flexionada 45° y cadera flexionada 45°. El examinador abraza la parte inferior de la pierna, de
manera que con una mano toma el tobillo y con la otra la rodilla.");
INSERT INTO keywords (name, description) VALUES ("Valoración del menisco medial", "Valorar el dolor a la palpación. Palpar la línea articular medial con la rodilla flexionada.
Valorar el chasquido que indica el traslado del menisco. Aplicar un esfuerzo en valgo sobre la rodilla flexionada. La pierna está ahora
externamente rotada (con la punta de los dedos hacia fuera). Extendemos despacio la rodilla mientras todavía está en valgo.");
INSERT INTO keywords (name, description) VALUES ("Valoración del menisco lateral", "Repetir el test anterior aplicando tensión en varo y rotación interna.");
INSERT INTO keywords (name, description) VALUES ("Hallazgo anormal", "El examinador deberá detectar chasquidos o sonido de ruidos secos cuando se administre el test; como hay varias estructuras en la
articulación de la rodilla que podrían producir estos signos, es fácil que este test dé falsos positivos.");
INSERT INTO keywords (name, description) VALUES ("Test de Ober", "Test que determina la extensibilidad de la banda iliotibial.
Se lleva a cabo con el paciente en decúbito lateral con la cadera totalmente en rotación externa y la articulación de la rodilla en posición
de desbloqueo.Test de Ober");
INSERT INTO keywords (name, description) VALUES ("Resultado normal", "La pierna supralateral debe poder caer (en aducción) hacia la camilla.");
INSERT INTO keywords (name, description) VALUES ("Resultado anormal", "La pierna no puede caer hacia la camilla.");
INSERT INTO keywords (name, description) VALUES ("Test de Phalen", "Test para el síndrome del túnel carpiano, en el que las muñecas se mantienen flexionadas durante 1 min. Si se manifiestan síntomas de
parestesia en los dedos, el test es positivo.");
INSERT INTO keywords (name, description) VALUES ("Test de Phalen para el síndrome del túnel carpiano", "");
INSERT INTO keywords (name, description) VALUES ("Test de presión en los gemelos", "Véase Test de Thompson.");
INSERT INTO keywords (name, description) VALUES ("Test de Rhomberg", "Test para distinguir entre ataxia cerebral y sensorial. Se pide al paciente que se mantenga de pie con los talones juntos, primero con los
ojos abiertos y luego con los ojos cerrados. Si muestra excesivo balanceo o pérdida de equilibrio sólo cuando los ojos están cerrados,
ello indica pérdida propioceptiva.");
INSERT INTO keywords (name, description) VALUES ("Test de sangre oculta fecal", "Test de laboratorio llevado a cabo en muestras de heces para detectar la presencia de sangre oculta.");
INSERT INTO keywords (name, description) VALUES ("Test de Schober", "Medida de la flexión lumbar. Se calcula trazando una línea en la articulación L4-L5, y se dibuja luego una marca 10 cm por encima de
la línea y otra 5 cm por debajo. El paciente se inclina hacia delante con las rodillas ligeramente flexionadas. El terapeuta sostiene elextremo de la cinta de medida en la marca superior y mide la distancia entre las dos marcas. Cualquier aumento por encima de los 15
cm corresponde a la flexión lumbar.");
INSERT INTO keywords (name, description) VALUES ("Test de Schober", "");
INSERT INTO keywords (name, description) VALUES ("Test de sulcus", "Véase Test del cajón inferior.");
INSERT INTO keywords (name, description) VALUES ("Test de tensión del miembro superior (TTMS)", "Véase Neurodinámica.");
INSERT INTO keywords (name, description) VALUES ("Test de Thomas", "Determina la presencia de una deformidad de flexión establecida en la cadera.
El paciente se tumba en decúbito supino, se flexiona completamente la cadera de forma pasiva y la lordosis lumbar desaparece.");
INSERT INTO keywords (name, description) VALUES ("Resultado anormal", "Si la cadera opuesta se despega de la camilla, ello indica la existencia de una deformidad de flexión establecida en la cadera. Esto
puede ser debido a rigidez o restricción en la cápsula, psoas ilíaco o recto anterior. Para diferenciar entre el psoas y el recto anterior
como fuente de restricción, se extiende pasivamente la rodilla del paciente. Si esto hace que la cadera del paciente se flexione menos, la
retracción estará en el recto anterior, debido a que, al extender la rodilla, se ha eliminado el elemento de estiramiento. Si la cadera no se
ve afectada y permanece en el mismo grado de flexión, independientemente de la extensión de rodilla, entonces la restricción estará en
el psoas.");
INSERT INTO keywords (name, description) VALUES ("Test de Thomas positivo", "");
INSERT INTO keywords (name, description) VALUES ("Test de Thompson (también conocido como test del apretón)", "Evalúa la integridad del complejo del tendón de Aquiles gastrocnemio/sóleo. El paciente se tumba en decúbito prono. El fisioterapeuta
comprime la pantorrilla con firmeza, inmediatamente distal al lugar de su máxima circunferencia. Si el tendón está intacto, el pie semoverá en flexión plantar. Un test positivo sería aquel en que el tendón de Aquiles estuviese roto y el pie no realizase flexión plantar.");
INSERT INTO keywords (name, description) VALUES ("Resultado anormal", "En ocasiones, si el tendón está roto, podría observarse un hueco en el tendón o en el vientre muscular.");
INSERT INTO keywords (name, description) VALUES ("Test de Thompson negativo", "");
INSERT INTO keywords (name, description) VALUES ("Test de Yergason", "Test para la subluxación del tendón del bíceps en el hombro. El fisioterapeuta resiste la flexión del hombro, la flexión de codo y la
supinación del antebrazo. Se palpa el tendón del bíceps para sentir si hay subluxación.");
INSERT INTO keywords (name, description) VALUES ("Test del apretón", "Véase Test de Thompson.");
INSERT INTO keywords (name, description) VALUES ("Test del cajón anterior (PA)", "Test para detectar la rotura del ligamento cruzado anterior.
El paciente se sitúa en decúbito supino. El terapeuta se sienta sobre el pie del paciente para estabilizar la pierna y agarra alrededor de la
zona proximal de la tibia y la tuberosidad tibial, y tira de la tibia hacia delante.
Un signo positivo sería la excesiva traslación de la tibia en sentido anterior.
Cajón anterior positivoTest del cajón anterior. Resultado normal: la traslación normal es de aproximadamente 6 mm. Un resultado anormal sería la traslación de 1,5 cm, que confirmaría la
rotura del ligamento. Comparar ambos lados");
INSERT INTO keywords (name, description) VALUES ("Test del cajón inferior (test de sulcus)", "El signo de sulcus se produce traccionando el brazo del paciente distalmente mientras está relajado. Si la cabeza humeral se desliza
fuera de la glenoide, una hendidura se abrirá debajo del acromion. El signo de sulcus es positivo en pacientes con laxitud de hombro.");
INSERT INTO keywords (name, description) VALUES ("Test del cajón inferior", "");
INSERT INTO keywords (name, description) VALUES ("Test del cajón posterior (AP)", "Test para valorar la integridad del ligamento cruzado posterior. El paciente está en decúbito supino. El terapeuta se sienta sobre el pie
del paciente para estabilizar la pierna y agarra alrededor de la parte posterior de la zona proximal de la tibia y empuja la tibia hacia
atrás.");
INSERT INTO keywords (name, description) VALUES ("Resultado anormal", "Excesiva traslación posterior de la tibia. Compárese con el otro lado.
Observación. Con el paciente en triple flexión, se observa un »signo de hundimiento« de forma que la tibia parece estar desplazada
posteriormente en relación con el fémur. Puede dar la falsa impresión de que el paciente padece una rotura del ligamento cruzado
anterior (LCA), ya que al realizar un test PA puede observarse un aumento considerable del movimiento, pero esto es debido al
regreso de la tibia a su posición de reposo.Test del cajón posterior");
INSERT INTO keywords (name, description) VALUES ("Test del cloruro del sudor", "Sencillo test que se utiliza para saber si el paciente padece fibrosis quística.");
INSERT INTO keywords (name, description) VALUES ("Test del dedo-nariz", "Test para comprobar la coordinación oculomotora voluntaria de los miembros superiores. Se pide al paciente que se toque lentamente
la punta de la nariz con el dedo índice extendido; puede ser utilizado para valorar la función cerebelosa.");
INSERT INTO keywords (name, description) VALUES ("Test del desplazamiento de líquido", "Se lleva a cabo forzando el exceso de líquido fuera de la bolsa suprarrotuliana, y después golpeando el lado interno de la rodilla para
desplazar cualquier exceso de líquido al lado externo de la articulación. El test es positivo si se observa que el exceso de líquido se
desplaza a través de la articulación y distiende el lado interno.");
INSERT INTO keywords (name, description) VALUES ("Test del hundimiento", "Véase Neurodinámica.");
INSERT INTO keywords (name, description) VALUES ("Test del supraespinoso (también conocido como test del vacío)", "Test que se realiza con la persona sentada o de pie, con los brazos en abducción de 90°, rotación interna completa y 30° de flexión
horizontal. El fisioterapeuta resiste la abducción del hombro.");
INSERT INTO keywords (name, description) VALUES ("Resultado anormal", "El supraespinoso es el principal soporte para el brazo suspendido en esta posición. El dolor o la resistencia sugerirán una lesión en el");
INSERT INTO keywords (name, description) VALUES ("vientre muscular o en el tendónTest del vacío", "");
INSERT INTO keywords (name, description) VALUES ("Test del talón a la tibia", "Test en que se pide al paciente que pase el talón por la espinilla de la tibia de la pierna contraria. Es un test de coordinación. Las
respuestas pobres pueden indicar una lesión del cerebelo, que dará lugar a una coordinación reducida.");
INSERT INTO keywords (name, description) VALUES ("Test no paramétrico", "Término de investigación que se aplica a un test estadístico que es menos sensible que un test paramétrico, pero que puede ser usado
con datos ordinales y nominales. Los tests no paramétricos pueden utilizarse con datos que no posean distribución normal.
Véase Distribución normal.");
INSERT INTO keywords (name, description) VALUES ("Test paramétrico", "Término de investigación que se aplica a un tipo de test estadístico que es más sensible y consistente que un test no paramétrico. A fin
de poder administrar un test paramétrico, los datos utilizados deben ser intervalos/coeficientes y deben, idealmente, hallarse
normalmente distribuidos.
Véase Distribución normal.");
INSERT INTO keywords (name, description) VALUES ("Test/signo de Lasègue", "Véase Neurodinámica.");
INSERT INTO keywords (name, description) VALUES ("Test/signo de Trendelenburg", "Evalúa la capacidad del mecanismo abductor de la cadera para estabilizarla mientras el paciente está en apoyo monopodal. El test de
Trendelenburg es positivo cuando el paciente está sobre una de sus piernas y la pelvis del lado contralateral cae.
Es un concepto un poco difícil de comprender; las siguientes figuras ayudan a entenderlo.Signo Trendelenburg positivo; nótese la diferencia de nivel de las EIPS (indicadas por los puntos negros)");
INSERT INTO keywords (name, description) VALUES ("Tests de electrodiagnóstico", "Tests que se utiliza para informar de la actividad eléctrica del cerebro o de los nervios; incluyen el electroencefalograma (EEG), los tests
de conducción nerviosa y los potenciales evocados (PE).");
INSERT INTO keywords (name, description) VALUES ("Tests neurodinámicos", "Elevación de la pierna estirada. Test del nervio ciático
La respuesta normal sería dolor y una intensa sensación de estiramiento u hormigueo en la parte posterior de muslo, rodilla, gemelos y
pie. La sensibilización de los tests para diferenciar los tejidos nerviosos de otros tejidos incluye:• Dorsiflexión del tobillo. Sensibiliza el nervio tibial.
• Flexión plantar del tobillo e inversión del antepié. Sensibiliza el nervio peroneo común.
• Aducción de cadera. Sensibiliza el nervio ciático.
• Rotación interna de cadera. Sensibiliza el nervio ciático.
• Flexión pasiva del cuello. Sensibiliza las meninges, la médula espinal y el nervio ciático.");
INSERT INTO keywords (name, description) VALUES ("Elevación de la pierna estirada 1", "");
INSERT INTO keywords (name, description) VALUES ("Elevación de la pierna estirada 2", "Flexión de la rodilla en prono. Test del nervio femoral
Tradicionalmente este test se lleva a cabo en decúbito prono; sin embargo, de ese modo no se logra diferenciar entre tejido nervioso
(nervio femoral) y músculos flexores de la cadera. Si se realiza el test con el paciente en decúbito lateral con la cabeza y el tronco
flexionados, ello permite utilizar la extensión cervical como prueba de desensibilización.
Una respuesta normal sería un rango de movimiento completo, de manera que el talón se aproxime a la nalga y se acompañe de un
fuerte estiramiento en la parte anterior del muslo.Flexión de la rodilla en prono 1");
INSERT INTO keywords (name, description) VALUES ("Flexión de la rodilla en prono 2", "Flexión pasiva del cuello. Test que permite la valoración de médula espinal, meninges de la columna lumbar y nervio");
INSERT INTO keywords (name, description) VALUES ("ciático", "Este test se realiza en decúbito supino y el fisioterapeuta flexiona la cabeza del paciente de forma pasiva. Una respuesta normal sería un
movimiento completo, libre de dolor. La sensibilización incluye el test de elevación de la pierna estirada y tests neurodinámicos de la
extremidad superior.");
INSERT INTO keywords (name, description) VALUES ("Flexión pasiva del cuello", "El test evalúa todos los niveles de la columna, y debería incluirse en todas las exploraciones cervicales, torácicas y lumbares. Se realiza
en posición sentada e incorpora la flexión cervical, torácica y lumbar.Se sensibiliza, por ejemplo, mediante la extensión de la rodilla y la dorsiflexión del tobillo.");
INSERT INTO keywords (name, description) VALUES ("Test de hundimiento (slump test)", "");
INSERT INTO keywords (name, description) VALUES ("Test de hundimiento (posición de partida)", "");
INSERT INTO keywords (name, description) VALUES ("Test de hundimiento (posición hundida)Hundimiento con flexión del cuello", "");
INSERT INTO keywords (name, description) VALUES ("Hundimiento con rodillas extendidasHundimiento con dorsiflexión de tobillo", "");
INSERT INTO keywords (name, description) VALUES ("Tests neurodinámicos de la extremidad superior", "Existen cuatro tests, cada uno destinado a la valoración de un nervio en particular:
1. Test neurodinámico de la extremidad superior n.° 1. Nervio mediano.
Test dinámico neural con miembro levantado, n.° 1Articulación del codo en abducción");
INSERT INTO keywords (name, description) VALUES ("Antebrazo en supinación", "");
INSERT INTO keywords (name, description) VALUES ("Articulación del codo en rotación lateraCodo en extensión", "Este test consiste en: depresión de la cintura escapular, abducción de hombro, supinación del antebrazo, extensión de dedos y muñeca,
rotación externa de hombro y extensión del codo.
El test de sensibilización implica una flexión cervical lateral hacia el lado asintomático, mientras que el movimiento de desensibilización
conlleva una flexión cervical lateral hacia el lado sintomático.
2. Test neurodinámico de la extremidad superior n.° 2a. Nervio mediano.
Test dinámico neural con miembro levantado, n.° 2: tendencia del nervio mediano. Hombro en depresión del manguito de los rotadores
Articulación del hombro en abducción de 10°Rotación lateral de todo el brazo");
INSERT INTO keywords (name, description) VALUES ("Extensión de codo", "");
INSERT INTO keywords (name, description) VALUES ("Extensión de muñeca, dedos y pulgar", "Este test consiste en: depresión de la cintura escapular, 10° de abducción de hombro, rotación externa de todo el brazo, extensión de
codo y muñeca, y extensión de dedos y pulgar.
El test de sensibilización implica inclinación de la columna cervical hacia el lado asintomático o abducción de hombro. El movimiento de
desensibilización conlleva inclinación de la columna cervical hacia el lado sintomático o liberación de la cintura escapular.3. Test neurodinámico de la extremidad superior n.° 2b. Nervio radial.");
INSERT INTO keywords (name, description) VALUES ("Hombro en descenso de cabeza humeral", "");
INSERT INTO keywords (name, description) VALUES ("Articulación del hombro en abducción de 10°", "");
INSERT INTO keywords (name, description) VALUES ("Rotación interna de todo el brazoExtensión de codo", "");
INSERT INTO keywords (name, description) VALUES ("Flexor de muñeca, dedos y pulgar", "Este test consiste en depresión de la cintura escapular, 10° de abducción del hombro, extensión del codo, rotación interna de todo el
brazo y flexión de muñeca, dedos y pulgar.
El test de sensibilización implica inclinación de la columna cervical hacia el lado asintomático o abducción de hombro. El movimiento de
desensibilización conlleva inclinación de la columna cervical hacia el lado sintomático o liberación de la cintura escapular.
4. Test neurodinámico de la extremidad superior n.° 3. Nervio cubital.
Test neurodinámico con miembro levantado, n.° 3. Tendencia del nervio cubital. Hombro en depresiónExtensión de muñeca y dedos");
INSERT INTO keywords (name, description) VALUES ("Pronación de antebrazo", "");
INSERT INTO keywords (name, description) VALUES ("Flexión de codoRotación lateral de hombro", "");
INSERT INTO keywords (name, description) VALUES ("Abducción de 90° de hombro", "Este test consiste en depresión de la cintura escapular, extensión de muñeca y dedos, pronación del antebrazo, flexión de codo,
rotación externa del hombro y 90° de abducción del hombro.
El test de sensibilización implica inclinación de la columna cervical hacia el lado asintomático o abducción del hombro. El movimiento de
desensibilización implica inclinación de la columna cervical hacia el lado sintomático o liberación de la cintura escapular.");
INSERT INTO keywords (name, description) VALUES ("Tétanos", "Contracción mantenida de un músculo esquelético en respuesta a una estimulación de alta frecuencia.");
INSERT INTO keywords (name, description) VALUES ("Tetralogía de Fallot", "Esta alteración, que es un ejemplo clásico de forma cianótica de enfermedad cardíaca congénita, recibe su nombre de un físico francés
que fue el que primero la describió. Es una malformación relativamente poco común, que consta de un defecto séptico ventricular,
estenosis valvular pulmonar, hipertrofia ventricular derecha y un desplazamiento de la aorta del lado izquierdo al lado derecho, por lo
que recibe sangre de ambos lados del corazón. Un recién nacido con esta enfermedad congénita puede sobrevivir hasta la infancia,
pero pocos sobreviven hasta la edad adulta sin cirugía (Porter, 2003).");
INSERT INTO keywords (name, description) VALUES ("Tetraplejía", "Este término relaciona la pérdida o alteración de la función motora y/o sensitiva con una lesión en la médula espinal de la zona cervical.
También puede denominarse cuadraparesia.");
INSERT INTO keywords (name, description) VALUES ("TFP", "Abreviatura médica común de test de la función pulmonar.TFT
Abreviatura médica común de test de la función tiroidea.");
INSERT INTO keywords (name, description) VALUES ("Tibia", "Hueso de la espinilla que se articula con el fémur por su parte superior y con el calcáneo en su parte inferior; también se articula con el
peroné, dando lugar a las articulaciones tibioperoneas superior e inferior.
(A) Tibia y peroné derecho, visión anterior y posterior. (B) Tibia derecha, visión superior");
INSERT INTO keywords (name, description) VALUES ("Tic", "1. Movimientos involuntarios que se pueden encontrar en casos de trastorno obsesivo-compulsivo u otras enfermedades.
2. Contracción rápida de un músculo en respuesta a un único estímulo.
t.i.d.
Abreviatura médica común de tres veces al día (del latín ter in die).");
INSERT INTO keywords (name, description) VALUES ("Tiempo de trombina", "Test de conversión del fibrinógeno en fibrina por la trombina, en el que se mide el tiempo de coagulación del plasma mezclado con una
solución de trombina.");
INSERT INTO keywords (name, description) VALUES ("Timo", "Órgano linfoide simétrico bilateral situado en el mediastino anterosuperior. Es el lugar de producción de linfocitos T. El timo alcanza su
máximo desarrollo en la pubertad.");
INSERT INTO keywords (name, description) VALUES ("Tinnitus", "Alteración que provoca sensación de ruido en el oído. Los pacientes describen el ruido como un zumbido o siseo alto o bajo. Si vaacompañado de sordera, se denomina enfermedad de Ménière.");
INSERT INTO keywords (name, description) VALUES ("Torniquete", "Aparato diseñado para la compresión de los vasos de una extremidad. Un torniquete poco apretado restringirá el flujo venoso de la
extremidad. Un torniquete muy apretado impedirá la circulación arterial hacia la extremidad.");
INSERT INTO keywords (name, description) VALUES ("Torrente celular", "Véase Microcirculación .");
INSERT INTO keywords (name, description) VALUES ("Torticolis espasmódico (rigidez cervical o distonía cervical)", "En el torticolis, los músculos del cuello están afectados, haciendo que la cabeza se incline y rote hacia un lado. Además, la cabeza
puede flexionarse o extenderse.");
INSERT INTO keywords (name, description) VALUES ("Tos", "Uno de los cuatro síntomas cardinales de la enfermedad respiratoria. Ha sido definido como sigue: »una tos espontánea efectiva es un
mecanismo reflejo que utiliza una exhalación forzada máxima para expulsar secreciones o agentes irritantes de las vías aéreas« ( AARC,
1993). Es necesario el cierre de la glotis para esta acción, por lo que la lesión del nervio laríngeo o las cuerdas vocales puede dar lugar
a una pérdida de la naturaleza explosiva de la tos (normalmente la tos tiene lugar cuando la elevada presión intratorácica desciende
repentinamente por la relajación de la glotis). La exploración de este síntoma es vital y puede aportar información clínica significativa
para ayudar al diagnóstico; por ejemplo, cuándo ocurre (los asmáticos a veces informan de tos nocturna), qué la dispara (si hay
componente alérgico o no), si es de larga duración o productora de esputo (posible fumador), etc.");
INSERT INTO keywords (name, description) VALUES ("Toxina botulínica", "Neurotoxina producida por la bacteria Clostridium botulinum; produce debilidad en los músculos diana, bloqueando la liberación de
acetilcolina en la unión neuromuscular. Se usa en el tratamiento y manejo de la plasticidad focal. Los efectos duran hasta 3 meses, y
sólo debería administrarse de forma complementaria al tratamiento.Trabajo angular");
INSERT INTO keywords (name, description) VALUES ("Trabajo de respiración", "Cantidad de energía requerida para vencer las fuerzas opuestas de la respiración (es decir, la elasticidad y resistencia propias del
pulmón y la pared torácica). Para mover un volumen de aire determinado en el pulmón, se requiere cierta cantidad de esfuerzo.");
INSERT INTO keywords (name, description) VALUES ("Trabajo en equipo", "Se refiere a trabajar colaborando con otros. La mayoría de los profesionales de la salud trabajan en equipo, ya que se considera que se
obtienen mayores logros cuando se trabaja en colaboración con otros que cuando se trabaja solo. Los equipos trabajan compartiendo
habilidades, conocimientos y recursos. Cada individuo desempeña un papel específico, pero el equipo tiene intereses y objetivos
comunes. Cada miembro comparte responsabilidad en las decisiones tomadas dentro del equipo, su completo funcionamiento y la
calidad de sus resultados. El trabajo en equipo permite que se incorporen una base más amplia de habilidades, actitudes y valores en la
práctica y en el proceso de toma de decisiones. Los pacientes y clientes deberían ser la parte central para cualquier equipo implicado
en su cuidado.
Véase Equipo interdisciplinario, Equipo intradisciplinario y Equipo multidisciplinario.");
INSERT INTO keywords (name, description) VALUES ("Trabajo en grupo", "Trabajo académico llevado a cabo por un grupo de estudiantes que trabajan juntos y comparten recursos; suele ser supervisado.");
INSERT INTO keywords (name, description) VALUES ("Tracción", "Terapia destinada a proporcionar una fuerza de distracción, tanto para la columna vertebral como para las articulaciones periféricas.");
INSERT INTO keywords (name, description) VALUES ("Tracción ósea", "Inserción de un alambre o clavija a través de un hueso y un sistema de pesos unido, para permitir una tracción localizada y efectiva.
La ilustración inferior muestra un ejemplo de tracción ósea con clavija Steinman. Este método suele aplicarse a la meseta tibial o el
calcáneo. Los lugares de aplicación se deben mantener limpios y libres de infección.");
INSERT INTO keywords (name, description) VALUES ("Tracción rotuliana anormal", "Recorrido anormal de la rótula (normalmente lateral) que puede ser una causa de dolor anterior de la rodilla y puede ser causado por
una biomecánica anormal de la rodilla o del pie, o por una anomalía en la longitud del tejido blando.
Para el tratamiento quirúrgico véase Liberación lateral.
Como en todos los procesos, el tratamiento dependerá de la causa, pero las técnicas del fisioterapeuta incluyen ejercicios del vasto
medial oblicuo, taping (esparadrapo), plantillas si el pie es la causa principal del problema, o movilizaciones de la rótula.");
INSERT INTO keywords (name, description) VALUES ("Tracto corticoespinal", "Se origina en la corteza cerebral y termina en la médula espinal. Está implicado en el control del movimiento voluntario.Tracto piramidal (tracto corticoespinal)
Ruta principal por la cual las órdenes voluntarias llegan a las neuronas motoras en la médula espinal. Se origina en la corteza motora,
atraviesa la cápsula interna de la materia blanca y se dirige luego a las neuronas motoras diana en la médula espinal.
Observación clínica Los pacientes con pérdida piramidal pura presentan disminución del control fino de los dedos y dificultad en el
movimiento de éstos.
Véase Tracto corticoespinal.");
INSERT INTO keywords (name, description) VALUES ("Tracto piramidal", "");
INSERT INTO keywords (name, description) VALUES ("Tracto reticuloespinal", "Rama del sistema nervioso que se origina de la formación reticular y se proyecta hacia los músculos axiales y proximales.");
INSERT INTO keywords (name, description) VALUES ("Tragus", "Prominencia situada delante de la abertura externa del oído.
Los fisioterapeutas a veces la utilizan como referencia objetiva cuando miden los movimientos vertebrales, por ejemplo contra una
pared.");
INSERT INTO keywords (name, description) VALUES ("Transferencia de cuidados", "Término utilizado para describir el proceso de transferencia de la responsabilidad de cuidado de un servicio a otro.");
INSERT INTO keywords (name, description) VALUES ("Transferencias", "Término utilizado para describir el movimiento asistido o independiente de un paciente de una posición a otra, por ejemplo, de la cama
a la silla de ruedas.");
INSERT INTO keywords (name, description) VALUES ("Transfusión", "Transferencia de sangre o productos sanguíneos de una persona (donante) al torrente sanguíneo de otra (receptor).");
INSERT INTO keywords (name, description) VALUES ("Transporte axoplásmico", "Proceso por el cual los materiales descienden por un axón.
TráqueaVía aérea principal, que marca el comienzo del tracto respiratorio superior. La tráquea está formada por anillos de cartílago con forma
de C (para mantener la permeabilidad de la vía aérea), musculatura lisa (para acomodar los cambios necesarios en el diámetro de la
vía) y epitelio ciliado (para facilitar el ascenso mucociliar).");
INSERT INTO keywords (name, description) VALUES ("Traqueítis", "Inflamación de la tráquea.");
INSERT INTO keywords (name, description) VALUES ("Traqueostomía", "Apertura creada quirúrgicamente en el cuello que permite el acceso directo a la tráquea (el tubo de respiración). Se mantiene abierto
con un tubo hueco denominado tubo de traqueostomía.");
INSERT INTO keywords (name, description) VALUES ("Tratamiento basado en el cuidado", "Proceso por el que una persona profesional (normalmente un trabajador social) valora las necesidades de los individuos en cuanto a
costes, planificación y seguimiento de los »convenios de cuidado«. El sistema del tratamiento del cuidado fue introducido con el NHS y
la Community Care Act (1990).");
INSERT INTO keywords (name, description) VALUES ("Traumatismo craneoencefálico", "Provocado por una agresión al cerebro causada por una fuerza externa, que puede dar lugar a una alteración de la conciencia y una
pérdida del movimiento, habla y alteración de la cognición, entre otras alteraciones. El traumatismo craneoencefálico es la causa más
común de muerte accidental.");
INSERT INTO keywords (name, description) VALUES ("Trayectoria motora descendente", "Tradicionalmente se divide en los tractos piramidal y extrapiramidal; también puede clasificarse por su localización anatómica.");
INSERT INTO keywords (name, description) VALUES ("Trayectos espinales (motores) descendentes", "");
