INSERT INTO keywords (name, description) VALUES ("Tectoespinal Ventromedial Componente motor de los reflejos auditivos y visuales", "Reticuloespinal Ventromedial Tono muscular, sistema autonómico, organización de los órganos sensoriales finales; ejemplo, husos");
INSERT INTO keywords (name, description) VALUES ("musculares", "");
INSERT INTO keywords (name, description) VALUES ("Rubrobulbar Dorsolateral Proyecta a la médulaRubroespinal", "");
INSERT INTO keywords (name, description) VALUES ("Dorsolateral", "");
INSERT INTO keywords (name, description) VALUES ("Control extrapiramidal de los músculos flexores", "");
INSERT INTO keywords (name, description) VALUES ("Trazado espirométrico mediante Vitalograph®", "Herramienta de diagnóstico útil para identificar estados normales, obstructivos o restrictivos de las vías aéreas.
M ediciones de los volúmenes pulmonares obtenidas con un espirómetro Vitalograph®");
INSERT INTO keywords (name, description) VALUES ("Triangulación", "Término de investigación que se aplica al proceso por el que los mismos datos se obtienen de varios medios como un intento de
aumentar su validez. Determina la solidez de los resultados reunidos de diferentes fuentes de datos y/o diferentes métodos de
investigación acerca de una cuestión de investigación de interés particular. Por ejemplo, se puede desear entrevistar a un grupo de
estudiantes y después convocarlos a todos juntos para un grupo central como medio de triangulación de datos.");
INSERT INTO keywords (name, description) VALUES ("Tróclea", "Término anatómico para una polea o estructura semejante; por ejemplo, la tróclea del húmero que articula con el cúbito.");
INSERT INTO keywords (name, description) VALUES ("Trombocitopenia", "Disminución del número de plaquetas sanguíneas; el resultado de esta disminución es un potencial incrementado de sangrado y una
disminución de la capacidad de formar coágulos.");
INSERT INTO keywords (name, description) VALUES ("Tromboembolismo", "Obstrucción de un vaso sanguíneo por material transportado por el torrente sanguíneo desde el lugar de origen hasta obstruir otro vaso.");
INSERT INTO keywords (name, description) VALUES ("Trombosis venosa profunda (TVP)", "La formación de un coágulo sanguíneo (trombo) afecta principalmente a las venas de la pierna y el muslo. El trombo puede bloquear la
circulación sanguínea en el área o puede desprenderse y viajar a través del torrente sanguíneo (embolia). El émbolo creado puede viajarhasta cerebro, pulmones, corazón u otra área provocando lesión. Las situaciones de riesgo pueden ser: sedestación prolongada, reposo
en cama o inmovilización, intervención o traumatismos recientes (especialmente en cadera, rodilla o una intervención ginecológica),
fracturas, haber tenido un hijo en los últimos 6 meses y uso de medicamentos como estrógenos o píldora anticonceptiva.
La mayoría de las trombosis venosas profundas (TVP) comienzan en el gemelo y remiten de manera espontánea. Las TVP proximales
remiten lentamente durante el tratamiento con anticoagulantes y los trombos continúan siendo detectables en la mitad de los pacientes
después de 1 año. La resolución de la TVP es menos frecuente en pacientes con un trombo inicial grande o cáncer. Alrededor del 10%
de los pacientes con TVP sintomática desarrollan síndromes trombóticos posteriores graves en el plazo de 5 años y la TVP ipsolateral
recurrente aumenta el riesgo (Kearon, 2003).");
INSERT INTO keywords (name, description) VALUES ("Trompa de Falopio", "Las trompas de Falopio normalmente transportan el óvulo desde el ovario al útero.");
INSERT INTO keywords (name, description) VALUES ("Tropomiosina", "Proteína que se enrolla alrededor del filamento delgado de la actina y cubre los lugares de unión en ausencia de calcio.");
INSERT INTO keywords (name, description) VALUES ("Troponina", "Proteína muscular que une la actina y la tropomiosina; en presencia de calcio, tira de la tropomiosina para dejar al descubierto los
lugares de unión para la miosina.");
INSERT INTO keywords (name, description) VALUES ("TSV", "Abreviatura médica común de taquicardia supraventricular.");
INSERT INTO keywords (name, description) VALUES ("Tto", "Abreviatura médica común de tratamiento.");
INSERT INTO keywords (name, description) VALUES ("Tubérculo", "Término anatómico para una proyección ósea circunscrita.");
INSERT INTO keywords (name, description) VALUES ("Tubérculo de Gerdy", "Tubérculo lateral en el extremo superior de la tibia, donde se inserta parcialmente la banda iliotibial. Es un lugar frecuente de patología
debido a la fricción de la banda iliotibial sobre el hueso.");
INSERT INTO keywords (name, description) VALUES ("Tuberosidad", "Término anatómico que hace referencia a una tuberosidad ósea rugosa para la inserción de músculos y tendones.");
INSERT INTO keywords (name, description) VALUES ("Tuberosidad del quinto metatarsiano", "Tubérculo en la parte posterior de la base de este hueso, en el cual se inserta el tendón del músculo peroneo corto.");
INSERT INTO keywords (name, description) VALUES ("Túnel carpiano", "Túnel formado en la muñeca por el retináculo flexor y los huesos carpianos.Tutor personal
Miembro de la plantilla académica destinado a un estudiante para monitorizar su progreso. Puede darse en el contexto académico o en
el pastoral.U");
INSERT INTO keywords (name, description) VALUES ("UCI", "Abreviatura médica común de unidad de cuidados intensivos.");
INSERT INTO keywords (name, description) VALUES ("Ulna", "Cúbito.
Véase Radio.");
